from pandas.core.dtypes.dtypes import CategoricalDtype, DatetimeTZDtype, ExtensionDtype, IntervalDtype, PeriodDtype
from pandas.core.dtypes.generic import ABCDataFrame, ABCExtensionArray, ABCIndex, ABCMultiIndex, ABCSeries
from pandas.core.dtypes.inference import is_list_like
if TYPE_CHECKING:
    from re import Pattern
    from pandas._libs.missing import NAType
    from pandas._libs.tslibs import NaTType
    from pandas._typing import ArrayLike, DtypeObj, NDFrame, NDFrameT, Scalar, npt
    from pandas import Series
    from pandas.core.indexes.base import Index
isposinf_scalar = libmissing.isposinf_scalar
isneginf_scalar = libmissing.isneginf_scalar
_dtype_object = np.dtype('object')
_dtype_str = np.dtype(str)

@overload
def isna(obj: Scalar | Pattern | NAType | NaTType) -> bool:
    ...

@overload
def isna(obj: ArrayLike | Index | list) -> npt.NDArray[np.bool_]:
    ...

@overload
def isna(obj: NDFrameT) -> NDFrameT:
    ...

@overload
def isna(obj: NDFrameT | ArrayLike | Index | list) -> NDFrameT | npt.NDArray[np.bool_]:
    ...

@overload
def isna(obj: object) -> bool | npt.NDArray[np.bool_] | NDFrame:
    ...

@set_module('pandas')
def isna(obj: object) -> bool | npt.NDArray[np.bool_] | NDFrame:
    return _isna(obj)
isnull = isna

def _isna(obj):
    if is_scalar(obj):
        return libmissing.checknull(obj)
    elif isinstance(obj, ABCMultiIndex):
        raise NotImplementedError('isna is not defined for MultiIndex')
    elif isinstance(obj, type):
        return False
    elif isinstance(obj, (np.ndarray, ABCExtensionArray)):
        return _isna_array(obj)
    elif isinstance(obj, ABCIndex):
        if not obj._can_hold_na:
            return obj.isna()
        return _isna_array(obj._values)
    elif isinstance(obj, ABCSeries):
        result = _isna_array(obj._values)
        result = obj._constructor(result, index=obj.index, name=obj.name, copy=False)
        return result
    elif isinstance(obj, ABCDataFrame):
        return obj.isna()
    elif isinstance(obj, list):
        return _isna_array(np.asarray(obj, dtype=object))
    elif hasattr(obj, '__array__'):
        return _isna_array(np.asarray(obj))
    else:
        return False

def _isna_array(values: ArrayLike) -> npt.NDArray[np.bool_] | NDFrame:
    dtype = values.dtype
    result: npt.NDArray[np.bool_] | NDFrame
    if not isinstance(values, np.ndarray):
        result = values.isna()
    elif isinstance(values, np.rec.recarray):
        result = _isna_recarray_dtype(values)
    elif is_string_or_object_np_dtype(values.dtype):
        result = _isna_string_dtype(values)
    elif dtype.kind in 'mM':
        result = values.view('i8') == iNaT
    else:
        result = np.isnan(values)
    return result

def _isna_string_dtype(values: np.ndarray) -> npt.NDArray[np.bool_]:
    dtype = values.dtype
    if dtype.kind in ('S', 'U'):
        result = np.zeros(values.shape, dtype=bool)
    elif values.ndim in {1, 2}:
        result = libmissing.isnaobj(values)
    else:
        result = libmissing.isnaobj(values.ravel())
        result = result.reshape(values.shape)
    return result

def _isna_recarray_dtype(values: np.rec.recarray) -> npt.NDArray[np.bool_]:
    result = np.zeros(values.shape, dtype=bool)
    for i, record in enumerate(values):
        record_as_array = np.array(record.tolist())
        does_record_contain_nan = isna_all(record_as_array)
        result[i] = np.any(does_record_contain_nan)
    return result

@overload
def notna(obj: Scalar | Pattern | NAType | NaTType) -> bool:
    ...

@overload
def notna(obj: ArrayLike | Index | list) -> npt.NDArray[np.bool_]:
    ...

@overload
def notna(obj: NDFrameT) -> NDFrameT:
    ...

@overload
def notna(obj: NDFrameT | ArrayLike | Index | list) -> NDFrameT | npt.NDArray[np.bool_]:
    ...

@overload
def notna(obj: object) -> bool | npt.NDArray[np.bool_] | NDFrame:
    ...

@set_module('pandas')
def notna(obj: object) -> bool | npt.NDArray[np.bool_] | NDFrame:
    res = isna(obj)
    if isinstance(res, bool):
        return not res
    return ~res
notnull = notna

def array_equivalent(left, right, strict_nan: bool=False, dtype_equal: bool=False) -> bool:
    left, right = (np.asarray(left), np.asarray(right))
    if left.shape != right.shape:
        return False
    if dtype_equal:
        if left.dtype.kind in 'fc':
            return _array_equivalent_float(left, right)
        elif left.dtype.kind in 'mM':
            return _array_equivalent_datetimelike(left, right)
        elif is_string_or_object_np_dtype(left.dtype):
            return _array_equivalent_object(left, right, strict_nan)
        else:
            return np.array_equal(left, right)
    if left.dtype.kind in 'OSU' or right.dtype.kind in 'OSU':
        return _array_equivalent_object(left, right, strict_nan)
    if left.dtype.kind in 'fc':
        if not (left.size and right.size):
            return True
        return ((left == right) | isna(left) & isna(right)).all()
    elif left.dtype.kind in 'mM' or right.dtype.kind in 'mM':
        if left.dtype != right.dtype:
            return False
        left = left.view('i8')
        right = right.view('i8')
    if (left.dtype.type is np.void or right.dtype.type is np.void) and left.dtype != right.dtype:
        return False
    return np.array_equal(left, right)

def _array_equivalent_float(left: np.ndarray, right: np.ndarray) -> bool:
    return bool(((left == right) | np.isnan(left) & np.isnan(right)).all())

def _array_equivalent_datetimelike(left: np.ndarray, right: np.ndarray) -> bool:
    return np.array_equal(left.view('i8'), right.view('i8'))

def _array_equivalent_object(left: np.ndarray, right: np.ndarray, strict_nan: bool) -> bool:
    left = ensure_object(left)
    right = ensure_object(right)
    mask: npt.NDArray[np.bool_] | None = None
    if strict_nan:
        mask = isna(left) & isna(right)
        if not mask.any():
            mask = None
    try:
        if mask is None:
            return lib.array_equivalent_object(left, right)
        if not lib.array_equivalent_object(left[~mask], right[~mask]):
            return False
        left_remaining = left[mask]
        right_remaining = right[mask]
    except ValueError:
        left_remaining = left
        right_remaining = right
    for left_value, right_value in zip(left_remaining, right_remaining, strict=True):
        if left_value is NaT and right_value is not NaT:
            return False
        elif left_value is libmissing.NA and right_value is not libmissing.NA:
            return False
        elif isinstance(left_value, float) and np.isnan(left_value):
            if not isinstance(right_value, float) or not np.isnan(right_value):
                return False
        else:
            with warnings.catch_warnings():
                warnings.simplefilter('ignore', DeprecationWarning)
                try:
                    if np.any(np.asarray(left_value != right_value)):
                        return False
                except TypeError as err:
                    if 'boolean value of NA is ambiguous' in str(err):
                        return False
                    raise
                except ValueError:
                    return False
    return True

def array_equals(left: ArrayLike, right: ArrayLike) -> bool:
    if left.dtype != right.dtype:
        return False
    elif isinstance(left, ABCExtensionArray):
        return left.equals(right)
    else:
        return array_equivalent(left, right, dtype_equal=True)

def infer_fill_value(val):
    if not is_list_like(val):
        val = [val]
    val = np.asarray(val)
    if val.dtype.kind in 'mM':
        return np.array('NaT', dtype=val.dtype)
    elif val.dtype == object:
        dtype = lib.infer_dtype(ensure_object(val), skipna=False)
        if dtype in ['datetime', 'datetime64']:
            return np.array('NaT', dtype=DT64NS_DTYPE)
        elif dtype in ['timedelta', 'timedelta64']:
            return np.array('NaT', dtype=TD64NS_DTYPE)
        return np.array(np.nan, dtype=object)
    elif val.dtype.kind == 'U':
        return np.array(np.nan, dtype=val.dtype)
    return np.nan

def construct_1d_array_from_inferred_fill_value(value: object, length: int) -> ArrayLike:
    from pandas.core.algorithms import take_nd
    from pandas.core.construction import sanitize_array
    from pandas.core.indexes.base import Index
    arr = sanitize_array(value, Index(range(1)), copy=False)
    taker = -1 * np.ones(length, dtype=np.intp)
    return take_nd(arr, taker)

def maybe_fill(arr: np.ndarray) -> np.ndarray:
    if arr.dtype.kind not in 'iub':
        arr.fill(np.nan)
    return arr

def na_value_for_dtype(dtype: DtypeObj, compat: bool=True):
    if isinstance(dtype, ExtensionDtype):
        return dtype.na_value
    elif dtype.kind in 'mM':
        unit = np.datetime_data(dtype)[0]
        return dtype.type('NaT', unit)
    elif dtype.kind in 'fc':
        return np.nan
    elif dtype.kind in 'iu':
        if compat:
            return 0
        return np.nan
    elif dtype.kind == 'b':
        if compat:
            return False
        return np.nan
    return np.nan

def remove_na_arraylike(arr: Series | Index | np.ndarray):
    if isinstance(arr.dtype, ExtensionDtype):
        return arr[notna(arr)]
    else:
        return arr[notna(np.asarray(arr))]

def is_valid_na_for_dtype(obj, dtype: DtypeObj) -> bool:
    if not lib.is_scalar(obj) or not isna(obj):
        return False
    elif dtype.kind == 'M':
        if isinstance(dtype, np.dtype):
            return not isinstance(obj, (np.timedelta64, Decimal))
        return not isinstance(obj, (np.timedelta64, np.datetime64, Decimal))
    elif dtype.kind == 'm':
        return not isinstance(obj, (np.datetime64, Decimal))
    elif dtype.kind in 'iufc':
        return obj is not NaT and (not isinstance(obj, (np.datetime64, np.timedelta64)))
    elif dtype.kind == 'b':
        return lib.is_float(obj) or obj is None or obj is libmissing.NA
    elif dtype == _dtype_str:
        return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal, float))
    elif dtype == _dtype_object:
        return True
    elif isinstance(dtype, PeriodDtype):
        return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal))
    elif isinstance(dtype, IntervalDtype):
        return lib.is_float(obj) or obj is None or obj is libmissing.NA
    elif isinstance(dtype, CategoricalDtype):
        return is_valid_na_for_dtype(obj, dtype.categories.dtype)
    return not isinstance(obj, (np.datetime64, np.timedelta64, Decimal))

def isna_all(arr: ArrayLike) -> bool:
    total_len = len(arr)
    chunk_len = max(total_len // 40, 1000)
    dtype = arr.dtype
    if lib.is_np_dtype(dtype, 'f'):
        checker = np.isnan
    elif lib.is_np_dtype(dtype, 'mM') or isinstance(dtype, (DatetimeTZDtype, PeriodDtype)):
        checker = lambda x: np.asarray(x.view('i8')) == iNaT
    else:
        checker = _isna_array
    return all((checker(arr[i:i + chunk_len]).all() for i in range(0, total_len, chunk_len)))

from __future__ import annotations
from functools import partial
import re
from typing import TYPE_CHECKING, Any, Literal, Self
import numpy as np
from pandas._libs import lib
from pandas.compat import HAS_PYARROW, pa_version_under17p0, pa_version_under21p0
if HAS_PYARROW:
    import pyarrow as pa
    import pyarrow.compute as pc
if TYPE_CHECKING:
    from collections.abc import Callable
    from pandas._typing import Scalar

class ArrowStringArrayMixin:
    _pa_array: pa.ChunkedArray

    def __init__(self, *args, **kwargs) -> None:
        raise NotImplementedError

    def _from_pyarrow_array(self, pa_array) -> Self:
        raise NotImplementedError

    def _convert_bool_result(self, result, na=lib.no_default, method_name=None):
        raise NotImplementedError

    def _convert_int_result(self, result):
        raise NotImplementedError

    def _apply_elementwise(self, func: Callable) -> list[list[Any]]:
        raise NotImplementedError

    @staticmethod
    def _has_unsupported_regex(pat: str | re.Pattern) -> bool:
        try:
            from re import _parser
            regex_parser = _parser.parse
        except Exception as err:
            raise type(err)('Incompatible version for regex; you will need to upgrade pandas or downgrade Python') from err

        def has_unsupported_code(tokens):
            for op_code, argument in tokens:
                if op_code == _parser.SUBPATTERN and has_unsupported_code(argument[3]) or (op_code == _parser.BRANCH and any((has_unsupported_code(tokens) for tokens in argument[1]))) or op_code in [_parser.ASSERT_NOT, _parser.ASSERT, _parser.GROUPREF]:
                    return True
            return False
        str_pat = pat.pattern if isinstance(pat, re.Pattern) else pat
        try:
            tokens = regex_parser(str_pat)
        except re.error:
            return False
        return has_unsupported_code(tokens)

    def _str_len(self):
        result = pc.utf8_length(self._pa_array)
        return self._convert_int_result(result)

    def _str_lower(self) -> Self:
        return self._from_pyarrow_array(pc.utf8_lower(self._pa_array))

    def _str_upper(self) -> Self:
        return self._from_pyarrow_array(pc.utf8_upper(self._pa_array))

    def _str_strip(self, to_strip=None) -> Self:
        if to_strip is None:
            result = pc.utf8_trim_whitespace(self._pa_array)
        else:
            result = pc.utf8_trim(self._pa_array, characters=to_strip)
        return self._from_pyarrow_array(result)

    def _str_lstrip(self, to_strip=None) -> Self:
        if to_strip is None:
            result = pc.utf8_ltrim_whitespace(self._pa_array)
        else:
            result = pc.utf8_ltrim(self._pa_array, characters=to_strip)
        return self._from_pyarrow_array(result)

    def _str_rstrip(self, to_strip=None) -> Self:
        if to_strip is None:
            result = pc.utf8_rtrim_whitespace(self._pa_array)
        else:
            result = pc.utf8_rtrim(self._pa_array, characters=to_strip)
        return self._from_pyarrow_array(result)

    def _str_pad(self, width: int, side: Literal['left', 'right', 'both']='left', fillchar: str=' ') -> Self:
        if side == 'left':
            pa_pad = pc.utf8_lpad
        elif side == 'right':
            pa_pad = pc.utf8_rpad
        elif side == 'both':
            if pa_version_under17p0:
                from pandas import array
                obj_arr = self.astype(object, copy=False)
                obj = array(obj_arr, dtype=object)
                result = obj._str_pad(width, side, fillchar)
                return type(self)._from_sequence(result, dtype=self.dtype)
            else:
                lean_left = width % 2 == 0
                pa_pad = partial(pc.utf8_center, lean_left_on_odd_padding=lean_left)
        else:
            raise ValueError(f"Invalid side: {side}. Side must be one of 'left', 'right', 'both'")
        return self._from_pyarrow_array(pa_pad(self._pa_array, width=width, padding=fillchar))

    def _str_get(self, i: int) -> Self:
        lengths = pc.utf8_length(self._pa_array)
        if i >= 0:
            out_of_bounds = pc.greater_equal(i, lengths)
            start = i
            stop = i + 1
            step = 1
        else:
            out_of_bounds = pc.greater(-i, lengths)
            start = i
            stop = i - 1
            step = -1
        not_out_of_bounds = pc.invert(out_of_bounds.fill_null(True))
        selected = pc.utf8_slice_codeunits(self._pa_array, start=start, stop=stop, step=step)
        null_value = pa.scalar(None, type=self._pa_array.type)
        result = pc.if_else(not_out_of_bounds, selected, null_value)
        return self._from_pyarrow_array(result)

    def _str_slice(self, start: int | None=None, stop: int | None=None, step: int | None=None) -> Self:
        if start is None:
            if step is not None and step < 0:
                start = -1
            else:
                start = 0
        if step is None:
            step = 1
        return self._from_pyarrow_array(pc.utf8_slice_codeunits(self._pa_array, start=start, stop=stop, step=step))

    def _str_slice_replace(self, start: int | None=None, stop: int | None=None, repl: str | None=None) -> Self:
        if repl is None:
            repl = ''
        if start is None:
            start = 0
        if stop is None:
            stop = np.iinfo(np.int64).max
        return self._from_pyarrow_array(pc.utf8_replace_slice(self._pa_array, start, stop, repl))

    def _str_replace(self, pat: str | re.Pattern, repl: str | Callable, n: int=-1, case: bool=True, flags: int=0, regex: bool=True) -> Self:
        if isinstance(pat, re.Pattern) or callable(repl) or (not case) or flags or (isinstance(repl, str) and '\\g<' in repl):
            raise NotImplementedError('replace is not supported with a re.Pattern, callable repl, case=False, flags!=0, or when the replacement string contains named group references (\\g<...>)')
        func = pc.replace_substring_regex if regex else pc.replace_substring
        pa_max_replacements = None if n < 0 else n
        result = func(self._pa_array, pattern=pat, replacement=repl, max_replacements=pa_max_replacements)
        return self._from_pyarrow_array(result)

    def _str_capitalize(self) -> Self:
        return self._from_pyarrow_array(pc.utf8_capitalize(self._pa_array))

    def _str_title(self) -> Self:
        return self._from_pyarrow_array(pc.utf8_title(self._pa_array))

    def _str_swapcase(self) -> Self:
        return self._from_pyarrow_array(pc.utf8_swapcase(self._pa_array))

    def _str_removeprefix(self, prefix: str):
        if prefix == '':
            return self._from_pyarrow_array(self._pa_array)
        starts_with = pc.starts_with(self._pa_array, pattern=prefix)
        removed = pc.utf8_slice_codeunits(self._pa_array, len(prefix))
        result = pc.if_else(starts_with, removed, self._pa_array)
        return self._from_pyarrow_array(result)

    def _str_removesuffix(self, suffix: str):
        if suffix == '':
            return self._from_pyarrow_array(self._pa_array)
        ends_with = pc.ends_with(self._pa_array, pattern=suffix)
        removed = pc.utf8_slice_codeunits(self._pa_array, 0, stop=-len(suffix))
        result = pc.if_else(ends_with, removed, self._pa_array)
        return self._from_pyarrow_array(result)

    def _str_startswith(self, pat: str | tuple[str, ...], na: Scalar | lib.NoDefault=lib.no_default):
        if isinstance(pat, str):
            result = pc.starts_with(self._pa_array, pattern=pat)
        elif len(pat) == 0:
            result = pc.if_else(pc.is_null(self._pa_array), None, False)
        else:
            result = pc.starts_with(self._pa_array, pattern=pat[0])
            for p in pat[1:]:
                result = pc.or_(result, pc.starts_with(self._pa_array, pattern=p))
        return self._convert_bool_result(result, na=na, method_name='startswith')

    def _str_endswith(self, pat: str | tuple[str, ...], na: Scalar | lib.NoDefault=lib.no_default):
        if isinstance(pat, str):
            result = pc.ends_with(self._pa_array, pattern=pat)
        elif len(pat) == 0:
            result = pc.if_else(pc.is_null(self._pa_array), None, False)
        else:
            result = pc.ends_with(self._pa_array, pattern=pat[0])
            for p in pat[1:]:
                result = pc.or_(result, pc.ends_with(self._pa_array, pattern=p))
        return self._convert_bool_result(result, na=na, method_name='endswith')

    def _str_isalnum(self):
        result = pc.utf8_is_alnum(self._pa_array)
        return self._convert_bool_result(result)

    def _str_isalpha(self):
        result = pc.utf8_is_alpha(self._pa_array)
        return self._convert_bool_result(result)

    def _str_isascii(self):
        result = pc.string_is_ascii(self._pa_array)
        return self._convert_bool_result(result)

    def _str_isdecimal(self):
        result = pc.utf8_is_decimal(self._pa_array)
        return self._convert_bool_result(result)

    def _str_isdigit(self):
        if pa_version_under21p0:
            res_list = self._apply_elementwise(str.isdigit)
            return self._convert_bool_result(pa.chunked_array(res_list, type=pa.bool_()))
        result = pc.utf8_is_digit(self._pa_array)
        return self._convert_bool_result(result)

    def _str_islower(self):
        result = pc.utf8_is_lower(self._pa_array)
        return self._convert_bool_result(result)

    def _str_isnumeric(self):
        result = pc.utf8_is_numeric(self._pa_array)
        return self._convert_bool_result(result)

    def _str_isspace(self):
        result = pc.utf8_is_space(self._pa_array)
        return self._convert_bool_result(result)

    def _str_istitle(self):
        result = pc.utf8_is_title(self._pa_array)
        return self._convert_bool_result(result)

    def _str_isupper(self):
        result = pc.utf8_is_upper(self._pa_array)
        return self._convert_bool_result(result)

    def _str_contains(self, pat, case: bool=True, flags: int=0, na: Scalar | lib.NoDefault=lib.no_default, regex: bool=True):
        if flags:
            raise NotImplementedError(f'contains not implemented with flags={flags!r}')
        if regex:
            pa_contains = pc.match_substring_regex
        else:
            pa_contains = pc.match_substring
        result = pa_contains(self._pa_array, pat, ignore_case=not case)
        return self._convert_bool_result(result, na=na, method_name='contains')

    def _str_match(self, pat: str, case: bool=True, flags: int=0, na: Scalar | lib.NoDefault=lib.no_default):
        if not pat.startswith('^'):
            pat = f'^({pat})'
        return ArrowStringArrayMixin._str_contains(self, pat, case, flags, na, regex=True)

    def _str_fullmatch(self, pat: str, case: bool=True, flags: int=0, na: Scalar | lib.NoDefault=lib.no_default):
        if (not pat.endswith('$') or pat.endswith('\\$')) and (not pat.startswith('^')):
            pat = f'^({pat})$'
        elif not pat.endswith('$') or pat.endswith('\\$'):
            pat = f'^({pat[1:]})$'
        elif not pat.startswith('^'):
            pat = f'^({pat[0:-1]})$'
        return ArrowStringArrayMixin._str_match(self, pat, case, flags, na)

    def _str_find(self, sub: str, start: int=0, end: int | None=None):
        if (start == 0 or start is None) and end is None:
            result = pc.find_substring(self._pa_array, sub)
        else:
            if sub == '':
                res_list = self._apply_elementwise(lambda val: val.find(sub, start, end))
                return self._convert_int_result(pa.chunked_array(res_list))
            if start is None:
                start_offset = 0
                start = 0
            elif start < 0:
                start_offset = pc.add(start, pc.utf8_length(self._pa_array))
                start_offset = pc.if_else(pc.less(start_offset, 0), 0, start_offset)
            else:
                start_offset = start
            slices = pc.utf8_slice_codeunits(self._pa_array, start, stop=end)
            result = pc.find_substring(slices, sub)
            found = pc.not_equal(result, pa.scalar(-1, type=result.type))
            offset_result = pc.add(result, start_offset)
            result = pc.if_else(found, offset_result, -1)
        return self._convert_int_result(result)

from __future__ import annotations
import operator
from typing import Any
import numpy as np
from pandas._libs import lib
from pandas._libs.ops_dispatch import maybe_dispatch_ufunc_to_dunder_op
from pandas.core.dtypes.cast import maybe_unbox_numpy_scalar
from pandas.core.dtypes.generic import ABCNDFrame
