        else:
            raise TypeError(f'Invalid type for url.  Expected str or httpx.URL, got {type(url)}: {url!r}')

    @property
    def scheme(self) -> str:
        return self._uri_reference.scheme

    @property
    def raw_scheme(self) -> bytes:
        return self._uri_reference.scheme.encode('ascii')

    @property
    def userinfo(self) -> bytes:
        return self._uri_reference.userinfo.encode('ascii')

    @property
    def username(self) -> str:
        userinfo = self._uri_reference.userinfo
        return unquote(userinfo.partition(':')[0])

    @property
    def password(self) -> str:
        userinfo = self._uri_reference.userinfo
        return unquote(userinfo.partition(':')[2])

    @property
    def host(self) -> str:
        host: str = self._uri_reference.host
        if host.startswith('xn--'):
            host = idna.decode(host)
        return host

    @property
    def raw_host(self) -> bytes:
        return self._uri_reference.host.encode('ascii')

    @property
    def port(self) -> int | None:
        return self._uri_reference.port

    @property
    def netloc(self) -> bytes:
        return self._uri_reference.netloc.encode('ascii')

    @property
    def path(self) -> str:
        path = self._uri_reference.path or '/'
        return unquote(path)

    @property
    def query(self) -> bytes:
        query = self._uri_reference.query or ''
        return query.encode('ascii')

    @property
    def params(self) -> QueryParams:
        return QueryParams(self._uri_reference.query)

    @property
    def raw_path(self) -> bytes:
        path = self._uri_reference.path or '/'
        if self._uri_reference.query is not None:
            path += '?' + self._uri_reference.query
        return path.encode('ascii')

    @property
    def fragment(self) -> str:
        return unquote(self._uri_reference.fragment or '')

    @property
    def is_absolute_url(self) -> bool:
        return bool(self._uri_reference.scheme and self._uri_reference.host)

    @property
    def is_relative_url(self) -> bool:
        return not self.is_absolute_url

    def copy_with(self, **kwargs: typing.Any) -> URL:
        return URL(self, **kwargs)

    def copy_set_param(self, key: str, value: typing.Any=None) -> URL:
        return self.copy_with(params=self.params.set(key, value))

    def copy_add_param(self, key: str, value: typing.Any=None) -> URL:
        return self.copy_with(params=self.params.add(key, value))

    def copy_remove_param(self, key: str) -> URL:
        return self.copy_with(params=self.params.remove(key))

    def copy_merge_params(self, params: QueryParamTypes) -> URL:
        return self.copy_with(params=self.params.merge(params))

    def join(self, url: URL | str) -> URL:
