from .constant import ENCODING_MARKS, IANA_SUPPORTED_SIMILAR, RE_POSSIBLE_ENCODING_INDICATION, UNICODE_RANGES_COMBINED, UNICODE_SECONDARY_RANGE_KEYWORD, UTF8_MAXIMAL_ALLOCATION, COMMON_CJK_CHARACTERS, _LATIN, _CJK, _HANGUL, _KATAKANA, _HIRAGANA, _THAI, _ARABIC, _ARABIC_ISOLATED_FORM, _ACCENT_KEYWORDS, _ACCENTUATED

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def _character_flags(character: str) -> int:
    try:
        desc: str = unicodedata.name(character)
    except ValueError:
        return 0
    flags: int = 0
    if 'LATIN' in desc:
        flags |= _LATIN
    if 'CJK' in desc:
        flags |= _CJK
    if 'HANGUL' in desc:
        flags |= _HANGUL
    if 'KATAKANA' in desc:
        flags |= _KATAKANA
    if 'HIRAGANA' in desc:
        flags |= _HIRAGANA
    if 'THAI' in desc:
        flags |= _THAI
    if 'ARABIC' in desc:
        flags |= _ARABIC
        if 'ISOLATED FORM' in desc:
            flags |= _ARABIC_ISOLATED_FORM
    for kw in _ACCENT_KEYWORDS:
        if kw in desc:
            flags |= _ACCENTUATED
            break
    return flags

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_accentuated(character: str) -> bool:
    return bool(_character_flags(character) & _ACCENTUATED)

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def remove_accent(character: str) -> str:
    decomposed: str = unicodedata.decomposition(character)
    if not decomposed:
        return character
    codes: list[str] = decomposed.split(' ')
    return chr(int(codes[0], 16))
_UNICODE_RANGES_SORTED: list[tuple[int, int, str]] = sorted(((ord_range.start, ord_range.stop, name) for name, ord_range in UNICODE_RANGES_COMBINED.items()))
_UNICODE_RANGE_STARTS: list[int] = [e[0] for e in _UNICODE_RANGES_SORTED]

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def unicode_range(character: str) -> str | None:
    character_ord: int = ord(character)
    idx = bisect_right(_UNICODE_RANGE_STARTS, character_ord) - 1
    if idx >= 0:
        start, stop, name = _UNICODE_RANGES_SORTED[idx]
        if character_ord < stop:
            return name
    return None

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_latin(character: str) -> bool:
    return bool(_character_flags(character) & _LATIN)

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_punctuation(character: str) -> bool:
    character_category: str = unicodedata.category(character)
    if 'P' in character_category:
        return True
    character_range: str | None = unicode_range(character)
    if character_range is None:
        return False
    return 'Punctuation' in character_range

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_symbol(character: str) -> bool:
    character_category: str = unicodedata.category(character)
    if 'S' in character_category or 'N' in character_category:
        return True
    character_range: str | None = unicode_range(character)
    if character_range is None:
        return False
    return 'Forms' in character_range and character_category != 'Lo'

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_emoticon(character: str) -> bool:
    character_range: str | None = unicode_range(character)
    if character_range is None:
        return False
    return 'Emoticons' in character_range or 'Pictographs' in character_range

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_separator(character: str) -> bool:
    if character.isspace() or character in {'｜', '+', '<', '>'}:
