@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_cjk_uncommon(character: str) -> bool:
    return character not in COMMON_CJK_CHARACTERS

@lru_cache(maxsize=len(UNICODE_RANGES_COMBINED))
def is_unicode_range_secondary(range_name: str) -> bool:
    return any((keyword in range_name for keyword in UNICODE_SECONDARY_RANGE_KEYWORD))

@lru_cache(maxsize=UTF8_MAXIMAL_ALLOCATION)
def is_unprintable(character: str) -> bool:
    return character.isspace() is False and character.isprintable() is False and (character != '\x1a') and (character != '\ufeff')

def any_specified_encoding(sequence: bytes | bytearray, search_zone: int=8192) -> str | None:
    if not isinstance(sequence, (bytes, bytearray)):
        raise TypeError
    seq_len: int = len(sequence)
    results: list[str] = findall(RE_POSSIBLE_ENCODING_INDICATION, sequence[:min(seq_len, search_zone)].decode('ascii', errors='ignore'))
    if len(results) == 0:
        return None
    for specified_encoding in results:
        specified_encoding = specified_encoding.lower().replace('-', '_')
        encoding_alias: str
        encoding_iana: str
        for encoding_alias, encoding_iana in aliases.items():
            if encoding_alias == specified_encoding:
                return encoding_iana
            if encoding_iana == specified_encoding:
                return encoding_iana
    return None

@lru_cache(maxsize=128)
def is_multi_byte_encoding(name: str) -> bool:
    return name in {'utf_8', 'utf_8_sig', 'utf_16', 'utf_16_be', 'utf_16_le', 'utf_32', 'utf_32_le', 'utf_32_be', 'utf_7'} or issubclass(importlib.import_module(f'encodings.{name}').IncrementalDecoder, MultibyteIncrementalDecoder)

def identify_sig_or_bom(sequence: bytes | bytearray) -> tuple[str | None, bytes]:
    for iana_encoding in ENCODING_MARKS:
        marks: bytes | list[bytes] = ENCODING_MARKS[iana_encoding]
        if isinstance(marks, bytes):
            marks = [marks]
        for mark in marks:
            if sequence.startswith(mark):
                return (iana_encoding, mark)
    return (None, b'')

def should_strip_sig_or_bom(iana_encoding: str) -> bool:
    return iana_encoding not in {'utf_16', 'utf_32'}

def iana_name(cp_name: str, strict: bool=True) -> str:
    cp_name = cp_name.lower().replace('-', '_')
    encoding_alias: str
    encoding_iana: str
    for encoding_alias, encoding_iana in aliases.items():
        if cp_name in [encoding_alias, encoding_iana]:
            return encoding_iana
    if strict:
        raise ValueError(f"Unable to retrieve IANA for '{cp_name}'")
    return cp_name

def cp_similarity(iana_name_a: str, iana_name_b: str) -> float:
    if is_multi_byte_encoding(iana_name_a) or is_multi_byte_encoding(iana_name_b):
        return 0.0
    decoder_a = importlib.import_module(f'encodings.{iana_name_a}').IncrementalDecoder
    decoder_b = importlib.import_module(f'encodings.{iana_name_b}').IncrementalDecoder
    id_a: IncrementalDecoder = decoder_a(errors='ignore')
    id_b: IncrementalDecoder = decoder_b(errors='ignore')
    character_match_count: int = 0
    for i in range(256):
        to_be_decoded: bytes = bytes([i])
        if id_a.decode(to_be_decoded) == id_b.decode(to_be_decoded):
            character_match_count += 1
    return character_match_count / 256

def is_cp_similar(iana_name_a: str, iana_name_b: str) -> bool:
    return iana_name_a in IANA_SUPPORTED_SIMILAR and iana_name_b in IANA_SUPPORTED_SIMILAR[iana_name_a]

def set_logging_handler(name: str='charset_normalizer', level: int=logging.INFO, format_string: str='%(asctime)s | %(levelname)s | %(message)s') -> None:
    logger = logging.getLogger(name)
    logger.setLevel(level)
    handler = logging.StreamHandler()
    handler.setFormatter(logging.Formatter(format_string))
    logger.addHandler(handler)

def cut_sequence_chunks(sequences: bytes | bytearray, encoding_iana: str, offsets: range, chunk_size: int, bom_or_sig_available: bool, strip_sig_or_bom: bool, sig_payload: bytes, is_multi_byte_decoder: bool, decoded_payload: str | None=None) -> Generator[str, None, None]:
    if decoded_payload and is_multi_byte_decoder is False:
        for i in offsets:
            chunk = decoded_payload[i:i + chunk_size]
            if not chunk:
                break
            yield chunk
    else:
        for i in offsets:
            chunk_end = i + chunk_size
            if chunk_end > len(sequences) + 8:
                continue
            cut_sequence = sequences[i:i + chunk_size]
            if bom_or_sig_available and strip_sig_or_bom is False:
                cut_sequence = sig_payload + cut_sequence
            chunk = cut_sequence.decode(encoding_iana, errors='ignore' if is_multi_byte_decoder else 'strict')
            if is_multi_byte_decoder and i > 0:
                chunk_partial_size_chk: int = min(chunk_size, 16)
                if decoded_payload and chunk[:chunk_partial_size_chk] not in decoded_payload:
                    for j in range(i, i - 4, -1):
                        cut_sequence = sequences[j:chunk_end]
                        if bom_or_sig_available and strip_sig_or_bom is False:
                            cut_sequence = sig_payload + cut_sequence
                        chunk = cut_sequence.decode(encoding_iana, errors='ignore')
                        if chunk[:chunk_partial_size_chk] in decoded_payload:
                            break
            yield chunk

from __future__ import annotations
import importlib
from codecs import IncrementalDecoder
from collections import Counter
from functools import lru_cache
from typing import Counter as TypeCounter
from .constant import FREQUENCIES, KO_NAMES, LANGUAGE_SUPPORTED_COUNT, TOO_SMALL_SEQUENCE, ZH_NAMES, _FREQUENCIES_SET, _FREQUENCIES_RANK
from .md import is_suspiciously_successive_range
from .models import CoherenceMatches
from .utils import is_accentuated, is_latin, is_multi_byte_encoding, is_unicode_range_secondary, unicode_range

def encoding_unicode_range(iana_name: str) -> list[str]:
    if is_multi_byte_encoding(iana_name):
        raise OSError('Function not supported on multi-byte code page')
    decoder = importlib.import_module(f'encodings.{iana_name}').IncrementalDecoder
    p: IncrementalDecoder = decoder(errors='ignore')
    seen_ranges: dict[str, int] = {}
    character_count: int = 0
    for i in range(64, 255):
        chunk: str = p.decode(bytes([i]))
        if chunk:
            character_range: str | None = unicode_range(chunk)
            if character_range is None:
                continue
            if is_unicode_range_secondary(character_range) is False:
                if character_range not in seen_ranges:
                    seen_ranges[character_range] = 0
                seen_ranges[character_range] += 1
                character_count += 1
    return sorted([character_range for character_range in seen_ranges if seen_ranges[character_range] / character_count >= 0.15])

def unicode_range_languages(primary_range: str) -> list[str]:
    languages: list[str] = []
    for language, characters in FREQUENCIES.items():
        for character in characters:
            if unicode_range(character) == primary_range:
                languages.append(language)
                break
    return languages

@lru_cache()
def encoding_languages(iana_name: str) -> list[str]:
    unicode_ranges: list[str] = encoding_unicode_range(iana_name)
    primary_range: str | None = None
    for specified_range in unicode_ranges:
        if 'Latin' not in specified_range:
            primary_range = specified_range
            break
    if primary_range is None:
        return ['Latin Based']
    return unicode_range_languages(primary_range)

@lru_cache()
def mb_encoding_languages(iana_name: str) -> list[str]:
    if iana_name.startswith('shift_') or iana_name.startswith('iso2022_jp') or iana_name.startswith('euc_j') or (iana_name == 'cp932'):
        return ['Japanese']
    if iana_name.startswith('gb') or iana_name in ZH_NAMES:
        return ['Chinese']
    if iana_name.startswith('iso2022_kr') or iana_name in KO_NAMES:
        return ['Korean']
    return []

@lru_cache(maxsize=LANGUAGE_SUPPORTED_COUNT)
def get_target_features(language: str) -> tuple[bool, bool]:
    target_have_accents: bool = False
    target_pure_latin: bool = True
    for character in FREQUENCIES[language]:
        if not target_have_accents and is_accentuated(character):
            target_have_accents = True
        if target_pure_latin and is_latin(character) is False:
            target_pure_latin = False
    return (target_have_accents, target_pure_latin)

def alphabet_languages(characters: list[str], ignore_non_latin: bool=False) -> list[str]:
    languages: list[tuple[str, float]] = []
    characters_set: frozenset[str] = frozenset(characters)
    source_have_accents = any((is_accentuated(character) for character in characters))
    for language, language_characters in FREQUENCIES.items():
        target_have_accents, target_pure_latin = get_target_features(language)
        if ignore_non_latin and target_pure_latin is False:
            continue
        if target_have_accents is False and source_have_accents:
            continue
        character_count: int = len(language_characters)
        character_match_count: int = len(_FREQUENCIES_SET[language] & characters_set)
        ratio: float = character_match_count / character_count
        if ratio >= 0.2:
            languages.append((language, ratio))
    languages = sorted(languages, key=lambda x: x[1], reverse=True)
    return [compatible_language[0] for compatible_language in languages]

def characters_popularity_compare(language: str, ordered_characters: list[str]) -> float:
    if language not in FREQUENCIES:
        raise ValueError(f'{language} not available')
    character_approved_count: int = 0
    frequencies_language_set: frozenset[str] = _FREQUENCIES_SET[language]
    lang_rank: dict[str, int] = _FREQUENCIES_RANK[language]
    ordered_characters_count: int = len(ordered_characters)
    target_language_characters_count: int = len(FREQUENCIES[language])
    large_alphabet: bool = target_language_characters_count > 26
    expected_projection_ratio: float = target_language_characters_count / ordered_characters_count
    ordered_rank: dict[str, int] = {char: rank for rank, char in enumerate(ordered_characters)}
    common_chars: list[tuple[int, int]] = [(lr, ordered_rank[c]) for c, lr in lang_rank.items() if c in ordered_rank]
    common_count: int = len(common_chars)
    common_lr: list[int] = [p[0] for p in common_chars]
    common_orr: list[int] = [p[1] for p in common_chars]
    for character, character_rank in zip(ordered_characters, range(0, ordered_characters_count)):
        if character not in frequencies_language_set:
            continue
        character_rank_in_language: int = lang_rank[character]
        character_rank_projection: int = int(character_rank * expected_projection_ratio)
        if large_alphabet is False and abs(character_rank_projection - character_rank_in_language) > 4:
            continue
        if large_alphabet is True and abs(character_rank_projection - character_rank_in_language) < target_language_characters_count / 3:
            character_approved_count += 1
            continue
        before_match_count: int = 0
        after_match_count: int = 0
        for i in range(common_count):
            lr_i: int = common_lr[i]
            orr_i: int = common_orr[i]
            if lr_i < character_rank_in_language:
                if orr_i < character_rank:
                    before_match_count += 1
            elif orr_i >= character_rank:
                after_match_count += 1
        after_len: int = target_language_characters_count - character_rank_in_language
        if character_rank_in_language == 0 and before_match_count <= 4:
            character_approved_count += 1
            continue
        if after_len == 0 and after_match_count <= 4:
            character_approved_count += 1
            continue
        if character_rank_in_language > 0 and before_match_count / character_rank_in_language >= 0.4 or (after_len > 0 and after_match_count / after_len >= 0.4):
            character_approved_count += 1
            continue
    return character_approved_count / len(ordered_characters)

def alpha_unicode_split(decoded_sequence: str) -> list[str]:
    layers: dict[str, list[str]] = {}
    single_layer_key: str | None = None
    multi_layer: bool = False
    prev_character_range: str | None = None
    prev_layer_target: str | None = None
    for character in decoded_sequence:
        if character.isalpha() is False:
            continue
        character_ord: int = ord(character)
        if character_ord < 128:
            character_range: str | None = 'Basic Latin'
        else:
            character_range = unicode_range(character)
        if character_range is None:
            continue
        if character_range == prev_character_range:
            if prev_layer_target is not None:
                layers[prev_layer_target].append(character)
            continue
        layer_target_range: str | None = None
        if multi_layer:
            for discovered_range in layers:
                if is_suspiciously_successive_range(discovered_range, character_range) is False:
                    layer_target_range = discovered_range
                    break
        elif single_layer_key is not None:
            if is_suspiciously_successive_range(single_layer_key, character_range) is False:
                layer_target_range = single_layer_key
        if layer_target_range is None:
            layer_target_range = character_range
        if layer_target_range not in layers:
            layers[layer_target_range] = []
            if single_layer_key is None:
                single_layer_key = layer_target_range
            else:
                multi_layer = True
        layers[layer_target_range].append(character)
        prev_character_range = character_range
        prev_layer_target = layer_target_range
    return [''.join(chars).lower() for chars in layers.values()]

def merge_coherence_ratios(results: list[CoherenceMatches]) -> CoherenceMatches:
    per_language_ratios: dict[str, list[float]] = {}
    for result in results:
        for sub_result in result:
            language, ratio = sub_result
            if language not in per_language_ratios:
                per_language_ratios[language] = [ratio]
                continue
            per_language_ratios[language].append(ratio)
    merge = [(language, round(sum(per_language_ratios[language]) / len(per_language_ratios[language]), 4)) for language in per_language_ratios]
    return sorted(merge, key=lambda x: x[1], reverse=True)

def filter_alt_coherence_matches(results: CoherenceMatches) -> CoherenceMatches:
    index_results: dict[str, list[float]] = dict()
    for result in results:
        language, ratio = result
        no_em_name: str = language.replace('—', '')
        if no_em_name not in index_results:
            index_results[no_em_name] = []
        index_results[no_em_name].append(ratio)
    if any((len(index_results[e]) > 1 for e in index_results)):
        filtered_results: CoherenceMatches = []
        for language in index_results:
            filtered_results.append((language, max(index_results[language])))
        return filtered_results
    return results

@lru_cache(maxsize=2048)
def coherence_ratio(decoded_sequence: str, threshold: float=0.1, lg_inclusion: str | None=None) -> CoherenceMatches:
    results: list[tuple[str, float]] = []
    ignore_non_latin: bool = False
    sufficient_match_count: int = 0
    lg_inclusion_list = lg_inclusion.split(',') if lg_inclusion is not None else []
    if 'Latin Based' in lg_inclusion_list:
        ignore_non_latin = True
        lg_inclusion_list.remove('Latin Based')
    for layer in alpha_unicode_split(decoded_sequence):
        sequence_frequencies: TypeCounter[str] = Counter(layer)
        most_common = sequence_frequencies.most_common()
        character_count: int = len(layer)
        if character_count <= TOO_SMALL_SEQUENCE:
            continue
        popular_character_ordered: list[str] = [c for c, o in most_common]
        for language in lg_inclusion_list or alphabet_languages(popular_character_ordered, ignore_non_latin):
            ratio: float = characters_popularity_compare(language, popular_character_ordered)
            if ratio < threshold:
                continue
            elif ratio >= 0.8:
                sufficient_match_count += 1
            results.append((language, round(ratio, 4)))
            if sufficient_match_count >= 3:
                break
    return sorted(filter_alt_coherence_matches(results), key=lambda x: x[1], reverse=True)

from __future__ import annotations
import inspect
import typing as t
from functools import update_wrapper
from gettext import gettext as _
from .core import Argument
from .core import Command
from .core import Context
from .core import Group
from .core import Option
from .core import Parameter
from .globals import get_current_context
from .utils import echo
if t.TYPE_CHECKING:
    import typing_extensions as te
    P = te.ParamSpec('P')
R = t.TypeVar('R')
T = t.TypeVar('T')
_AnyCallable = t.Callable[..., t.Any]
FC = t.TypeVar('FC', bound='_AnyCallable | Command')

def pass_context(f: t.Callable[te.Concatenate[Context, P], R]) -> t.Callable[P, R]:

    def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
        return f(get_current_context(), *args, **kwargs)
    return update_wrapper(new_func, f)

def pass_obj(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:

    def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
        return f(get_current_context().obj, *args, **kwargs)
    return update_wrapper(new_func, f)

def make_pass_decorator(object_type: type[T], ensure: bool=False) -> t.Callable[[t.Callable[te.Concatenate[T, P], R]], t.Callable[P, R]]:

    def decorator(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:

        def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
            ctx = get_current_context()
            obj: T | None
            if ensure:
                obj = ctx.ensure_object(object_type)
            else:
                obj = ctx.find_object(object_type)
            if obj is None:
                raise RuntimeError(f'Managed to invoke callback without a context object of type {object_type.__name__!r} existing.')
            return ctx.invoke(f, obj, *args, **kwargs)
        return update_wrapper(new_func, f)
    return decorator

def pass_meta_key(key: str, *, doc_description: str | None=None) -> t.Callable[[t.Callable[te.Concatenate[T, P], R]], t.Callable[P, R]]:

    def decorator(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:

        def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
            ctx = get_current_context()
            obj = ctx.meta[key]
            return ctx.invoke(f, obj, *args, **kwargs)
        return update_wrapper(new_func, f)
    if doc_description is None:
        doc_description = f'the {key!r} key from :attr:`click.Context.meta`'
    decorator.__doc__ = f'Decorator that passes {doc_description} as the first argument to the decorated function.'
    return decorator
CmdType = t.TypeVar('CmdType', bound=Command)

@t.overload
def command(name: _AnyCallable) -> Command:
    ...

@t.overload
def command(name: str | None, cls: type[CmdType], **attrs: t.Any) -> t.Callable[[_AnyCallable], CmdType]:
    ...

@t.overload
def command(name: None=None, *, cls: type[CmdType], **attrs: t.Any) -> t.Callable[[_AnyCallable], CmdType]:
    ...

@t.overload
def command(name: str | None=..., cls: None=None, **attrs: t.Any) -> t.Callable[[_AnyCallable], Command]:
    ...

def command(name: str | _AnyCallable | None=None, cls: type[CmdType] | None=None, **attrs: t.Any) -> Command | t.Callable[[_AnyCallable], Command | CmdType]:
    func: t.Callable[[_AnyCallable], t.Any] | None = None
    if callable(name):
        func = name
        name = None
        assert cls is None, "Use 'command(cls=cls)(callable)' to specify a class."
        assert not attrs, "Use 'command(**kwargs)(callable)' to provide arguments."
    if cls is None:
        cls = t.cast('type[CmdType]', Command)

    def decorator(f: _AnyCallable) -> CmdType:
        if isinstance(f, Command):
            raise TypeError('Attempted to convert a callback into a command twice.')
        attr_params = attrs.pop('params', None)
        params = attr_params if attr_params is not None else []
        try:
            decorator_params = f.__click_params__
        except AttributeError:
            pass
        else:
            del f.__click_params__
            params.extend(reversed(decorator_params))
        if attrs.get('help') is None:
            attrs['help'] = f.__doc__
        if t.TYPE_CHECKING:
            assert cls is not None
            assert not callable(name)
        if name is not None:
            cmd_name = name
        else:
            cmd_name = f.__name__.lower().replace('_', '-')
            cmd_left, sep, suffix = cmd_name.rpartition('-')
            if sep and suffix in {'command', 'cmd', 'group', 'grp'}:
                cmd_name = cmd_left
        cmd = cls(name=cmd_name, callback=f, params=params, **attrs)
        cmd.__doc__ = f.__doc__
        return cmd
    if func is not None:
        return decorator(func)
    return decorator
GrpType = t.TypeVar('GrpType', bound=Group)

@t.overload
def group(name: _AnyCallable) -> Group:
    ...

@t.overload
def group(name: str | None, cls: type[GrpType], **attrs: t.Any) -> t.Callable[[_AnyCallable], GrpType]:
    ...

@t.overload
def group(name: None=None, *, cls: type[GrpType], **attrs: t.Any) -> t.Callable[[_AnyCallable], GrpType]:
    ...

@t.overload
def group(name: str | None=..., cls: None=None, **attrs: t.Any) -> t.Callable[[_AnyCallable], Group]:
    ...

def group(name: str | _AnyCallable | None=None, cls: type[GrpType] | None=None, **attrs: t.Any) -> Group | t.Callable[[_AnyCallable], Group | GrpType]:
    if cls is None:
        cls = t.cast('type[GrpType]', Group)
    if callable(name):
        return command(cls=cls, **attrs)(name)
    return command(name, cls, **attrs)

def _param_memo(f: t.Callable[..., t.Any], param: Parameter) -> None:
    if isinstance(f, Command):
        f.params.append(param)
    else:
        if not hasattr(f, '__click_params__'):
            f.__click_params__ = []
        f.__click_params__.append(param)

def argument(*param_decls: str, cls: type[Argument] | None=None, **attrs: t.Any) -> t.Callable[[FC], FC]:
    if cls is None:
        cls = Argument

    def decorator(f: FC) -> FC:
        _param_memo(f, cls(param_decls, **attrs))
        return f
    return decorator

def option(*param_decls: str, cls: type[Option] | None=None, **attrs: t.Any) -> t.Callable[[FC], FC]:
    if cls is None:
        cls = Option

    def decorator(f: FC) -> FC:
        _param_memo(f, cls(param_decls, **attrs))
        return f
    return decorator

def confirmation_option(*param_decls: str, **kwargs: t.Any) -> t.Callable[[FC], FC]:

    def callback(ctx: Context, param: Parameter, value: bool) -> None:
        if not value:
            ctx.abort()
    if not param_decls:
        param_decls = ('--yes',)
    kwargs.setdefault('is_flag', True)
    kwargs.setdefault('callback', callback)
    kwargs.setdefault('expose_value', False)
    kwargs.setdefault('prompt', 'Do you want to continue?')
    kwargs.setdefault('help', 'Confirm the action without prompting.')
    return option(*param_decls, **kwargs)

def password_option(*param_decls: str, **kwargs: t.Any) -> t.Callable[[FC], FC]:
    if not param_decls:
        param_decls = ('--password',)
    kwargs.setdefault('prompt', True)
    kwargs.setdefault('confirmation_prompt', True)
    kwargs.setdefault('hide_input', True)
    return option(*param_decls, **kwargs)

def version_option(version: str | None=None, *param_decls: str, package_name: str | None=None, prog_name: str | None=None, message: str | None=None, **kwargs: t.Any) -> t.Callable[[FC], FC]:
    if message is None:
        message = _('%(prog)s, version %(version)s')
    if version is None and package_name is None:
        frame = inspect.currentframe()
        f_back = frame.f_back if frame is not None else None
        f_globals = f_back.f_globals if f_back is not None else None
        del frame
        if f_globals is not None:
            package_name = f_globals.get('__name__')
            if package_name == '__main__':
                package_name = f_globals.get('__package__')
            if package_name:
                package_name = package_name.partition('.')[0]

    def callback(ctx: Context, param: Parameter, value: bool) -> None:
        if not value or ctx.resilient_parsing:
            return
        nonlocal prog_name
        nonlocal version
        if prog_name is None:
            prog_name = ctx.find_root().info_name
        if version is None and package_name is not None:
            import importlib.metadata
            try:
                version = importlib.metadata.version(package_name)
            except importlib.metadata.PackageNotFoundError:
                raise RuntimeError(f"{package_name!r} is not installed. Try passing 'package_name' instead.") from None
        if version is None:
            raise RuntimeError(f'Could not determine the version for {package_name!r} automatically.')
        echo(message % {'prog': prog_name, 'package': package_name, 'version': version}, color=ctx.color)
        ctx.exit()
    if not param_decls:
        param_decls = ('--version',)
    kwargs.setdefault('is_flag', True)
    kwargs.setdefault('expose_value', False)
    kwargs.setdefault('is_eager', True)
    kwargs.setdefault('help', _('Show the version and exit.'))
    kwargs['callback'] = callback
    return option(*param_decls, **kwargs)

def help_option(*param_decls: str, **kwargs: t.Any) -> t.Callable[[FC], FC]:

    def show_help(ctx: Context, param: Parameter, value: bool) -> None:
        if value and (not ctx.resilient_parsing):
            echo(ctx.get_help(), color=ctx.color)
            ctx.exit()
    if not param_decls:
        param_decls = ('--help',)
    kwargs.setdefault('is_flag', True)
    kwargs.setdefault('expose_value', False)
    kwargs.setdefault('is_eager', True)
    kwargs.setdefault('help', _('Show this message and exit.'))
    kwargs.setdefault('callback', show_help)
    return option(*param_decls, **kwargs)

from __future__ import annotations
import itertools
from typing import TYPE_CHECKING, cast
import numpy as np
from pandas._libs import algos, hashtable, lib
from pandas._libs.hashtable import unique_label_indices
from pandas.core.dtypes.common import ensure_int64, ensure_platform_int
from pandas.core.dtypes.generic import ABCMultiIndex, ABCRangeIndex
from pandas.core.dtypes.missing import isna
from pandas.core.construction import extract_array
if TYPE_CHECKING:
    from collections.abc import Callable, Hashable, Sequence
    from pandas._typing import ArrayLike, AxisInt, IndexKeyFunc, Level, NaPosition, Shape, SortKind, npt
    from pandas import MultiIndex, Series
    from pandas.core.arrays import ExtensionArray
    from pandas.core.indexes.base import Index

def get_indexer_indexer(target: Index, level: Level | list[Level] | None, ascending: list[bool] | bool, kind: SortKind, na_position: NaPosition, sort_remaining: bool, key: IndexKeyFunc) -> npt.NDArray[np.intp] | None:
    target = ensure_key_mapped(target, key, levels=level)
    target = target._sort_levels_monotonic()
    if level is not None:
        _, indexer = target.sortlevel(level, ascending=ascending, sort_remaining=sort_remaining, na_position=na_position)
    elif np.all(ascending) and target.is_monotonic_increasing or (not np.any(ascending) and target.is_monotonic_decreasing):
        return None
    elif isinstance(target, ABCMultiIndex):
        codes = [lev.codes for lev in target._get_codes_for_sorting()]
        indexer = lexsort_indexer(codes, orders=ascending, na_position=na_position, codes_given=True)
    else:
        indexer = nargsort(target, kind=kind, ascending=cast(bool, ascending), na_position=na_position)
    return indexer

def get_group_index(labels, shape: Shape, sort: bool, xnull: bool) -> npt.NDArray[np.int64]:

    def _int64_cut_off(shape) -> int:
        acc = 1
        for i, mul in enumerate(shape):
            acc *= int(mul)
            if not acc < lib.i8max:
                return i
        return len(shape)

    def maybe_lift(lab, size: int) -> tuple[np.ndarray, int]:
        return (lab + 1, size + 1) if (lab == -1).any() else (lab, size)
    labels = [ensure_int64(x) for x in labels]
    lshape = list(shape)
    if not xnull:
        for i, (lab, size) in enumerate(zip(labels, shape, strict=True)):
            labels[i], lshape[i] = maybe_lift(lab, size)
    while True:
        nlev = _int64_cut_off(lshape)
        stride = np.prod(lshape[1:nlev], dtype='i8')
        out = stride * labels[0].astype('i8', subok=False, copy=False)
        for i in range(1, nlev):
            if lshape[i] == 0:
                stride = np.int64(0)
            else:
                stride //= lshape[i]
            out += labels[i] * stride
        if xnull:
            mask = labels[0] == -1
            for lab in labels[1:nlev]:
                mask |= lab == -1
            out[mask] = -1
        if nlev == len(lshape):
            break
        comp_ids, obs_ids = compress_group_index(out, sort=sort)
        labels = [comp_ids, *labels[nlev:]]
        lshape = [len(obs_ids), *lshape[nlev:]]
    return out

def get_compressed_ids(labels, sizes: Shape) -> tuple[npt.NDArray[np.intp], npt.NDArray[np.int64]]:
    ids = get_group_index(labels, sizes, sort=True, xnull=False)
    return compress_group_index(ids, sort=True)

def is_int64_overflow_possible(shape: Shape) -> bool:
    the_prod = 1
    for x in shape:
        the_prod *= int(x)
    return the_prod >= lib.i8max

def _decons_group_index(comp_labels: npt.NDArray[np.intp], shape: Shape) -> list[npt.NDArray[np.intp]]:
    if is_int64_overflow_possible(shape):
        raise ValueError('cannot deconstruct factorized group indices!')
    label_list = []
    factor = 1
    y = np.array(0)
    x = comp_labels
    for i in reversed(range(len(shape))):
        labels = (x - y) % (factor * shape[i]) // factor
        np.putmask(labels, comp_labels < 0, -1)
        label_list.append(labels)
        y = labels * factor
        factor *= shape[i]
    return label_list[::-1]

def decons_obs_group_ids(comp_ids: npt.NDArray[np.intp], obs_ids: npt.NDArray[np.intp], shape: Shape, labels: Sequence[npt.NDArray[np.signedinteger]], xnull: bool) -> list[npt.NDArray[np.intp]]:
    if not xnull:
        lift = np.fromiter(((a == -1).any() for a in labels), dtype=np.intp)
        arr_shape = np.asarray(shape, dtype=np.intp) + lift
        shape = tuple(arr_shape)
    if not is_int64_overflow_possible(shape):
        out = _decons_group_index(obs_ids, shape)
        return out if xnull or not lift.any() else [x - y for x, y in zip(out, lift, strict=True)]
    indexer = unique_label_indices(comp_ids)
    return [lab[indexer].astype(np.intp, subok=False, copy=True) for lab in labels]

def lexsort_indexer(keys: Sequence[ArrayLike | Index | Series], orders=None, na_position: str='last', key: Callable | None=None, codes_given: bool=False) -> npt.NDArray[np.intp]:
    from pandas.core.arrays import Categorical
    if na_position not in ['last', 'first']:
        raise ValueError(f'invalid na_position: {na_position}')
    if isinstance(orders, bool):
        orders = itertools.repeat(orders, len(keys))
    elif orders is None:
        orders = itertools.repeat(True, len(keys))
    else:
        orders = reversed(orders)
    labels = []
    for k, order in zip(reversed(keys), orders, strict=True):
        k = ensure_key_mapped(k, key)
        if codes_given:
            codes = cast(np.ndarray, k)
            n = codes.max() + 1 if len(codes) else 0
        else:
            cat = Categorical(k, ordered=True)
            codes = cat.codes
            n = len(cat.categories)
        mask = codes == -1
        if na_position == 'last' and mask.any():
            codes = np.where(mask, n, codes)
        if not order:
            codes = np.where(mask, codes, n - codes - 1)
        labels.append(codes)
    return np.lexsort(labels)

def nargsort(items: ArrayLike | Index | Series, kind: SortKind='quicksort', ascending: bool=True, na_position: str='last', key: Callable | None=None, mask: npt.NDArray[np.bool_] | None=None) -> npt.NDArray[np.intp]:
    if key is not None:
        items = ensure_key_mapped(items, key)
        return nargsort(items, kind=kind, ascending=ascending, na_position=na_position, key=None, mask=mask)
    if isinstance(items, ABCRangeIndex):
        return items.argsort(ascending=ascending)
    elif not isinstance(items, ABCMultiIndex):
        items = extract_array(items)
    else:
        raise TypeError('nargsort does not support MultiIndex. Use index.sort_values instead.')
    if mask is None:
        mask = np.asarray(isna(items))
    if not isinstance(items, np.ndarray):
        return items.argsort(ascending=ascending, kind=kind, na_position=na_position)
    idx = np.arange(len(items))
    non_nans = items[~mask]
    non_nan_idx = idx[~mask]
    nan_idx = np.nonzero(mask)[0]
    if not ascending:
        non_nans = non_nans[::-1]
        non_nan_idx = non_nan_idx[::-1]
    indexer = non_nan_idx[non_nans.argsort(kind=kind)]
    if not ascending:
        indexer = indexer[::-1]
    if na_position == 'last':
        indexer = np.concatenate([indexer, nan_idx])
    elif na_position == 'first':
        indexer = np.concatenate([nan_idx, indexer])
    else:
        raise ValueError(f'invalid na_position: {na_position}')
    return ensure_platform_int(indexer)

def nargminmax(values: ExtensionArray, method: str, axis: AxisInt=0):
    assert method in {'argmax', 'argmin'}
    func = np.argmax if method == 'argmax' else np.argmin
    mask = np.asarray(isna(values))
    arr_values = values._values_for_argsort()
    if arr_values.ndim > 1:
        if mask.any():
            if axis == 1:
                zipped = zip(arr_values, mask, strict=True)
            else:
                zipped = zip(arr_values.T, mask.T, strict=True)
            return np.array([_nanargminmax(v, m, func) for v, m in zipped])
        return func(arr_values, axis=axis)
    return _nanargminmax(arr_values, mask, func)

def _nanargminmax(values: np.ndarray, mask: npt.NDArray[np.bool_], func) -> int:
    idx = np.arange(values.shape[0])
    non_nans = values[~mask]
    non_nan_idx = idx[~mask]
    return non_nan_idx[func(non_nans)]

def _ensure_key_mapped_multiindex(index: MultiIndex, key: Callable, level=None) -> MultiIndex:
    if level is not None:
        if isinstance(level, (str, int)):
            level_iter = [level]
        else:
            level_iter = level
        sort_levels: range | set = {index._get_level_number(lev) for lev in level_iter}
    else:
        sort_levels = range(index.nlevels)
    mapped = [ensure_key_mapped(index._get_level_values(level), key) if level in sort_levels else index._get_level_values(level) for level in range(index.nlevels)]
    return type(index).from_arrays(mapped)

def ensure_key_mapped(values: ArrayLike | Index | Series, key: Callable | None, levels=None) -> ArrayLike | Index | Series:
    from pandas.core.indexes.api import Index
    if not key:
        return values
    if isinstance(values, ABCMultiIndex):
        return _ensure_key_mapped_multiindex(values, key, level=levels)
    result = key(values.copy())
    if len(result) != len(values):
        raise ValueError('User-provided `key` function must not change the shape of the array.')
    try:
        if isinstance(values, Index):
            result = Index(result, tupleize_cols=False)
        else:
            type_of_values = type(values)
            result = type_of_values(result)
    except TypeError as err:
        raise TypeError(f'User-provided `key` function returned an invalid type {type(result)}             which could not be converted to {type(values)}.') from err
    return result

def get_indexer_dict(label_list: list[np.ndarray], keys: list[Index]) -> dict[Hashable, npt.NDArray[np.intp]]:
    shape = tuple((len(x) for x in keys))
    group_index = get_group_index(label_list, shape, sort=True, xnull=True)
    if np.all(group_index == -1):
        return {}
    ngroups = (group_index.size and group_index.max()) + 1 if is_int64_overflow_possible(shape) else np.prod(shape, dtype='i8')
    sorter = get_group_index_sorter(group_index, ngroups)
    sorted_labels = [lab.take(sorter) for lab in label_list]
    group_index = group_index.take(sorter)
    return lib.indices_fast(sorter, group_index, keys, sorted_labels)

def get_group_index_sorter(group_index: npt.NDArray[np.intp], ngroups: int | None=None) -> npt.NDArray[np.intp]:
    if ngroups is None:
        ngroups = 1 + group_index.max()
    count = len(group_index)
    alpha = 0.0
    beta = 1.0
    do_groupsort = count > 0 and alpha + beta * ngroups < count * np.log(count)
    if do_groupsort:
        sorter, _ = algos.groupsort_indexer(ensure_platform_int(group_index), ngroups)
    else:
        sorter = group_index.argsort(kind='mergesort')
    return ensure_platform_int(sorter)

def compress_group_index(group_index: npt.NDArray[np.int64], sort: bool=True) -> tuple[npt.NDArray[np.int64], npt.NDArray[np.int64]]:
    if len(group_index) and np.all(group_index[1:] >= group_index[:-1]):
        unique_mask = np.concatenate([group_index[:1] > -1, group_index[1:] != group_index[:-1]])
        comp_ids = unique_mask.cumsum()
        comp_ids -= 1
        obs_group_ids = group_index[unique_mask]
    else:
        size_hint = len(group_index)
        table = hashtable.Int64HashTable(size_hint)
        group_index = ensure_int64(group_index)
        comp_ids, obs_group_ids = table.get_labels_groupby(group_index)
        if sort and len(obs_group_ids) > 0:
            obs_group_ids, comp_ids = _reorder_by_uniques(obs_group_ids, comp_ids)
    return (ensure_int64(comp_ids), ensure_int64(obs_group_ids))

def _reorder_by_uniques(uniques: npt.NDArray[np.int64], labels: npt.NDArray[np.intp]) -> tuple[npt.NDArray[np.int64], npt.NDArray[np.intp]]:
    sorter = uniques.argsort()
    reverse_indexer = np.empty(len(sorter), dtype=np.intp)
    reverse_indexer.put(sorter, np.arange(len(sorter)))
    mask = labels < 0
    labels = reverse_indexer.take(labels)
    np.putmask(labels, mask, -1)
    uniques = uniques.take(sorter)
    return (uniques, labels)

