class _Deprecate:

    def __init__(self, old_name=None, new_name=None, message=None):
        self.old_name = old_name
        self.new_name = new_name
        self.message = message

    def __call__(self, func, *args, **kwargs):
        old_name = self.old_name
        new_name = self.new_name
        message = self.message
        if old_name is None:
            old_name = func.__name__
        if new_name is None:
            depdoc = f'`{old_name}` is deprecated!'
        else:
            depdoc = f'`{old_name}` is deprecated, use `{new_name}` instead!'
        if message is not None:
            depdoc += '\n' + message

        @functools.wraps(func)
        def newfunc(*args, **kwds):
            warnings.warn(depdoc, DeprecationWarning, stacklevel=2)
            return func(*args, **kwds)
        newfunc.__name__ = old_name
        doc = func.__doc__
        if doc is None:
            doc = depdoc
        else:
            lines = doc.expandtabs().split('\n')
            indent = _get_indent(lines[1:])
            if lines[0].lstrip():
                doc = indent * ' ' + doc
            else:
                skip = len(lines[0]) + 1
                for line in lines[1:]:
                    if len(line) > indent:
                        break
                    skip += len(line) + 1
                doc = doc[skip:]
            depdoc = textwrap.indent(depdoc, ' ' * indent)
            doc = f'{depdoc}\n\n{doc}'
        newfunc.__doc__ = doc
        return newfunc

def _get_indent(lines):
    indent = sys.maxsize
    for line in lines:
        content = len(line.lstrip())
        if content:
            indent = min(indent, len(line) - content)
    if indent == sys.maxsize:
        indent = 0
    return indent

def deprecate(*args, **kwargs):
    warnings.warn('`deprecate` is deprecated, use `warn` with `DeprecationWarning` instead. (deprecated in NumPy 2.0)', DeprecationWarning, stacklevel=2)
    if args:
        fn = args[0]
        args = args[1:]
        return _Deprecate(*args, **kwargs)(fn)
    else:
        return _Deprecate(*args, **kwargs)

def deprecate_with_doc(msg):
    warnings.warn('`deprecate` is deprecated, use `warn` with `DeprecationWarning` instead. (deprecated in NumPy 2.0)', DeprecationWarning, stacklevel=2)
    return _Deprecate(message=msg)

def _split_line(name, arguments, width):
    firstwidth = len(name)
    k = firstwidth
    newstr = name
    sepstr = ', '
    arglist = arguments.split(sepstr)
    for argument in arglist:
        if k == firstwidth:
            addstr = ''
        else:
            addstr = sepstr
        k = k + len(argument) + len(addstr)
        if k > width:
            k = firstwidth + 1 + len(argument)
            newstr = newstr + ',\n' + ' ' * (firstwidth + 2) + argument
        else:
            newstr = newstr + addstr + argument
    return newstr
_namedict = None
_dictlist = None

def _makenamedict(module='numpy'):
    module = __import__(module, globals(), locals(), [])
    thedict = {module.__name__: module.__dict__}
    dictlist = [module.__name__]
    totraverse = [module.__dict__]
    while True:
        if len(totraverse) == 0:
            break
        thisdict = totraverse.pop(0)
        for x in thisdict.keys():
            if isinstance(thisdict[x], types.ModuleType):
                modname = thisdict[x].__name__
                if modname not in dictlist:
                    moddict = thisdict[x].__dict__
                    dictlist.append(modname)
                    totraverse.append(moddict)
                    thedict[modname] = moddict
    return (thedict, dictlist)

def _info(obj, output=None):
    extra = ''
    tic = ''
    bp = lambda x: x
    cls = getattr(obj, '__class__', type(obj))
    nm = getattr(cls, '__name__', cls)
    strides = obj.strides
    endian = obj.dtype.byteorder
    if output is None:
        output = sys.stdout
    print('class: ', nm, file=output)
    print('shape: ', obj.shape, file=output)
    print('strides: ', strides, file=output)
    print('itemsize: ', obj.itemsize, file=output)
    print('aligned: ', bp(obj.flags.aligned), file=output)
    print('contiguous: ', bp(obj.flags.contiguous), file=output)
    print('fortran: ', obj.flags.fortran, file=output)
    print(f'data pointer: {hex(obj.ctypes._as_parameter_.value)}{extra}', file=output)
    print('byteorder: ', end=' ', file=output)
    if endian in ['|', '=']:
        print(f'{tic}{sys.byteorder}{tic}', file=output)
        byteswap = False
    elif endian == '>':
        print(f'{tic}big{tic}', file=output)
        byteswap = sys.byteorder != 'big'
    else:
        print(f'{tic}little{tic}', file=output)
        byteswap = sys.byteorder != 'little'
    print('byteswap: ', bp(byteswap), file=output)
    print(f'type: {obj.dtype}', file=output)

@set_module('numpy')
def info(object=None, maxwidth=76, output=None, toplevel='numpy'):
    global _namedict, _dictlist
    import inspect
    import pydoc
    if hasattr(object, '_ppimport_importer') or hasattr(object, '_ppimport_module'):
        object = object._ppimport_module
    elif hasattr(object, '_ppimport_attr'):
        object = object._ppimport_attr
    if output is None:
        output = sys.stdout
    if object is None:
        info(info)
    elif isinstance(object, ndarray):
        _info(object, output=output)
    elif isinstance(object, str):
        if _namedict is None:
            _namedict, _dictlist = _makenamedict(toplevel)
        numfound = 0
        objlist = []
        for namestr in _dictlist:
            try:
                obj = _namedict[namestr][object]
                if id(obj) in objlist:
                    print(f'\n     *** Repeat reference found in {namestr} *** ', file=output)
                else:
                    objlist.append(id(obj))
                    print(f'     *** Found in {namestr} ***', file=output)
                    info(obj)
                    print('-' * maxwidth, file=output)
                numfound += 1
            except KeyError:
                pass
        if numfound == 0:
            print(f'Help for {object} not found.', file=output)
        else:
            print('\n     *** Total of %d references found. ***' % numfound, file=output)
    elif inspect.isfunction(object) or inspect.ismethod(object):
        name = object.__name__
        try:
            arguments = str(inspect.signature(object))
        except Exception:
            arguments = '()'
        if len(name + arguments) > maxwidth:
            argstr = _split_line(name, arguments, maxwidth)
        else:
            argstr = name + arguments
        print(' ' + argstr + '\n', file=output)
        print(inspect.getdoc(object), file=output)
    elif inspect.isclass(object):
        name = object.__name__
        try:
            arguments = str(inspect.signature(object))
        except Exception:
            arguments = '()'
        if len(name + arguments) > maxwidth:
            argstr = _split_line(name, arguments, maxwidth)
        else:
            argstr = name + arguments
        print(' ' + argstr + '\n', file=output)
        doc1 = inspect.getdoc(object)
        if doc1 is None:
            if hasattr(object, '__init__'):
                print(inspect.getdoc(object.__init__), file=output)
        else:
            print(inspect.getdoc(object), file=output)
        methods = pydoc.allmethods(object)
        public_methods = [meth for meth in methods if meth[0] != '_']
        if public_methods:
            print('\n\nMethods:\n', file=output)
            for meth in public_methods:
                thisobj = getattr(object, meth, None)
                if thisobj is not None:
                    methstr, other = pydoc.splitdoc(inspect.getdoc(thisobj) or 'None')
                print(f'  {meth}  --  {methstr}', file=output)
    elif hasattr(object, '__doc__'):
        print(inspect.getdoc(object), file=output)

def safe_eval(source):
    warnings.warn('`safe_eval` is deprecated. Use `ast.literal_eval` instead. Be aware of security implications, such as memory exhaustion based attacks (deprecated in NumPy 2.0)', DeprecationWarning, stacklevel=2)
    import ast
    return ast.literal_eval(source)

def _median_nancheck(data, result, axis):
    if data.size == 0:
        return result
    potential_nans = data.take(-1, axis=axis)
    n = np.isnan(potential_nans)
    if np.ma.isMaskedArray(n):
        n = n.filled(False)
    if not n.any():
        return result
    if isinstance(result, np.generic):
        return potential_nans
    np.copyto(result, potential_nans, where=n)
    return result

def _opt_info():
    from numpy._core._multiarray_umath import __cpu_baseline__, __cpu_dispatch__, __cpu_features__
    if len(__cpu_baseline__) == 0 and len(__cpu_dispatch__) == 0:
        return ''
    enabled_features = ' '.join(__cpu_baseline__)
    for feature in __cpu_dispatch__:
        if __cpu_features__[feature]:
            enabled_features += f' {feature}*'
        else:
            enabled_features += f' {feature}?'
    return enabled_features

def drop_metadata(dtype, /):
    if dtype.fields is not None:
        found_metadata = dtype.metadata is not None
        names = []
        formats = []
        offsets = []
        titles = []
        for name, field in dtype.fields.items():
            field_dt = drop_metadata(field[0])
            if field_dt is not field[0]:
                found_metadata = True
            names.append(name)
            formats.append(field_dt)
            offsets.append(field[1])
            titles.append(None if len(field) < 3 else field[2])
        if not found_metadata:
            return dtype
        structure = {'names': names, 'formats': formats, 'offsets': offsets, 'titles': titles, 'itemsize': dtype.itemsize}
        return np.dtype(structure, align=dtype.isalignedstruct)
    elif dtype.subdtype is not None:
        subdtype, shape = dtype.subdtype
        new_subdtype = drop_metadata(subdtype)
        if dtype.metadata is None and new_subdtype is subdtype:
            return dtype
        return np.dtype((new_subdtype, shape))
    else:
        if dtype.metadata is None:
            return dtype
        return np.dtype(dtype.str)

from __future__ import annotations
import contextlib
import functools
import os
import sys
from collections.abc import Callable, Mapping
from types import FrameType
from typing import Any, TypeVar, cast
from coverage import env
from coverage.core import Core
from coverage.data import CoverageData
from coverage.debug import short_stack
from coverage.exceptions import ConfigError
from coverage.misc import human_sorted_items, isolate_module
from coverage.plugin import CoveragePlugin
from coverage.types import TArc, TCheckIncludeFn, TFileDisposition, Tracer, TShouldStartContextFn, TShouldTraceFn, TTraceData, TTraceFn, TWarnFn
os = isolate_module(os)
T = TypeVar('T')

class Collector:
    _collectors: list[Collector] = []

    def __init__(self, core: Core, should_trace: TShouldTraceFn, check_include: TCheckIncludeFn, should_start_context: TShouldStartContextFn | None, file_mapper: Callable[[str], str], branch: bool, warn: TWarnFn, concurrency: list[str]) -> None:
        self.core = core
        self.should_trace = should_trace
        self.check_include = check_include
        self.should_start_context = should_start_context
        self.file_mapper = file_mapper
        self.branch = branch
        self.warn = warn
        assert isinstance(concurrency, list), f'Expected a list: {concurrency!r}'
        self.pid = os.getpid()
        self.covdata: CoverageData
        self.threading = None
        self.static_context: str | None = None
        self.origin = short_stack()
        self.concur_id_func = None
        do_threading = False
        tried = 'nothing'
        try:
            if 'greenlet' in concurrency:
                tried = 'greenlet'
                import greenlet
                self.concur_id_func = greenlet.getcurrent
            elif 'eventlet' in concurrency:
                tried = 'eventlet'
                import eventlet.greenthread
                self.concur_id_func = eventlet.greenthread.getcurrent
            elif 'gevent' in concurrency:
                tried = 'gevent'
                import gevent
                self.concur_id_func = gevent.getcurrent
            if 'thread' in concurrency:
                do_threading = True
        except ImportError as ex:
            msg = f"Couldn't trace with concurrency={tried}, the module isn't installed."
            raise ConfigError(msg) from ex
        if self.concur_id_func and (not hasattr(core.tracer_class, 'concur_id_func')):
            raise ConfigError("Can't support concurrency={} with {}, only threads are supported.".format(tried, self.tracer_name()))
        if do_threading or not concurrency:
            import threading
            self.threading = threading
        self.reset()

    def __repr__(self) -> str:
        return f'<Collector at {id(self):#x}: {self.tracer_name()}>'

    def use_data(self, covdata: CoverageData, context: str | None) -> None:
        self.covdata = covdata
        self.static_context = context
        self.covdata.set_context(self.static_context)

    def tracer_name(self) -> str:
        return self.core.tracer_class.__name__

    def _clear_data(self) -> None:
        with self.data_lock or contextlib.nullcontext():
            for d in self.data.values():
                d.clear()
        for tracer in self.tracers:
            tracer.reset_activity()

    def reset(self) -> None:
        self.data_lock = self.threading.Lock() if self.threading else None
        self.data: TTraceData = {}
        self.file_tracers: dict[str, str] = {}
        self.disabled_plugins: set[str] = set()
        if env.PYPY:
            import __pypy__
            self.should_trace_cache = __pypy__.newdict('module')
        else:
            self.should_trace_cache = {}
        self.tracers: list[Tracer] = []
        self._clear_data()

    def lock_data(self) -> None:
        if self.data_lock is not None:
            self.data_lock.acquire()

    def unlock_data(self) -> None:
        if self.data_lock is not None:
            self.data_lock.release()

    def _start_tracer(self) -> TTraceFn | None:
        tracer = self.core.tracer_class(**self.core.tracer_kwargs)
        tracer.data = self.data
        tracer.lock_data = self.lock_data
        tracer.unlock_data = self.unlock_data
        tracer.trace_arcs = self.branch
        tracer.should_trace = self.should_trace
        tracer.should_trace_cache = self.should_trace_cache
        tracer.warn = self.warn
        if hasattr(tracer, 'concur_id_func'):
            tracer.concur_id_func = self.concur_id_func
        if hasattr(tracer, 'file_tracers'):
            tracer.file_tracers = self.file_tracers
        if hasattr(tracer, 'threading'):
            tracer.threading = self.threading
        if hasattr(tracer, 'check_include'):
            tracer.check_include = self.check_include
        if hasattr(tracer, 'should_start_context'):
            tracer.should_start_context = self.should_start_context
        if hasattr(tracer, 'switch_context'):
            tracer.switch_context = self.switch_context
        if hasattr(tracer, 'disable_plugin'):
            tracer.disable_plugin = self.disable_plugin
        fn = tracer.start()
        self.tracers.append(tracer)
        return fn

    def _installation_trace(self, frame: FrameType, event: str, arg: Any) -> TTraceFn | None:
        sys.settrace(None)
        fn: TTraceFn | None = self._start_tracer()
        if fn:
            fn = fn(frame, event, arg)
        return fn

    def start(self) -> None:
        keep_collectors = []
        for c in self._collectors:
            if c.pid == self.pid:
                keep_collectors.append(c)
            else:
                c.post_fork()
        self._collectors[:] = keep_collectors
        if self._collectors:
            self._collectors[-1].pause()
        self.tracers = []
        try:
            self._start_tracer()
        except:
            if self._collectors:
                self._collectors[-1].resume()
            raise
        self._collectors.append(self)
        if self.core.systrace and self.threading:
            self.threading.settrace(self._installation_trace)

    def stop(self) -> None:
        assert self._collectors
        if self._collectors[-1] is not self:
            print('self._collectors:')
            for c in self._collectors:
                print(f'  {c!r}\n{c.origin}')
        assert self._collectors[-1] is self, f"Expected current collector to be {self!r}, but it's {self._collectors[-1]!r}"
        self.pause()
        self._collectors.pop()
        if self._collectors:
            self._collectors[-1].resume()

    def pause(self) -> None:
        for tracer in self.tracers:
            tracer.stop()
            stats = tracer.get_stats()
            if stats:
                print(f'\nCoverage.py {tracer.__class__.__name__} stats:')
                for k, v in human_sorted_items(stats.items()):
                    print(f'{k:>20}: {v}')
        if self.threading:
            self.threading.settrace(None)

    def resume(self) -> None:
        for tracer in self.tracers:
            tracer.start()
        if self.core.systrace:
            if self.threading:
                self.threading.settrace(self._installation_trace)
            else:
                self._start_tracer()

    def post_fork(self) -> None:
        for tracer in self.tracers:
            if hasattr(tracer, 'post_fork'):
                tracer.post_fork()

    def _activity(self) -> bool:
        return any((tracer.activity() for tracer in self.tracers))

    def switch_context(self, new_context: str | None) -> None:
        context: str | None
        self.flush_data()
        if self.static_context:
            context = self.static_context
            if new_context:
                context += '|' + new_context
        else:
            context = new_context
        self.covdata.set_context(context)

    def disable_plugin(self, disposition: TFileDisposition) -> None:
        file_tracer = disposition.file_tracer
        assert file_tracer is not None
        plugin = file_tracer._coverage_plugin
        plugin_name = plugin._coverage_plugin_name
        self.warn(f'Disabling plug-in {plugin_name!r} due to previous exception')
        plugin._coverage_enabled = False
        disposition.trace = False

    @functools.cache
    def cached_mapped_file(self, filename: str) -> str:
        return self.file_mapper(filename)

    def mapped_file_dict(self, d: Mapping[str, T]) -> dict[str, T]:
        runtime_err = None
        for _ in range(3):
            try:
                items = list(d.items())
            except RuntimeError as ex:
                runtime_err = ex
            else:
                break
        else:
            assert isinstance(runtime_err, Exception)
            raise runtime_err
        return {self.cached_mapped_file(k): v for k, v in items if v}

    def plugin_was_disabled(self, plugin: CoveragePlugin) -> None:
        self.disabled_plugins.add(plugin._coverage_plugin_name)

    def flush_data(self) -> bool:
        if not self._activity():
            return False
        if self.branch:
            if self.core.packed_arcs:
                arc_data: dict[str, list[TArc]] = {}
                packed_data = cast(dict[str, set[int]], self.data)
                for fname, packeds in list(packed_data.items()):
                    tuples = []
                    for packed in list(packeds):
                        l1 = packed & 268435455
                        l2 = (packed & 268435455 << 28) >> 28
                        if packed & 1 << 56:
                            l1 *= -1
                        if packed & 1 << 57:
                            l2 *= -1
                        tuples.append((l1, l2))
                    arc_data[fname] = tuples
            else:
                arc_data = cast(dict[str, list[TArc]], self.data)
            self.covdata.add_arcs(self.mapped_file_dict(arc_data))
        else:
            line_data = cast(dict[str, set[int]], self.data)
            self.covdata.add_lines(self.mapped_file_dict(line_data))
        file_tracers = {self.cached_mapped_file(k): v for k, v in self.file_tracers.items() if v not in self.disabled_plugins}
        self.covdata.add_file_tracers(file_tracers)
        self._clear_data()
        return True

