WARN_NOIPYW = 'IProgress not found. Please update jupyter and ipywidgets. See https://ipywidgets.readthedocs.io/en/stable/user_install.html'

class TqdmHBox(HBox):

    def _json_(self, pretty=None):
        pbar = getattr(self, 'pbar', None)
        if pbar is None:
            return {}
        d = pbar.format_dict
        if pretty is not None:
            d['ascii'] = not pretty
        return d

    def __repr__(self, pretty=False):
        pbar = getattr(self, 'pbar', None)
        if pbar is None:
            return super().__repr__()
        return pbar.format_meter(**self._json_(pretty))

    def _repr_pretty_(self, pp, *_, **__):
        pp.text(self.__repr__(True))

class tqdm_notebook(std_tqdm):

    @staticmethod
    def status_printer(_, total=None, desc=None, ncols=None):
        if IProgress is None:
            raise ImportError(WARN_NOIPYW)
        if total:
            pbar = IProgress(min=0, max=total)
        else:
            pbar = IProgress(min=0, max=1)
            pbar.value = 1
            pbar.bar_style = 'info'
            if ncols is None:
                pbar.layout.width = '20px'
        ltext = HTML()
        rtext = HTML()
        if desc:
            ltext.value = desc
        container = TqdmHBox(children=[ltext, pbar, rtext])
        if ncols is not None:
            ncols = str(ncols)
            try:
                if int(ncols) > 0:
                    ncols += 'px'
            except ValueError:
                pass
            pbar.layout.flex = '2'
            container.layout.width = ncols
            container.layout.display = 'inline-flex'
            container.layout.flex_flow = 'row wrap'
        return container

    def display(self, msg=None, pos=None, close=False, bar_style=None, check_delay=True):
        if not msg and (not close):
            d = self.format_dict
            d['bar_format'] = (d['bar_format'] or '{l_bar}<bar/>{r_bar}').replace('{bar}', '<bar/>')
            msg = self.format_meter(**d)
        ltext, pbar, rtext = self.container.children
        pbar.value = self.n
        if msg:
            msg = msg.replace(' ', '\u2007')
            if '<bar/>' in msg:
                left, right = map(escape, re.split('\\|?<bar/>\\|?', msg, maxsplit=1))
            else:
                left, right = ('', escape(msg))
            ltext.value = left
            if right:
                rtext.value = right
        if bar_style:
            if pbar.bar_style != 'danger' or bar_style != 'success':
                pbar.bar_style = bar_style
        if close and pbar.bar_style != 'danger':
            try:
                self.container.close()
            except AttributeError:
                self.container.visible = False
            self.container.layout.visibility = 'hidden'
        if check_delay and self.delay > 0 and (not self.displayed):
            display(self.container)
            self.displayed = True

    @property
    def colour(self):
        if hasattr(self, 'container'):
            return self.container.children[-2].style.bar_color

    @colour.setter
    def colour(self, bar_color):
        if hasattr(self, 'container'):
            self.container.children[-2].style.bar_color = bar_color

    def __init__(self, *args, **kwargs):
        kwargs = kwargs.copy()
        file_kwarg = kwargs.get('file', sys.stderr)
        if file_kwarg is sys.stderr or file_kwarg is None:
            kwargs['file'] = sys.stdout
        kwargs['gui'] = True
        kwargs['disable'] = bool(kwargs.get('disable', False))
        colour = kwargs.pop('colour', None)
        display_here = kwargs.pop('display', True)
        super().__init__(*args, **kwargs)
        if self.disable or not kwargs['gui']:
            self.disp = lambda *_, **__: None
            return
        self.ncols = '100%' if self.dynamic_ncols else kwargs.get('ncols', None)
        unit_scale = 1 if self.unit_scale is True else self.unit_scale or 1
        total = self.total * unit_scale if self.total else self.total
        self.container = self.status_printer(self.fp, total, self.desc, self.ncols)
        self.container.pbar = proxy(self)
        self.displayed = False
        if display_here and self.delay <= 0:
            display(self.container)
            self.displayed = True
        self.disp = self.display
        self.colour = colour
        if not self.disable:
            self.display(check_delay=False)

    def __iter__(self):
        try:
            it = super().__iter__()
            yield from it
        except:
            self.disp(bar_style='danger')
            raise

    def update(self, n=1):
        try:
            return super().update(n=n)
        except:
            self.disp(bar_style='danger')
            raise

    def close(self):
        if self.disable:
            return
        super().close()
        if self.total and self.n < self.total:
            self.disp(bar_style='danger', check_delay=False)
        elif self.leave:
            self.disp(bar_style='success', check_delay=False)
        else:
            self.disp(close=True, check_delay=False)

    def clear(self, *_, **__):
        pass

    def reset(self, total=None):
        if self.disable:
            return super().reset(total=total)
        _, pbar, _ = self.container.children
        pbar.bar_style = ''
        if total is not None:
            pbar.max = total
            if not self.total and self.ncols is None:
                pbar.layout.width = None
        return super().reset(total=total)

def tnrange(*args, **kwargs):
    return tqdm_notebook(range(*args), **kwargs)
tqdm = tqdm_notebook
trange = tnrange

from __future__ import annotations
from typing import TYPE_CHECKING, Any, Literal, cast
import numpy as np
from pandas._libs import Timedelta, Timestamp, lib
from pandas.util._decorators import set_module
from pandas.core.dtypes.common import ensure_platform_int, is_bool_dtype, is_integer, is_list_like, is_numeric_dtype, is_scalar
from pandas.core.dtypes.dtypes import CategoricalDtype, DatetimeTZDtype, ExtensionDtype
from pandas.core.dtypes.generic import ABCSeries
from pandas.core.dtypes.missing import isna
from pandas import Categorical, Index, IntervalIndex
import pandas.core.algorithms as algos
from pandas.core.arrays.datetimelike import dtype_to_unit
from pandas.core.col import Expression
if TYPE_CHECKING:
    from collections.abc import Callable
    from pandas._typing import DtypeObj, IntervalLeftRight, TimeUnit

@set_module('pandas')
def cut(x, bins, right: bool=True, labels=None, retbins: bool=False, precision: int=3, include_lowest: bool=False, duplicates: str='raise', ordered: bool=True):
    original = x
    x_idx = _preprocess_for_cut(x)
    x_idx, _ = _coerce_to_type(x_idx)
    if not np.iterable(bins):
        bins = _nbins_to_bins(x_idx, bins, right)
    elif isinstance(bins, IntervalIndex):
        if bins.is_overlapping:
            raise ValueError('Overlapping IntervalIndex is not accepted.')
    else:
        bins = Index(bins)
        if not bins.is_monotonic_increasing:
            raise ValueError('bins must increase monotonically.')
    fac, bins = _bins_to_cuts(x_idx, bins, right=right, labels=labels, precision=precision, include_lowest=include_lowest, duplicates=duplicates, ordered=ordered)
    return _postprocess_for_cut(fac, bins, retbins, original)

@set_module('pandas')
def qcut(x, q, labels=None, retbins: bool=False, precision: int=3, duplicates: str='raise'):
    if isinstance(x, Expression):
        return x._call_with_func(qcut, x=x, q=q, labels=labels, retbins=retbins, precision=precision)
    original = x
    x_idx = _preprocess_for_cut(x)
    x_idx, _ = _coerce_to_type(x_idx)
    if is_integer(q):
        quantiles = np.linspace(0, 1, q + 1)
        np.putmask(quantiles, q * quantiles != np.arange(q + 1), np.nextafter(quantiles, 1))
    else:
        quantiles = q
    bins = x_idx.to_series().dropna().quantile(quantiles)
    fac, bins = _bins_to_cuts(x_idx, Index(bins), labels=labels, precision=precision, include_lowest=True, duplicates=duplicates)
    return _postprocess_for_cut(fac, bins, retbins, original)

def _nbins_to_bins(x_idx: Index, nbins: int, right: bool) -> Index:
    if is_scalar(nbins) and nbins < 1:
        raise ValueError('`bins` should be a positive integer.')
    if x_idx.size == 0:
        raise ValueError('Cannot cut empty array')
    rng = (x_idx.min(), x_idx.max())
    mn, mx = rng
    if is_numeric_dtype(x_idx.dtype) and (np.isinf(mn) or np.isinf(mx)):
        raise ValueError('cannot specify integer `bins` when input data contains infinity')
    if mn == mx:
        if _is_dt_or_td(x_idx.dtype):
            unit = dtype_to_unit(x_idx.dtype)
            td = Timedelta(seconds=1).as_unit(cast('TimeUnit', unit))
            bins = x_idx._values._generate_range(start=mn - td, end=mx + td, periods=nbins + 1, freq=None, unit=unit)
        else:
            mn -= 0.001 * abs(mn) if mn != 0 else 0.001
            mx += 0.001 * abs(mx) if mx != 0 else 0.001
            bins = np.linspace(mn, mx, nbins + 1, endpoint=True)
    else:
        if _is_dt_or_td(x_idx.dtype):
            unit = dtype_to_unit(x_idx.dtype)
            bins = x_idx._values._generate_range(start=mn, end=mx, periods=nbins + 1, freq=None, unit=unit)
        else:
            bins = np.linspace(mn, mx, nbins + 1, endpoint=True)
        adj = (mx - mn) * 0.001
        if right:
            bins[0] -= adj
        else:
            bins[-1] += adj
    return Index(bins, copy=False)

def _bins_to_cuts(x_idx: Index, bins: Index, right: bool=True, labels=None, precision: int=3, include_lowest: bool=False, duplicates: str='raise', ordered: bool=True):
    if not ordered and labels is None:
        raise ValueError("'labels' must be provided if 'ordered = False'")
    if duplicates not in ['raise', 'drop']:
        raise ValueError("invalid value for 'duplicates' parameter, valid options are: raise, drop")
    result: Categorical | np.ndarray
    if isinstance(bins, IntervalIndex):
        ids = bins.get_indexer(x_idx)
        cat_dtype = CategoricalDtype(bins, ordered=True)
        result = Categorical.from_codes(ids, dtype=cat_dtype, validate=False)
        return (result, bins)
    unique_bins = algos.unique(bins)
    if len(unique_bins) < len(bins) and len(bins) != 2:
        if duplicates == 'raise':
            raise ValueError(f"Bin edges must be unique: {bins!r}.\nYou can drop duplicate edges by setting the 'duplicates' kwarg")
        bins = unique_bins
    side: Literal['left', 'right'] = 'left' if right else 'right'
    try:
        ids = bins.searchsorted(x_idx, side=side)
    except TypeError as err:
        if x_idx.dtype.kind == 'm':
            raise ValueError('bins must be of timedelta64 dtype') from err
        elif x_idx.dtype.kind == bins.dtype.kind == 'M':
            raise ValueError('Cannot use timezone-naive bins with timezone-aware values, or vice-versa') from err
        elif x_idx.dtype.kind == 'M':
            raise ValueError('bins must be of datetime64 dtype') from err
        else:
            raise
    ids = ensure_platform_int(ids)
    if include_lowest:
        ids[x_idx == bins[0]] = 1
    na_mask = isna(x_idx) | (ids == len(bins)) | (ids == 0)
    has_nas = na_mask.any()
    if labels is not False:
        if not (labels is None or is_list_like(labels)):
            raise ValueError('Bin labels must either be False, None or passed in as a list-like argument')
        if labels is None:
            labels = _format_labels(bins, precision, right=right, include_lowest=include_lowest)
        elif ordered and len(set(labels)) != len(labels):
            raise ValueError('labels must be unique if ordered=True; pass ordered=False for duplicate labels')
        elif len(labels) != len(bins) - 1:
            raise ValueError('Bin labels must be one fewer than the number of bin edges')
        if not isinstance(getattr(labels, 'dtype', None), CategoricalDtype):
            labels = Categorical(labels, categories=labels if len(set(labels)) == len(labels) else None, ordered=ordered)
        np.putmask(ids, na_mask, 0)
        result = algos.take_nd(labels, ids - 1)
    else:
        result = ids - 1
        if has_nas:
            result = result.astype(np.float64)
            np.putmask(result, na_mask, np.nan)
    return (result, bins)

def _coerce_to_type(x: Index) -> tuple[Index, DtypeObj | None]:
    dtype: DtypeObj | None = None
    if _is_dt_or_td(x.dtype):
        dtype = x.dtype
    elif is_bool_dtype(x.dtype):
        x = x.astype(np.int64)
    elif isinstance(x.dtype, ExtensionDtype) and is_numeric_dtype(x.dtype):
        x_arr = x.to_numpy(dtype=np.float64, na_value=np.nan)
        x = Index(x_arr, copy=False)
    return (Index(x), dtype)

def _is_dt_or_td(dtype: DtypeObj) -> bool:
    return isinstance(dtype, DatetimeTZDtype) or lib.is_np_dtype(dtype, 'mM')

def _format_labels(bins: Index, precision: int, right: bool=True, include_lowest: bool=False) -> IntervalIndex:
    closed: IntervalLeftRight = 'right' if right else 'left'
    formatter: Callable[[Any], Timestamp] | Callable[[Any], Timedelta]
    if _is_dt_or_td(bins.dtype):
        unit = dtype_to_unit(bins.dtype)
        unit = cast('TimeUnit', unit)
        formatter = lambda x: x
        adjust = lambda x: x - Timedelta(1, unit=unit).as_unit(unit)
    else:
        precision = _infer_precision(precision, bins)
        formatter = lambda x: _round_frac(x, precision)
        adjust = lambda x: x - 10 ** (-precision)
    breaks = [formatter(b) for b in bins]
    if right and include_lowest:
        breaks[0] = adjust(breaks[0])
    if _is_dt_or_td(bins.dtype):
        breaks = type(bins)(breaks).as_unit(unit)
    return IntervalIndex.from_breaks(breaks, closed=closed)

def _preprocess_for_cut(x) -> Index:
    ndim = getattr(x, 'ndim', None)
    if ndim is None:
        x = np.asarray(x)
    if x.ndim != 1:
        raise ValueError('Input array must be 1 dimensional')
    return Index(x, copy=False)

def _postprocess_for_cut(fac, bins, retbins: bool, original):
    if isinstance(original, ABCSeries):
        fac = original._constructor(fac, index=original.index, name=original.name)
    if not retbins:
        return fac
    if isinstance(bins, Index) and is_numeric_dtype(bins.dtype):
        bins = bins._values
    return (fac, bins)

def _round_frac(x, precision: int):
    if not np.isfinite(x) or x == 0:
        return x
    else:
        frac, whole = np.modf(x)
        if whole == 0:
            digits = -int(np.floor(np.log10(abs(frac)))) - 1 + precision
        else:
            digits = precision
        return np.around(x, digits)

def _infer_precision(base_precision: int, bins: Index) -> int:
    for precision in range(base_precision, 20):
        levels = np.asarray([_round_frac(b, precision) for b in bins])
        if algos.unique(levels).size == bins.size:
            return precision
    return base_precision

from __future__ import annotations
import functools
from typing import TYPE_CHECKING, Any
import warnings
from pandas._libs.tslibs import BaseOffset, Period, to_offset
from pandas._libs.tslibs.dtypes import OFFSET_TO_PERIOD_FREQSTR, FreqGroup
from pandas.core.dtypes.generic import ABCDatetimeIndex, ABCPeriodIndex, ABCTimedeltaIndex
from pandas.io.formats.printing import pprint_thing
from pandas.plotting._matplotlib.converter import TimeSeries_DateFormatter, TimeSeries_DateLocator, TimeSeries_TimedeltaFormatter
from pandas.tseries.frequencies import get_period_alias, is_subperiod, is_superperiod
if TYPE_CHECKING:
    from datetime import timedelta
    from matplotlib.axes import Axes
    from pandas._typing import NDFrameT
    from pandas import DatetimeIndex, Index, PeriodIndex, Series

def maybe_resample(series: Series, ax: Axes, kwargs: dict[str, Any]):
    if 'how' in kwargs:
        raise ValueError("'how' is not a valid keyword for plotting functions. If plotting multiple objects on shared axes, resample manually first.")
    freq, ax_freq = _get_freq(ax, series)
    if freq is None:
        raise ValueError('Cannot use dynamic axis without frequency info')
    if isinstance(series.index, ABCDatetimeIndex):
        series = series.to_period(freq=freq)
    if ax_freq is not None and freq != ax_freq:
        if is_superperiod(freq, ax_freq):
            series = series.copy(deep=False)
            series.index = series.index.asfreq(ax_freq, how='s')
            freq = ax_freq
        elif _is_sup(freq, ax_freq):
            how = 'last'
            series = getattr(series.resample('D'), how)().dropna()
            series = getattr(series.resample(ax_freq), how)().dropna()
            freq = ax_freq
        elif is_subperiod(freq, ax_freq) or _is_sub(freq, ax_freq):
            _upsample_others(ax, freq, kwargs)
        else:
            raise ValueError('Incompatible frequency conversion')
    return (freq, series)

def _is_sub(f1: str, f2: str) -> bool:
    return f1.startswith('W') and is_subperiod('D', f2) or (f2.startswith('W') and is_subperiod(f1, 'D'))

def _is_sup(f1: str, f2: str) -> bool:
    return f1.startswith('W') and is_superperiod('D', f2) or (f2.startswith('W') and is_superperiod(f1, 'D'))

def _upsample_others(ax: Axes, freq: BaseOffset, kwargs: dict[str, Any]) -> None:
    legend = ax.get_legend()
    lines, labels = _replot_ax(ax, freq)
    _replot_ax(ax, freq)
    other_ax = None
    if hasattr(ax, 'left_ax'):
        other_ax = ax.left_ax
    if hasattr(ax, 'right_ax'):
        other_ax = ax.right_ax
    if other_ax is not None:
        rlines, rlabels = _replot_ax(other_ax, freq)
        lines.extend(rlines)
        labels.extend(rlabels)
    if legend is not None and kwargs.get('legend', True) and (len(lines) > 0):
        title: str | None = legend.get_title().get_text()
        if title == 'None':
            title = None
        ax.legend(lines, labels, loc='best', title=title)

def _replot_ax(ax: Axes, freq: BaseOffset):
    data = getattr(ax, '_plot_data', None)
    ax._plot_data = []
    ax.clear()
    decorate_axes(ax, freq)
    lines = []
    labels = []
    if data is not None:
        for series, plotf, kwds in data:
            series = series.copy(deep=False)
            idx = series.index.asfreq(freq, how='S')
            series.index = idx
            ax._plot_data.append((series, plotf, kwds))
            if isinstance(plotf, str):
                from pandas.plotting._matplotlib import PLOT_CLASSES
                plotf = PLOT_CLASSES[plotf]._plot
            lines.append(plotf(ax, series.index._mpl_repr(), series.values, **kwds)[0])
            labels.append(pprint_thing(series.name))
    return (lines, labels)

def decorate_axes(ax: Axes, freq: BaseOffset) -> None:
    if not hasattr(ax, '_plot_data'):
        ax._plot_data = []
    ax.freq = freq
    xaxis = ax.get_xaxis()
    xaxis.freq = freq

def _get_ax_freq(ax: Axes):
    ax_freq = getattr(ax, 'freq', None)
    if ax_freq is None:
        if hasattr(ax, 'left_ax'):
            ax_freq = getattr(ax.left_ax, 'freq', None)
        elif hasattr(ax, 'right_ax'):
            ax_freq = getattr(ax.right_ax, 'freq', None)
    if ax_freq is None:
        shared_axes = ax.get_shared_x_axes().get_siblings(ax)
        if len(shared_axes) > 1:
            for shared_ax in shared_axes:
                ax_freq = getattr(shared_ax, 'freq', None)
                if ax_freq is not None:
                    break
    return ax_freq

def _get_period_alias(freq: timedelta | BaseOffset | str) -> str | None:
    if isinstance(freq, BaseOffset):
        freqstr = freq.name
    else:
        freqstr = to_offset(freq, is_period=True).rule_code
    return get_period_alias(freqstr)

def _get_freq(ax: Axes, series: Series):
    freq = getattr(series.index, 'freq', None)
    if freq is None:
        freq = getattr(series.index, 'inferred_freq', None)
        freq = to_offset(freq, is_period=True)
    ax_freq = _get_ax_freq(ax)
    if freq is None:
        freq = ax_freq
    freq = _get_period_alias(freq)
    return (freq, ax_freq)

def use_dynamic_x(ax: Axes, index: Index) -> bool:
    freq = _get_index_freq(index)
    ax_freq = _get_ax_freq(ax)
    if freq is None:
        freq = ax_freq
    elif ax_freq is None and len(ax.get_lines()) > 0:
        return False
    if freq is None:
        return False
    freq_str = _get_period_alias(freq)
    if freq_str is None:
        return False
    if isinstance(index, ABCDatetimeIndex):
        freq_str = OFFSET_TO_PERIOD_FREQSTR.get(freq_str, freq_str)
        base = to_offset(freq_str, is_period=True)._period_dtype_code
        if base <= FreqGroup.FR_DAY.value:
            return index[:1].is_normalized
        period = Period(index[0], freq_str)
        assert isinstance(period, Period)
        return period.to_timestamp().tz_localize(index.tz) == index[0]
    return True

def _get_index_freq(index: Index) -> BaseOffset | None:
    freq = getattr(index, 'freq', None)
    if freq is None:
        freq = getattr(index, 'inferred_freq', None)
        freq = to_offset(freq)
    return freq

def maybe_convert_index(ax: Axes, data: NDFrameT) -> NDFrameT:
    if isinstance(data.index, (ABCDatetimeIndex, ABCPeriodIndex)):
        freq = _get_index_freq(data.index)
        if freq is None:
            freq = _get_ax_freq(ax)
        if freq is None:
            raise ValueError('Could not get frequency alias for plotting')
        freq_str = _get_period_alias(freq)
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', 'PeriodDtype\\[B\\] is deprecated', category=FutureWarning)
            if isinstance(data.index, ABCDatetimeIndex):
                data = data.tz_localize(None).to_period(freq=freq_str)
            elif isinstance(data.index, ABCPeriodIndex):
                data.index = data.index.asfreq(freq=freq_str, how='start')
    return data

def _format_coord(freq: BaseOffset, t, y) -> str:
    time_period = Period(ordinal=int(t), freq=freq)
    return f't = {time_period}  y = {y:8f}'

def format_dateaxis(subplot, freq: BaseOffset, index: DatetimeIndex | PeriodIndex) -> None:
    import matplotlib.pyplot as plt
    if isinstance(index, ABCPeriodIndex):
        majlocator = TimeSeries_DateLocator(freq, dynamic_mode=True, minor_locator=False, plot_obj=subplot)
        minlocator = TimeSeries_DateLocator(freq, dynamic_mode=True, minor_locator=True, plot_obj=subplot)
        subplot.xaxis.set_major_locator(majlocator)
        subplot.xaxis.set_minor_locator(minlocator)
        majformatter = TimeSeries_DateFormatter(freq, dynamic_mode=True, minor_locator=False, plot_obj=subplot)
        minformatter = TimeSeries_DateFormatter(freq, dynamic_mode=True, minor_locator=True, plot_obj=subplot)
        subplot.xaxis.set_major_formatter(majformatter)
        subplot.xaxis.set_minor_formatter(minformatter)
        subplot.format_coord = functools.partial(_format_coord, freq)
    elif isinstance(index, ABCTimedeltaIndex):
        subplot.xaxis.set_major_formatter(TimeSeries_TimedeltaFormatter(index.unit))
    else:
        raise TypeError('index type not supported')
    plt.draw_if_interactive()

def prepare_ts_data(series: Series, ax: Axes, kwargs: dict[str, Any]) -> tuple[BaseOffset | str, Series]:
    freq, data = maybe_resample(series, ax, kwargs)
    decorate_axes(ax, freq)
    if hasattr(ax, 'left_ax'):
        decorate_axes(ax.left_ax, freq)
    if hasattr(ax, 'right_ax'):
        decorate_axes(ax.right_ax, freq)
    return (freq, data)

from __future__ import annotations
from collections.abc import Hashable, Iterable, Iterator, Sequence
import csv as csvlib
import os
from typing import TYPE_CHECKING, Any, cast
import numpy as np
from pandas._libs import writers as libwriters
from pandas._typing import SequenceNotStr
from pandas.util._decorators import cache_readonly
from pandas.core.dtypes.generic import ABCDatetimeIndex, ABCIndex, ABCMultiIndex, ABCPeriodIndex
from pandas.core.dtypes.missing import notna
from pandas.core.indexes.api import Index
from pandas.io.common import get_handle
if TYPE_CHECKING:
    from pandas._typing import CompressionOptions, FilePath, FloatFormatType, IndexLabel, StorageOptions, WriteBuffer, npt
    from pandas.io.formats.format import DataFrameFormatter
_DEFAULT_CHUNKSIZE_CELLS = 100000

class CSVFormatter:
    cols: npt.NDArray[np.object_]

    def __init__(self, formatter: DataFrameFormatter, path_or_buf: FilePath | WriteBuffer[str] | WriteBuffer[bytes]='', sep: str=',', cols: Sequence[Hashable] | None=None, index_label: IndexLabel | None=None, mode: str='w', encoding: str | None=None, errors: str='strict', compression: CompressionOptions='infer', quoting: int | None=None, lineterminator: str | None='\n', chunksize: int | None=None, quotechar: str | None='"', date_format: str | None=None, doublequote: bool=True, escapechar: str | None=None, storage_options: StorageOptions | None=None) -> None:
        self.fmt = formatter
        self.obj = self.fmt.frame
        self.filepath_or_buffer = path_or_buf
        self.encoding = encoding
        self.compression: CompressionOptions = compression
        self.mode = mode
        self.storage_options = storage_options
        self.sep = sep
        self.index_label = self._initialize_index_label(index_label)
        self.errors = errors
        self.quoting = quoting or csvlib.QUOTE_MINIMAL
        self.doublequote = doublequote
        self.escapechar = escapechar
        self.quotechar = self._initialize_quotechar(quotechar)
        self.lineterminator = lineterminator or os.linesep
        self.date_format = date_format
        self.cols = self._initialize_columns(cols)
        self.chunksize = self._initialize_chunksize(chunksize)

    @property
    def na_rep(self) -> str:
        return self.fmt.na_rep

    @property
    def float_format(self) -> FloatFormatType | None:
        return self.fmt.float_format

    @property
    def decimal(self) -> str:
        return self.fmt.decimal

    @property
    def header(self) -> bool | SequenceNotStr[str]:
        return self.fmt.header

    @property
    def index(self) -> bool:
        return self.fmt.index

    def _initialize_index_label(self, index_label: IndexLabel | None) -> IndexLabel:
        if index_label is not False:
            if index_label is None:
                return self._get_index_label_from_obj()
            elif not isinstance(index_label, (list, tuple, np.ndarray, ABCIndex)):
                return [index_label]
        return index_label

    def _get_index_label_from_obj(self) -> Sequence[Hashable]:
        if isinstance(self.obj.index, ABCMultiIndex):
            return self._get_index_label_multiindex()
        else:
            return self._get_index_label_flat()

    def _get_index_label_multiindex(self) -> Sequence[Hashable]:
        return [name or '' for name in self.obj.index.names]

    def _get_index_label_flat(self) -> Sequence[Hashable]:
        index_label = self.obj.index.name
        return [''] if index_label is None else [index_label]

    def _initialize_quotechar(self, quotechar: str | None) -> str | None:
        if self.quoting != csvlib.QUOTE_NONE or self.escapechar is not None:
            return quotechar
        return None

    @property
    def has_mi_columns(self) -> bool:
        return bool(isinstance(self.obj.columns, ABCMultiIndex))

    def _initialize_columns(self, cols: Iterable[Hashable] | None) -> npt.NDArray[np.object_]:
        if self.has_mi_columns:
            if cols is not None:
                msg = 'cannot specify cols with a MultiIndex on the columns'
                raise TypeError(msg)
        if cols is not None:
            if isinstance(cols, ABCIndex):
                cols = cols._get_values_for_csv(**self._number_format)
            else:
                cols = list(cols)
            self.obj = self.obj.loc[:, cols]
        new_cols = self.obj.columns
        return new_cols._get_values_for_csv(**self._number_format)

    def _initialize_chunksize(self, chunksize: int | None) -> int:
        if chunksize is None:
            return _DEFAULT_CHUNKSIZE_CELLS // (len(self.cols) or 1) or 1
        return int(chunksize)

    @property
    def _number_format(self) -> dict[str, Any]:
        return {'na_rep': self.na_rep, 'float_format': self.float_format, 'date_format': self.date_format, 'quoting': self.quoting, 'decimal': self.decimal}

    @cache_readonly
    def data_index(self) -> Index:
        data_index = self.obj.index
        if isinstance(data_index, (ABCDatetimeIndex, ABCPeriodIndex)) and self.date_format is not None:
            data_index = Index([x.strftime(self.date_format) if notna(x) else '' for x in data_index])
        elif isinstance(data_index, ABCMultiIndex):
            data_index = data_index.remove_unused_levels()
        return data_index

    @property
    def nlevels(self) -> int:
        if self.index:
            return getattr(self.data_index, 'nlevels', 1)
        else:
            return 0

    @property
    def _has_aliases(self) -> bool:
        return isinstance(self.header, (tuple, list, np.ndarray, ABCIndex))

    @property
    def _need_to_save_header(self) -> bool:
        return bool(self._has_aliases or self.header)

    @property
    def write_cols(self) -> SequenceNotStr[Hashable]:
        if self._has_aliases:
            assert not isinstance(self.header, bool)
            if len(self.header) != len(self.cols):
                raise ValueError(f'Writing {len(self.cols)} cols but got {len(self.header)} aliases')
            return self.header
        else:
            return cast(SequenceNotStr[Hashable], self.cols)

    @property
    def encoded_labels(self) -> list[Hashable]:
        encoded_labels: list[Hashable] = []
        if self.index and self.index_label:
            assert isinstance(self.index_label, Sequence)
            encoded_labels = list(self.index_label)
        if not self.has_mi_columns or self._has_aliases:
            encoded_labels += list(self.write_cols)
        return encoded_labels

    def save(self) -> None:
        with get_handle(self.filepath_or_buffer, self.mode, encoding=self.encoding, errors=self.errors, compression=self.compression, storage_options=self.storage_options) as handles:
            self.writer = csvlib.writer(handles.handle, lineterminator=self.lineterminator, delimiter=self.sep, quoting=self.quoting, doublequote=self.doublequote, escapechar=self.escapechar, quotechar=self.quotechar)
            self._save()

    def _save(self) -> None:
        if self._need_to_save_header:
            self._save_header()
        self._save_body()

    def _save_header(self) -> None:
        if not self.has_mi_columns or self._has_aliases:
            self.writer.writerow(self.encoded_labels)
        else:
            for row in self._generate_multiindex_header_rows():
                self.writer.writerow(row)

    def _generate_multiindex_header_rows(self) -> Iterator[list[Hashable]]:
        columns = self.obj.columns
        for i in range(columns.nlevels):
            col_line = []
            if self.index:
                col_line.append(columns.names[i])
                if isinstance(self.index_label, list) and len(self.index_label) > 1:
                    col_line.extend([''] * (len(self.index_label) - 1))
            col_line.extend(columns._get_level_values(i))
            yield col_line
        if self.encoded_labels and set(self.encoded_labels) != {''}:
            yield (self.encoded_labels + [''] * len(columns))

    def _save_body(self) -> None:
        nrows = len(self.data_index)
        chunks = nrows // self.chunksize + 1
        for i in range(chunks):
            start_i = i * self.chunksize
            end_i = min(start_i + self.chunksize, nrows)
            if start_i >= end_i:
                break
            self._save_chunk(start_i, end_i)

    def _save_chunk(self, start_i: int, end_i: int) -> None:
        slicer = slice(start_i, end_i)
        df = self.obj.iloc[slicer]
        res = df._get_values_for_csv(**self._number_format)
        data = list(res._iter_column_arrays())
        ix = self.data_index[slicer]._get_values_for_csv(**self._number_format) if self.nlevels != 0 else np.empty(end_i - start_i)
        libwriters.write_csv_rows(data, ix, self.nlevels, self.cols, self.writer)

import collections.abc
import inspect
import sys
import types
from dataclasses import _MISSING_TYPE, MISSING, Field, field, fields, make_dataclass
from functools import lru_cache, wraps
from typing import Annotated, Any, Callable, ForwardRef, Literal, Optional, Type, TypeVar, Union, get_args, get_origin, overload
try:
    from typing import NotRequired, Required
except ImportError:
    try:
        from typing_extensions import NotRequired, Required
    except ImportError:
        Required = type('Required', (), {})
        NotRequired = type('NotRequired', (), {})
from .errors import StrictDataclassClassValidationError, StrictDataclassDefinitionError, StrictDataclassFieldValidationError
Validator_T = Callable[[Any], None]
T = TypeVar('T')
TypedDictType = TypeVar('TypedDictType', bound=dict[str, Any])
_TYPED_DICT_DEFAULT_VALUE = object()

@overload
def strict(cls: Type[T]) -> Type[T]:
    ...

@overload
def strict(*, accept_kwargs: bool=False) -> Callable[[Type[T]], Type[T]]:
    ...

def strict(cls: Optional[Type[T]]=None, *, accept_kwargs: bool=False) -> Union[Type[T], Callable[[Type[T]], Type[T]]]:

    def wrap(cls: Type[T]) -> Type[T]:
        if not hasattr(cls, '__dataclass_fields__'):
            raise StrictDataclassDefinitionError(f"Class '{cls.__name__}' must be a dataclass before applying @strict.")
        field_validators: dict[str, list[Validator_T]] = {}
        for f in fields(cls):
            validators = []
            validators.append(_create_type_validator(f))
            custom_validator = f.metadata.get('validator')
            if custom_validator is not None:
                if not isinstance(custom_validator, list):
                    custom_validator = [custom_validator]
                for validator in custom_validator:
                    if not _is_validator(validator):
                        raise StrictDataclassDefinitionError(f"Invalid validator for field '{f.name}': {validator}. Must be a callable taking a single argument.")
                validators.extend(custom_validator)
            field_validators[f.name] = validators
        cls.__validators__ = field_validators
        original_setattr = cls.__setattr__

        def __strict_setattr__(self: Any, name: str, value: Any) -> None:
            for validator in self.__validators__.get(name, []):
                try:
                    validator(value)
                except (ValueError, TypeError) as e:
                    raise StrictDataclassFieldValidationError(field=name, cause=e) from e
            original_setattr(self, name, value)
        cls.__setattr__ = __strict_setattr__
        if accept_kwargs:
            original_init = cls.__init__

            @wraps(original_init)
            def __init__(self, *args, **kwargs: Any) -> None:
                dataclass_fields = {f.name for f in fields(cls)}
                standard_kwargs = {k: v for k, v in kwargs.items() if k in dataclass_fields}
                if len(args) > 0:
                    raise ValueError(f'When `accept_kwargs=True`, {cls.__name__} accepts only keyword arguments, but found `{len(args)}` positional args.')
                for f in fields(cls):
                    if f.name in standard_kwargs:
                        setattr(self, f.name, standard_kwargs[f.name])
                    elif f.default is not MISSING:
                        setattr(self, f.name, f.default)
                    elif f.default_factory is not MISSING:
                        setattr(self, f.name, f.default_factory())
                    else:
                        raise TypeError(f"Missing required field - '{f.name}'")
                additional_kwargs = {}
                for name, value in kwargs.items():
                    if name not in dataclass_fields:
                        additional_kwargs[name] = value
                self.__post_init__(**additional_kwargs)
            cls.__init__ = __init__
            if not hasattr(cls, '__post_init__'):

                def __post_init__(self, **kwargs: Any) -> None:
                    for name, value in kwargs.items():
                        setattr(self, name, value)
                cls.__post_init__ = __post_init__
            original_repr = cls.__repr__

            @wraps(original_repr)
            def __repr__(self) -> str:
                standard_repr = original_repr(self)
                additional_kwargs = [f'*{k}={v!r}' for k, v in self.__dict__.items() if k not in cls.__dataclass_fields__]
                additional_repr = ', '.join(additional_kwargs)
                return f'{standard_repr[:-1]}, {additional_repr})' if additional_kwargs else standard_repr
            if cls.__dataclass_params__.repr is True:
                cls.__repr__ = __repr__
        class_validators = []
        for name in dir(cls):
            if not name.startswith('validate_'):
                continue
            method = getattr(cls, name)
            if not callable(method):
                continue
            if len(inspect.signature(method).parameters) != 1:
                raise StrictDataclassDefinitionError(f"Class '{cls.__name__}' has a class validator '{name}' that takes more than one argument. Class validators must take only 'self' as an argument. Methods starting with 'validate_' are considered to be class validators.")
            class_validators.append(method)
        cls.__class_validators__ = class_validators

        def validate(self: T) -> None:
            for validator in cls.__class_validators__:
                try:
                    validator(self)
                except (ValueError, TypeError) as e:
                    raise StrictDataclassClassValidationError(validator=validator.__name__, cause=e) from e
        validate.__is_defined_by_strict_decorator__ = True
        if hasattr(cls, 'validate'):
            if not getattr(cls.validate, '__is_defined_by_strict_decorator__', False):
                raise StrictDataclassDefinitionError(f"Class '{cls.__name__}' already implements a method called 'validate'. This method name is reserved when using the @strict decorator on a dataclass. If you want to keep your own method, please rename it.")
        cls.validate = validate
        initial_init = cls.__init__

        @wraps(initial_init)
        def init_with_validate(self, *args, **kwargs) -> None:
            initial_init(self, *args, **kwargs)
            cls.validate(self)
        setattr(cls, '__init__', init_with_validate)
        return cls
    return wrap(cls) if cls is not None else wrap

def validate_typed_dict(schema: type[TypedDictType], data: dict) -> None:
    strict_cls = _build_strict_cls_from_typed_dict(schema)
    strict_cls(**data)

@lru_cache
def _build_strict_cls_from_typed_dict(schema: type[TypedDictType]) -> Type:
    type_hints = _get_typed_dict_annotations(schema)
    if not getattr(schema, '__total__', True):
        for key, value in type_hints.items():
            origin = get_origin(value)
            if origin is Annotated:
                base, *meta = get_args(value)
                if not _is_required_or_notrequired(base):
                    base = NotRequired[base]
                type_hints[key] = Annotated[tuple([base] + list(meta))]
            elif not _is_required_or_notrequired(value):
                type_hints[key] = NotRequired[value]
    fields = []
    for key, value in type_hints.items():
        if get_origin(value) is Annotated:
            base, *meta = get_args(value)
            fields.append((key, base, field(default=_TYPED_DICT_DEFAULT_VALUE, metadata={'validator': meta[0]})))
        else:
            fields.append((key, value, field(default=_TYPED_DICT_DEFAULT_VALUE)))
    return strict(make_dataclass(schema.__name__, fields))

def _get_typed_dict_annotations(schema: type[TypedDictType]) -> dict[str, Any]:
    try:
        import annotationlib
        return annotationlib.get_annotations(schema)
    except ImportError:
        return {name: value if value is not None else type(None) for name, value in schema.__dict__.get('__annotations__', {}).items()}

def validated_field(validator: Union[list[Validator_T], Validator_T], default: Union[Any, _MISSING_TYPE]=MISSING, default_factory: Union[Callable[[], Any], _MISSING_TYPE]=MISSING, init: bool=True, repr: bool=True, hash: Optional[bool]=None, compare: bool=True, metadata: Optional[dict]=None, **kwargs: Any) -> Any:
    if not isinstance(validator, list):
        validator = [validator]
    if metadata is None:
        metadata = {}
    metadata['validator'] = validator
    return field(default=default, default_factory=default_factory, init=init, repr=repr, hash=hash, compare=compare, metadata=metadata, **kwargs)

def as_validated_field(validator: Validator_T):

    def _inner(default: Union[Any, _MISSING_TYPE]=MISSING, default_factory: Union[Callable[[], Any], _MISSING_TYPE]=MISSING, init: bool=True, repr: bool=True, hash: Optional[bool]=None, compare: bool=True, metadata: Optional[dict]=None, **kwargs: Any):
        return validated_field(validator, default=default, default_factory=default_factory, init=init, repr=repr, hash=hash, compare=compare, metadata=metadata, **kwargs)
    return _inner

def type_validator(name: str, value: Any, expected_type: Any) -> None:
    origin = get_origin(expected_type)
    args = get_args(expected_type)
    if expected_type is Any:
        return
    elif (validator := _BASIC_TYPE_VALIDATORS.get(origin)):
        validator(name, value, args)
    elif isinstance(expected_type, type):
        _validate_simple_type(name, value, expected_type)
    elif isinstance(expected_type, ForwardRef) or isinstance(expected_type, str):
        return
    elif origin is Required:
        if value is _TYPED_DICT_DEFAULT_VALUE:
            raise TypeError(f"Field '{name}' is required but missing.")
        type_validator(name, value, args[0])
    elif origin is NotRequired:
        if value is _TYPED_DICT_DEFAULT_VALUE:
            return
        type_validator(name, value, args[0])
    else:
        raise TypeError(f"Unsupported type for field '{name}': {expected_type}")

def _validate_union(name: str, value: Any, args: tuple[Any, ...]) -> None:
    errors = []
    for t in args:
        try:
            type_validator(name, value, t)
            return
        except TypeError as e:
            errors.append(str(e))
    raise TypeError(f"Field '{name}' with value {repr(value)} doesn't match any type in {args}. Errors: {'; '.join(errors)}")

def _validate_literal(name: str, value: Any, args: tuple[Any, ...]) -> None:
    if value not in args:
        raise TypeError(f"Field '{name}' expected one of {args}, got {value}")

def _validate_list(name: str, value: Any, args: tuple[Any, ...]) -> None:
    if not isinstance(value, list):
        raise TypeError(f"Field '{name}' expected a list, got {type(value).__name__}")
    item_type = args[0]
    for i, item in enumerate(value):
        try:
            type_validator(f'{name}[{i}]', item, item_type)
        except TypeError as e:
