from __future__ import annotations
import argparse
from collections.abc import Callable
from collections.abc import Mapping
from collections.abc import Sequence
import os
import sys
from typing import Any
from typing import final
from typing import Literal
from typing import NoReturn
from .exceptions import UsageError
import _pytest._io
from _pytest.deprecated import check_ispytest
FILE_OR_DIR = 'file_or_dir'

class NotSet:

    def __repr__(self) -> str:
        return '<notset>'
NOT_SET = NotSet()

@final
class Parser:

    def __init__(self, usage: str | None=None, processopt: Callable[[Argument], None] | None=None, *, _ispytest: bool=False) -> None:
        check_ispytest(_ispytest)
        from _pytest._argcomplete import filescompleter
        self._processopt = processopt
        self.extra_info: dict[str, Any] = {}
        self.optparser = PytestArgumentParser(self, usage, self.extra_info)
        anonymous_arggroup = self.optparser.add_argument_group('Custom options')
        self._anonymous = OptionGroup(anonymous_arggroup, '_anonymous', self, _ispytest=True)
        self._groups = [self._anonymous]
        file_or_dir_arg = self.optparser.add_argument(FILE_OR_DIR, nargs='*')
        file_or_dir_arg.completer = filescompleter
        self._inidict: dict[str, tuple[str, str, Any]] = {}
        self._ini_aliases: dict[str, str] = {}

    @property
    def prog(self) -> str:
        return self.optparser.prog

    @prog.setter
    def prog(self, value: str) -> None:
        self.optparser.prog = value

    def processoption(self, option: Argument) -> None:
        if self._processopt:
            if option.dest:
                self._processopt(option)

    def getgroup(self, name: str, description: str='', after: str | None=None) -> OptionGroup:
        for group in self._groups:
            if group.name == name:
                return group
        arggroup = self.optparser.add_argument_group(description or name)
        group = OptionGroup(arggroup, name, self, _ispytest=True)
        i = 0
        for i, grp in enumerate(self._groups):
            if grp.name == after:
                break
        self._groups.insert(i + 1, group)
        self.optparser._action_groups.insert(i + 1, self.optparser._action_groups.pop())
        return group

    def addoption(self, *opts: str, **attrs: Any) -> None:
        self._anonymous.addoption(*opts, **attrs)

    def parse(self, args: Sequence[str | os.PathLike[str]], namespace: argparse.Namespace | None=None) -> argparse.Namespace:
        from _pytest._argcomplete import try_argcomplete
        try_argcomplete(self.optparser)
        strargs = [os.fspath(x) for x in args]
        if namespace is None:
            namespace = argparse.Namespace()
        try:
            namespace._raise_print_help = True
            return self.optparser.parse_intermixed_args(strargs, namespace=namespace)
        finally:
            del namespace._raise_print_help

    def parse_known_args(self, args: Sequence[str | os.PathLike[str]], namespace: argparse.Namespace | None=None) -> argparse.Namespace:
        return self.parse_known_and_unknown_args(args, namespace=namespace)[0]

    def parse_known_and_unknown_args(self, args: Sequence[str | os.PathLike[str]], namespace: argparse.Namespace | None=None) -> tuple[argparse.Namespace, list[str]]:
        strargs = [os.fspath(x) for x in args]
        if sys.version_info < (3, 12, 8) or (3, 13) <= sys.version_info < (3, 13, 1):
            namespace, unknown = self.optparser.parse_known_args(strargs, namespace)
            assert namespace is not None
            file_or_dir = getattr(namespace, FILE_OR_DIR)
            unknown_flags: list[str] = []
            for arg in unknown:
                (unknown_flags if arg.startswith('-') else file_or_dir).append(arg)
            return (namespace, unknown_flags)
        else:
            return self.optparser.parse_known_intermixed_args(strargs, namespace)

    def addini(self, name: str, help: str, type: Literal['string', 'paths', 'pathlist', 'args', 'linelist', 'bool', 'int', 'float'] | None=None, default: Any=NOT_SET, *, aliases: Sequence[str]=()) -> None:
        assert type in (None, 'string', 'paths', 'pathlist', 'args', 'linelist', 'bool', 'int', 'float')
        if type is None:
            type = 'string'
        if default is NOT_SET:
            default = get_ini_default_for_type(type)
        self._inidict[name] = (help, type, default)
        for alias in aliases:
            if alias in self._inidict:
                raise ValueError(f'alias {alias!r} conflicts with existing configuration option')
            if (already := self._ini_aliases.get(alias)) is not None:
                raise ValueError(f'{alias!r} is already an alias of {already!r}')
            self._ini_aliases[alias] = name

def get_ini_default_for_type(type: Literal['string', 'paths', 'pathlist', 'args', 'linelist', 'bool', 'int', 'float']) -> Any:
    if type in ('paths', 'pathlist', 'args', 'linelist'):
        return []
    elif type == 'bool':
        return False
    elif type == 'int':
        return 0
    elif type == 'float':
        return 0.0
    else:
        return ''

class ArgumentError(Exception):

    def __init__(self, msg: str, option: Argument | str) -> None:
        self.msg = msg
        self.option_id = str(option)

    def __str__(self) -> str:
        if self.option_id:
            return f'option {self.option_id}: {self.msg}'
        else:
            return self.msg

class Argument:

    def __init__(self, *names: str, **attrs: Any) -> None:
        self._attrs = attrs
        self._short_opts: list[str] = []
        self._long_opts: list[str] = []
        try:
            self.type = attrs['type']
        except KeyError:
            pass
        try:
            self.default = attrs['default']
        except KeyError:
            pass
        self._set_opt_strings(names)
        dest: str | None = attrs.get('dest')
        if dest:
            self.dest = dest
        elif self._long_opts:
            self.dest = self._long_opts[0][2:].replace('-', '_')
        else:
            try:
                self.dest = self._short_opts[0][1:]
            except IndexError as e:
                self.dest = '???'
                raise ArgumentError('need a long or short option', self) from e

    def names(self) -> list[str]:
        return self._short_opts + self._long_opts

    def attrs(self) -> Mapping[str, Any]:
        for attr in ('default', 'dest', 'help', self.dest):
            try:
                self._attrs[attr] = getattr(self, attr)
            except AttributeError:
                pass
        return self._attrs

    def _set_opt_strings(self, opts: Sequence[str]) -> None:
        for opt in opts:
            if len(opt) < 2:
                raise ArgumentError(f'invalid option string {opt!r}: must be at least two characters long', self)
            elif len(opt) == 2:
                if not (opt[0] == '-' and opt[1] != '-'):
                    raise ArgumentError(f'invalid short option string {opt!r}: must be of the form -x, (x any non-dash char)', self)
                self._short_opts.append(opt)
            else:
                if not (opt[0:2] == '--' and opt[2] != '-'):
                    raise ArgumentError(f'invalid long option string {opt!r}: must start with --, followed by non-dash', self)
                self._long_opts.append(opt)

    def __repr__(self) -> str:
        args: list[str] = []
        if self._short_opts:
            args += ['_short_opts: ' + repr(self._short_opts)]
        if self._long_opts:
            args += ['_long_opts: ' + repr(self._long_opts)]
        args += ['dest: ' + repr(self.dest)]
        if hasattr(self, 'type'):
            args += ['type: ' + repr(self.type)]
        if hasattr(self, 'default'):
            args += ['default: ' + repr(self.default)]
        return 'Argument({})'.format(', '.join(args))

class OptionGroup:

    def __init__(self, arggroup: argparse._ArgumentGroup, name: str, parser: Parser | None, _ispytest: bool=False) -> None:
        check_ispytest(_ispytest)
        self._arggroup = arggroup
        self.name = name
        self.options: list[Argument] = []
        self.parser = parser

    def addoption(self, *opts: str, **attrs: Any) -> None:
        conflict = set(opts).intersection((name for opt in self.options for name in opt.names()))
        if conflict:
            raise ValueError(f'option names {conflict} already added')
        option = Argument(*opts, **attrs)
        self._addoption_instance(option, shortupper=False)

    def _addoption(self, *opts: str, **attrs: Any) -> None:
        option = Argument(*opts, **attrs)
        self._addoption_instance(option, shortupper=True)

    def _addoption_instance(self, option: Argument, shortupper: bool=False) -> None:
        if not shortupper:
            for opt in option._short_opts:
                if opt[0] == '-' and opt[1].islower():
                    raise ValueError('lowercase shortoptions reserved')
        if self.parser:
            self.parser.processoption(option)
        self._arggroup.add_argument(*option.names(), **option.attrs())
        self.options.append(option)

class PytestArgumentParser(argparse.ArgumentParser):

    def __init__(self, parser: Parser, usage: str | None, extra_info: dict[str, str]) -> None:
        self._parser = parser
        super().__init__(usage=usage, add_help=False, formatter_class=DropShorterLongHelpFormatter, allow_abbrev=False, fromfile_prefix_chars='@')
        self.extra_info = extra_info

    def error(self, message: str) -> NoReturn:
        msg = f'{self.prog}: error: {message}'
        if self.extra_info:
            msg += '\n' + '\n'.join((f'  {k}: {v}' for k, v in sorted(self.extra_info.items())))
        raise UsageError(self.format_usage() + msg)

class DropShorterLongHelpFormatter(argparse.HelpFormatter):

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        if 'width' not in kwargs:
            kwargs['width'] = _pytest._io.get_terminal_width()
        super().__init__(*args, **kwargs)

    def _format_action_invocation(self, action: argparse.Action) -> str:
        orgstr = super()._format_action_invocation(action)
        if orgstr and orgstr[0] != '-':
            return orgstr
        res: str | None = getattr(action, '_formatted_action_invocation', None)
        if res:
            return res
        options = orgstr.split(', ')
        if len(options) == 2 and (len(options[0]) == 2 or len(options[1]) == 2):
            action._formatted_action_invocation = orgstr
            return orgstr
        return_list = []
        short_long: dict[str, str] = {}
        for option in options:
            if len(option) == 2 or option[2] == ' ':
                continue
            if not option.startswith('--'):
                raise ArgumentError(f'long optional argument without "--": [{option}]', option)
            xxoption = option[2:]
            shortened = xxoption.replace('-', '')
            if shortened not in short_long or len(short_long[shortened]) < len(xxoption):
                short_long[shortened] = xxoption
        for option in options:
            if len(option) == 2 or option[2] == ' ':
                return_list.append(option)
            if option[2:] == short_long.get(option.replace('-', '')):
                return_list.append(option.replace(' ', '=', 1))
        formatted_action_invocation = ', '.join(return_list)
        action._formatted_action_invocation = formatted_action_invocation
        return formatted_action_invocation

    def _split_lines(self, text, width):
        import textwrap
        lines = []
        for line in text.splitlines():
            lines.extend(textwrap.wrap(line.strip(), width))
        return lines

class OverrideIniAction(argparse.Action):

    def __init__(self, option_strings: Sequence[str], dest: str, nargs: int | str | None=None, *args, ini_option: str, ini_value: str, **kwargs) -> None:
        super().__init__(option_strings, dest, 0, *args, **kwargs)
        self.ini_option = ini_option
        self.ini_value = ini_value

    def __call__(self, parser: argparse.ArgumentParser, namespace: argparse.Namespace, *args, **kwargs) -> None:
        setattr(namespace, self.dest, True)
        current_overrides = getattr(namespace, 'override_ini', None)
        if current_overrides is None:
            current_overrides = []
        current_overrides.append(f'{self.ini_option}={self.ini_value}')
        setattr(namespace, 'override_ini', current_overrides)

import bisect
import re
import unicodedata
from typing import Optional, Union
from . import idnadata
from .intranges import intranges_contain
_virama_combining_class = 9
_alabel_prefix = b'xn--'
_unicode_dots_re = re.compile('[.。．｡]')

class IDNAError(UnicodeError):
    pass

class IDNABidiError(IDNAError):
    pass

class InvalidCodepoint(IDNAError):
    pass

class InvalidCodepointContext(IDNAError):
    pass

def _combining_class(cp: int) -> int:
    v = unicodedata.combining(chr(cp))
    if v == 0:
        if not unicodedata.name(chr(cp)):
            raise ValueError('Unknown character in unicodedata')
    return v

def _is_script(cp: str, script: str) -> bool:
    return intranges_contain(ord(cp), idnadata.scripts[script])

def _punycode(s: str) -> bytes:
    return s.encode('punycode')

def _unot(s: int) -> str:
    return 'U+{:04X}'.format(s)

def valid_label_length(label: Union[bytes, str]) -> bool:
    if len(label) > 63:
        return False
    return True

def valid_string_length(label: Union[bytes, str], trailing_dot: bool) -> bool:
    if len(label) > (254 if trailing_dot else 253):
        return False
    return True

def check_bidi(label: str, check_ltr: bool=False) -> bool:
    bidi_label = False
    for idx, cp in enumerate(label, 1):
        direction = unicodedata.bidirectional(cp)
        if direction == '':
            raise IDNABidiError('Unknown directionality in label {} at position {}'.format(repr(label), idx))
        if direction in ['R', 'AL', 'AN']:
            bidi_label = True
    if not bidi_label and (not check_ltr):
        return True
    direction = unicodedata.bidirectional(label[0])
    if direction in ['R', 'AL']:
        rtl = True
    elif direction == 'L':
        rtl = False
    else:
        raise IDNABidiError('First codepoint in label {} must be directionality L, R or AL'.format(repr(label)))
    valid_ending = False
    number_type: Optional[str] = None
    for idx, cp in enumerate(label, 1):
        direction = unicodedata.bidirectional(cp)
        if rtl:
            if direction not in ['R', 'AL', 'AN', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise IDNABidiError('Invalid direction for codepoint at position {} in a right-to-left label'.format(idx))
            if direction in ['R', 'AL', 'EN', 'AN']:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False
            if direction in ['AN', 'EN']:
                if not number_type:
                    number_type = direction
                elif number_type != direction:
                    raise IDNABidiError('Can not mix numeral types in a right-to-left label')
        else:
            if direction not in ['L', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise IDNABidiError('Invalid direction for codepoint at position {} in a left-to-right label'.format(idx))
            if direction in ['L', 'EN']:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False
    if not valid_ending:
        raise IDNABidiError('Label ends with illegal codepoint directionality')
    return True

def check_initial_combiner(label: str) -> bool:
    if unicodedata.category(label[0])[0] == 'M':
        raise IDNAError('Label begins with an illegal combining character')
    return True

def check_hyphen_ok(label: str) -> bool:
    if label[2:4] == '--':
        raise IDNAError('Label has disallowed hyphens in 3rd and 4th position')
    if label[0] == '-' or label[-1] == '-':
        raise IDNAError('Label must not start or end with a hyphen')
    return True

def check_nfc(label: str) -> None:
    if unicodedata.normalize('NFC', label) != label:
        raise IDNAError('Label must be in Normalization Form C')

def valid_contextj(label: str, pos: int) -> bool:
    cp_value = ord(label[pos])
    if cp_value == 8204:
        if pos > 0:
            if _combining_class(ord(label[pos - 1])) == _virama_combining_class:
                return True
        ok = False
        for i in range(pos - 1, -1, -1):
            joining_type = idnadata.joining_types.get(ord(label[i]))
            if joining_type == ord('T'):
                continue
            elif joining_type in [ord('L'), ord('D')]:
                ok = True
                break
            else:
                break
        if not ok:
            return False
        ok = False
        for i in range(pos + 1, len(label)):
            joining_type = idnadata.joining_types.get(ord(label[i]))
            if joining_type == ord('T'):
                continue
            elif joining_type in [ord('R'), ord('D')]:
                ok = True
                break
            else:
                break
        return ok
    if cp_value == 8205:
        if pos > 0:
            if _combining_class(ord(label[pos - 1])) == _virama_combining_class:
                return True
        return False
    else:
        return False

def valid_contexto(label: str, pos: int, exception: bool=False) -> bool:
    cp_value = ord(label[pos])
    if cp_value == 183:
        if 0 < pos < len(label) - 1:
            if ord(label[pos - 1]) == 108 and ord(label[pos + 1]) == 108:
                return True
        return False
    elif cp_value == 885:
        if pos < len(label) - 1 and len(label) > 1:
            return _is_script(label[pos + 1], 'Greek')
        return False
    elif cp_value == 1523 or cp_value == 1524:
        if pos > 0:
            return _is_script(label[pos - 1], 'Hebrew')
        return False
    elif cp_value == 12539:
        for cp in label:
            if cp == '・':
                continue
            if _is_script(cp, 'Hiragana') or _is_script(cp, 'Katakana') or _is_script(cp, 'Han'):
                return True
        return False
    elif 1632 <= cp_value <= 1641:
        for cp in label:
            if 1776 <= ord(cp) <= 1785:
                return False
        return True
    elif 1776 <= cp_value <= 1785:
        for cp in label:
            if 1632 <= ord(cp) <= 1641:
                return False
        return True
    return False

def check_label(label: Union[str, bytes, bytearray]) -> None:
    if isinstance(label, (bytes, bytearray)):
        label = label.decode('utf-8')
    if len(label) == 0:
        raise IDNAError('Empty Label')
    check_nfc(label)
    check_hyphen_ok(label)
    check_initial_combiner(label)
    for pos, cp in enumerate(label):
        cp_value = ord(cp)
        if intranges_contain(cp_value, idnadata.codepoint_classes['PVALID']):
            continue
        elif intranges_contain(cp_value, idnadata.codepoint_classes['CONTEXTJ']):
            try:
                if not valid_contextj(label, pos):
                    raise InvalidCodepointContext('Joiner {} not allowed at position {} in {}'.format(_unot(cp_value), pos + 1, repr(label)))
            except ValueError:
                raise IDNAError('Unknown codepoint adjacent to joiner {} at position {} in {}'.format(_unot(cp_value), pos + 1, repr(label)))
        elif intranges_contain(cp_value, idnadata.codepoint_classes['CONTEXTO']):
            if not valid_contexto(label, pos):
                raise InvalidCodepointContext('Codepoint {} not allowed at position {} in {}'.format(_unot(cp_value), pos + 1, repr(label)))
        else:
            raise InvalidCodepoint('Codepoint {} at position {} of {} not allowed'.format(_unot(cp_value), pos + 1, repr(label)))
    check_bidi(label)

def alabel(label: str) -> bytes:
    try:
        label_bytes = label.encode('ascii')
        ulabel(label_bytes)
        if not valid_label_length(label_bytes):
            raise IDNAError('Label too long')
        return label_bytes
    except UnicodeEncodeError:
        pass
    check_label(label)
    label_bytes = _alabel_prefix + _punycode(label)
    if not valid_label_length(label_bytes):
        raise IDNAError('Label too long')
    return label_bytes

def ulabel(label: Union[str, bytes, bytearray]) -> str:
    if not isinstance(label, (bytes, bytearray)):
        try:
            label_bytes = label.encode('ascii')
        except UnicodeEncodeError:
            check_label(label)
            return label
    else:
        label_bytes = bytes(label)
    label_bytes = label_bytes.lower()
    if label_bytes.startswith(_alabel_prefix):
        label_bytes = label_bytes[len(_alabel_prefix):]
        if not label_bytes:
            raise IDNAError('Malformed A-label, no Punycode eligible content found')
        if label_bytes.decode('ascii')[-1] == '-':
            raise IDNAError('A-label must not end with a hyphen')
    else:
        check_label(label_bytes)
        return label_bytes.decode('ascii')
    try:
        label = label_bytes.decode('punycode')
    except UnicodeError:
        raise IDNAError('Invalid A-label')
    check_label(label)
    return label

def uts46_remap(domain: str, std3_rules: bool=True, transitional: bool=False) -> str:
    from .uts46data import uts46data
    output = ''
    for pos, char in enumerate(domain):
        code_point = ord(char)
        try:
            uts46row = uts46data[code_point if code_point < 256 else bisect.bisect_left(uts46data, (code_point, 'Z')) - 1]
            status = uts46row[1]
            replacement: Optional[str] = None
            if len(uts46row) == 3:
                replacement = uts46row[2]
            if status == 'V' or (status == 'D' and (not transitional)) or (status == '3' and (not std3_rules) and (replacement is None)):
                output += char
            elif replacement is not None and (status == 'M' or (status == '3' and (not std3_rules)) or (status == 'D' and transitional)):
                output += replacement
            elif status != 'I':
                raise IndexError()
        except IndexError:
            raise InvalidCodepoint('Codepoint {} not allowed at position {} in {}'.format(_unot(code_point), pos + 1, repr(domain)))
    return unicodedata.normalize('NFC', output)

def encode(s: Union[str, bytes, bytearray], strict: bool=False, uts46: bool=False, std3_rules: bool=False, transitional: bool=False) -> bytes:
    if not isinstance(s, str):
        try:
            s = str(s, 'ascii')
        except UnicodeDecodeError:
            raise IDNAError('should pass a unicode string to the function rather than a byte string.')
    if uts46:
        s = uts46_remap(s, std3_rules, transitional)
    trailing_dot = False
    result = []
    if strict:
        labels = s.split('.')
    else:
        labels = _unicode_dots_re.split(s)
    if not labels or labels == ['']:
        raise IDNAError('Empty domain')
    if labels[-1] == '':
        del labels[-1]
        trailing_dot = True
    for label in labels:
        s = alabel(label)
        if s:
            result.append(s)
        else:
            raise IDNAError('Empty label')
    if trailing_dot:
        result.append(b'')
    s = b'.'.join(result)
    if not valid_string_length(s, trailing_dot):
        raise IDNAError('Domain too long')
    return s

def decode(s: Union[str, bytes, bytearray], strict: bool=False, uts46: bool=False, std3_rules: bool=False) -> str:
    try:
        if not isinstance(s, str):
            s = str(s, 'ascii')
    except UnicodeDecodeError:
        raise IDNAError('Invalid ASCII in A-label')
    if uts46:
        s = uts46_remap(s, std3_rules, False)
    trailing_dot = False
    result = []
    if not strict:
        labels = _unicode_dots_re.split(s)
    else:
        labels = s.split('.')
    if not labels or labels == ['']:
        raise IDNAError('Empty domain')
    if not labels[-1]:
        del labels[-1]
        trailing_dot = True
    for label in labels:
        s = ulabel(label)
        if s:
            result.append(s)
        else:
            raise IDNAError('Empty label')
    if trailing_dot:
        result.append('')
    return '.'.join(result)

from __future__ import annotations
from collections.abc import Iterable
from collections.abc import Sequence
from dataclasses import dataclass
from dataclasses import KW_ONLY
import os
from pathlib import Path
import sys
from typing import Literal
from typing import TypeAlias
import iniconfig
from .exceptions import UsageError
from _pytest.outcomes import fail
from _pytest.pathlib import absolutepath
from _pytest.pathlib import commonpath
from _pytest.pathlib import safe_exists

@dataclass(frozen=True)
class ConfigValue:
    value: object
    _: KW_ONLY
    origin: Literal['file', 'override']
    mode: Literal['ini', 'toml']
ConfigDict: TypeAlias = dict[str, ConfigValue]

def _parse_ini_config(path: Path) -> iniconfig.IniConfig:
    try:
        return iniconfig.IniConfig(str(path))
    except iniconfig.ParseError as exc:
        raise UsageError(str(exc)) from exc

def load_config_dict_from_file(filepath: Path) -> ConfigDict | None:
    if filepath.suffix == '.ini':
        iniconfig = _parse_ini_config(filepath)
        if 'pytest' in iniconfig:
            return {k: ConfigValue(v, origin='file', mode='ini') for k, v in iniconfig['pytest'].items()}
        elif filepath.name in {'pytest.ini', '.pytest.ini'}:
            return {}
    elif filepath.suffix == '.cfg':
        iniconfig = _parse_ini_config(filepath)
        if 'tool:pytest' in iniconfig.sections:
            return {k: ConfigValue(v, origin='file', mode='ini') for k, v in iniconfig['tool:pytest'].items()}
        elif 'pytest' in iniconfig.sections:
            fail(CFG_PYTEST_SECTION.format(filename='setup.cfg'), pytrace=False)
    elif filepath.suffix == '.toml':
        if sys.version_info >= (3, 11):
            import tomllib
        else:
            import tomli as tomllib
        toml_text = filepath.read_text(encoding='utf-8')
        try:
            config = tomllib.loads(toml_text)
        except tomllib.TOMLDecodeError as exc:
            raise UsageError(f'{filepath}: {exc}') from exc
        if filepath.name in ('pytest.toml', '.pytest.toml'):
            pytest_config = config.get('pytest', {})
            if pytest_config:
                return {k: ConfigValue(v, origin='file', mode='toml') for k, v in pytest_config.items()}
            return {}
        else:
            tool_pytest = config.get('tool', {}).get('pytest', {})
            toml_config = {k: v for k, v in tool_pytest.items() if k != 'ini_options'}
            ini_config = tool_pytest.get('ini_options', None)
            if toml_config and ini_config:
                raise UsageError(f'{filepath}: Cannot use both [tool.pytest] (native TOML types) and [tool.pytest.ini_options] (string-based INI format) simultaneously. Please use [tool.pytest] with native TOML types (recommended) or [tool.pytest.ini_options] for backwards compatibility.')
            if toml_config:
                return {k: ConfigValue(v, origin='file', mode='toml') for k, v in toml_config.items()}
            elif ini_config is not None:

                def make_scalar(v: object) -> str | list[str]:
                    return v if isinstance(v, list) else str(v)
                return {k: ConfigValue(make_scalar(v), origin='file', mode='ini') for k, v in ini_config.items()}
    return None

def locate_config(invocation_dir: Path, args: Iterable[Path]) -> tuple[Path | None, Path | None, ConfigDict, Sequence[str]]:
    config_names = ['pytest.toml', '.pytest.toml', 'pytest.ini', '.pytest.ini', 'pyproject.toml', 'tox.ini', 'setup.cfg']
    args = [x for x in args if not str(x).startswith('-')]
    if not args:
        args = [invocation_dir]
    found_pyproject_toml: Path | None = None
    ignored_config_files: list[str] = []
    for arg in args:
        argpath = absolutepath(arg)
        for base in (argpath, *argpath.parents):
            for config_name in config_names:
                p = base / config_name
                if p.is_file():
                    if p.name == 'pyproject.toml' and found_pyproject_toml is None:
                        found_pyproject_toml = p
                    ini_config = load_config_dict_from_file(p)
                    if ini_config is not None:
                        index = config_names.index(config_name)
                        for remainder in config_names[index + 1:]:
                            p2 = base / remainder
                            if p2.is_file() and load_config_dict_from_file(p2) is not None:
                                ignored_config_files.append(remainder)
                        return (base, p, ini_config, ignored_config_files)
    if found_pyproject_toml is not None:
        return (found_pyproject_toml.parent, found_pyproject_toml, {}, [])
    return (None, None, {}, [])

def get_common_ancestor(invocation_dir: Path, paths: Iterable[Path]) -> Path:
    common_ancestor: Path | None = None
    for path in paths:
        if not path.exists():
            continue
        if common_ancestor is None:
            common_ancestor = path
        elif common_ancestor in path.parents or path == common_ancestor:
            continue
        elif path in common_ancestor.parents:
            common_ancestor = path
        else:
            shared = commonpath(path, common_ancestor)
            if shared is not None:
                common_ancestor = shared
    if common_ancestor is None:
        common_ancestor = invocation_dir
    elif common_ancestor.is_file():
        common_ancestor = common_ancestor.parent
    return common_ancestor

def get_dirs_from_args(args: Iterable[str]) -> list[Path]:

    def is_option(x: str) -> bool:
        return x.startswith('-')

    def get_file_part_from_node_id(x: str) -> str:
        return x.split('::')[0]

    def get_dir_from_path(path: Path) -> Path:
        if path.is_dir():
            return path
        return path.parent
    possible_paths = (absolutepath(get_file_part_from_node_id(arg)) for arg in args if not is_option(arg))
    return [get_dir_from_path(path) for path in possible_paths if safe_exists(path)]

def parse_override_ini(override_ini: Sequence[str] | None) -> ConfigDict:
    overrides = {}
    for ini_config in override_ini or ():
        try:
            key, user_ini_value = ini_config.split('=', 1)
        except ValueError as e:
            raise UsageError(f'-o/--override-ini expects option=value style (got: {ini_config!r}).') from e
        else:
            overrides[key] = ConfigValue(user_ini_value, origin='override', mode='ini')
    return overrides
CFG_PYTEST_SECTION = '[pytest] section in {filename} files is no longer supported, change to [tool:pytest] instead.'

def determine_setup(*, inifile: str | None, override_ini: Sequence[str] | None, args: Sequence[str], rootdir_cmd_arg: str | None, invocation_dir: Path) -> tuple[Path, Path | None, ConfigDict, Sequence[str]]:
    rootdir = None
    dirs = get_dirs_from_args(args)
    ignored_config_files: Sequence[str] = []
    if inifile:
        inipath_ = absolutepath(inifile)
        inipath: Path | None = inipath_
        inicfg = load_config_dict_from_file(inipath_) or {}
        if rootdir_cmd_arg is None:
            rootdir = inipath_.parent
    else:
        ancestor = get_common_ancestor(invocation_dir, dirs)
        rootdir, inipath, inicfg, ignored_config_files = locate_config(invocation_dir, [ancestor])
        if rootdir is None and rootdir_cmd_arg is None:
            for possible_rootdir in (ancestor, *ancestor.parents):
                if (possible_rootdir / 'setup.py').is_file():
                    rootdir = possible_rootdir
                    break
            else:
                if dirs != [ancestor]:
                    rootdir, inipath, inicfg, _ = locate_config(invocation_dir, dirs)
                if rootdir is None:
                    rootdir = get_common_ancestor(invocation_dir, [invocation_dir, ancestor])
                    if is_fs_root(rootdir):
                        rootdir = ancestor
    if rootdir_cmd_arg:
        rootdir = absolutepath(os.path.expandvars(rootdir_cmd_arg))
        if not rootdir.is_dir():
            raise UsageError(f"Directory '{rootdir}' not found. Check your '--rootdir' option.")
    ini_overrides = parse_override_ini(override_ini)
    inicfg.update(ini_overrides)
    assert rootdir is not None
    return (rootdir, inipath, inicfg, ignored_config_files)

def is_fs_root(p: Path) -> bool:
    return os.path.splitdrive(str(p))[1] == os.sep

from datetime import datetime, timedelta, time, date
import calendar
from dateutil import tz
from functools import wraps
import re
import six
__all__ = ['isoparse', 'isoparser']

def _takes_ascii(f):

    @wraps(f)
    def func(self, str_in, *args, **kwargs):
        str_in = getattr(str_in, 'read', lambda: str_in)()
        if isinstance(str_in, six.text_type):
            try:
                str_in = str_in.encode('ascii')
            except UnicodeEncodeError as e:
                msg = 'ISO-8601 strings should contain only ASCII characters'
                six.raise_from(ValueError(msg), e)
        return f(self, str_in, *args, **kwargs)
    return func

class isoparser(object):

    def __init__(self, sep=None):
        if sep is not None:
            if len(sep) != 1 or ord(sep) >= 128 or sep in '0123456789':
                raise ValueError('Separator must be a single, non-numeric ' + 'ASCII character')
            sep = sep.encode('ascii')
        self._sep = sep

    @_takes_ascii
    def isoparse(self, dt_str):
        components, pos = self._parse_isodate(dt_str)
        if len(dt_str) > pos:
            if self._sep is None or dt_str[pos:pos + 1] == self._sep:
                components += self._parse_isotime(dt_str[pos + 1:])
            else:
                raise ValueError('String contains unknown ISO components')
        if len(components) > 3 and components[3] == 24:
            components[3] = 0
            return datetime(*components) + timedelta(days=1)
        return datetime(*components)

    @_takes_ascii
    def parse_isodate(self, datestr):
        components, pos = self._parse_isodate(datestr)
        if pos < len(datestr):
            raise ValueError('String contains unknown ISO ' + 'components: {!r}'.format(datestr.decode('ascii')))
        return date(*components)

    @_takes_ascii
    def parse_isotime(self, timestr):
        components = self._parse_isotime(timestr)
        if components[0] == 24:
            components[0] = 0
        return time(*components)

    @_takes_ascii
    def parse_tzstr(self, tzstr, zero_as_utc=True):
        return self._parse_tzstr(tzstr, zero_as_utc=zero_as_utc)
    _DATE_SEP = b'-'
    _TIME_SEP = b':'
    _FRACTION_REGEX = re.compile(b'[\\.,]([0-9]+)')

    def _parse_isodate(self, dt_str):
        try:
            return self._parse_isodate_common(dt_str)
        except ValueError:
            return self._parse_isodate_uncommon(dt_str)

    def _parse_isodate_common(self, dt_str):
        len_str = len(dt_str)
        components = [1, 1, 1]
        if len_str < 4:
            raise ValueError('ISO string too short')
        components[0] = int(dt_str[0:4])
        pos = 4
        if pos >= len_str:
            return (components, pos)
        has_sep = dt_str[pos:pos + 1] == self._DATE_SEP
        if has_sep:
            pos += 1
        if len_str - pos < 2:
            raise ValueError('Invalid common month')
        components[1] = int(dt_str[pos:pos + 2])
        pos += 2
        if pos >= len_str:
            if has_sep:
                return (components, pos)
            else:
                raise ValueError('Invalid ISO format')
        if has_sep:
            if dt_str[pos:pos + 1] != self._DATE_SEP:
                raise ValueError('Invalid separator in ISO string')
            pos += 1
        if len_str - pos < 2:
            raise ValueError('Invalid common day')
        components[2] = int(dt_str[pos:pos + 2])
        return (components, pos + 2)

    def _parse_isodate_uncommon(self, dt_str):
        if len(dt_str) < 4:
            raise ValueError('ISO string too short')
        year = int(dt_str[0:4])
        has_sep = dt_str[4:5] == self._DATE_SEP
        pos = 4 + has_sep
        if dt_str[pos:pos + 1] == b'W':
            pos += 1
            weekno = int(dt_str[pos:pos + 2])
            pos += 2
            dayno = 1
            if len(dt_str) > pos:
                if (dt_str[pos:pos + 1] == self._DATE_SEP) != has_sep:
                    raise ValueError('Inconsistent use of dash separator')
                pos += has_sep
                dayno = int(dt_str[pos:pos + 1])
                pos += 1
            base_date = self._calculate_weekdate(year, weekno, dayno)
        else:
            if len(dt_str) - pos < 3:
                raise ValueError('Invalid ordinal day')
            ordinal_day = int(dt_str[pos:pos + 3])
            pos += 3
            if ordinal_day < 1 or ordinal_day > 365 + calendar.isleap(year):
                raise ValueError('Invalid ordinal day' + ' {} for year {}'.format(ordinal_day, year))
            base_date = date(year, 1, 1) + timedelta(days=ordinal_day - 1)
        components = [base_date.year, base_date.month, base_date.day]
        return (components, pos)

    def _calculate_weekdate(self, year, week, day):
        if not 0 < week < 54:
            raise ValueError('Invalid week: {}'.format(week))
        if not 0 < day < 8:
            raise ValueError('Invalid weekday: {}'.format(day))
        jan_4 = date(year, 1, 4)
        week_1 = jan_4 - timedelta(days=jan_4.isocalendar()[2] - 1)
        week_offset = (week - 1) * 7 + (day - 1)
        return week_1 + timedelta(days=week_offset)

    def _parse_isotime(self, timestr):
        len_str = len(timestr)
        components = [0, 0, 0, 0, None]
        pos = 0
        comp = -1
        if len_str < 2:
            raise ValueError('ISO time too short')
        has_sep = False
        while pos < len_str and comp < 5:
            comp += 1
            if timestr[pos:pos + 1] in b'-+Zz':
                components[-1] = self._parse_tzstr(timestr[pos:])
                pos = len_str
                break
            if comp == 1 and timestr[pos:pos + 1] == self._TIME_SEP:
                has_sep = True
                pos += 1
            elif comp == 2 and has_sep:
                if timestr[pos:pos + 1] != self._TIME_SEP:
                    raise ValueError('Inconsistent use of colon separator')
                pos += 1
            if comp < 3:
                components[comp] = int(timestr[pos:pos + 2])
                pos += 2
            if comp == 3:
                frac = self._FRACTION_REGEX.match(timestr[pos:])
                if not frac:
                    continue
                us_str = frac.group(1)[:6]
                components[comp] = int(us_str) * 10 ** (6 - len(us_str))
                pos += len(frac.group())
        if pos < len_str:
            raise ValueError('Unused components in ISO string')
        if components[0] == 24:
            if any((component != 0 for component in components[1:4])):
                raise ValueError('Hour may only be 24 at 24:00:00.000')
        return components

    def _parse_tzstr(self, tzstr, zero_as_utc=True):
        if tzstr == b'Z' or tzstr == b'z':
            return tz.UTC
        if len(tzstr) not in {3, 5, 6}:
            raise ValueError('Time zone offset must be 1, 3, 5 or 6 characters')
        if tzstr[0:1] == b'-':
            mult = -1
        elif tzstr[0:1] == b'+':
            mult = 1
        else:
            raise ValueError('Time zone offset requires sign')
        hours = int(tzstr[1:3])
        if len(tzstr) == 3:
            minutes = 0
        else:
            minutes = int(tzstr[4 if tzstr[3:4] == self._TIME_SEP else 3:])
        if zero_as_utc and hours == 0 and (minutes == 0):
            return tz.UTC
        else:
            if minutes > 59:
                raise ValueError('Invalid minutes in time zone offset')
            if hours > 23:
                raise ValueError('Invalid hours in time zone offset')
            return tz.tzoffset(None, mult * (hours * 60 + minutes) * 60)
DEFAULT_ISOPARSER = isoparser()
isoparse = DEFAULT_ISOPARSER.isoparse

from __future__ import annotations
import tokenize
from typing import TYPE_CHECKING, Any
import warnings
from pandas.util._decorators import set_module
from pandas.util._exceptions import find_stack_level
from pandas.util._validators import validate_bool_kwarg
from pandas.core.dtypes.common import is_extension_array_dtype, is_string_dtype
from pandas.core.computation.engines import ENGINES
from pandas.core.computation.expr import PARSERS, Expr
from pandas.core.computation.parsing import tokenize_string
from pandas.core.computation.scope import ensure_scope
from pandas.core.generic import NDFrame
from pandas.io.formats.printing import pprint_thing
if TYPE_CHECKING:
    from pandas.core.computation.ops import BinOp

def _check_engine(engine: str | None) -> str:
    from pandas.core.computation.check import NUMEXPR_INSTALLED
    from pandas.core.computation.expressions import USE_NUMEXPR
    if engine is None:
        engine = 'numexpr' if USE_NUMEXPR else 'python'
    if engine not in ENGINES:
        valid_engines = list(ENGINES.keys())
        raise KeyError(f"Invalid engine '{engine}' passed, valid engines are {valid_engines}")
    if engine == 'numexpr' and (not NUMEXPR_INSTALLED):
        raise ImportError("'numexpr' is not installed or an unsupported version. Cannot use engine='numexpr' for query/eval if 'numexpr' is not installed")
    return engine

def _check_parser(parser: str) -> None:
    if parser not in PARSERS:
        raise KeyError(f"Invalid parser '{parser}' passed, valid parsers are {PARSERS.keys()}")

def _check_resolvers(resolvers) -> None:
    if resolvers is not None:
        for resolver in resolvers:
            if not hasattr(resolver, '__getitem__'):
                name = type(resolver).__name__
                raise TypeError(f"Resolver of type '{name}' does not implement the __getitem__ method")

def _check_expression(expr) -> None:
    if not expr:
        raise ValueError('expr cannot be an empty string')

def _convert_expression(expr) -> str:
    s = pprint_thing(expr)
    _check_expression(s)
    return s

def _check_for_locals(expr: str, stack_level: int, parser: str) -> None:
    at_top_of_stack = stack_level == 0
    not_pandas_parser = parser != 'pandas'
    if not_pandas_parser:
        msg = "The '@' prefix is only supported by the pandas parser"
    elif at_top_of_stack:
        msg = "The '@' prefix is not allowed in top-level eval calls.\nplease refer to your variables by name without the '@' prefix."
    if at_top_of_stack or not_pandas_parser:
        for toknum, tokval in tokenize_string(expr):
            if toknum == tokenize.OP and tokval == '@':
                raise SyntaxError(msg)

@set_module('pandas')
def eval(expr: str | BinOp, parser: str='pandas', engine: str | None=None, local_dict=None, global_dict=None, resolvers=(), level: int=0, target=None, inplace: bool=False) -> Any:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    exprs: list[str | BinOp]
    if isinstance(expr, str):
        _check_expression(expr)
        exprs = [e.strip() for e in expr.splitlines() if e.strip() != '']
    else:
        exprs = [expr]
    multi_line = len(exprs) > 1
    if multi_line and target is None:
        raise ValueError('multi-line expressions are only valid in the context of data, use DataFrame.eval')
    engine = _check_engine(engine)
    _check_parser(parser)
    _check_resolvers(resolvers)
    ret = None
    first_expr = True
    target_modified = False
    for expr in exprs:
        expr = _convert_expression(expr)
        _check_for_locals(expr, level, parser)
        env = ensure_scope(level + 1, global_dict=global_dict, local_dict=local_dict, resolvers=resolvers, target=target)
        parsed_expr = Expr(expr, engine=engine, parser=parser, env=env)
        if engine == 'numexpr' and (is_extension_array_dtype(parsed_expr.terms.return_type) and (not is_string_dtype(parsed_expr.terms.return_type)) or (getattr(parsed_expr.terms, 'operand_types', None) is not None and any((is_extension_array_dtype(elem) and (not is_string_dtype(elem)) for elem in parsed_expr.terms.operand_types)))):
            warnings.warn("Engine has switched to 'python' because numexpr does not support extension array dtypes. Please set your engine to python manually.", RuntimeWarning, stacklevel=find_stack_level())
            engine = 'python'
        eng = ENGINES[engine]
        eng_inst = eng(parsed_expr)
        ret = eng_inst.evaluate()
        if parsed_expr.assigner is None:
            if multi_line:
                raise ValueError('Multi-line expressions are only valid if all expressions contain an assignment')
            if inplace:
                raise ValueError('Cannot operate inplace if there is no assignment')
        assigner = parsed_expr.assigner
        if env.target is not None and assigner is not None:
            target_modified = True
            if not inplace and first_expr:
                try:
                    target = env.target
                    if isinstance(target, NDFrame):
                        target = target.copy(deep=False)
                    else:
                        target = target.copy()
                except AttributeError as err:
                    raise ValueError('Cannot return a copy of the target') from err
            else:
                target = env.target
            try:
                if inplace and isinstance(target, NDFrame):
                    target.loc[:, assigner] = ret
                else:
                    target[assigner] = ret
            except (TypeError, IndexError) as err:
                raise ValueError('Cannot assign expression output to target') from err
            if not resolvers:
                resolvers = ({assigner: ret},)
            else:
                for resolver in resolvers:
                    if assigner in resolver:
                        resolver[assigner] = ret
                        break
                else:
                    resolvers += ({assigner: ret},)
            ret = None
            first_expr = False
    if inplace is False:
        return target if target_modified else ret

from __future__ import annotations
import ipaddress
import re
import typing
import idna
from ._exceptions import InvalidURL
MAX_URL_LENGTH = 65536
UNRESERVED_CHARACTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~'
SUB_DELIMS = "!$&'()*+,;="
PERCENT_ENCODED_REGEX = re.compile('%[A-Fa-f0-9]{2}')
FRAG_SAFE = ''.join([chr(i) for i in range(32, 127) if i not in (32, 34, 60, 62, 96)])
QUERY_SAFE = ''.join([chr(i) for i in range(32, 127) if i not in (32, 34, 35, 60, 62)])
PATH_SAFE = ''.join([chr(i) for i in range(32, 127) if i not in (32, 34, 35, 60, 62) + (63, 96, 123, 125)])
USERNAME_SAFE = ''.join([chr(i) for i in range(32, 127) if i not in (32, 34, 35, 60, 62) + (63, 96, 123, 125) + (47, 58, 59, 61, 64, 91, 92, 93, 94, 124)])
PASSWORD_SAFE = ''.join([chr(i) for i in range(32, 127) if i not in (32, 34, 35, 60, 62) + (63, 96, 123, 125) + (47, 58, 59, 61, 64, 91, 92, 93, 94, 124)])
USERINFO_SAFE = ''.join([chr(i) for i in range(32, 127) if i not in (32, 34, 35, 60, 62) + (63, 96, 123, 125) + (47, 59, 61, 64, 91, 92, 93, 94, 124)])
URL_REGEX = re.compile('(?:(?P<scheme>{scheme}):)?(?://(?P<authority>{authority}))?(?P<path>{path})(?:\\?(?P<query>{query}))?(?:#(?P<fragment>{fragment}))?'.format(scheme='([a-zA-Z][a-zA-Z0-9+.-]*)?', authority='[^/?#]*', path='[^?#]*', query='[^#]*', fragment='.*'))
AUTHORITY_REGEX = re.compile('(?:(?P<userinfo>{userinfo})@)?(?P<host>{host}):?(?P<port>{port})?'.format(userinfo='.*', host='(\\[.*\\]|[^:@]*)', port='.*'))
COMPONENT_REGEX = {'scheme': re.compile('([a-zA-Z][a-zA-Z0-9+.-]*)?'), 'authority': re.compile('[^/?#]*'), 'path': re.compile('[^?#]*'), 'query': re.compile('[^#]*'), 'fragment': re.compile('.*'), 'userinfo': re.compile('[^@]*'), 'host': re.compile('(\\[.*\\]|[^:]*)'), 'port': re.compile('.*')}
IPv4_STYLE_HOSTNAME = re.compile('^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+$')
IPv6_STYLE_HOSTNAME = re.compile('^\\[.*\\]$')

class ParseResult(typing.NamedTuple):
    scheme: str
    userinfo: str
    host: str
    port: int | None
    path: str
    query: str | None
    fragment: str | None

    @property
    def authority(self) -> str:
        return ''.join([f'{self.userinfo}@' if self.userinfo else '', f'[{self.host}]' if ':' in self.host else self.host, f':{self.port}' if self.port is not None else ''])

    @property
    def netloc(self) -> str:
        return ''.join([f'[{self.host}]' if ':' in self.host else self.host, f':{self.port}' if self.port is not None else ''])

    def copy_with(self, **kwargs: str | None) -> ParseResult:
        if not kwargs:
            return self
        defaults = {'scheme': self.scheme, 'authority': self.authority, 'path': self.path, 'query': self.query, 'fragment': self.fragment}
        defaults.update(kwargs)
        return urlparse('', **defaults)

    def __str__(self) -> str:
        authority = self.authority
        return ''.join([f'{self.scheme}:' if self.scheme else '', f'//{authority}' if authority else '', self.path, f'?{self.query}' if self.query is not None else '', f'#{self.fragment}' if self.fragment is not None else ''])

def urlparse(url: str='', **kwargs: str | None) -> ParseResult:
    if len(url) > MAX_URL_LENGTH:
        raise InvalidURL('URL too long')
    if any((char.isascii() and (not char.isprintable()) for char in url)):
        char = next((char for char in url if char.isascii() and (not char.isprintable())))
        idx = url.find(char)
        error = f'Invalid non-printable ASCII character in URL, {char!r} at position {idx}.'
        raise InvalidURL(error)
    if 'port' in kwargs:
        port = kwargs['port']
        kwargs['port'] = str(port) if isinstance(port, int) else port
    if 'netloc' in kwargs:
        netloc = kwargs.pop('netloc') or ''
        kwargs['host'], _, kwargs['port'] = netloc.partition(':')
    if 'username' in kwargs or 'password' in kwargs:
        username = quote(kwargs.pop('username', '') or '', safe=USERNAME_SAFE)
        password = quote(kwargs.pop('password', '') or '', safe=PASSWORD_SAFE)
        kwargs['userinfo'] = f'{username}:{password}' if password else username
    if 'raw_path' in kwargs:
        raw_path = kwargs.pop('raw_path') or ''
        kwargs['path'], seperator, kwargs['query'] = raw_path.partition('?')
        if not seperator:
            kwargs['query'] = None
    if 'host' in kwargs:
        host = kwargs.get('host') or ''
        if ':' in host and (not (host.startswith('[') and host.endswith(']'))):
            kwargs['host'] = f'[{host}]'
    for key, value in kwargs.items():
        if value is not None:
            if len(value) > MAX_URL_LENGTH:
                raise InvalidURL(f"URL component '{key}' too long")
            if any((char.isascii() and (not char.isprintable()) for char in value)):
                char = next((char for char in value if char.isascii() and (not char.isprintable())))
                idx = value.find(char)
                error = f'Invalid non-printable ASCII character in URL {key} component, {char!r} at position {idx}.'
                raise InvalidURL(error)
            if not COMPONENT_REGEX[key].fullmatch(value):
                raise InvalidURL(f"Invalid URL component '{key}'")
    url_match = URL_REGEX.match(url)
    assert url_match is not None
    url_dict = url_match.groupdict()
    scheme = kwargs.get('scheme', url_dict['scheme']) or ''
    authority = kwargs.get('authority', url_dict['authority']) or ''
    path = kwargs.get('path', url_dict['path']) or ''
    query = kwargs.get('query', url_dict['query'])
    frag = kwargs.get('fragment', url_dict['fragment'])
    authority_match = AUTHORITY_REGEX.match(authority)
    assert authority_match is not None
    authority_dict = authority_match.groupdict()
    userinfo = kwargs.get('userinfo', authority_dict['userinfo']) or ''
    host = kwargs.get('host', authority_dict['host']) or ''
    port = kwargs.get('port', authority_dict['port'])
    parsed_scheme: str = scheme.lower()
    parsed_userinfo: str = quote(userinfo, safe=USERINFO_SAFE)
    parsed_host: str = encode_host(host)
    parsed_port: int | None = normalize_port(port, scheme)
    has_scheme = parsed_scheme != ''
    has_authority = parsed_userinfo != '' or parsed_host != '' or parsed_port is not None
    validate_path(path, has_scheme=has_scheme, has_authority=has_authority)
    if has_scheme or has_authority:
        path = normalize_path(path)
    parsed_path: str = quote(path, safe=PATH_SAFE)
    parsed_query: str | None = None if query is None else quote(query, safe=QUERY_SAFE)
    parsed_frag: str | None = None if frag is None else quote(frag, safe=FRAG_SAFE)
    return ParseResult(parsed_scheme, parsed_userinfo, parsed_host, parsed_port, parsed_path, parsed_query, parsed_frag)

def encode_host(host: str) -> str:
    if not host:
        return ''
    elif IPv4_STYLE_HOSTNAME.match(host):
        try:
            ipaddress.IPv4Address(host)
        except ipaddress.AddressValueError:
            raise InvalidURL(f'Invalid IPv4 address: {host!r}')
        return host
    elif IPv6_STYLE_HOSTNAME.match(host):
        try:
            ipaddress.IPv6Address(host[1:-1])
        except ipaddress.AddressValueError:
            raise InvalidURL(f'Invalid IPv6 address: {host!r}')
        return host[1:-1]
    elif host.isascii():
        WHATWG_SAFE = '"`{}%|\\'
        return quote(host.lower(), safe=SUB_DELIMS + WHATWG_SAFE)
    try:
        return idna.encode(host.lower()).decode('ascii')
    except idna.IDNAError:
        raise InvalidURL(f'Invalid IDNA hostname: {host!r}')

def normalize_port(port: str | int | None, scheme: str) -> int | None:
    if port is None or port == '':
        return None
    try:
        port_as_int = int(port)
    except ValueError:
        raise InvalidURL(f'Invalid port: {port!r}')
    default_port = {'ftp': 21, 'http': 80, 'https': 443, 'ws': 80, 'wss': 443}.get(scheme)
    if port_as_int == default_port:
        return None
    return port_as_int

def validate_path(path: str, has_scheme: bool, has_authority: bool) -> None:
    if has_authority:
        if path and (not path.startswith('/')):
            raise InvalidURL("For absolute URLs, path must be empty or begin with '/'")
    if not has_scheme and (not has_authority):
        if path.startswith('//'):
            raise InvalidURL("Relative URLs cannot have a path starting with '//'")
        if path.startswith(':'):
            raise InvalidURL("Relative URLs cannot have a path starting with ':'")

def normalize_path(path: str) -> str:
    if '.' not in path:
        return path
    components = path.split('/')
    if '.' not in components and '..' not in components:
        return path
    output: list[str] = []
    for component in components:
        if component == '.':
            pass
        elif component == '..':
            if output and output != ['']:
                output.pop()
        else:
            output.append(component)
    return '/'.join(output)

def PERCENT(string: str) -> str:
    return ''.join([f'%{byte:02X}' for byte in string.encode('utf-8')])

def percent_encoded(string: str, safe: str) -> str:
    NON_ESCAPED_CHARS = UNRESERVED_CHARACTERS + safe
    if not string.rstrip(NON_ESCAPED_CHARS):
        return string
    return ''.join([char if char in NON_ESCAPED_CHARS else PERCENT(char) for char in string])

def quote(string: str, safe: str) -> str:
    parts = []
    current_position = 0
    for match in re.finditer(PERCENT_ENCODED_REGEX, string):
        start_position, end_position = (match.start(), match.end())
        matched_text = match.group(0)
        if start_position != current_position:
            leading_text = string[current_position:start_position]
            parts.append(percent_encoded(leading_text, safe=safe))
        parts.append(matched_text)
        current_position = end_position
    if current_position != len(string):
        trailing_text = string[current_position:]
        parts.append(percent_encoded(trailing_text, safe=safe))
    return ''.join(parts)

from __future__ import annotations
from collections.abc import Iterable, Sequence
from typing import TypeVar, overload
import numpy as np
from pandas._libs import lib
from pandas._libs.missing import NA
from pandas.core.dtypes.common import is_bool, is_integer
BoolishT = TypeVar('BoolishT', bool, int)
BoolishNoneT = TypeVar('BoolishNoneT', bool, int, None)

def _check_arg_length(fname, args, max_fname_arg_count, compat_args) -> None:
    if max_fname_arg_count < 0:
        raise ValueError("'max_fname_arg_count' must be non-negative")
    if len(args) > len(compat_args):
        max_arg_count = len(compat_args) + max_fname_arg_count
        actual_arg_count = len(args) + max_fname_arg_count
        argument = 'argument' if max_arg_count == 1 else 'arguments'
        raise TypeError(f'{fname}() takes at most {max_arg_count} {argument} ({actual_arg_count} given)')

def _check_for_default_values(fname, arg_val_dict, compat_args) -> None:
    for key in arg_val_dict:
        try:
            v1 = arg_val_dict[key]
            v2 = compat_args[key]
            if v1 is not None and v2 is None or (v1 is None and v2 is not None):
                match = False
            else:
                match = v1 == v2
            if not is_bool(match):
                raise ValueError("'match' is not a boolean")
        except ValueError:
            match = arg_val_dict[key] is compat_args[key]
        if not match:
            raise ValueError(f"the '{key}' parameter is not supported in the pandas implementation of {fname}()")

def validate_args(fname, args, max_fname_arg_count, compat_args) -> None:
    _check_arg_length(fname, args, max_fname_arg_count, compat_args)
    kwargs = dict(zip(compat_args, args, strict=False))
    _check_for_default_values(fname, kwargs, compat_args)

def _check_for_invalid_keys(fname, kwargs, compat_args) -> None:
    diff = set(kwargs) - set(compat_args)
    if diff:
        bad_arg = next(iter(diff))
        raise TypeError(f"{fname}() got an unexpected keyword argument '{bad_arg}'")

def validate_kwargs(fname, kwargs, compat_args) -> None:
    kwds = kwargs.copy()
    _check_for_invalid_keys(fname, kwargs, compat_args)
    _check_for_default_values(fname, kwds, compat_args)

def validate_args_and_kwargs(fname, args, kwargs, max_fname_arg_count, compat_args) -> None:
    _check_arg_length(fname, args + tuple(kwargs.values()), max_fname_arg_count, compat_args)
    args_dict = dict(zip(compat_args, args, strict=False))
    for key in args_dict:
        if key in kwargs:
            raise TypeError(f"{fname}() got multiple values for keyword argument '{key}'")
    kwargs.update(args_dict)
    validate_kwargs(fname, kwargs, compat_args)

def validate_bool_kwarg(value: BoolishNoneT, arg_name: str, none_allowed: bool=True, int_allowed: bool=False) -> BoolishNoneT:
    good_value = is_bool(value)
    if none_allowed:
        good_value = good_value or value is None
    if int_allowed:
        good_value = good_value or isinstance(value, int)
    if not good_value:
        raise ValueError(f'For argument "{arg_name}" expected type bool, received type {type(value).__name__}.')
    return value

def validate_na_arg(value, name: str):
    if value is lib.no_default or isinstance(value, bool) or value is None or (value is NA) or (lib.is_float(value) and np.isnan(value)):
        return
    raise ValueError(f'{name} must be None, pd.NA, np.nan, True, or False; got {value}')

def validate_fillna_kwargs(value, method, validate_scalar_dict_value: bool=True):
    from pandas.core.missing import clean_fill_method
    if value is None and method is None:
        raise ValueError("Must specify a fill 'value' or 'method'.")
    if value is None and method is not None:
        method = clean_fill_method(method)
    elif value is not None and method is None:
        if validate_scalar_dict_value and isinstance(value, (list, tuple)):
            raise TypeError(f'"value" parameter must be a scalar or dict, but you passed a "{type(value).__name__}"')
    elif value is not None and method is not None:
        raise ValueError("Cannot specify both 'value' and 'method'.")
    return (value, method)

def validate_percentile(q: float | Iterable[float]) -> np.ndarray:
    q_arr = np.asarray(q)
    msg = 'percentiles should all be in the interval [0, 1]'
    if q_arr.ndim == 0:
        if not 0 <= q_arr <= 1:
            raise ValueError(msg)
    elif not all((0 <= qs <= 1 for qs in q_arr)):
        raise ValueError(msg)
    return q_arr

@overload
def validate_ascending(ascending: BoolishT) -> BoolishT:
    ...

@overload
def validate_ascending(ascending: Sequence[BoolishT]) -> list[BoolishT]:
    ...

def validate_ascending(ascending: bool | int | Sequence[BoolishT]) -> bool | int | list[BoolishT]:
    kwargs = {'none_allowed': False, 'int_allowed': True}
    if not isinstance(ascending, Sequence):
        return validate_bool_kwarg(ascending, 'ascending', **kwargs)
    return [validate_bool_kwarg(item, 'ascending', **kwargs) for item in ascending]

def validate_endpoints(closed: str | None) -> tuple[bool, bool]:
    left_closed = False
    right_closed = False
    if closed is None:
        left_closed = True
        right_closed = True
    elif closed == 'left':
        left_closed = True
    elif closed == 'right':
        right_closed = True
    else:
        raise ValueError("Closed has to be either 'left', 'right' or None")
    return (left_closed, right_closed)

def validate_inclusive(inclusive: str | None) -> tuple[bool, bool]:
    left_right_inclusive: tuple[bool, bool] | None = None
    if isinstance(inclusive, str):
        left_right_inclusive = {'both': (True, True), 'left': (True, False), 'right': (False, True), 'neither': (False, False)}.get(inclusive)
    if left_right_inclusive is None:
        raise ValueError("Inclusive has to be either 'both', 'neither', 'left' or 'right'")
    return left_right_inclusive

def validate_insert_loc(loc: int, length: int) -> int:
    if not is_integer(loc):
        raise TypeError(f'loc must be an integer between -{length} and {length}')
    if loc < 0:
        loc += length
    if not 0 <= loc <= length:
        raise IndexError(f'loc must be an integer between -{length} and {length}')
    return loc

def check_dtype_backend(dtype_backend) -> None:
    if dtype_backend is not lib.no_default:
        if dtype_backend not in ['numpy_nullable', 'pyarrow']:
            raise ValueError(f"dtype_backend {dtype_backend} is invalid, only 'numpy_nullable' and 'pyarrow' are allowed.")

import re
import textwrap
from collections import Counter
from itertools import groupby
from operator import itemgetter
from typing import Any, ClassVar, Optional
import yaml
from huggingface_hub import DatasetCardData
from ..config import METADATA_CONFIGS_FIELD
from ..features import Features
from ..info import DatasetInfo, DatasetInfosDict
from ..naming import _split_re
from ..utils.logging import get_logger
logger = get_logger(__name__)

class _NoDuplicateSafeLoader(yaml.SafeLoader):

    def _check_no_duplicates_on_constructed_node(self, node):
        keys = [self.constructed_objects[key_node] for key_node, _ in node.value]
        keys = [tuple(key) if isinstance(key, list) else key for key in keys]
        counter = Counter(keys)
        duplicate_keys = [key for key in counter if counter[key] > 1]
        if duplicate_keys:
            raise TypeError(f'Got duplicate yaml keys: {duplicate_keys}')

    def construct_mapping(self, node, deep=False):
        mapping = super().construct_mapping(node, deep=deep)
        self._check_no_duplicates_on_constructed_node(node)
        return mapping

def _split_yaml_from_readme(readme_content: str) -> tuple[Optional[str], str]:
    full_content = list(readme_content.splitlines())
    if full_content and full_content[0] == '---' and ('---' in full_content[1:]):
        sep_idx = full_content[1:].index('---') + 1
        yamlblock = '\n'.join(full_content[1:sep_idx])
        return (yamlblock, '\n'.join(full_content[sep_idx + 1:]))
    return (None, '\n'.join(full_content))

class MetadataConfigs(dict[str, dict[str, Any]]):
    FIELD_NAME: ClassVar[str] = METADATA_CONFIGS_FIELD

    @staticmethod
    def _raise_if_data_files_field_not_valid(metadata_config: dict):
        yaml_data_files = metadata_config.get('data_files')
        if yaml_data_files is not None:
            yaml_error_message = textwrap.dedent(f"\n                Expected data_files in YAML to be either a string or a list of strings\n                or a list of dicts with two keys: 'split' and 'path', but got {yaml_data_files}\n                Examples of data_files in YAML:\n\n                   data_files: data.csv\n\n                   data_files: data/*.png\n\n                   data_files:\n                    - part0/*\n                    - part1/*\n\n                   data_files:\n                    - split: train\n                      path: train/*\n                    - split: test\n                      path: test/*\n\n                   data_files:\n                    - split: train\n                      path:\n                      - train/part1/*\n                      - train/part2/*\n                    - split: test\n                      path: test/*\n\n                PS: some symbols like dashes '-' are not allowed in split names\n                ")
            if not isinstance(yaml_data_files, (list, str)):
                raise ValueError(yaml_error_message)
            if isinstance(yaml_data_files, list):
                for yaml_data_files_item in yaml_data_files:
                    if not isinstance(yaml_data_files_item, (str, dict)) or (isinstance(yaml_data_files_item, dict) and (not (len(yaml_data_files_item) == 2 and 'split' in yaml_data_files_item and re.match(_split_re, yaml_data_files_item['split']) and isinstance(yaml_data_files_item.get('path'), (str, list))))):
                        raise ValueError(yaml_error_message)

    @classmethod
    def _from_exported_parquet_files_and_dataset_infos(cls, parquet_commit_hash: str, exported_parquet_files: list[dict[str, Any]], dataset_infos: DatasetInfosDict) -> 'MetadataConfigs':
        metadata_configs = {config_name: {'data_files': [{'split': split_name, 'path': [parquet_file['url'].replace('refs%2Fconvert%2Fparquet', parquet_commit_hash) for parquet_file in parquet_files_for_split]} for split_name, parquet_files_for_split in groupby(parquet_files_for_config, itemgetter('split'))], 'version': str(dataset_infos.get(config_name, DatasetInfo()).version or '0.0.0')} for config_name, parquet_files_for_config in groupby(exported_parquet_files, itemgetter('config'))}
        if dataset_infos:
            metadata_configs = {config_name: {'data_files': [data_file for split_name in dataset_info.splits for data_file in metadata_configs[config_name]['data_files'] if data_file['split'] == split_name], 'version': metadata_configs[config_name]['version']} for config_name, dataset_info in dataset_infos.items()}
        return cls(metadata_configs)

    @classmethod
    def from_dataset_card_data(cls, dataset_card_data: DatasetCardData) -> 'MetadataConfigs':
        if dataset_card_data.get(cls.FIELD_NAME):
            metadata_configs = dataset_card_data[cls.FIELD_NAME]
            if not isinstance(metadata_configs, list):
                raise ValueError(f"Expected {cls.FIELD_NAME} to be a list, but got '{metadata_configs}'")
            for metadata_config in metadata_configs:
                if 'config_name' not in metadata_config:
                    raise ValueError(f'Each config must include `config_name` field with a string name of a config, but got {metadata_config}. ')
                cls._raise_if_data_files_field_not_valid(metadata_config)
            return cls({config.pop('config_name'): {param: value if param != 'features' else Features._from_yaml_list(value) for param, value in config.items()} for metadata_config in metadata_configs if (config := metadata_config.copy())})
        return cls()

    def to_dataset_card_data(self, dataset_card_data: DatasetCardData) -> None:
        if self:
            for metadata_config in self.values():
                self._raise_if_data_files_field_not_valid(metadata_config)
            current_metadata_configs = self.from_dataset_card_data(dataset_card_data)
            total_metadata_configs = dict(sorted({**current_metadata_configs, **self}.items()))
            for config_name, config_metadata in total_metadata_configs.items():
                config_metadata.pop('config_name', None)
            dataset_card_data[self.FIELD_NAME] = [{'config_name': config_name, **config_metadata} for config_name, config_metadata in total_metadata_configs.items()]

    def get_default_config_name(self) -> Optional[str]:
        default_config_name = None
        for config_name, metadata_config in self.items():
            if len(self) == 1 or config_name == 'default' or metadata_config.get('default'):
                if default_config_name is None:
                    default_config_name = config_name
                else:
                    raise ValueError(f"Dataset has several default configs: '{default_config_name}' and '{config_name}'.")
        return default_config_name
