def validate_groupby_func(name: str, args, kwargs, allowed=None) -> None:
    if allowed is None:
        allowed = []
    kwargs = set(kwargs) - set(allowed)
    if len(args) + len(kwargs) > 0:
        raise UnsupportedFunctionCall(f'numpy operations are not valid with groupby. Use .groupby(...).{name}() instead')

def validate_minmax_axis(axis: AxisInt | None, ndim: int=1) -> None:
    if axis is None:
        return
    if axis >= ndim or (axis < 0 and ndim + axis < 0):
        raise ValueError(f'`axis` must be fewer than the number of dimensions ({ndim})')
_validation_funcs = {'median': validate_median, 'mean': validate_mean, 'min': validate_min, 'max': validate_max, 'sum': validate_sum, 'prod': validate_prod}

def validate_func(fname, args, kwargs) -> None:
    if fname not in _validation_funcs:
        return validate_stat_func(args, kwargs, fname=fname)
    validation_func = _validation_funcs[fname]
    return validation_func(args, kwargs)

from __future__ import annotations
import logging
import platform
import re
import struct
import subprocess
import sys
import sysconfig
from importlib.machinery import EXTENSION_SUFFIXES
from typing import Any, Iterable, Iterator, Sequence, Tuple, cast
from . import _manylinux, _musllinux
logger = logging.getLogger(__name__)
PythonVersion = Sequence[int]
AppleVersion = Tuple[int, int]
INTERPRETER_SHORT_NAMES: dict[str, str] = {'python': 'py', 'cpython': 'cp', 'pypy': 'pp', 'ironpython': 'ip', 'jython': 'jy'}
_32_BIT_INTERPRETER = struct.calcsize('P') == 4

class Tag:
    __slots__ = ['_abi', '_hash', '_interpreter', '_platform']

    def __init__(self, interpreter: str, abi: str, platform: str) -> None:
        self._interpreter = interpreter.lower()
        self._abi = abi.lower()
        self._platform = platform.lower()
        self._hash = hash((self._interpreter, self._abi, self._platform))

    @property
    def interpreter(self) -> str:
        return self._interpreter

    @property
    def abi(self) -> str:
        return self._abi

    @property
    def platform(self) -> str:
        return self._platform

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Tag):
            return NotImplemented
        return self._hash == other._hash and self._platform == other._platform and (self._abi == other._abi) and (self._interpreter == other._interpreter)

    def __hash__(self) -> int:
        return self._hash

    def __str__(self) -> str:
        return f'{self._interpreter}-{self._abi}-{self._platform}'

    def __repr__(self) -> str:
        return f'<{self} @ {id(self)}>'

    def __setstate__(self, state: tuple[None, dict[str, Any]]) -> None:
        _, slots = state
        for k, v in slots.items():
            setattr(self, k, v)
        self._hash = hash((self._interpreter, self._abi, self._platform))

def parse_tag(tag: str) -> frozenset[Tag]:
    tags = set()
    interpreters, abis, platforms = tag.split('-')
    for interpreter in interpreters.split('.'):
        for abi in abis.split('.'):
            for platform_ in platforms.split('.'):
                tags.add(Tag(interpreter, abi, platform_))
    return frozenset(tags)

def _get_config_var(name: str, warn: bool=False) -> int | str | None:
    value: int | str | None = sysconfig.get_config_var(name)
    if value is None and warn:
        logger.debug("Config variable '%s' is unset, Python ABI tag may be incorrect", name)
    return value

def _normalize_string(string: str) -> str:
    return string.replace('.', '_').replace('-', '_').replace(' ', '_')

def _is_threaded_cpython(abis: list[str]) -> bool:
    if len(abis) == 0:
        return False
    m = re.match('cp\\d+(.*)', abis[0])
    if not m:
        return False
    abiflags = m.group(1)
    return 't' in abiflags

def _abi3_applies(python_version: PythonVersion, threading: bool) -> bool:
    return len(python_version) > 1 and tuple(python_version) >= (3, 2) and (not threading)

def _cpython_abis(py_version: PythonVersion, warn: bool=False) -> list[str]:
    py_version = tuple(py_version)
    abis = []
    version = _version_nodot(py_version[:2])
    threading = debug = pymalloc = ucs4 = ''
    with_debug = _get_config_var('Py_DEBUG', warn)
    has_refcount = hasattr(sys, 'gettotalrefcount')
    has_ext = '_d.pyd' in EXTENSION_SUFFIXES
    if with_debug or (with_debug is None and (has_refcount or has_ext)):
        debug = 'd'
    if py_version >= (3, 13) and _get_config_var('Py_GIL_DISABLED', warn):
        threading = 't'
    if py_version < (3, 8):
        with_pymalloc = _get_config_var('WITH_PYMALLOC', warn)
        if with_pymalloc or with_pymalloc is None:
            pymalloc = 'm'
        if py_version < (3, 3):
            unicode_size = _get_config_var('Py_UNICODE_SIZE', warn)
            if unicode_size == 4 or (unicode_size is None and sys.maxunicode == 1114111):
                ucs4 = 'u'
    elif debug:
        abis.append(f'cp{version}{threading}')
    abis.insert(0, f'cp{version}{threading}{debug}{pymalloc}{ucs4}')
    return abis

def cpython_tags(python_version: PythonVersion | None=None, abis: Iterable[str] | None=None, platforms: Iterable[str] | None=None, *, warn: bool=False) -> Iterator[Tag]:
    if not python_version:
        python_version = sys.version_info[:2]
    interpreter = f'cp{_version_nodot(python_version[:2])}'
    if abis is None:
        abis = _cpython_abis(python_version, warn) if len(python_version) > 1 else []
    abis = list(abis)
    for explicit_abi in ('abi3', 'none'):
        try:
            abis.remove(explicit_abi)
        except ValueError:
            pass
    platforms = list(platforms or platform_tags())
    for abi in abis:
        for platform_ in platforms:
            yield Tag(interpreter, abi, platform_)
    threading = _is_threaded_cpython(abis)
    use_abi3 = _abi3_applies(python_version, threading)
    if use_abi3:
        yield from (Tag(interpreter, 'abi3', platform_) for platform_ in platforms)
    yield from (Tag(interpreter, 'none', platform_) for platform_ in platforms)
    if use_abi3:
        for minor_version in range(python_version[1] - 1, 1, -1):
            for platform_ in platforms:
                version = _version_nodot((python_version[0], minor_version))
                interpreter = f'cp{version}'
                yield Tag(interpreter, 'abi3', platform_)

def _generic_abi() -> list[str]:
    ext_suffix = _get_config_var('EXT_SUFFIX', warn=True)
    if not isinstance(ext_suffix, str) or ext_suffix[0] != '.':
        raise SystemError("invalid sysconfig.get_config_var('EXT_SUFFIX')")
    parts = ext_suffix.split('.')
    if len(parts) < 3:
        return _cpython_abis(sys.version_info[:2])
    soabi = parts[1]
    if soabi.startswith('cpython'):
        abi = 'cp' + soabi.split('-')[1]
    elif soabi.startswith('cp'):
        abi = soabi.split('-')[0]
    elif soabi.startswith('pypy'):
        abi = '-'.join(soabi.split('-')[:2])
    elif soabi.startswith('graalpy'):
        abi = '-'.join(soabi.split('-')[:3])
    elif soabi:
        abi = soabi
    else:
        return []
    return [_normalize_string(abi)]

def generic_tags(interpreter: str | None=None, abis: Iterable[str] | None=None, platforms: Iterable[str] | None=None, *, warn: bool=False) -> Iterator[Tag]:
    if not interpreter:
        interp_name = interpreter_name()
        interp_version = interpreter_version(warn=warn)
        interpreter = f'{interp_name}{interp_version}'
    abis = _generic_abi() if abis is None else list(abis)
    platforms = list(platforms or platform_tags())
    if 'none' not in abis:
        abis.append('none')
    for abi in abis:
        for platform_ in platforms:
            yield Tag(interpreter, abi, platform_)

def _py_interpreter_range(py_version: PythonVersion) -> Iterator[str]:
    if len(py_version) > 1:
        yield f'py{_version_nodot(py_version[:2])}'
    yield f'py{py_version[0]}'
    if len(py_version) > 1:
        for minor in range(py_version[1] - 1, -1, -1):
            yield f'py{_version_nodot((py_version[0], minor))}'

def compatible_tags(python_version: PythonVersion | None=None, interpreter: str | None=None, platforms: Iterable[str] | None=None) -> Iterator[Tag]:
    if not python_version:
        python_version = sys.version_info[:2]
    platforms = list(platforms or platform_tags())
    for version in _py_interpreter_range(python_version):
        for platform_ in platforms:
            yield Tag(version, 'none', platform_)
    if interpreter:
        yield Tag(interpreter, 'none', 'any')
    for version in _py_interpreter_range(python_version):
        yield Tag(version, 'none', 'any')

def _mac_arch(arch: str, is_32bit: bool=_32_BIT_INTERPRETER) -> str:
    if not is_32bit:
        return arch
    if arch.startswith('ppc'):
        return 'ppc'
    return 'i386'

def _mac_binary_formats(version: AppleVersion, cpu_arch: str) -> list[str]:
    formats = [cpu_arch]
    if cpu_arch == 'x86_64':
        if version < (10, 4):
            return []
        formats.extend(['intel', 'fat64', 'fat32'])
    elif cpu_arch == 'i386':
        if version < (10, 4):
            return []
        formats.extend(['intel', 'fat32', 'fat'])
    elif cpu_arch == 'ppc64':
        if version > (10, 5) or version < (10, 4):
            return []
        formats.append('fat64')
    elif cpu_arch == 'ppc':
        if version > (10, 6):
            return []
        formats.extend(['fat32', 'fat'])
    if cpu_arch in {'arm64', 'x86_64'}:
        formats.append('universal2')
    if cpu_arch in {'x86_64', 'i386', 'ppc64', 'ppc', 'intel'}:
        formats.append('universal')
    return formats

def mac_platforms(version: AppleVersion | None=None, arch: str | None=None) -> Iterator[str]:
    version_str, _, cpu_arch = platform.mac_ver()
    if version is None:
        version = cast('AppleVersion', tuple(map(int, version_str.split('.')[:2])))
        if version == (10, 16):
            version_str = subprocess.run([sys.executable, '-sS', '-c', 'import platform; print(platform.mac_ver()[0])'], check=True, env={'SYSTEM_VERSION_COMPAT': '0'}, stdout=subprocess.PIPE, text=True).stdout
            version = cast('AppleVersion', tuple(map(int, version_str.split('.')[:2])))
    if arch is None:
        arch = _mac_arch(cpu_arch)
    if (10, 0) <= version < (11, 0):
        major_version = 10
        for minor_version in range(version[1], -1, -1):
            compat_version = (major_version, minor_version)
            binary_formats = _mac_binary_formats(compat_version, arch)
            for binary_format in binary_formats:
                yield f'macosx_{major_version}_{minor_version}_{binary_format}'
    if version >= (11, 0):
        minor_version = 0
        for major_version in range(version[0], 10, -1):
            compat_version = (major_version, minor_version)
            binary_formats = _mac_binary_formats(compat_version, arch)
            for binary_format in binary_formats:
                yield f'macosx_{major_version}_{minor_version}_{binary_format}'
    if version >= (11, 0):
        major_version = 10
        if arch == 'x86_64':
            for minor_version in range(16, 3, -1):
                compat_version = (major_version, minor_version)
                binary_formats = _mac_binary_formats(compat_version, arch)
                for binary_format in binary_formats:
                    yield f'macosx_{major_version}_{minor_version}_{binary_format}'
        else:
            for minor_version in range(16, 3, -1):
                compat_version = (major_version, minor_version)
                binary_format = 'universal2'
                yield f'macosx_{major_version}_{minor_version}_{binary_format}'

def ios_platforms(version: AppleVersion | None=None, multiarch: str | None=None) -> Iterator[str]:
    if version is None:
        _, release, _, _ = platform.ios_ver()
        version = cast('AppleVersion', tuple(map(int, release.split('.')[:2])))
    if multiarch is None:
        multiarch = sys.implementation._multiarch
    multiarch = multiarch.replace('-', '_')
    ios_platform_template = 'ios_{major}_{minor}_{multiarch}'
    if version[0] < 12:
        return
    yield ios_platform_template.format(major=version[0], minor=version[1], multiarch=multiarch)
    for minor in range(version[1] - 1, -1, -1):
        yield ios_platform_template.format(major=version[0], minor=minor, multiarch=multiarch)
    for major in range(version[0] - 1, 11, -1):
        for minor in range(9, -1, -1):
            yield ios_platform_template.format(major=major, minor=minor, multiarch=multiarch)

def android_platforms(api_level: int | None=None, abi: str | None=None) -> Iterator[str]:
    if platform.system() != 'Android' and (api_level is None or abi is None):
        raise TypeError('on non-Android platforms, the api_level and abi arguments are required')
    if api_level is None:
        api_level = platform.android_ver().api_level
    if abi is None:
        abi = sysconfig.get_platform().split('-')[-1]
    abi = _normalize_string(abi)
    min_api_level = 16
    for ver in range(api_level, min_api_level - 1, -1):
        yield f'android_{ver}_{abi}'

def _linux_platforms(is_32bit: bool=_32_BIT_INTERPRETER) -> Iterator[str]:
    linux = _normalize_string(sysconfig.get_platform())
    if not linux.startswith('linux_'):
        yield linux
        return
    if is_32bit:
        if linux == 'linux_x86_64':
            linux = 'linux_i686'
        elif linux == 'linux_aarch64':
            linux = 'linux_armv8l'
    _, arch = linux.split('_', 1)
    archs = {'armv8l': ['armv8l', 'armv7l']}.get(arch, [arch])
    yield from _manylinux.platform_tags(archs)
    yield from _musllinux.platform_tags(archs)
    for arch in archs:
        yield f'linux_{arch}'

def _generic_platforms() -> Iterator[str]:
    yield _normalize_string(sysconfig.get_platform())

def platform_tags() -> Iterator[str]:
    if platform.system() == 'Darwin':
        return mac_platforms()
    elif platform.system() == 'iOS':
        return ios_platforms()
    elif platform.system() == 'Android':
        return android_platforms()
    elif platform.system() == 'Linux':
        return _linux_platforms()
    else:
        return _generic_platforms()

def interpreter_name() -> str:
    name = sys.implementation.name
    return INTERPRETER_SHORT_NAMES.get(name) or name

def interpreter_version(*, warn: bool=False) -> str:
    version = _get_config_var('py_version_nodot', warn=warn)
    return str(version) if version else _version_nodot(sys.version_info[:2])

def _version_nodot(version: PythonVersion) -> str:
    return ''.join(map(str, version))

def sys_tags(*, warn: bool=False) -> Iterator[Tag]:
    interp_name = interpreter_name()
    if interp_name == 'cp':
        yield from cpython_tags(warn=warn)
    else:
        yield from generic_tags()
    if interp_name == 'pp':
        interp = 'pp3'
    elif interp_name == 'cp':
        interp = 'cp' + interpreter_version(warn=warn)
    else:
        interp = None
    yield from compatible_tags(interpreter=interp)

import asyncio
import collections
import contextlib
import functools
import itertools
import socket
from typing import List, Optional, Sequence, Set, Union
from . import _staggered
from .types import AddrInfoType, SocketFactoryType

async def start_connection(addr_infos: Sequence[AddrInfoType], *, local_addr_infos: Optional[Sequence[AddrInfoType]]=None, happy_eyeballs_delay: Optional[float]=None, interleave: Optional[int]=None, loop: Optional[asyncio.AbstractEventLoop]=None, socket_factory: Optional[SocketFactoryType]=None) -> socket.socket:
    if not (current_loop := loop):
        current_loop = asyncio.get_running_loop()
    single_addr_info = len(addr_infos) == 1
    if happy_eyeballs_delay is not None and interleave is None:
        interleave = 1
    if interleave and (not single_addr_info):
        addr_infos = _interleave_addrinfos(addr_infos, interleave)
    sock: Optional[socket.socket] = None
    exceptions: List[List[Union[OSError, RuntimeError]]] = []
    if happy_eyeballs_delay is None or single_addr_info:
        for addrinfo in addr_infos:
            try:
                sock = await _connect_sock(current_loop, exceptions, addrinfo, local_addr_infos, None, socket_factory)
                break
            except (RuntimeError, OSError):
                continue
    else:
        open_sockets: Set[socket.socket] = set()
        try:
            sock, _, _ = await _staggered.staggered_race((functools.partial(_connect_sock, current_loop, exceptions, addrinfo, local_addr_infos, open_sockets, socket_factory) for addrinfo in addr_infos), happy_eyeballs_delay)
        finally:
            for s in open_sockets:
                if s is not sock:
                    with contextlib.suppress(OSError):
                        s.close()
            open_sockets = None
    if sock is None:
        all_exceptions = [exc for sub in exceptions for exc in sub]
        try:
            first_exception = all_exceptions[0]
            if len(all_exceptions) == 1:
                raise first_exception
            else:
                model = str(first_exception)
                if all((str(exc) == model for exc in all_exceptions)):
                    raise first_exception
                msg = 'Multiple exceptions: {}'.format(', '.join((str(exc) for exc in all_exceptions)))
                if isinstance(first_exception, OSError):
                    first_errno = first_exception.errno
                    if all((isinstance(exc, OSError) and exc.errno == first_errno for exc in all_exceptions)):
                        raise OSError(first_errno, msg)
                elif isinstance(first_exception, RuntimeError) and all((isinstance(exc, RuntimeError) for exc in all_exceptions)):
                    raise RuntimeError(msg)
                raise OSError(msg)
        finally:
            all_exceptions = None
            exceptions = None
    return sock

async def _connect_sock(loop: asyncio.AbstractEventLoop, exceptions: List[List[Union[OSError, RuntimeError]]], addr_info: AddrInfoType, local_addr_infos: Optional[Sequence[AddrInfoType]]=None, open_sockets: Optional[Set[socket.socket]]=None, socket_factory: Optional[SocketFactoryType]=None) -> socket.socket:
    my_exceptions: List[Union[OSError, RuntimeError]] = []
    exceptions.append(my_exceptions)
    family, type_, proto, _, address = addr_info
    sock = None
    try:
        if socket_factory is not None:
            sock = socket_factory(addr_info)
        else:
            sock = socket.socket(family=family, type=type_, proto=proto)
        if open_sockets is not None:
            open_sockets.add(sock)
        sock.setblocking(False)
        if local_addr_infos is not None:
            for lfamily, _, _, _, laddr in local_addr_infos:
                if lfamily != family:
                    continue
                try:
                    sock.bind(laddr)
                    break
                except OSError as exc:
                    msg = f"error while attempting to bind on address {laddr!r}: {(exc.strerror or '').lower()}"
                    exc = OSError(exc.errno, msg)
                    my_exceptions.append(exc)
            else:
                if my_exceptions:
                    raise my_exceptions.pop()
                else:
                    raise OSError(f'no matching local address with family={family!r} found')
        await loop.sock_connect(sock, address)
        return sock
    except (RuntimeError, OSError) as exc:
        my_exceptions.append(exc)
        if sock is not None:
            if open_sockets is not None:
                open_sockets.remove(sock)
            try:
                sock.close()
            except OSError as e:
                my_exceptions.append(e)
                raise
        raise
    except:
        if sock is not None:
            if open_sockets is not None:
                open_sockets.remove(sock)
            try:
                sock.close()
            except OSError as e:
                my_exceptions.append(e)
                raise
        raise
    finally:
        exceptions = my_exceptions = None

def _interleave_addrinfos(addrinfos: Sequence[AddrInfoType], first_address_family_count: int=1) -> List[AddrInfoType]:
    addrinfos_by_family: collections.OrderedDict[int, List[AddrInfoType]] = collections.OrderedDict()
    for addr in addrinfos:
        family = addr[0]
        if family not in addrinfos_by_family:
            addrinfos_by_family[family] = []
        addrinfos_by_family[family].append(addr)
    addrinfos_lists = list(addrinfos_by_family.values())
    reordered: List[AddrInfoType] = []
    if first_address_family_count > 1:
        reordered.extend(addrinfos_lists[0][:first_address_family_count - 1])
        del addrinfos_lists[0][:first_address_family_count - 1]
    reordered.extend((a for a in itertools.chain.from_iterable(itertools.zip_longest(*addrinfos_lists)) if a is not None))
    return reordered

from __future__ import annotations
from collections.abc import Callable, Generator, Iterable, Mapping, MutableMapping
from contextlib import contextmanager
from typing import Any, Literal, overload
from . import helpers, presets
from .common import normalize_url, utils
from .parser_block import ParserBlock
from .parser_core import ParserCore
from .parser_inline import ParserInline
from .renderer import RendererHTML, RendererProtocol
from .rules_core.state_core import StateCore
from .token import Token
from .utils import EnvType, OptionsDict, OptionsType, PresetType
try:
    import linkify_it
except ModuleNotFoundError:
    linkify_it = None
_PRESETS: dict[str, PresetType] = {'default': presets.default.make(), 'js-default': presets.js_default.make(), 'zero': presets.zero.make(), 'commonmark': presets.commonmark.make(), 'gfm-like': presets.gfm_like.make()}

class MarkdownIt:

    def __init__(self, config: str | PresetType='commonmark', options_update: Mapping[str, Any] | None=None, *, renderer_cls: Callable[[MarkdownIt], RendererProtocol]=RendererHTML):
        self.utils = utils
        self.helpers = helpers
        self.inline = ParserInline()
        self.block = ParserBlock()
        self.core = ParserCore()
        self.renderer = renderer_cls(self)
        self.linkify = linkify_it.LinkifyIt() if linkify_it else None
        if options_update and (not isinstance(options_update, Mapping)):
            raise TypeError(f'options_update should be a mapping: {options_update}\n(Perhaps you intended this to be the renderer_cls?)')
        self.configure(config, options_update=options_update)

    def __repr__(self) -> str:
        return f'{self.__class__.__module__}.{self.__class__.__name__}()'

    @overload
    def __getitem__(self, name: Literal['inline']) -> ParserInline:
        ...

    @overload
    def __getitem__(self, name: Literal['block']) -> ParserBlock:
        ...

    @overload
    def __getitem__(self, name: Literal['core']) -> ParserCore:
        ...

    @overload
    def __getitem__(self, name: Literal['renderer']) -> RendererProtocol:
        ...

    @overload
    def __getitem__(self, name: str) -> Any:
        ...

    def __getitem__(self, name: str) -> Any:
        return {'inline': self.inline, 'block': self.block, 'core': self.core, 'renderer': self.renderer}[name]

    def set(self, options: OptionsType) -> None:
        self.options = OptionsDict(options)

    def configure(self, presets: str | PresetType, options_update: Mapping[str, Any] | None=None) -> MarkdownIt:
        if isinstance(presets, str):
            if presets not in _PRESETS:
                raise KeyError(f"Wrong `markdown-it` preset '{presets}', check name")
            config = _PRESETS[presets]
        else:
            config = presets
        if not config:
            raise ValueError("Wrong `markdown-it` config, can't be empty")
        options = config.get('options', {}) or {}
        if options_update:
            options = {**options, **options_update}
        self.set(options)
        if 'components' in config:
            for name, component in config['components'].items():
                rules = component.get('rules', None)
                if rules:
                    self[name].ruler.enableOnly(rules)
                rules2 = component.get('rules2', None)
                if rules2:
                    self[name].ruler2.enableOnly(rules2)
        return self

    def get_all_rules(self) -> dict[str, list[str]]:
        rules = {chain: self[chain].ruler.get_all_rules() for chain in ['core', 'block', 'inline']}
        rules['inline2'] = self.inline.ruler2.get_all_rules()
        return rules

    def get_active_rules(self) -> dict[str, list[str]]:
        rules = {chain: self[chain].ruler.get_active_rules() for chain in ['core', 'block', 'inline']}
        rules['inline2'] = self.inline.ruler2.get_active_rules()
        return rules

    def enable(self, names: str | Iterable[str], ignoreInvalid: bool=False) -> MarkdownIt:
        result = []
        if isinstance(names, str):
            names = [names]
        for chain in ['core', 'block', 'inline']:
            result.extend(self[chain].ruler.enable(names, True))
        result.extend(self.inline.ruler2.enable(names, True))
        missed = [name for name in names if name not in result]
        if missed and (not ignoreInvalid):
            raise ValueError(f'MarkdownIt. Failed to enable unknown rule(s): {missed}')
        return self

    def disable(self, names: str | Iterable[str], ignoreInvalid: bool=False) -> MarkdownIt:
        result = []
        if isinstance(names, str):
            names = [names]
        for chain in ['core', 'block', 'inline']:
            result.extend(self[chain].ruler.disable(names, True))
        result.extend(self.inline.ruler2.disable(names, True))
        missed = [name for name in names if name not in result]
        if missed and (not ignoreInvalid):
            raise ValueError(f'MarkdownIt. Failed to disable unknown rule(s): {missed}')
        return self

    @contextmanager
    def reset_rules(self) -> Generator[None, None, None]:
        chain_rules = self.get_active_rules()
        yield
        for chain, rules in chain_rules.items():
            if chain != 'inline2':
                self[chain].ruler.enableOnly(rules)
        self.inline.ruler2.enableOnly(chain_rules['inline2'])

    def add_render_rule(self, name: str, function: Callable[..., Any], fmt: str='html') -> None:
        if self.renderer.__output__ == fmt:
            self.renderer.rules[name] = function.__get__(self.renderer)

    def use(self, plugin: Callable[..., None], *params: Any, **options: Any) -> MarkdownIt:
        plugin(self, *params, **options)
        return self

    def parse(self, src: str, env: EnvType | None=None) -> list[Token]:
        env = {} if env is None else env
        if not isinstance(env, MutableMapping):
            raise TypeError(f'Input data should be a MutableMapping, not {type(env)}')
        if not isinstance(src, str):
            raise TypeError(f'Input data should be a string, not {type(src)}')
        state = StateCore(src, self, env)
        self.core.process(state)
        return state.tokens

    def render(self, src: str, env: EnvType | None=None) -> Any:
        env = {} if env is None else env
        return self.renderer.render(self.parse(src, env), self.options, env)

    def parseInline(self, src: str, env: EnvType | None=None) -> list[Token]:
        env = {} if env is None else env
        if not isinstance(env, MutableMapping):
            raise TypeError(f'Input data should be an MutableMapping, not {type(env)}')
        if not isinstance(src, str):
            raise TypeError(f'Input data should be a string, not {type(src)}')
        state = StateCore(src, self, env)
        state.inlineMode = True
        self.core.process(state)
        return state.tokens

    def renderInline(self, src: str, env: EnvType | None=None) -> Any:
        env = {} if env is None else env
        return self.renderer.render(self.parseInline(src, env), self.options, env)

    def validateLink(self, url: str) -> bool:
        return normalize_url.validateLink(url)

    def normalizeLink(self, url: str) -> str:
        return normalize_url.normalizeLink(url)

    def normalizeLinkText(self, link: str) -> str:
        return normalize_url.normalizeLinkText(link)

from __future__ import annotations
import collections
from collections.abc import Callable
import functools
import sys
import threading
import traceback
from typing import NamedTuple
from typing import TYPE_CHECKING
import warnings
from _pytest.config import Config
from _pytest.nodes import Item
from _pytest.stash import StashKey
from _pytest.tracemalloc import tracemalloc_message
import pytest
if TYPE_CHECKING:
    pass
if sys.version_info < (3, 11):
    from exceptiongroup import ExceptionGroup

class ThreadExceptionMeta(NamedTuple):
    msg: str
    cause_msg: str
    exc_value: BaseException | None
thread_exceptions: StashKey[collections.deque[ThreadExceptionMeta | BaseException]] = StashKey()

def collect_thread_exception(config: Config) -> None:
    pop_thread_exception = config.stash[thread_exceptions].pop
    errors: list[pytest.PytestUnhandledThreadExceptionWarning | RuntimeError] = []
    meta = None
    hook_error = None
    try:
        while True:
            try:
                meta = pop_thread_exception()
            except IndexError:
                break
            if isinstance(meta, BaseException):
                hook_error = RuntimeError('Failed to process thread exception')
                hook_error.__cause__ = meta
                errors.append(hook_error)
                continue
            msg = meta.msg
            try:
                warnings.warn(pytest.PytestUnhandledThreadExceptionWarning(msg))
            except pytest.PytestUnhandledThreadExceptionWarning as e:
                if meta.exc_value is not None:
                    e.args = (meta.cause_msg,)
                    e.__cause__ = meta.exc_value
                errors.append(e)
        if len(errors) == 1:
            raise errors[0]
        if errors:
            raise ExceptionGroup('multiple thread exception warnings', errors)
    finally:
        del errors, meta, hook_error

def cleanup(*, config: Config, prev_hook: Callable[[threading.ExceptHookArgs], object]) -> None:
    try:
        try:
            collect_thread_exception(config)
        finally:
            threading.excepthook = prev_hook
    finally:
        del config.stash[thread_exceptions]

def thread_exception_hook(args: threading.ExceptHookArgs, /, *, append: Callable[[ThreadExceptionMeta | BaseException], object]) -> None:
    try:
        thread_name = '<unknown>' if args.thread is None else args.thread.name
        summary = f'Exception in thread {thread_name}'
        traceback_message = '\n\n' + ''.join(traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback))
        tracemalloc_tb = '\n' + tracemalloc_message(args.thread)
        msg = summary + traceback_message + tracemalloc_tb
        cause_msg = summary + tracemalloc_tb
        append(ThreadExceptionMeta(msg=msg, cause_msg=cause_msg, exc_value=args.exc_value))
    except BaseException as e:
        append(e)
        raise

def pytest_configure(config: Config) -> None:
    prev_hook = threading.excepthook
    deque: collections.deque[ThreadExceptionMeta | BaseException] = collections.deque()
    config.stash[thread_exceptions] = deque
    config.add_cleanup(functools.partial(cleanup, config=config, prev_hook=prev_hook))
    threading.excepthook = functools.partial(thread_exception_hook, append=deque.append)

@pytest.hookimpl(trylast=True)
def pytest_runtest_setup(item: Item) -> None:
    collect_thread_exception(item.config)

@pytest.hookimpl(trylast=True)
def pytest_runtest_call(item: Item) -> None:
    collect_thread_exception(item.config)

@pytest.hookimpl(trylast=True)
def pytest_runtest_teardown(item: Item) -> None:
    collect_thread_exception(item.config)

from __future__ import annotations
from contextlib import contextmanager
import re
from typing import TYPE_CHECKING, Any, NamedTuple, cast
import warnings
from pandas._typing import F
from pandas.util._exceptions import find_stack_level
if TYPE_CHECKING:
    from collections.abc import Callable, Generator, Sequence

class DeprecatedOption(NamedTuple):
    key: str
    category: type[Warning]
    msg: str | None
    rkey: str | None
    removal_ver: str | None

class RegisteredOption(NamedTuple):
    key: str
    defval: Any
    doc: str
    validator: Callable[[object], Any] | None
    cb: Callable[[str], Any] | None
_deprecated_options: dict[str, DeprecatedOption] = {}
_registered_options: dict[str, RegisteredOption] = {}
_global_config: dict[str, Any] = {}
_reserved_keys: list[str] = ['all']

class OptionError(AttributeError, KeyError):
    __module__ = 'pandas.errors'

def _get_single_key(pat: str) -> str:
    keys = _select_options(pat)
    if len(keys) == 0:
        _warn_if_deprecated(pat)
        raise OptionError(f'No such keys(s): {pat!r}')
    if len(keys) > 1:
        raise OptionError('Pattern matched multiple keys')
    key = keys[0]
    _warn_if_deprecated(key)
    key = _translate_key(key)
    return key

def get_option(pat: str) -> Any:
    key = _get_single_key(pat)
    root, k = _get_root(key)
    return root[k]

def set_option(*args) -> None:
    if len(args) == 1 and isinstance(args[0], dict):
        args = tuple((kv for item in args[0].items() for kv in item))
    nargs = len(args)
    if not nargs or nargs % 2 != 0:
        raise ValueError('Must provide an even number of non-keyword arguments')
    for k, v in zip(args[::2], args[1::2], strict=True):
        key = _get_single_key(k)
        opt = _get_registered_option(key)
        if opt and opt.validator:
            opt.validator(v)
        root, k_root = _get_root(key)
        root[k_root] = v
        if opt.cb:
            opt.cb(key)

def describe_option(pat: str='', _print_desc: bool=True) -> str | None:
    keys = _select_options(pat)
    if len(keys) == 0:
        raise OptionError(f'No such keys(s) for pat={pat!r}')
    s = '\n'.join([_build_option_description(k) for k in keys])
    if _print_desc:
        print(s)
        return None
    return s

def reset_option(pat: str) -> None:
    keys = _select_options(pat)
    if len(keys) == 0:
        raise OptionError(f'No such keys(s) for pat={pat!r}')
    if len(keys) > 1 and len(pat) < 4 and (pat != 'all'):
        raise ValueError('You must specify at least 4 characters when resetting multiple keys, use the special keyword "all" to reset all the options to their default value')
    for k in keys:
        set_option(k, _registered_options[k].defval)

def get_default_val(pat: str):
    key = _get_single_key(pat)
    return _get_registered_option(key).defval

class DictWrapper:
    d: dict[str, Any]

    def __init__(self, d: dict[str, Any], prefix: str='') -> None:
        object.__setattr__(self, 'd', d)
        object.__setattr__(self, 'prefix', prefix)

    def __setattr__(self, key: str, val: Any) -> None:
        prefix = object.__getattribute__(self, 'prefix')
        if prefix:
            prefix += '.'
        prefix += key
        if key in self.d and (not isinstance(self.d[key], dict)):
            set_option(prefix, val)
        else:
            raise OptionError('You can only set the value of existing options')

    def __getattr__(self, key: str):
        prefix = object.__getattribute__(self, 'prefix')
        if prefix:
            prefix += '.'
        prefix += key
        try:
            v = object.__getattribute__(self, 'd')[key]
        except KeyError as err:
            raise OptionError('No such option') from err
        if isinstance(v, dict):
            return DictWrapper(v, prefix)
        else:
            return get_option(prefix)

    def __dir__(self) -> list[str]:
        return list(self.d.keys())
options = DictWrapper(_global_config)
object.__setattr__(options, '__module__', 'pandas')

@contextmanager
def option_context(*args) -> Generator[None]:
    if len(args) == 1 and isinstance(args[0], dict):
        args = tuple((kv for item in args[0].items() for kv in item))
    if len(args) % 2 != 0 or len(args) < 2:
        raise ValueError('Provide an even amount of arguments as option_context(pat, val, pat, val...).')
    ops = tuple(zip(args[::2], args[1::2], strict=True))
    undo: tuple[tuple[Any, Any], ...] = ()
    try:
        undo = tuple(((pat, get_option(pat)) for pat, val in ops))
        for pat, val in ops:
            set_option(pat, val)
        yield
    finally:
        for pat, val in undo:
            set_option(pat, val)

def register_option(key: str, defval: object, doc: str='', validator: Callable[[object], Any] | None=None, cb: Callable[[str], Any] | None=None) -> None:
    import keyword
    import tokenize
    key = key.lower()
    if key in _registered_options:
        raise OptionError(f"Option '{key}' has already been registered")
    if key in _reserved_keys:
        raise OptionError(f"Option '{key}' is a reserved key")
    if validator:
        validator(defval)
    path = key.split('.')
    for k in path:
        if not re.match('^' + tokenize.Name + '$', k):
            raise ValueError(f'{k} is not a valid identifier')
        if keyword.iskeyword(k):
            raise ValueError(f'{k} is a python keyword')
    cursor = _global_config
    msg = "Path prefix to option '{option}' is already an option"
    for i, p in enumerate(path[:-1]):
        if not isinstance(cursor, dict):
            raise OptionError(msg.format(option='.'.join(path[:i])))
        if p not in cursor:
            cursor[p] = {}
        cursor = cursor[p]
    if not isinstance(cursor, dict):
        raise OptionError(msg.format(option='.'.join(path[:-1])))
    cursor[path[-1]] = defval
    _registered_options[key] = RegisteredOption(key=key, defval=defval, doc=doc, validator=validator, cb=cb)

def deprecate_option(key: str, category: type[Warning], msg: str | None=None, rkey: str | None=None, removal_ver: str | None=None) -> None:
    key = key.lower()
    if key in _deprecated_options:
        raise OptionError(f"Option '{key}' has already been defined as deprecated.")
    _deprecated_options[key] = DeprecatedOption(key, category, msg, rkey, removal_ver)

def _select_options(pat: str) -> list[str]:
    if pat in _registered_options:
        return [pat]
    keys = sorted(_registered_options.keys())
    if pat == 'all':
        return keys
    return [k for k in keys if re.search(pat, k, re.I)]

def _get_root(key: str) -> tuple[dict[str, Any], str]:
    path = key.split('.')
    cursor = _global_config
    for p in path[:-1]:
        cursor = cursor[p]
    return (cursor, path[-1])

def _get_deprecated_option(key: str):
    try:
        d = _deprecated_options[key]
    except KeyError:
        return None
    else:
        return d

def _get_registered_option(key: str):
    return _registered_options.get(key)

def _translate_key(key: str) -> str:
    d = _get_deprecated_option(key)
    if d:
        return d.rkey or key
    else:
        return key

def _warn_if_deprecated(key: str) -> bool:
    d = _get_deprecated_option(key)
    if d:
        if d.msg:
            warnings.warn(d.msg, d.category, stacklevel=find_stack_level())
        else:
            msg = f"'{key}' is deprecated"
            if d.removal_ver:
                msg += f' and will be removed in {d.removal_ver}'
            if d.rkey:
                msg += f", please use '{d.rkey}' instead."
            else:
                msg += ', please refrain from using it.'
            warnings.warn(msg, d.category, stacklevel=find_stack_level())
        return True
    return False

def _build_option_description(k: str) -> str:
    o = _get_registered_option(k)
    d = _get_deprecated_option(k)
    s = f'{k} '
    if o.doc:
        s += '\n'.join(o.doc.strip().split('\n'))
    else:
        s += 'No description available.'
    if o:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', FutureWarning)
            warnings.simplefilter('ignore', DeprecationWarning)
            s += f'\n    [default: {o.defval}] [currently: {get_option(k)}]'
    if d:
        rkey = d.rkey or ''
        s += '\n    (Deprecated'
        s += f', use `{rkey}` instead.'
        s += ')'
    return s

@contextmanager
def config_prefix(prefix: str) -> Generator[None]:
    global register_option, get_option, set_option

    def wrap(func: F) -> F:

        def inner(key: str, *args, **kwds):
            pkey = f'{prefix}.{key}'
            return func(pkey, *args, **kwds)
        return cast(F, inner)
    _register_option = register_option
    _get_option = get_option
    _set_option = set_option
    set_option = wrap(set_option)
    get_option = wrap(get_option)
    register_option = wrap(register_option)
    try:
        yield
    finally:
        set_option = _set_option
        get_option = _get_option
        register_option = _register_option

def is_type_factory(_type: type[Any]) -> Callable[[Any], None]:

    def inner(x) -> None:
        if type(x) != _type:
            raise ValueError(f"Value must have type '{_type}'")
    return inner

def is_instance_factory(_type: type | tuple[type, ...]) -> Callable[[Any], None]:
    if isinstance(_type, tuple):
        type_repr = '|'.join(map(str, _type))
    else:
        type_repr = f"'{_type}'"

    def inner(x) -> None:
        if not isinstance(x, _type):
            raise ValueError(f'Value must be an instance of {type_repr}')
    return inner

def is_one_of_factory(legal_values: Sequence) -> Callable[[Any], None]:
    callables = [c for c in legal_values if callable(c)]
    legal_values = [c for c in legal_values if not callable(c)]

    def inner(x) -> None:
        if x not in legal_values:
            if not any((c(x) for c in callables)):
                uvals = [str(lval) for lval in legal_values]
                pp_values = '|'.join(uvals)
                msg = f'Value must be one of {pp_values}'
                if len(callables):
                    msg += ' or a callable'
                raise ValueError(msg)
    return inner

def is_nonnegative_int(value: object) -> None:
    if value is None:
        return
    elif isinstance(value, int):
        if value >= 0:
            return
    msg = 'Value must be a nonnegative integer or None'
    raise ValueError(msg)
