from __future__ import annotations
from collections import abc, defaultdict
import copy
from typing import TYPE_CHECKING, Any, DefaultDict, overload
import numpy as np
from pandas._libs.writers import convert_json_to_lines
from pandas.util._decorators import set_module
import pandas as pd
from pandas import DataFrame, Series
if TYPE_CHECKING:
    from collections.abc import Iterable
    from pandas._typing import IgnoreRaise, Scalar

def convert_to_line_delimits(s: str) -> str:
    if not s[0] == '[' and s[-1] == ']':
        return s
    s = s[1:-1]
    return convert_json_to_lines(s)

@overload
def nested_to_record(ds: dict, prefix: str=..., sep: str=..., level: int=..., max_level: int | None=...) -> dict[str, Any]:
    ...

@overload
def nested_to_record(ds: list[dict], prefix: str=..., sep: str=..., level: int=..., max_level: int | None=...) -> list[dict[str, Any]]:
    ...

def nested_to_record(ds: dict | list[dict], prefix: str='', sep: str='.', level: int=0, max_level: int | None=None) -> dict[str, Any] | list[dict[str, Any]]:
    singleton = False
    if isinstance(ds, dict):
        ds = [ds]
        singleton = True
    new_ds = []
    for d in ds:
        new_d = copy.deepcopy(d)
        for k, v in d.items():
            if not isinstance(k, str):
                k = str(k)
            if level == 0:
                newkey = k
            else:
                newkey = prefix + sep + k
            if not isinstance(v, dict) or (max_level is not None and level >= max_level):
                if level != 0:
                    v = new_d.pop(k)
                    new_d[newkey] = v
                continue
            v = new_d.pop(k)
            new_d.update(nested_to_record(v, newkey, sep, level + 1, max_level))
        new_ds.append(new_d)
    if singleton:
        return new_ds[0]
    return new_ds

def _normalize_json(data: Any, key_string: str, normalized_dict: dict[str, Any], separator: str) -> dict[str, Any]:
    if isinstance(data, dict):
        for key, value in data.items():
            new_key = f'{key_string}{separator}{key}'
            if not key_string:
                new_key = new_key.removeprefix(separator)
            _normalize_json(data=value, key_string=new_key, normalized_dict=normalized_dict, separator=separator)
    else:
        normalized_dict[key_string] = data
    return normalized_dict

def _normalize_json_ordered(data: dict[str, Any], separator: str) -> dict[str, Any]:
    top_dict_ = {k: v for k, v in data.items() if not isinstance(v, dict)}
    nested_dict_ = _normalize_json(data={k: v for k, v in data.items() if isinstance(v, dict)}, key_string='', normalized_dict={}, separator=separator)
    return {**top_dict_, **nested_dict_}

def _simple_json_normalize(ds: dict | list[dict], sep: str='.') -> dict | list[dict] | Any:
    normalized_json_object = {}
    if isinstance(ds, dict):
        normalized_json_object = _normalize_json_ordered(data=ds, separator=sep)
    elif isinstance(ds, list):
        normalized_json_list = [_simple_json_normalize(row, sep=sep) for row in ds]
        return normalized_json_list
    return normalized_json_object

def _validate_meta(meta: str | list[str | list[str]] | None) -> None:
    if meta is None:
        return
    if isinstance(meta, str):
        return
    for item in meta:
        if isinstance(item, list):
            for subitem in item:
                if not isinstance(subitem, str):
                    raise TypeError(f'All elements in nested meta paths must be strings. Found {type(subitem).__name__}: {subitem!r}')
        elif not isinstance(item, str):
            raise TypeError(f"All elements in 'meta' must be strings or lists of strings. Found {type(item).__name__}: {item!r}")

@set_module('pandas')
def json_normalize(data: dict | list[dict] | Series, record_path: str | list | None=None, meta: str | list[str | list[str]] | None=None, meta_prefix: str | None=None, record_prefix: str | None=None, errors: IgnoreRaise='raise', sep: str='.', max_level: int | None=None) -> DataFrame:
    _validate_meta(meta)

    def _pull_field(js: dict[str, Any], spec: list | str, extract_record: bool=False) -> Scalar | Iterable:
        result = js
        try:
            if isinstance(spec, list):
                for field in spec:
                    if result is None:
                        raise KeyError(field)
                    result = result[field]
            else:
                result = result[spec]
        except KeyError as e:
            if extract_record:
                raise KeyError(f'Key {e} not found. If specifying a record_path, all elements of data should have the path.') from e
            if errors == 'ignore':
                return np.nan
            else:
                raise KeyError(f"Key {e} not found. To replace missing values of {e} with np.nan, pass in errors='ignore'") from e
        return result

    def _pull_records(js: dict[str, Any], spec: list | str) -> list:
        result = _pull_field(js, spec, extract_record=True)
        if not isinstance(result, list):
            if pd.isnull(result):
                result = []
            else:
                raise TypeError(f'Path must contain list or null, but got {type(result).__name__} at {spec!r}')
        return result
    if isinstance(data, Series):
        index = data.index
    else:
        index = None
    if isinstance(data, list) and (not data):
        return DataFrame()
    elif isinstance(data, dict):
        data = [data]
    elif isinstance(data, abc.Iterable) and (not isinstance(data, str)):
        data = list(data)
        for item in data:
            if not isinstance(item, dict):
                msg = f'All items in data must be of type dict, found {type(item).__name__}'
                raise TypeError(msg)
    else:
        raise NotImplementedError
    if record_path is None and meta is None and (meta_prefix is None) and (record_prefix is None) and (max_level is None):
        return DataFrame(_simple_json_normalize(data, sep=sep), index=index)
    if record_path is None:
        if any(([isinstance(x, dict) for x in y.values()] for y in data)):
            data = nested_to_record(data, sep=sep, max_level=max_level)
        result = DataFrame(data, index=index)
        if record_prefix is not None:
            result = result.rename(columns=lambda x: f'{record_prefix}{x}')
        return result
    elif not isinstance(record_path, list):
        record_path = [record_path]
    if meta is None:
        meta = []
    elif not isinstance(meta, list):
        meta = [meta]
    _meta = [m if isinstance(m, list) else [m] for m in meta]
    records: list = []
    lengths = []
    meta_vals: DefaultDict = defaultdict(list)
    meta_keys = [sep.join(val) for val in _meta]

    def _recursive_extract(data, path, seen_meta, level: int=0) -> None:
        if isinstance(data, dict):
            data = [data]
        if len(path) > 1:
            for obj in data:
                for val, key in zip(_meta, meta_keys, strict=True):
                    if level + 1 == len(val):
                        seen_meta[key] = _pull_field(obj, val[-1])
                _recursive_extract(obj[path[0]], path[1:], seen_meta, level=level + 1)
        else:
            for obj in data:
                recs = _pull_records(obj, path[0])
                recs = [nested_to_record(r, sep=sep, max_level=max_level) if isinstance(r, dict) else r for r in recs]
                lengths.append(len(recs))
                for val, key in zip(_meta, meta_keys, strict=True):
                    if level + 1 > len(val):
                        meta_val = seen_meta[key]
                    else:
                        meta_val = _pull_field(obj, val[level:])
                    meta_vals[key].append(meta_val)
                records.extend(recs)
    _recursive_extract(data, record_path, {}, level=0)
    result = DataFrame(records)
    if record_prefix is not None:
        result = result.rename(columns=lambda x: f'{record_prefix}{x}')
    for k, v in meta_vals.items():
        if meta_prefix is not None:
            k = meta_prefix + k
        if k in result:
            raise ValueError(f'Conflicting metadata name {k}, need distinguishing prefix ')
        values = np.array(v, dtype=object)
        if values.ndim > 1:
            values = np.empty((len(v),), dtype=object)
            for i, val in enumerate(v):
                values[i] = val
        result[k] = values.repeat(lengths)
    if index is not None:
        result.index = index.repeat(lengths)
    return result

from __future__ import annotations
import os.path
import types
import zipimport
from collections.abc import Iterable
from typing import TYPE_CHECKING
from coverage import env
from coverage.exceptions import CoverageException, NoSource
from coverage.files import canonical_filename, relative_filename, zip_location
from coverage.misc import isolate_module, join_regex
from coverage.parser import PythonParser
from coverage.phystokens import source_encoding, source_token_lines
from coverage.plugin import CodeRegion, FileReporter
from coverage.regions import code_regions
from coverage.types import TArc, TLineNo, TMorf, TSourceTokenLines
if TYPE_CHECKING:
    from coverage import Coverage
os = isolate_module(os)
open = open

def read_python_source(filename: str) -> bytes:
    with open(filename, 'rb') as f:
        source = f.read()
    return source.replace(b'\r\n', b'\n').replace(b'\r', b'\n')

def get_python_source(filename: str) -> str:
    base, ext = os.path.splitext(filename)
    if ext == '.py' and env.WINDOWS:
        exts = ['.py', '.pyw']
    else:
        exts = [ext]
    source_bytes: bytes | None
    for ext in exts:
        try_filename = base + ext
        if os.path.exists(try_filename):
            source_bytes = read_python_source(try_filename)
            break
        source_bytes = get_zip_bytes(try_filename)
        if source_bytes is not None:
            break
    else:
        raise NoSource(f"No source for code: '{filename}'.", slug='no-source')
    source_bytes = source_bytes.replace(b'\x0c', b' ')
    source = source_bytes.decode(source_encoding(source_bytes), 'replace')
    if source and source[-1] != '\n':
        source += '\n'
    return source

def get_zip_bytes(filename: str) -> bytes | None:
    zipfile_inner = zip_location(filename)
    if zipfile_inner is not None:
        zipfile, inner = zipfile_inner
        try:
            zi = zipimport.zipimporter(zipfile)
        except zipimport.ZipImportError:
            return None
        try:
            data = zi.get_data(inner)
        except OSError:
            return None
        return data
    return None

def source_for_file(filename: str) -> str:
    if filename.endswith('.py'):
        return filename
    elif filename.endswith(('.pyc', '.pyo')):
        py_filename = filename[:-1]
        if os.path.exists(py_filename):
            return py_filename
        if env.WINDOWS:
            pyw_filename = py_filename + 'w'
            if os.path.exists(pyw_filename):
                return pyw_filename
        return py_filename
    return filename

def source_for_morf(morf: TMorf) -> str:
    if hasattr(morf, '__file__') and morf.__file__:
        filename = morf.__file__
    elif isinstance(morf, types.ModuleType):
        raise CoverageException(f'Module {morf} has no file')
    else:
        filename = morf
    filename = source_for_file(filename)
    return filename

class PythonFileReporter(FileReporter):

    def __init__(self, morf: TMorf, coverage: Coverage | None=None) -> None:
        self.coverage = coverage
        filename = source_for_morf(morf)
        fname = filename
        canonicalize = True
        if self.coverage is not None:
            if self.coverage.config.relative_files:
                canonicalize = False
        if canonicalize:
            fname = canonical_filename(filename)
        super().__init__(fname)
        if hasattr(morf, '__name__'):
            name = morf.__name__.replace('.', os.sep)
            if os.path.basename(filename).startswith('__init__.'):
                name += os.sep + '__init__'
            name += '.py'
        else:
            name = relative_filename(filename)
        self.relname = name
        self._source: str | None = None
        self._parser: PythonParser | None = None
        self._excluded = None

    def __repr__(self) -> str:
        return f'<PythonFileReporter {self.filename!r}>'

    def relative_filename(self) -> str:
        return self.relname

    @property
    def parser(self) -> PythonParser:
        assert self.coverage is not None
        if self._parser is None:
            self._parser = PythonParser(filename=self.filename, exclude=self.coverage._exclude_regex('exclude'))
            self._parser.parse_source()
        return self._parser

    def lines(self) -> set[TLineNo]:
        return self.parser.statements

    def multiline_map(self) -> dict[TLineNo, TLineNo]:
        return self.parser.multiline_map

    def excluded_lines(self) -> set[TLineNo]:
        return self.parser.excluded

    def translate_lines(self, lines: Iterable[TLineNo]) -> set[TLineNo]:
        return self.parser.translate_lines(lines)

    def translate_arcs(self, arcs: Iterable[TArc]) -> set[TArc]:
        return self.parser.translate_arcs(arcs)

    def no_branch_lines(self) -> set[TLineNo]:
        assert self.coverage is not None
        no_branch = self.parser.lines_matching(join_regex(self.coverage.config.partial_list + self.coverage.config.partial_always_list))
        return no_branch

    def arcs(self) -> set[TArc]:
        return self.parser.arcs()

    def exit_counts(self) -> dict[TLineNo, int]:
        return self.parser.exit_counts()

    def missing_arc_description(self, start: TLineNo, end: TLineNo, executed_arcs: Iterable[TArc] | None=None) -> str:
        return self.parser.missing_arc_description(start, end)

    def arc_description(self, start: TLineNo, end: TLineNo) -> str:
        return self.parser.arc_description(start, end)

    def source(self) -> str:
        if self._source is None:
            self._source = get_python_source(self.filename)
        return self._source

    def should_be_python(self) -> bool:
        _, ext = os.path.splitext(self.filename)
        if ext.startswith('.py'):
            return True
        if not ext:
            return True
        return False

    def source_token_lines(self) -> TSourceTokenLines:
        return source_token_lines(self.source())

    def code_regions(self) -> Iterable[CodeRegion]:
        return code_regions(self.source())

    def code_region_kinds(self) -> Iterable[tuple[str, str]]:
        return [('function', 'functions'), ('class', 'classes')]

from __future__ import annotations
__all__ = ('TLSAttribute', 'TLSConnectable', 'TLSListener', 'TLSStream')
import logging
import re
import ssl
import sys
from collections.abc import Callable, Mapping
from dataclasses import dataclass
from functools import wraps
from ssl import SSLContext
from typing import Any, TypeAlias, TypeVar
from .. import BrokenResourceError, EndOfStream, aclose_forcefully, get_cancelled_exc_class, to_thread
from .._core._typedattr import TypedAttributeSet, typed_attribute
from ..abc import AnyByteStream, AnyByteStreamConnectable, ByteStream, ByteStreamConnectable, Listener, TaskGroup
if sys.version_info >= (3, 11):
    from typing import TypeVarTuple, Unpack
else:
    from typing_extensions import TypeVarTuple, Unpack
if sys.version_info >= (3, 12):
    from typing import override
else:
    from typing_extensions import override
T_Retval = TypeVar('T_Retval')
PosArgsT = TypeVarTuple('PosArgsT')
_PCTRTT: TypeAlias = tuple[tuple[str, str], ...]
_PCTRTTT: TypeAlias = tuple[_PCTRTT, ...]

class TLSAttribute(TypedAttributeSet):
    alpn_protocol: str | None = typed_attribute()
    channel_binding_tls_unique: bytes = typed_attribute()
    cipher: tuple[str, str, int] = typed_attribute()
    peer_certificate: None | dict[str, str | _PCTRTTT | _PCTRTT] = typed_attribute()
    peer_certificate_binary: bytes | None = typed_attribute()
    server_side: bool = typed_attribute()
    shared_ciphers: list[tuple[str, str, int]] | None = typed_attribute()
    ssl_object: ssl.SSLObject = typed_attribute()
    standard_compatible: bool = typed_attribute()
    tls_version: str = typed_attribute()

@dataclass(eq=False)
class TLSStream(ByteStream):
    transport_stream: AnyByteStream
    standard_compatible: bool
    _ssl_object: ssl.SSLObject
    _read_bio: ssl.MemoryBIO
    _write_bio: ssl.MemoryBIO

    @classmethod
    async def wrap(cls, transport_stream: AnyByteStream, *, server_side: bool | None=None, hostname: str | None=None, ssl_context: ssl.SSLContext | None=None, standard_compatible: bool=True) -> TLSStream:
        if server_side is None:
            server_side = not hostname
        if not ssl_context:
            purpose = ssl.Purpose.CLIENT_AUTH if server_side else ssl.Purpose.SERVER_AUTH
            ssl_context = ssl.create_default_context(purpose)
            if hasattr(ssl, 'OP_IGNORE_UNEXPECTED_EOF'):
                ssl_context.options &= ~ssl.OP_IGNORE_UNEXPECTED_EOF
        bio_in = ssl.MemoryBIO()
        bio_out = ssl.MemoryBIO()
        if type(ssl_context) is ssl.SSLContext:
            ssl_object = ssl_context.wrap_bio(bio_in, bio_out, server_side=server_side, server_hostname=hostname)
        else:
            ssl_object = await to_thread.run_sync(ssl_context.wrap_bio, bio_in, bio_out, server_side, hostname, None)
        wrapper = cls(transport_stream=transport_stream, standard_compatible=standard_compatible, _ssl_object=ssl_object, _read_bio=bio_in, _write_bio=bio_out)
        await wrapper._call_sslobject_method(ssl_object.do_handshake)
        return wrapper

    async def _call_sslobject_method(self, func: Callable[[Unpack[PosArgsT]], T_Retval], *args: Unpack[PosArgsT]) -> T_Retval:
        while True:
            try:
                result = func(*args)
            except ssl.SSLWantReadError:
                try:
                    if self._write_bio.pending:
                        await self.transport_stream.send(self._write_bio.read())
                    data = await self.transport_stream.receive()
                except EndOfStream:
                    self._read_bio.write_eof()
                except OSError as exc:
                    self._read_bio.write_eof()
                    self._write_bio.write_eof()
                    raise BrokenResourceError from exc
                else:
                    self._read_bio.write(data)
            except ssl.SSLWantWriteError:
                await self.transport_stream.send(self._write_bio.read())
            except ssl.SSLSyscallError as exc:
                self._read_bio.write_eof()
                self._write_bio.write_eof()
                raise BrokenResourceError from exc
            except ssl.SSLError as exc:
                self._read_bio.write_eof()
                self._write_bio.write_eof()
                if isinstance(exc, ssl.SSLEOFError) or (exc.strerror and 'UNEXPECTED_EOF_WHILE_READING' in exc.strerror):
                    if self.standard_compatible:
                        raise BrokenResourceError from exc
                    else:
                        raise EndOfStream from None
                raise
            else:
                if self._write_bio.pending:
                    await self.transport_stream.send(self._write_bio.read())
                return result

    async def unwrap(self) -> tuple[AnyByteStream, bytes]:
        await self._call_sslobject_method(self._ssl_object.unwrap)
        self._read_bio.write_eof()
        self._write_bio.write_eof()
        return (self.transport_stream, self._read_bio.read())

    async def aclose(self) -> None:
        if self.standard_compatible:
            try:
                await self.unwrap()
            except BaseException:
                await aclose_forcefully(self.transport_stream)
                raise
        await self.transport_stream.aclose()

    async def receive(self, max_bytes: int=65536) -> bytes:
        data = await self._call_sslobject_method(self._ssl_object.read, max_bytes)
        if not data:
            raise EndOfStream
        return data

    async def send(self, item: bytes) -> None:
        await self._call_sslobject_method(self._ssl_object.write, item)

    async def send_eof(self) -> None:
        tls_version = self.extra(TLSAttribute.tls_version)
        match = re.match('TLSv(\\d+)(?:\\.(\\d+))?', tls_version)
        if match:
            major, minor = (int(match.group(1)), int(match.group(2) or 0))
            if (major, minor) < (1, 3):
                raise NotImplementedError(f'send_eof() requires at least TLSv1.3; current session uses {tls_version}')
        raise NotImplementedError('send_eof() has not yet been implemented for TLS streams')

    @property
    def extra_attributes(self) -> Mapping[Any, Callable[[], Any]]:
        return {**self.transport_stream.extra_attributes, TLSAttribute.alpn_protocol: self._ssl_object.selected_alpn_protocol, TLSAttribute.channel_binding_tls_unique: self._ssl_object.get_channel_binding, TLSAttribute.cipher: self._ssl_object.cipher, TLSAttribute.peer_certificate: lambda: self._ssl_object.getpeercert(False), TLSAttribute.peer_certificate_binary: lambda: self._ssl_object.getpeercert(True), TLSAttribute.server_side: lambda: self._ssl_object.server_side, TLSAttribute.shared_ciphers: lambda: self._ssl_object.shared_ciphers() if self._ssl_object.server_side else None, TLSAttribute.standard_compatible: lambda: self.standard_compatible, TLSAttribute.ssl_object: lambda: self._ssl_object, TLSAttribute.tls_version: self._ssl_object.version}

@dataclass(eq=False)
class TLSListener(Listener[TLSStream]):
    listener: Listener[Any]
    ssl_context: ssl.SSLContext
    standard_compatible: bool = True
    handshake_timeout: float = 30

    @staticmethod
    async def handle_handshake_error(exc: BaseException, stream: AnyByteStream) -> None:
        await aclose_forcefully(stream)
        if not isinstance(exc, get_cancelled_exc_class()):
            logging.getLogger(__name__).exception('Error during TLS handshake', exc_info=exc)
        if not isinstance(exc, Exception) or isinstance(exc, get_cancelled_exc_class()):
            raise

    async def serve(self, handler: Callable[[TLSStream], Any], task_group: TaskGroup | None=None) -> None:

        @wraps(handler)
        async def handler_wrapper(stream: AnyByteStream) -> None:
            from .. import fail_after
            try:
                with fail_after(self.handshake_timeout):
                    wrapped_stream = await TLSStream.wrap(stream, ssl_context=self.ssl_context, standard_compatible=self.standard_compatible)
            except BaseException as exc:
                await self.handle_handshake_error(exc, stream)
            else:
                await handler(wrapped_stream)
        await self.listener.serve(handler_wrapper, task_group)

    async def aclose(self) -> None:
        await self.listener.aclose()

    @property
    def extra_attributes(self) -> Mapping[Any, Callable[[], Any]]:
        return {TLSAttribute.standard_compatible: lambda: self.standard_compatible}

class TLSConnectable(ByteStreamConnectable):

    def __init__(self, connectable: AnyByteStreamConnectable, *, hostname: str | None=None, ssl_context: ssl.SSLContext | None=None, standard_compatible: bool=True) -> None:
        self.connectable = connectable
        self.ssl_context: SSLContext = ssl_context or ssl.create_default_context(ssl.Purpose.SERVER_AUTH)
        if not isinstance(self.ssl_context, ssl.SSLContext):
            raise TypeError(f'ssl_context must be an instance of ssl.SSLContext, not {type(self.ssl_context).__name__}')
        self.hostname = hostname
        self.standard_compatible = standard_compatible

    @override
    async def connect(self) -> TLSStream:
        stream = await self.connectable.connect()
        try:
            return await TLSStream.wrap(stream, hostname=self.hostname, ssl_context=self.ssl_context, standard_compatible=self.standard_compatible)
        except BaseException:
            await aclose_forcefully(stream)
            raise

import array
import logging
import posixpath
import warnings
from collections.abc import MutableMapping
from functools import cached_property
from fsspec.core import url_to_fs
logger = logging.getLogger('fsspec.mapping')

class FSMap(MutableMapping):

    def __init__(self, root, fs, check=False, create=False, missing_exceptions=None):
        self.fs = fs
        self.root = fs._strip_protocol(root)
        self._root_key_to_str = fs._strip_protocol(posixpath.join(root, 'x'))[:-1]
        if missing_exceptions is None:
            missing_exceptions = (FileNotFoundError, IsADirectoryError, NotADirectoryError)
        self.missing_exceptions = missing_exceptions
        self.check = check
        self.create = create
        if create:
            if not self.fs.exists(root):
                self.fs.mkdir(root)
        if check:
            if not self.fs.exists(root):
                raise ValueError(f'Path {root} does not exist. Create  with the ``create=True`` keyword')
            self.fs.touch(root + '/a')
            self.fs.rm(root + '/a')

    @cached_property
    def dirfs(self):
        from .implementations.dirfs import DirFileSystem
        return DirFileSystem(path=self._root_key_to_str, fs=self.fs)

    def clear(self):
        logger.info('Clear mapping at %s', self.root)
        try:
            self.fs.rm(self.root, True)
            self.fs.mkdir(self.root)
        except:
            pass

    def getitems(self, keys, on_error='raise'):
        keys2 = [self._key_to_str(k) for k in keys]
        oe = on_error if on_error == 'raise' else 'return'
        try:
            out = self.fs.cat(keys2, on_error=oe)
            if isinstance(out, bytes):
                out = {keys2[0]: out}
        except self.missing_exceptions as e:
            raise KeyError from e
        out = {k: KeyError() if isinstance(v, self.missing_exceptions) else v for k, v in out.items()}
        return {key: out[k2] if on_error == 'raise' else out.get(k2, KeyError(k2)) for key, k2 in zip(keys, keys2) if on_error == 'return' or not isinstance(out[k2], BaseException)}

    def setitems(self, values_dict):
        values = {self._key_to_str(k): maybe_convert(v) for k, v in values_dict.items()}
        self.fs.pipe(values)

    def delitems(self, keys):
        self.fs.rm([self._key_to_str(k) for k in keys])

    def _key_to_str(self, key):
        if not isinstance(key, str):
            warnings.warn('from fsspec 2023.5 onward FSMap non-str keys will raise TypeError', DeprecationWarning)
            if isinstance(key, list):
                key = tuple(key)
            key = str(key)
        return f'{self._root_key_to_str}{key}'.rstrip('/')

    def _str_to_key(self, s):
        return s[len(self.root):].lstrip('/')

    def __getitem__(self, key, default=None):
        k = self._key_to_str(key)
        try:
            result = self.fs.cat(k)
        except self.missing_exceptions as exc:
            if default is not None:
                return default
            raise KeyError(key) from exc
        return result

    def pop(self, key, default=None):
        result = self.__getitem__(key, default)
        try:
            del self[key]
        except KeyError:
            pass
        return result

    def __setitem__(self, key, value):
        key = self._key_to_str(key)
        self.fs.mkdirs(self.fs._parent(key), exist_ok=True)
        self.fs.pipe_file(key, maybe_convert(value))

    def __iter__(self):
        return (self._str_to_key(x) for x in self.fs.find(self.root))

    def __len__(self):
        return len(self.fs.find(self.root))

    def __delitem__(self, key):
        try:
            self.fs.rm(self._key_to_str(key))
        except Exception as exc:
            raise KeyError from exc

    def __contains__(self, key):
        path = self._key_to_str(key)
        return self.fs.isfile(path)

    def __reduce__(self):
        return (FSMap, (self.root, self.fs, False, False, self.missing_exceptions))

def maybe_convert(value):
    if isinstance(value, array.array) or hasattr(value, '__array__'):
        if hasattr(value, 'dtype') and value.dtype.kind in 'Mm':
            value = value.view('int64')
        value = bytes(memoryview(value))
    return value

def get_mapper(url='', check=False, create=False, missing_exceptions=None, alternate_root=None, **kwargs):
    fs, urlpath = url_to_fs(url, **kwargs)
    root = alternate_root if alternate_root is not None else urlpath
    return FSMap(root, fs, check, create, missing_exceptions=missing_exceptions)

import re
from pygments.lexer import Lexer
from pygments.token import Text, Comment, Operator, Keyword, Name, Number, Punctuation, Error
__all__ = ['TNTLexer']

class TNTLexer(Lexer):
    name = 'Typographic Number Theory'
    url = 'https://github.com/Kenny2github/language-tnt'
    aliases = ['tnt']
    filenames = ['*.tnt']
    version_added = '2.7'
    cur = []
    LOGIC = set('⊃→]&∧^|∨Vv')
    OPERATORS = set('+.⋅*')
    VARIABLES = set('abcde')
    PRIMES = set("'′")
    NEGATORS = set('~!')
    QUANTIFIERS = set('AE∀∃')
    NUMBERS = set('0123456789')
    WHITESPACE = set('\t \x0b\n')
    RULES = re.compile('(?xi)\n        joining | separation | double-tilde | fantasy\\ rule\n        | carry[- ]over(?:\\ of)?(?:\\ line)?\\ ([0-9]+) | detachment\n        | contrapositive | De\\ Morgan | switcheroo\n        | specification | generalization | interchange\n        | existence | symmetry | transitivity\n        | add\\ S | drop\\ S | induction\n        | axiom\\ ([1-5]) | premise | push | pop\n    ')
    LINENOS = re.compile('(?:[0-9]+)(?:(?:, ?|,? and )(?:[0-9]+))*')
    COMMENT = re.compile('\\[[^\\n\\]]+\\]')

    def __init__(self, *args, **kwargs):
        Lexer.__init__(self, *args, **kwargs)
        self.cur = []

    def whitespace(self, start, text, required=False):
        end = start
        try:
            while text[end] in self.WHITESPACE:
                end += 1
        except IndexError:
            end = len(text)
        if required and end == start:
            raise AssertionError
        if end != start:
            self.cur.append((start, Text, text[start:end]))
        return end

    def variable(self, start, text):
        if text[start] not in self.VARIABLES:
            raise AssertionError
        end = start + 1
        while text[end] in self.PRIMES:
            end += 1
        self.cur.append((start, Name.Variable, text[start:end]))
        return end

    def term(self, start, text):
        if text[start] == 'S':
            end = start + 1
            while text[end] == 'S':
                end += 1
            self.cur.append((start, Number.Integer, text[start:end]))
            return self.term(end, text)
        if text[start] == '0':
            self.cur.append((start, Number.Integer, text[start]))
            return start + 1
        if text[start] in self.VARIABLES:
            return self.variable(start, text)
        if text[start] == '(':
            self.cur.append((start, Punctuation, text[start]))
            start = self.term(start + 1, text)
            if text[start] not in self.OPERATORS:
                raise AssertionError
            self.cur.append((start, Operator, text[start]))
            start = self.term(start + 1, text)
            if text[start] != ')':
                raise AssertionError
            self.cur.append((start, Punctuation, text[start]))
            return start + 1
        raise AssertionError

    def formula(self, start, text):
        if text[start] in self.NEGATORS:
            end = start + 1
            while text[end] in self.NEGATORS:
                end += 1
            self.cur.append((start, Operator, text[start:end]))
            return self.formula(end, text)
        if text[start] in self.QUANTIFIERS:
            self.cur.append((start, Keyword.Declaration, text[start]))
            start = self.variable(start + 1, text)
            if text[start] != ':':
                raise AssertionError
            self.cur.append((start, Punctuation, text[start]))
            return self.formula(start + 1, text)
        if text[start] == '<':
            self.cur.append((start, Punctuation, text[start]))
            start = self.formula(start + 1, text)
            if text[start] not in self.LOGIC:
                raise AssertionError
            self.cur.append((start, Operator, text[start]))
            start = self.formula(start + 1, text)
            if text[start] != '>':
                raise AssertionError
            self.cur.append((start, Punctuation, text[start]))
            return start + 1
        start = self.term(start, text)
        if text[start] != '=':
            raise AssertionError
        self.cur.append((start, Operator, text[start]))
        start = self.term(start + 1, text)
        return start

    def rule(self, start, text):
        match = self.RULES.match(text, start)
        if match is None:
            raise AssertionError
        groups = sorted(match.regs[1:])
        for group in groups:
            if group[0] >= 0:
                self.cur.append((start, Keyword, text[start:group[0]]))
                self.cur.append((group[0], Number.Integer, text[group[0]:group[1]]))
                if group[1] != match.end():
                    self.cur.append((group[1], Keyword, text[group[1]:match.end()]))
                break
        else:
            self.cur.append((start, Keyword, text[start:match.end()]))
        return match.end()

    def lineno(self, start, text):
        end = start
        while text[end] not in self.NUMBERS:
            end += 1
        self.cur.append((start, Punctuation, text[start]))
        self.cur.append((start + 1, Text, text[start + 1:end]))
        start = end
        match = self.LINENOS.match(text, start)
        if match is None:
            raise AssertionError
        if text[match.end()] != ')':
            raise AssertionError
        self.cur.append((match.start(), Number.Integer, match.group(0)))
        self.cur.append((match.end(), Punctuation, text[match.end()]))
        return match.end() + 1

    def error_till_line_end(self, start, text):
        end = start
        try:
            while text[end] != '\n':
                end += 1
        except IndexError:
            end = len(text)
        if end != start:
            self.cur.append((start, Error, text[start:end]))
        end = self.whitespace(end, text)
        return end

    def get_tokens_unprocessed(self, text):
        self.cur = []
        start = end = self.whitespace(0, text)
        while start <= end < len(text):
            try:
                while text[end] in self.NUMBERS:
                    end += 1
                if end != start:
                    self.cur.append((start, Number.Integer, text[start:end]))
                    orig = len(self.cur)
                    try:
                        start = end = self.whitespace(end, text, True)
                    except AssertionError:
                        del self.cur[orig:]
                        start = end = self.error_till_line_end(end, text)
                        continue
                match = self.COMMENT.match(text, start)
                if match is not None:
                    self.cur.append((start, Comment, text[start:match.end()]))
                    start = end = match.end()
                    start = end = self.error_till_line_end(start, text)
                    continue
                del match
                if text[start] in '[]':
                    self.cur.append((start, Keyword, text[start]))
                    start += 1
                    end += 1
                else:
                    orig = len(self.cur)
                    try:
                        start = end = self.formula(start, text)
                    except (AssertionError, RecursionError):
                        del self.cur[orig:]
                        while text[end] not in self.WHITESPACE:
                            end += 1
                        self.cur.append((start, Error, text[start:end]))
                        start = end
                orig = len(self.cur)
                try:
                    start = end = self.whitespace(end, text, True)
                except AssertionError:
                    del self.cur[orig:]
                    start = end = self.error_till_line_end(start, text)
                    continue
                orig = len(self.cur)
                try:
                    start = end = self.rule(start, text)
                except AssertionError:
                    del self.cur[orig:]
                    start = end = self.error_till_line_end(start, text)
                    continue
                start = end = self.whitespace(end, text)
                if text[start] == '(':
                    orig = len(self.cur)
                    try:
                        start = end = self.lineno(start, text)
                    except AssertionError:
                        del self.cur[orig:]
                        start = end = self.error_till_line_end(start, text)
                        continue
                    start = end = self.whitespace(start, text)
            except IndexError:
                try:
                    del self.cur[orig:]
                except NameError:
                    pass
                self.error_till_line_end(start, text)
        return self.cur

from __future__ import annotations
import collections.abc as cabc
import typing as t
from collections import deque
from gettext import gettext as _
from gettext import ngettext
from ._utils import FLAG_NEEDS_VALUE
from ._utils import UNSET
from .exceptions import BadArgumentUsage
from .exceptions import BadOptionUsage
from .exceptions import NoSuchOption
from .exceptions import UsageError
if t.TYPE_CHECKING:
    from ._utils import T_FLAG_NEEDS_VALUE
    from ._utils import T_UNSET
    from .core import Argument as CoreArgument
    from .core import Context
    from .core import Option as CoreOption
    from .core import Parameter as CoreParameter
V = t.TypeVar('V')

def _unpack_args(args: cabc.Sequence[str], nargs_spec: cabc.Sequence[int]) -> tuple[cabc.Sequence[str | cabc.Sequence[str | None] | None], list[str]]:
    args = deque(args)
    nargs_spec = deque(nargs_spec)
    rv: list[str | tuple[str | T_UNSET, ...] | T_UNSET] = []
    spos: int | None = None

    def _fetch(c: deque[V]) -> V | T_UNSET:
        try:
            if spos is None:
                return c.popleft()
            else:
                return c.pop()
        except IndexError:
            return UNSET
    while nargs_spec:
        nargs = _fetch(nargs_spec)
        if nargs is None:
            continue
        if nargs == 1:
            rv.append(_fetch(args))
        elif nargs > 1:
            x = [_fetch(args) for _ in range(nargs)]
            if spos is not None:
                x.reverse()
            rv.append(tuple(x))
        elif nargs < 0:
            if spos is not None:
                raise TypeError('Cannot have two nargs < 0')
            spos = len(rv)
            rv.append(UNSET)
    if spos is not None:
        rv[spos] = tuple(args)
        args = []
        rv[spos + 1:] = reversed(rv[spos + 1:])
    return (tuple(rv), list(args))

def _split_opt(opt: str) -> tuple[str, str]:
    first = opt[:1]
    if first.isalnum():
        return ('', opt)
    if opt[1:2] == first:
        return (opt[:2], opt[2:])
    return (first, opt[1:])

def _normalize_opt(opt: str, ctx: Context | None) -> str:
    if ctx is None or ctx.token_normalize_func is None:
        return opt
    prefix, opt = _split_opt(opt)
    return f'{prefix}{ctx.token_normalize_func(opt)}'

class _Option:

    def __init__(self, obj: CoreOption, opts: cabc.Sequence[str], dest: str | None, action: str | None=None, nargs: int=1, const: t.Any | None=None):
        self._short_opts = []
        self._long_opts = []
        self.prefixes: set[str] = set()
        for opt in opts:
            prefix, value = _split_opt(opt)
            if not prefix:
                raise ValueError(f'Invalid start character for option ({opt})')
            self.prefixes.add(prefix[0])
            if len(prefix) == 1 and len(value) == 1:
                self._short_opts.append(opt)
            else:
                self._long_opts.append(opt)
                self.prefixes.add(prefix)
        if action is None:
            action = 'store'
        self.dest = dest
        self.action = action
        self.nargs = nargs
        self.const = const
        self.obj = obj

    @property
    def takes_value(self) -> bool:
        return self.action in ('store', 'append')

    def process(self, value: t.Any, state: _ParsingState) -> None:
        if self.action == 'store':
            state.opts[self.dest] = value
        elif self.action == 'store_const':
            state.opts[self.dest] = self.const
        elif self.action == 'append':
            state.opts.setdefault(self.dest, []).append(value)
        elif self.action == 'append_const':
            state.opts.setdefault(self.dest, []).append(self.const)
        elif self.action == 'count':
            state.opts[self.dest] = state.opts.get(self.dest, 0) + 1
        else:
            raise ValueError(f"unknown action '{self.action}'")
        state.order.append(self.obj)

class _Argument:

    def __init__(self, obj: CoreArgument, dest: str | None, nargs: int=1):
        self.dest = dest
        self.nargs = nargs
        self.obj = obj

    def process(self, value: str | cabc.Sequence[str | None] | None | T_UNSET, state: _ParsingState) -> None:
        if self.nargs > 1:
            assert isinstance(value, cabc.Sequence)
            holes = sum((1 for x in value if x is UNSET))
            if holes == len(value):
                value = UNSET
            elif holes != 0:
                raise BadArgumentUsage(_('Argument {name!r} takes {nargs} values.').format(name=self.dest, nargs=self.nargs))
        if value == ():
            value = UNSET
        state.opts[self.dest] = value
        state.order.append(self.obj)

class _ParsingState:

    def __init__(self, rargs: list[str]) -> None:
        self.opts: dict[str, t.Any] = {}
        self.largs: list[str] = []
        self.rargs = rargs
        self.order: list[CoreParameter] = []

class _OptionParser:

    def __init__(self, ctx: Context | None=None) -> None:
        self.ctx = ctx
        self.allow_interspersed_args: bool = True
        self.ignore_unknown_options: bool = False
        if ctx is not None:
            self.allow_interspersed_args = ctx.allow_interspersed_args
            self.ignore_unknown_options = ctx.ignore_unknown_options
        self._short_opt: dict[str, _Option] = {}
        self._long_opt: dict[str, _Option] = {}
        self._opt_prefixes = {'-', '--'}
        self._args: list[_Argument] = []

    def add_option(self, obj: CoreOption, opts: cabc.Sequence[str], dest: str | None, action: str | None=None, nargs: int=1, const: t.Any | None=None) -> None:
        opts = [_normalize_opt(opt, self.ctx) for opt in opts]
        option = _Option(obj, opts, dest, action=action, nargs=nargs, const=const)
        self._opt_prefixes.update(option.prefixes)
        for opt in option._short_opts:
            self._short_opt[opt] = option
        for opt in option._long_opts:
            self._long_opt[opt] = option

    def add_argument(self, obj: CoreArgument, dest: str | None, nargs: int=1) -> None:
        self._args.append(_Argument(obj, dest=dest, nargs=nargs))

    def parse_args(self, args: list[str]) -> tuple[dict[str, t.Any], list[str], list[CoreParameter]]:
        state = _ParsingState(args)
        try:
            self._process_args_for_options(state)
            self._process_args_for_args(state)
        except UsageError:
            if self.ctx is None or not self.ctx.resilient_parsing:
                raise
        return (state.opts, state.largs, state.order)

    def _process_args_for_args(self, state: _ParsingState) -> None:
        pargs, args = _unpack_args(state.largs + state.rargs, [x.nargs for x in self._args])
        for idx, arg in enumerate(self._args):
            arg.process(pargs[idx], state)
        state.largs = args
        state.rargs = []

    def _process_args_for_options(self, state: _ParsingState) -> None:
        while state.rargs:
            arg = state.rargs.pop(0)
            arglen = len(arg)
            if arg == '--':
                return
            elif arg[:1] in self._opt_prefixes and arglen > 1:
                self._process_opts(arg, state)
            elif self.allow_interspersed_args:
                state.largs.append(arg)
            else:
                state.rargs.insert(0, arg)
                return

    def _match_long_opt(self, opt: str, explicit_value: str | None, state: _ParsingState) -> None:
        if opt not in self._long_opt:
            from difflib import get_close_matches
            possibilities = get_close_matches(opt, self._long_opt)
            raise NoSuchOption(opt, possibilities=possibilities, ctx=self.ctx)
        option = self._long_opt[opt]
        if option.takes_value:
            if explicit_value is not None:
                state.rargs.insert(0, explicit_value)
            value = self._get_value_from_state(opt, option, state)
        elif explicit_value is not None:
            raise BadOptionUsage(opt, _('Option {name!r} does not take a value.').format(name=opt))
        else:
            value = UNSET
        option.process(value, state)

    def _match_short_opt(self, arg: str, state: _ParsingState) -> None:
        stop = False
        i = 1
        prefix = arg[0]
        unknown_options = []
        for ch in arg[1:]:
            opt = _normalize_opt(f'{prefix}{ch}', self.ctx)
            option = self._short_opt.get(opt)
            i += 1
            if not option:
                if self.ignore_unknown_options:
                    unknown_options.append(ch)
                    continue
                raise NoSuchOption(opt, ctx=self.ctx)
            if option.takes_value:
                if i < len(arg):
                    state.rargs.insert(0, arg[i:])
                    stop = True
                value = self._get_value_from_state(opt, option, state)
            else:
                value = UNSET
            option.process(value, state)
            if stop:
                break
        if self.ignore_unknown_options and unknown_options:
            state.largs.append(f"{prefix}{''.join(unknown_options)}")

    def _get_value_from_state(self, option_name: str, option: _Option, state: _ParsingState) -> str | cabc.Sequence[str] | T_FLAG_NEEDS_VALUE:
        nargs = option.nargs
        value: str | cabc.Sequence[str] | T_FLAG_NEEDS_VALUE
        if len(state.rargs) < nargs:
            if option.obj._flag_needs_value:
                value = FLAG_NEEDS_VALUE
            else:
                raise BadOptionUsage(option_name, ngettext('Option {name!r} requires an argument.', 'Option {name!r} requires {nargs} arguments.', nargs).format(name=option_name, nargs=nargs))
        elif nargs == 1:
            next_rarg = state.rargs[0]
            if option.obj._flag_needs_value and isinstance(next_rarg, str) and (next_rarg[:1] in self._opt_prefixes) and (len(next_rarg) > 1):
                value = FLAG_NEEDS_VALUE
            else:
                value = state.rargs.pop(0)
        else:
            value = tuple(state.rargs[:nargs])
            del state.rargs[:nargs]
        return value

    def _process_opts(self, arg: str, state: _ParsingState) -> None:
        explicit_value = None
        if '=' in arg:
            long_opt, explicit_value = arg.split('=', 1)
        else:
            long_opt = arg
        norm_long_opt = _normalize_opt(long_opt, self.ctx)
        try:
            self._match_long_opt(norm_long_opt, explicit_value, state)
        except NoSuchOption:
            if arg[:2] not in self._opt_prefixes:
                self._match_short_opt(arg, state)
                return
            if not self.ignore_unknown_options:
                raise
            state.largs.append(arg)

def __getattr__(name: str) -> object:
    import warnings
    if name in {'OptionParser', 'Argument', 'Option', 'split_opt', 'normalize_opt', 'ParsingState'}:
        warnings.warn(f"'parser.{name}' is deprecated and will be removed in Click 9.0. The old parser is available in 'optparse'.", DeprecationWarning, stacklevel=2)
        return globals()[f'_{name}']
    if name == 'split_arg_string':
        from .shell_completion import split_arg_string
