    return str(value)

def make_default_short_help(help: str, max_length: int=45) -> str:
    paragraph_end = help.find('\n\n')
    if paragraph_end != -1:
        help = help[:paragraph_end]
    words = help.split()
    if not words:
        return ''
    if words[0] == '\x08':
        words = words[1:]
    total_length = 0
    last_index = len(words) - 1
    for i, word in enumerate(words):
        total_length += len(word) + (i > 0)
        if total_length > max_length:
            break
        if word[-1] == '.':
            return ' '.join(words[:i + 1])
        if total_length == max_length and i != last_index:
            break
    else:
        return ' '.join(words)
    total_length += len('...')
    while i > 0:
        total_length -= len(words[i]) + (i > 0)
        if total_length <= max_length:
            break
        i -= 1
    return ' '.join(words[:i]) + '...'

class LazyFile:

    def __init__(self, filename: str | os.PathLike[str], mode: str='r', encoding: str | None=None, errors: str | None='strict', atomic: bool=False):
        self.name: str = os.fspath(filename)
        self.mode = mode
        self.encoding = encoding
        self.errors = errors
        self.atomic = atomic
        self._f: t.IO[t.Any] | None
        self.should_close: bool
        if self.name == '-':
            self._f, self.should_close = open_stream(filename, mode, encoding, errors)
        else:
            if 'r' in mode:
                open(filename, mode).close()
            self._f = None
            self.should_close = True

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self.open(), name)

    def __repr__(self) -> str:
        if self._f is not None:
            return repr(self._f)
        return f"<unopened file '{format_filename(self.name)}' {self.mode}>"

    def open(self) -> t.IO[t.Any]:
        if self._f is not None:
            return self._f
        try:
            rv, self.should_close = open_stream(self.name, self.mode, self.encoding, self.errors, atomic=self.atomic)
        except OSError as e:
            from .exceptions import FileError
            raise FileError(self.name, hint=e.strerror) from e
        self._f = rv
        return rv

    def close(self) -> None:
        if self._f is not None:
            self._f.close()

    def close_intelligently(self) -> None:
        if self.should_close:
            self.close()

    def __enter__(self) -> LazyFile:
        return self

    def __exit__(self, exc_type: type[BaseException] | None, exc_value: BaseException | None, tb: TracebackType | None) -> None:
        self.close_intelligently()

    def __iter__(self) -> cabc.Iterator[t.AnyStr]:
        self.open()
        return iter(self._f)

class KeepOpenFile:

    def __init__(self, file: t.IO[t.Any]) -> None:
        self._file: t.IO[t.Any] = file

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def __enter__(self) -> KeepOpenFile:
        return self

    def __exit__(self, exc_type: type[BaseException] | None, exc_value: BaseException | None, tb: TracebackType | None) -> None:
        pass

    def __repr__(self) -> str:
        return repr(self._file)

    def __iter__(self) -> cabc.Iterator[t.AnyStr]:
        return iter(self._file)

def echo(message: t.Any | None=None, file: t.IO[t.Any] | None=None, nl: bool=True, err: bool=False, color: bool | None=None) -> None:
    if file is None:
        if err:
            file = _default_text_stderr()
        else:
            file = _default_text_stdout()
        if file is None:
            return
    if message is not None and (not isinstance(message, (str, bytes, bytearray))):
        out: str | bytes | bytearray | None = str(message)
    else:
        out = message
    if nl:
        out = out or ''
        if isinstance(out, str):
            out += '\n'
        else:
            out += b'\n'
    if not out:
        file.flush()
        return
    if isinstance(out, (bytes, bytearray)):
        binary_file = _find_binary_writer(file)
        if binary_file is not None:
            file.flush()
            binary_file.write(out)
            binary_file.flush()
            return
    else:
        color = resolve_color_default(color)
        if should_strip_ansi(file, color):
            out = strip_ansi(out)
        elif WIN:
            if auto_wrap_for_ansi is not None:
                file = auto_wrap_for_ansi(file, color)
            elif not color:
                out = strip_ansi(out)
    file.write(out)
    file.flush()

def get_binary_stream(name: t.Literal['stdin', 'stdout', 'stderr']) -> t.BinaryIO:
    opener = binary_streams.get(name)
    if opener is None:
        raise TypeError(f"Unknown standard stream '{name}'")
    return opener()

def get_text_stream(name: t.Literal['stdin', 'stdout', 'stderr'], encoding: str | None=None, errors: str | None='strict') -> t.TextIO:
    opener = text_streams.get(name)
    if opener is None:
        raise TypeError(f"Unknown standard stream '{name}'")
    return opener(encoding, errors)

def open_file(filename: str | os.PathLike[str], mode: str='r', encoding: str | None=None, errors: str | None='strict', lazy: bool=False, atomic: bool=False) -> t.IO[t.Any]:
    if lazy:
        return t.cast('t.IO[t.Any]', LazyFile(filename, mode, encoding, errors, atomic=atomic))
    f, should_close = open_stream(filename, mode, encoding, errors, atomic=atomic)
    if not should_close:
        f = t.cast('t.IO[t.Any]', KeepOpenFile(f))
    return f

def format_filename(filename: str | bytes | os.PathLike[str] | os.PathLike[bytes], shorten: bool=False) -> str:
    if shorten:
        filename = os.path.basename(filename)
    else:
        filename = os.fspath(filename)
    if isinstance(filename, bytes):
        filename = filename.decode(sys.getfilesystemencoding(), 'replace')
    else:
        filename = filename.encode('utf-8', 'surrogateescape').decode('utf-8', 'replace')
    return filename

def get_app_dir(app_name: str, roaming: bool=True, force_posix: bool=False) -> str:
    if WIN:
        key = 'APPDATA' if roaming else 'LOCALAPPDATA'
        folder = os.environ.get(key)
        if folder is None:
            folder = os.path.expanduser('~')
        return os.path.join(folder, app_name)
    if force_posix:
        return os.path.join(os.path.expanduser(f'~/.{_posixify(app_name)}'))
    if sys.platform == 'darwin':
        return os.path.join(os.path.expanduser('~/Library/Application Support'), app_name)
    return os.path.join(os.environ.get('XDG_CONFIG_HOME', os.path.expanduser('~/.config')), _posixify(app_name))

class PacifyFlushWrapper:

    def __init__(self, wrapped: t.IO[t.Any]) -> None:
        self.wrapped = wrapped

    def flush(self) -> None:
        try:
            self.wrapped.flush()
        except OSError as e:
            import errno
            if e.errno != errno.EPIPE:
                raise

    def __getattr__(self, attr: str) -> t.Any:
        return getattr(self.wrapped, attr)

def _detect_program_name(path: str | None=None, _main: ModuleType | None=None) -> str:
    if _main is None:
        _main = sys.modules['__main__']
    if not path:
        path = sys.argv[0]
    if getattr(_main, '__package__', None) in {None, ''} or (os.name == 'nt' and _main.__package__ == '' and (not os.path.exists(path)) and os.path.exists(f'{path}.exe')):
        return os.path.basename(path)
    py_module = t.cast(str, _main.__package__)
    name = os.path.splitext(os.path.basename(path))[0]
    if name != '__main__':
        py_module = f'{py_module}.{name}'
    return f"python -m {py_module.lstrip('.')}"

def _expand_args(args: cabc.Iterable[str], *, user: bool=True, env: bool=True, glob_recursive: bool=True) -> list[str]:
    from glob import glob
    out = []
    for arg in args:
        if user:
            arg = os.path.expanduser(arg)
        if env:
            arg = os.path.expandvars(arg)
        try:
            matches = glob(arg, recursive=glob_recursive)
        except re.error:
            matches = []
        if not matches:
            out.append(arg)
        else:
            out.extend(matches)
    return out

from dataclasses import dataclass
from typing import Literal, Optional, Union
import pyarrow as pa
import pyarrow.dataset as ds
import pyarrow.parquet as pq
import datasets
from datasets.builder import Key
from datasets.table import table_cast
logger = datasets.utils.logging.get_logger(__name__)

@dataclass
class ParquetConfig(datasets.BuilderConfig):
    batch_size: Optional[int] = None
    columns: Optional[list[str]] = None
    features: Optional[datasets.Features] = None
    filters: Optional[Union[ds.Expression, list[tuple], list[list[tuple]]]] = None
    fragment_scan_options: Optional[ds.ParquetFragmentScanOptions] = None
    on_bad_files: Literal['error', 'warn', 'skip'] = 'error'

    def __post_init__(self):
        super().__post_init__()

class Parquet(datasets.ArrowBasedBuilder):
    BUILDER_CONFIG_CLASS = ParquetConfig

    def _info(self):
        if self.config.columns is not None and self.config.features is not None and (set(self.config.columns) != set(self.config.features)):
            raise ValueError('The columns and features argument must contain the same columns, but got ', f'{self.config.columns} and {self.config.features}')
        return datasets.DatasetInfo(features=self.config.features)

    def _split_generators(self, dl_manager):
        if not self.config.data_files:
            raise ValueError(f'At least one data file must be specified, but got data_files={self.config.data_files}')
        dl_manager.download_config.extract_on_the_fly = True
        data_files = dl_manager.download(self.config.data_files)
        splits = []
        for split_name, files in data_files.items():
            if self.info.features is None:
                for file in files:
                    try:
                        with open(file, 'rb') as f:
                            self.info.features = datasets.Features.from_arrow_schema(pq.read_schema(f))
                            break
                    except pa.ArrowInvalid as e:
                        if self.config.on_bad_files == 'error':
                            logger.error(f"Failed to read schema from '{file}' with error {type(e).__name__}: {e}")
                            raise
                        elif self.config.on_bad_files == 'warn':
                            logger.warning(f"Skipping bad schema from '{file}'. {type(e).__name__}: {e}`")
                        else:
                            logger.debug(f"Skipping bad schema from '{file}'. {type(e).__name__}: {e}`")
            if self.info.features is None:
                raise ValueError(f'At least one valid data file must be specified, all the data_files are invalid: {self.config.data_files}')
            splits.append(datasets.SplitGenerator(name=split_name, gen_kwargs={'files': files, 'row_groups_list': [None] * len(files)}))
        if self.config.columns is not None and set(self.config.columns) != set(self.info.features):
            self.info.features = datasets.Features({col: feat for col, feat in self.info.features.items() if col in self.config.columns})
        return splits

    def _cast_table(self, pa_table: pa.Table) -> pa.Table:
        if self.info.features is not None:
            pa_table = table_cast(pa_table, self.info.features.arrow_schema)
        return pa_table

    def _generate_shards(self, files, row_groups_list):
        if not row_groups_list:
            yield from files
        else:
            for file, row_groups in zip(files, row_groups_list):
                yield {'fragment_data_file': file, 'fragment_row_groups': row_groups}

    def _generate_more_gen_kwargs(self, files, row_groups_list):
        if not row_groups_list:
            parquet_file_format = ds.ParquetFileFormat(default_fragment_scan_options=self.config.fragment_scan_options)
            for file in files:
                with open(file, 'rb') as f:
                    parquet_fragment = parquet_file_format.make_fragment(f)
                    yield {'files': [file] * parquet_fragment.num_row_groups, 'row_groups_list': [(row_group_id,) for row_group_id in range(parquet_fragment.num_row_groups)]}
        else:
            for file, row_groups in zip(files, row_groups_list):
                yield {'files': [file], 'row_groups_list': [row_groups]}

    def _generate_tables(self, files, row_groups_list):
        if self.config.features is not None and self.config.columns is not None:
            if sorted((field.name for field in self.info.features.arrow_schema)) != sorted(self.config.columns):
                raise ValueError(f"Tried to load parquet data with columns '{self.config.columns}' with mismatching features '{self.info.features}'")
        filter_expr = pq.filters_to_expression(self.config.filters) if isinstance(self.config.filters, list) else self.config.filters
        parquet_file_format = ds.ParquetFileFormat(default_fragment_scan_options=self.config.fragment_scan_options)
        for file_idx, (file, row_groups) in enumerate(zip(files, row_groups_list)):
            try:
                with open(file, 'rb') as f:
                    parquet_fragment = parquet_file_format.make_fragment(f)
                    if row_groups is not None:
                        parquet_fragment.subset(row_group_ids=row_groups)
                    if parquet_fragment.row_groups:
                        batch_size = self.config.batch_size or parquet_fragment.row_groups[0].num_rows
                        for batch_idx, record_batch in enumerate(parquet_fragment.to_batches(batch_size=batch_size, columns=self.config.columns, filter=filter_expr, batch_readahead=0, fragment_readahead=0)):
                            pa_table = pa.Table.from_batches([record_batch])
                            yield (Key(file_idx, batch_idx), self._cast_table(pa_table))
            except (pa.ArrowInvalid, ValueError) as e:
                if self.config.on_bad_files == 'error':
                    logger.error(f"Failed to read file '{file}' with error {type(e).__name__}: {e}")
                    raise
                elif self.config.on_bad_files == 'warn':
                    logger.warning(f"Skipping bad file '{file}'. {type(e).__name__}: {e}`")
                else:
                    logger.debug(f"Skipping bad file '{file}'. {type(e).__name__}: {e}`")

import inspect
import os
import random
import shutil
import tempfile
import weakref
from functools import wraps
from pathlib import Path
from typing import TYPE_CHECKING, Any, Callable, Optional, Union
import numpy as np
import xxhash
from . import config
from .naming import INVALID_WINDOWS_CHARACTERS_IN_PATH
from .utils._dill import dumps
from .utils.logging import get_logger
if TYPE_CHECKING:
    from .arrow_dataset import Dataset
logger = get_logger(__name__)
_CACHING_ENABLED = True
_TEMP_DIR_FOR_TEMP_CACHE_FILES: Optional['_TempCacheDir'] = None
_DATASETS_WITH_TABLE_IN_TEMP_DIR: Optional[weakref.WeakSet] = None

class _TempCacheDir:

    def __init__(self):
        tmpdir = os.environ.get('TMPDIR') or os.environ.get('TEMP') or os.environ.get('TMP')
        if tmpdir:
            tmpdir = os.path.normpath(tmpdir)
            if not os.path.exists(tmpdir):
                try:
                    os.makedirs(tmpdir, exist_ok=True)
                    logger.info(f'Created TMPDIR directory: {tmpdir}')
                except OSError as e:
                    raise OSError(f"TMPDIR is set to '{tmpdir}' but the directory does not exist and could not be created: {e}. Please create it manually or unset TMPDIR to fall back to the default temporary directory.") from e
            elif not os.path.isdir(tmpdir):
                raise OSError(f"TMPDIR is set to '{tmpdir}' but it is not a directory. Please point TMPDIR to a writable directory or unset it to fall back to the default temporary directory.")
        self.name = tempfile.mkdtemp(prefix=config.TEMP_CACHE_DIR_PREFIX, dir=tmpdir)
        self._finalizer = weakref.finalize(self, self._cleanup)

    def _cleanup(self):
        for dset in get_datasets_with_cache_file_in_temp_dir():
            dset.__del__()
        if os.path.exists(self.name):
            try:
                shutil.rmtree(self.name)
            except Exception as e:
                raise OSError(f'An error occurred while trying to delete temporary cache directory {self.name}. Please delete it manually.') from e

    def cleanup(self):
        if self._finalizer.detach():
            self._cleanup()

def maybe_register_dataset_for_temp_dir_deletion(dataset):
    if _TEMP_DIR_FOR_TEMP_CACHE_FILES is None:
        return
    global _DATASETS_WITH_TABLE_IN_TEMP_DIR
    if _DATASETS_WITH_TABLE_IN_TEMP_DIR is None:
        _DATASETS_WITH_TABLE_IN_TEMP_DIR = weakref.WeakSet()
    if any((Path(_TEMP_DIR_FOR_TEMP_CACHE_FILES.name) in Path(cache_file['filename']).parents for cache_file in dataset.cache_files)):
        _DATASETS_WITH_TABLE_IN_TEMP_DIR.add(dataset)

def get_datasets_with_cache_file_in_temp_dir():
    return list(_DATASETS_WITH_TABLE_IN_TEMP_DIR) if _DATASETS_WITH_TABLE_IN_TEMP_DIR is not None else []

def enable_caching():
    global _CACHING_ENABLED
    _CACHING_ENABLED = True

def disable_caching():
    global _CACHING_ENABLED
    _CACHING_ENABLED = False

def is_caching_enabled() -> bool:
    global _CACHING_ENABLED
    return bool(_CACHING_ENABLED)

def get_temporary_cache_files_directory() -> str:
    global _TEMP_DIR_FOR_TEMP_CACHE_FILES
    if _TEMP_DIR_FOR_TEMP_CACHE_FILES is None:
        _TEMP_DIR_FOR_TEMP_CACHE_FILES = _TempCacheDir()
    return _TEMP_DIR_FOR_TEMP_CACHE_FILES.name

class Hasher:
    dispatch: dict = {}

    def __init__(self):
        self.m = xxhash.xxh64()

    @classmethod
    def hash_bytes(cls, value: Union[bytes, list[bytes]]) -> str:
        value = [value] if isinstance(value, bytes) else value
        m = xxhash.xxh64()
        for x in value:
            m.update(x)
        return m.hexdigest()

    @classmethod
    def hash(cls, value: Any) -> str:
        return cls.hash_bytes(dumps(value))

    def update(self, value: Any) -> None:
        header_for_update = f'=={type(value)}=='
        value_for_update = self.hash(value)
        self.m.update(header_for_update.encode('utf8'))
        self.m.update(value_for_update.encode('utf-8'))

    def hexdigest(self) -> str:
        return self.m.hexdigest()
fingerprint_rng = random.Random()
fingerprint_warnings: dict[str, bool] = {}

def generate_fingerprint(dataset: 'Dataset') -> str:
    state = dataset.__dict__
    hasher = Hasher()
    for key in sorted(state):
        if key == '_fingerprint':
            continue
        hasher.update(key)
        hasher.update(state[key])
    for cache_file in dataset.cache_files:
        hasher.update(os.path.getmtime(cache_file['filename']))
    return hasher.hexdigest()

def generate_random_fingerprint(nbits: int=64) -> str:
    return f'{fingerprint_rng.getrandbits(nbits):0{nbits // 4}x}'

def update_fingerprint(fingerprint, transform, transform_args):
    global fingerprint_warnings
    hasher = Hasher()
    hasher.update(fingerprint)
    try:
        hasher.update(transform)
    except:
        if _CACHING_ENABLED:
            if not fingerprint_warnings.get('update_fingerprint_transform_hash_failed', False):
                logger.warning(f"Transform {transform} couldn't be hashed properly, a random hash was used instead. Make sure your transforms and parameters are serializable with pickle or dill for the dataset fingerprinting and caching to work. If you reuse this transform, the caching mechanism will consider it to be different from the previous calls and recompute everything. This warning is only shown once. Subsequent hashing failures won't be shown.")
                fingerprint_warnings['update_fingerprint_transform_hash_failed'] = True
            else:
                logger.info(f"Transform {transform} couldn't be hashed properly, a random hash was used instead.")
        else:
            logger.info(f"Transform {transform} couldn't be hashed properly, a random hash was used instead. This doesn't affect caching since it's disabled.")
        return generate_random_fingerprint()
    for key in sorted(transform_args):
        hasher.update(key)
        try:
            hasher.update(transform_args[key])
        except:
            if _CACHING_ENABLED:
                if not fingerprint_warnings.get('update_fingerprint_transform_hash_failed', False):
                    logger.warning(f"Parameter '{key}'={transform_args[key]} of the transform {transform} couldn't be hashed properly, a random hash was used instead. Make sure your transforms and parameters are serializable with pickle or dill for the dataset fingerprinting and caching to work. If you reuse this transform, the caching mechanism will consider it to be different from the previous calls and recompute everything. This warning is only shown once. Subsequent hashing failures won't be shown.")
                    fingerprint_warnings['update_fingerprint_transform_hash_failed'] = True
                else:
                    logger.info(f"Parameter '{key}'={transform_args[key]} of the transform {transform} couldn't be hashed properly, a random hash was used instead.")
            else:
                logger.info(f"Parameter '{key}'={transform_args[key]} of the transform {transform} couldn't be hashed properly, a random hash was used instead. This doesn't affect caching since it's disabled.")
            return generate_random_fingerprint()
    return hasher.hexdigest()

def validate_fingerprint(fingerprint: str, max_length=64):
    if not isinstance(fingerprint, str) or not fingerprint:
        raise ValueError(f"Invalid fingerprint '{fingerprint}': it should be a non-empty string.")
    for invalid_char in INVALID_WINDOWS_CHARACTERS_IN_PATH:
        if invalid_char in fingerprint:
            raise ValueError(f"Invalid fingerprint. Bad characters from black list '{INVALID_WINDOWS_CHARACTERS_IN_PATH}' found in '{fingerprint}'. They could create issues when creating cache files.")
    if len(fingerprint) > max_length:
        raise ValueError(f"Invalid fingerprint. Maximum lenth is {max_length} but '{fingerprint}' has length {len(fingerprint)}.It could create issues when creating cache files.")

def format_transform_for_fingerprint(func: Callable, version: Optional[str]=None) -> str:
    transform = f'{func.__module__}.{func.__qualname__}'
    if version is not None:
        transform += f'@{version}'
    return transform

def format_kwargs_for_fingerprint(func: Callable, args: tuple, kwargs: dict[str, Any], use_kwargs: Optional[list[str]]=None, ignore_kwargs: Optional[list[str]]=None, randomized_function: bool=False) -> dict[str, Any]:
    kwargs_for_fingerprint = kwargs.copy()
    if args:
        params = [p.name for p in inspect.signature(func).parameters.values() if p != p.VAR_KEYWORD]
        args = args[1:]
        params = params[1:]
        kwargs_for_fingerprint.update(zip(params, args))
    else:
        del kwargs_for_fingerprint[next(iter(inspect.signature(func).parameters))]
    if use_kwargs:
        kwargs_for_fingerprint = {k: v for k, v in kwargs_for_fingerprint.items() if k in use_kwargs}
    if ignore_kwargs:
        kwargs_for_fingerprint = {k: v for k, v in kwargs_for_fingerprint.items() if k not in ignore_kwargs}
    if randomized_function:
        if kwargs_for_fingerprint.get('seed') is None and kwargs_for_fingerprint.get('generator') is None:
            _, seed, pos, *_ = np.random.get_state()
            seed = seed[pos] if pos < 624 else seed[0]
            kwargs_for_fingerprint['generator'] = np.random.default_rng(seed)
    default_values = {p.name: p.default for p in inspect.signature(func).parameters.values() if p.default != inspect._empty}
    for default_varname, default_value in default_values.items():
        if default_varname in kwargs_for_fingerprint and kwargs_for_fingerprint[default_varname] == default_value:
            kwargs_for_fingerprint.pop(default_varname)
    return kwargs_for_fingerprint

def fingerprint_transform(inplace: bool, use_kwargs: Optional[list[str]]=None, ignore_kwargs: Optional[list[str]]=None, fingerprint_names: Optional[list[str]]=None, randomized_function: bool=False, version: Optional[str]=None):
    if use_kwargs is not None and (not isinstance(use_kwargs, list)):
        raise ValueError(f'use_kwargs is supposed to be a list, not {type(use_kwargs)}')
    if ignore_kwargs is not None and (not isinstance(ignore_kwargs, list)):
        raise ValueError(f'ignore_kwargs is supposed to be a list, not {type(use_kwargs)}')
    if inplace and fingerprint_names:
        raise ValueError('fingerprint_names are only used when inplace is False')
    fingerprint_names = fingerprint_names if fingerprint_names is not None else ['new_fingerprint']

    def _fingerprint(func):
        if not inplace and (not all((name in func.__code__.co_varnames for name in fingerprint_names))):
            raise ValueError(f'function {func} is missing parameters {fingerprint_names} in signature')
        if randomized_function:
            if 'seed' not in func.__code__.co_varnames:
                raise ValueError(f"'seed' must be in {func}'s signature")
            if 'generator' not in func.__code__.co_varnames:
                raise ValueError(f"'generator' must be in {func}'s signature")
        transform = format_transform_for_fingerprint(func, version=version)

        @wraps(func)
        def wrapper(*args, **kwargs):
            kwargs_for_fingerprint = format_kwargs_for_fingerprint(func, args, kwargs, use_kwargs=use_kwargs, ignore_kwargs=ignore_kwargs, randomized_function=randomized_function)
            if args:
                dataset: Dataset = args[0]
                args = args[1:]
            else:
                dataset: Dataset = kwargs.pop(next(iter(inspect.signature(func).parameters)))
            if inplace:
                new_fingerprint = update_fingerprint(dataset._fingerprint, transform, kwargs_for_fingerprint)
            else:
                for fingerprint_name in fingerprint_names:
                    if kwargs.get(fingerprint_name) is None:
                        kwargs_for_fingerprint['fingerprint_name'] = fingerprint_name
                        kwargs[fingerprint_name] = update_fingerprint(dataset._fingerprint, transform, kwargs_for_fingerprint)
                    else:
                        validate_fingerprint(kwargs[fingerprint_name])
            out = func(dataset, *args, **kwargs)
            if inplace:
                dataset._fingerprint = new_fingerprint
            return out
        wrapper._decorator_name_ = 'fingerprint'
        return wrapper
    return _fingerprint

from __future__ import annotations
import re
import typing
from ..exceptions import LocationParseError
from .util import to_str
_NORMALIZABLE_SCHEMES = ('http', 'https', None)
_PERCENT_RE = re.compile('%[a-fA-F0-9]{2}')
_SCHEME_RE = re.compile('^(?:[a-zA-Z][a-zA-Z0-9+-]*:|/)')
_URI_RE = re.compile('^(?:([a-zA-Z][a-zA-Z0-9+.-]*):)?(?://([^\\\\/?#]*))?([^?#]*)(?:\\?([^#]*))?(?:#(.*))?$', re.UNICODE | re.DOTALL)
_IPV4_PAT = '(?:[0-9]{1,3}\\.){3}[0-9]{1,3}'
_HEX_PAT = '[0-9A-Fa-f]{1,4}'
_LS32_PAT = '(?:{hex}:{hex}|{ipv4})'.format(hex=_HEX_PAT, ipv4=_IPV4_PAT)
_subs = {'hex': _HEX_PAT, 'ls32': _LS32_PAT}
_variations = ['(?:%(hex)s:){6}%(ls32)s', '::(?:%(hex)s:){5}%(ls32)s', '(?:%(hex)s)?::(?:%(hex)s:){4}%(ls32)s', '(?:(?:%(hex)s:)?%(hex)s)?::(?:%(hex)s:){3}%(ls32)s', '(?:(?:%(hex)s:){0,2}%(hex)s)?::(?:%(hex)s:){2}%(ls32)s', '(?:(?:%(hex)s:){0,3}%(hex)s)?::%(hex)s:%(ls32)s', '(?:(?:%(hex)s:){0,4}%(hex)s)?::%(ls32)s', '(?:(?:%(hex)s:){0,5}%(hex)s)?::%(hex)s', '(?:(?:%(hex)s:){0,6}%(hex)s)?::']
_UNRESERVED_PAT = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._\\-~'
_IPV6_PAT = '(?:' + '|'.join([x % _subs for x in _variations]) + ')'
_ZONE_ID_PAT = '(?:%25|%)(?:[' + _UNRESERVED_PAT + ']|%[a-fA-F0-9]{2})+'
_IPV6_ADDRZ_PAT = '\\[' + _IPV6_PAT + '(?:' + _ZONE_ID_PAT + ')?\\]'
_REG_NAME_PAT = '(?:[^\\[\\]%:/?#]|%[a-fA-F0-9]{2})*'
_TARGET_RE = re.compile('^(/[^?#]*)(?:\\?([^#]*))?(?:#.*)?$')
_IPV4_RE = re.compile('^' + _IPV4_PAT + '$')
_IPV6_RE = re.compile('^' + _IPV6_PAT + '$')
_IPV6_ADDRZ_RE = re.compile('^' + _IPV6_ADDRZ_PAT + '$')
_BRACELESS_IPV6_ADDRZ_RE = re.compile('^' + _IPV6_ADDRZ_PAT[2:-2] + '$')
_ZONE_ID_RE = re.compile('(' + _ZONE_ID_PAT + ')\\]$')
_HOST_PORT_PAT = '^(%s|%s|%s)(?::0*?(|0|[1-9][0-9]{0,4}))?$' % (_REG_NAME_PAT, _IPV4_PAT, _IPV6_ADDRZ_PAT)
_HOST_PORT_RE = re.compile(_HOST_PORT_PAT, re.UNICODE | re.DOTALL)
_UNRESERVED_CHARS = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789._-~')
_SUB_DELIM_CHARS = set("!$&'()*+,;=")
_USERINFO_CHARS = _UNRESERVED_CHARS | _SUB_DELIM_CHARS | {':'}
_PATH_CHARS = _USERINFO_CHARS | {'@', '/'}
_QUERY_CHARS = _FRAGMENT_CHARS = _PATH_CHARS | {'?'}

class Url(typing.NamedTuple('Url', [('scheme', typing.Optional[str]), ('auth', typing.Optional[str]), ('host', typing.Optional[str]), ('port', typing.Optional[int]), ('path', typing.Optional[str]), ('query', typing.Optional[str]), ('fragment', typing.Optional[str])])):

    def __new__(cls, scheme: str | None=None, auth: str | None=None, host: str | None=None, port: int | None=None, path: str | None=None, query: str | None=None, fragment: str | None=None):
        if path and (not path.startswith('/')):
            path = '/' + path
        if scheme is not None:
            scheme = scheme.lower()
        return super().__new__(cls, scheme, auth, host, port, path, query, fragment)

    @property
    def hostname(self) -> str | None:
        return self.host

    @property
    def request_uri(self) -> str:
        uri = self.path or '/'
        if self.query is not None:
            uri += '?' + self.query
        return uri

    @property
    def authority(self) -> str | None:
        userinfo = self.auth
        netloc = self.netloc
        if netloc is None or userinfo is None:
            return netloc
        else:
            return f'{userinfo}@{netloc}'

    @property
    def netloc(self) -> str | None:
        if self.host is None:
            return None
        if self.port:
            return f'{self.host}:{self.port}'
        return self.host

    @property
    def url(self) -> str:
        scheme, auth, host, port, path, query, fragment = self
        url = ''
        if scheme is not None:
            url += scheme + '://'
        if auth is not None:
            url += auth + '@'
        if host is not None:
            url += host
        if port is not None:
            url += ':' + str(port)
        if path is not None:
            url += path
        if query is not None:
            url += '?' + query
        if fragment is not None:
            url += '#' + fragment
        return url

    def __str__(self) -> str:
        return self.url

@typing.overload
def _encode_invalid_chars(component: str, allowed_chars: typing.Container[str]) -> str:
    ...

@typing.overload
def _encode_invalid_chars(component: None, allowed_chars: typing.Container[str]) -> None:
    ...

def _encode_invalid_chars(component: str | None, allowed_chars: typing.Container[str]) -> str | None:
    if component is None:
        return component
    component = to_str(component)
    component, percent_encodings = _PERCENT_RE.subn(lambda match: match.group(0).upper(), component)
    uri_bytes = component.encode('utf-8', 'surrogatepass')
    is_percent_encoded = percent_encodings == uri_bytes.count(b'%')
    encoded_component = bytearray()
    for i in range(0, len(uri_bytes)):
        byte = uri_bytes[i:i + 1]
        byte_ord = ord(byte)
        if is_percent_encoded and byte == b'%' or (byte_ord < 128 and byte.decode() in allowed_chars):
            encoded_component += byte
            continue
        encoded_component.extend(b'%' + hex(byte_ord)[2:].encode().zfill(2).upper())
    return encoded_component.decode()

def _remove_path_dot_segments(path: str) -> str:
    segments = path.split('/')
    output = []
    for segment in segments:
        if segment == '.':
            continue
        if segment != '..':
            output.append(segment)
        elif output:
            output.pop()
    if path.startswith('/') and (not output or output[0]):
        output.insert(0, '')
    if path.endswith(('/.', '/..')):
        output.append('')
    return '/'.join(output)

@typing.overload
def _normalize_host(host: None, scheme: str | None) -> None:
    ...

@typing.overload
def _normalize_host(host: str, scheme: str | None) -> str:
    ...

def _normalize_host(host: str | None, scheme: str | None) -> str | None:
    if host:
        if scheme in _NORMALIZABLE_SCHEMES:
            is_ipv6 = _IPV6_ADDRZ_RE.match(host)
            if is_ipv6:
                match = _ZONE_ID_RE.search(host)
                if match:
                    start, end = match.span(1)
                    zone_id = host[start:end]
                    if zone_id.startswith('%25') and zone_id != '%25':
                        zone_id = zone_id[3:]
                    else:
                        zone_id = zone_id[1:]
                    zone_id = _encode_invalid_chars(zone_id, _UNRESERVED_CHARS)
                    return f'{host[:start].lower()}%{zone_id}{host[end:]}'
                else:
                    return host.lower()
            elif not _IPV4_RE.match(host):
                return to_str(b'.'.join([_idna_encode(label) for label in host.split('.')]), 'ascii')
    return host

def _idna_encode(name: str) -> bytes:
    if not name.isascii():
        try:
            import idna
        except ImportError:
            raise LocationParseError("Unable to parse URL without the 'idna' module") from None
        try:
            return idna.encode(name.lower(), strict=True, std3_rules=True)
        except idna.IDNAError:
            raise LocationParseError(f"Name '{name}' is not a valid IDNA label") from None
    return name.lower().encode('ascii')

def _encode_target(target: str) -> str:
    match = _TARGET_RE.match(target)
    if not match:
        raise LocationParseError(f'{target!r} is not a valid request URI')
    path, query = match.groups()
    encoded_target = _encode_invalid_chars(path, _PATH_CHARS)
    if query is not None:
        query = _encode_invalid_chars(query, _QUERY_CHARS)
        encoded_target += '?' + query
    return encoded_target

def parse_url(url: str) -> Url:
    if not url:
        return Url()
    source_url = url
    if not _SCHEME_RE.search(url):
        url = '//' + url
    scheme: str | None
    authority: str | None
    auth: str | None
    host: str | None
    port: str | None
    port_int: int | None
    path: str | None
    query: str | None
    fragment: str | None
    try:
        scheme, authority, path, query, fragment = _URI_RE.match(url).groups()
        normalize_uri = scheme is None or scheme.lower() in _NORMALIZABLE_SCHEMES
        if scheme:
            scheme = scheme.lower()
        if authority:
            auth, _, host_port = authority.rpartition('@')
            auth = auth or None
            host, port = _HOST_PORT_RE.match(host_port).groups()
            if auth and normalize_uri:
                auth = _encode_invalid_chars(auth, _USERINFO_CHARS)
            if port == '':
                port = None
        else:
            auth, host, port = (None, None, None)
        if port is not None:
            port_int = int(port)
            if not 0 <= port_int <= 65535:
                raise LocationParseError(url)
        else:
            port_int = None
        host = _normalize_host(host, scheme)
        if normalize_uri and path:
            path = _remove_path_dot_segments(path)
            path = _encode_invalid_chars(path, _PATH_CHARS)
        if normalize_uri and query:
            query = _encode_invalid_chars(query, _QUERY_CHARS)
        if normalize_uri and fragment:
            fragment = _encode_invalid_chars(fragment, _FRAGMENT_CHARS)
    except (ValueError, AttributeError) as e:
        raise LocationParseError(source_url) from e
    if not path:
        if query is not None or fragment is not None:
            path = ''
        else:
            path = None
    return Url(scheme=scheme, auth=auth, host=host, port=port_int, path=path, query=query, fragment=fragment)

