        self.exception = exception
        self.exc_info = exc_info

    @property
    def output(self) -> str:
        return self.output_bytes.decode(self.runner.charset, 'replace').replace('\r\n', '\n')

    @property
    def stdout(self) -> str:
        return self.stdout_bytes.decode(self.runner.charset, 'replace').replace('\r\n', '\n')

    @property
    def stderr(self) -> str:
        return self.stderr_bytes.decode(self.runner.charset, 'replace').replace('\r\n', '\n')

    def __repr__(self) -> str:
        exc_str = repr(self.exception) if self.exception else 'okay'
        return f'<{type(self).__name__} {exc_str}>'

class CliRunner:

    def __init__(self, charset: str='utf-8', env: cabc.Mapping[str, str | None] | None=None, echo_stdin: bool=False, catch_exceptions: bool=True) -> None:
        self.charset = charset
        self.env: cabc.Mapping[str, str | None] = env or {}
        self.echo_stdin = echo_stdin
        self.catch_exceptions = catch_exceptions

    def get_default_prog_name(self, cli: Command) -> str:
        return cli.name or 'root'

    def make_env(self, overrides: cabc.Mapping[str, str | None] | None=None) -> cabc.Mapping[str, str | None]:
        rv = dict(self.env)
        if overrides:
            rv.update(overrides)
        return rv

    @contextlib.contextmanager
    def isolation(self, input: str | bytes | t.IO[t.Any] | None=None, env: cabc.Mapping[str, str | None] | None=None, color: bool=False) -> cabc.Iterator[tuple[io.BytesIO, io.BytesIO, io.BytesIO]]:
        bytes_input = make_input_stream(input, self.charset)
        echo_input = None
        old_stdin = sys.stdin
        old_stdout = sys.stdout
        old_stderr = sys.stderr
        old_forced_width = formatting.FORCED_WIDTH
        formatting.FORCED_WIDTH = 80
        env = self.make_env(env)
        stream_mixer = StreamMixer()
        if self.echo_stdin:
            bytes_input = echo_input = t.cast(t.BinaryIO, EchoingStdin(bytes_input, stream_mixer.stdout))
        sys.stdin = text_input = _NamedTextIOWrapper(bytes_input, encoding=self.charset, name='<stdin>', mode='r')
        if self.echo_stdin:
            text_input._CHUNK_SIZE = 1
        sys.stdout = _NamedTextIOWrapper(stream_mixer.stdout, encoding=self.charset, name='<stdout>', mode='w')
        sys.stderr = _NamedTextIOWrapper(stream_mixer.stderr, encoding=self.charset, name='<stderr>', mode='w', errors='backslashreplace')

        @_pause_echo(echo_input)
        def visible_input(prompt: str | None=None) -> str:
            sys.stdout.write(prompt or '')
            try:
                val = next(text_input).rstrip('\r\n')
            except StopIteration as e:
                raise EOFError() from e
            sys.stdout.write(f'{val}\n')
            sys.stdout.flush()
            return val

        @_pause_echo(echo_input)
        def hidden_input(prompt: str | None=None) -> str:
            sys.stdout.write(f"{prompt or ''}\n")
            sys.stdout.flush()
            try:
                return next(text_input).rstrip('\r\n')
            except StopIteration as e:
                raise EOFError() from e

        @_pause_echo(echo_input)
        def _getchar(echo: bool) -> str:
            char = sys.stdin.read(1)
            if echo:
                sys.stdout.write(char)
            sys.stdout.flush()
            return char
        default_color = color

        def should_strip_ansi(stream: t.IO[t.Any] | None=None, color: bool | None=None) -> bool:
            if color is None:
                return not default_color
            return not color
        old_visible_prompt_func = termui.visible_prompt_func
        old_hidden_prompt_func = termui.hidden_prompt_func
        old__getchar_func = termui._getchar
        old_should_strip_ansi = utils.should_strip_ansi
        old__compat_should_strip_ansi = _compat.should_strip_ansi
        termui.visible_prompt_func = visible_input
        termui.hidden_prompt_func = hidden_input
        termui._getchar = _getchar
        utils.should_strip_ansi = should_strip_ansi
        _compat.should_strip_ansi = should_strip_ansi
        old_env = {}
        try:
            for key, value in env.items():
                old_env[key] = os.environ.get(key)
                if value is None:
                    try:
                        del os.environ[key]
                    except Exception:
                        pass
                else:
                    os.environ[key] = value
            yield (stream_mixer.stdout, stream_mixer.stderr, stream_mixer.output)
        finally:
            for key, value in old_env.items():
                if value is None:
                    try:
                        del os.environ[key]
                    except Exception:
                        pass
                else:
                    os.environ[key] = value
            sys.stdout = old_stdout
            sys.stderr = old_stderr
            sys.stdin = old_stdin
            termui.visible_prompt_func = old_visible_prompt_func
            termui.hidden_prompt_func = old_hidden_prompt_func
            termui._getchar = old__getchar_func
            utils.should_strip_ansi = old_should_strip_ansi
            _compat.should_strip_ansi = old__compat_should_strip_ansi
            formatting.FORCED_WIDTH = old_forced_width

    def invoke(self, cli: Command, args: str | cabc.Sequence[str] | None=None, input: str | bytes | t.IO[t.Any] | None=None, env: cabc.Mapping[str, str | None] | None=None, catch_exceptions: bool | None=None, color: bool=False, **extra: t.Any) -> Result:
        exc_info = None
        if catch_exceptions is None:
            catch_exceptions = self.catch_exceptions
        with self.isolation(input=input, env=env, color=color) as outstreams:
            return_value = None
            exception: BaseException | None = None
            exit_code = 0
            if isinstance(args, str):
                args = shlex.split(args)
            try:
                prog_name = extra.pop('prog_name')
            except KeyError:
                prog_name = self.get_default_prog_name(cli)
            try:
                return_value = cli.main(args=args or (), prog_name=prog_name, **extra)
            except SystemExit as e:
                exc_info = sys.exc_info()
                e_code = t.cast('int | t.Any | None', e.code)
                if e_code is None:
                    e_code = 0
                if e_code != 0:
                    exception = e
                if not isinstance(e_code, int):
                    sys.stdout.write(str(e_code))
                    sys.stdout.write('\n')
                    e_code = 1
                exit_code = e_code
            except Exception as e:
                if not catch_exceptions:
                    raise
                exception = e
                exit_code = 1
                exc_info = sys.exc_info()
            finally:
                sys.stdout.flush()
                sys.stderr.flush()
                stdout = outstreams[0].getvalue()
                stderr = outstreams[1].getvalue()
                output = outstreams[2].getvalue()
        return Result(runner=self, stdout_bytes=stdout, stderr_bytes=stderr, output_bytes=output, return_value=return_value, exit_code=exit_code, exception=exception, exc_info=exc_info)

    @contextlib.contextmanager
    def isolated_filesystem(self, temp_dir: str | os.PathLike[str] | None=None) -> cabc.Iterator[str]:
        cwd = os.getcwd()
        dt = tempfile.mkdtemp(dir=temp_dir)
        os.chdir(dt)
        try:
            yield dt
        finally:
            os.chdir(cwd)
            if temp_dir is None:
                import shutil
                try:
                    shutil.rmtree(dt)
                except OSError:
                    pass

import io
