        self.path_in_repo = _validate_path_in_repo(self.path_in_repo)

@dataclass
class CommitOperationAdd:
    path_in_repo: str
    path_or_fileobj: Union[str, Path, bytes, BinaryIO]
    upload_info: UploadInfo = field(init=False, repr=False)
    _upload_mode: Optional[UploadMode] = field(init=False, repr=False, default=None)
    _should_ignore: Optional[bool] = field(init=False, repr=False, default=None)
    _remote_oid: Optional[str] = field(init=False, repr=False, default=None)
    _is_uploaded: bool = field(init=False, repr=False, default=False)
    _is_committed: bool = field(init=False, repr=False, default=False)

    def __post_init__(self) -> None:
        self.path_in_repo = _validate_path_in_repo(self.path_in_repo)
        if isinstance(self.path_or_fileobj, Path):
            self.path_or_fileobj = str(self.path_or_fileobj)
        if isinstance(self.path_or_fileobj, str):
            path_or_fileobj = os.path.normpath(os.path.expanduser(self.path_or_fileobj))
            if not os.path.isfile(path_or_fileobj):
                raise ValueError(f"Provided path: '{path_or_fileobj}' is not a file on the local file system")
        elif not isinstance(self.path_or_fileobj, (io.BufferedIOBase, bytes)):
            raise ValueError('path_or_fileobj must be either an instance of str, bytes or io.BufferedIOBase. If you passed a file-like object, make sure it is in binary mode.')
        if isinstance(self.path_or_fileobj, io.BufferedIOBase):
            try:
                self.path_or_fileobj.tell()
                self.path_or_fileobj.seek(0, os.SEEK_CUR)
            except (OSError, AttributeError) as exc:
                raise ValueError('path_or_fileobj is a file-like object but does not implement seek() and tell()') from exc
        if isinstance(self.path_or_fileobj, str):
            self.upload_info = UploadInfo.from_path(self.path_or_fileobj)
        elif isinstance(self.path_or_fileobj, bytes):
            self.upload_info = UploadInfo.from_bytes(self.path_or_fileobj)
        else:
            self.upload_info = UploadInfo.from_fileobj(self.path_or_fileobj)

    @contextmanager
    def as_file(self, with_tqdm: bool=False) -> Iterator[BinaryIO]:
        if isinstance(self.path_or_fileobj, str) or isinstance(self.path_or_fileobj, Path):
            if with_tqdm:
                with tqdm_stream_file(self.path_or_fileobj) as file:
                    yield file
            else:
                with open(self.path_or_fileobj, 'rb') as file:
                    yield file
        elif isinstance(self.path_or_fileobj, bytes):
            yield io.BytesIO(self.path_or_fileobj)
        elif isinstance(self.path_or_fileobj, io.BufferedIOBase):
            prev_pos = self.path_or_fileobj.tell()
            yield self.path_or_fileobj
            self.path_or_fileobj.seek(prev_pos, io.SEEK_SET)

    def b64content(self) -> bytes:
        with self.as_file() as file:
            return base64.b64encode(file.read())

    @property
    def _local_oid(self) -> Optional[str]:
        if self._upload_mode is None:
            return None
        elif self._upload_mode == 'lfs':
            return self.upload_info.sha256.hex()
        else:
            with self.as_file() as file:
                return sha.git_hash(file.read())

def _validate_path_in_repo(path_in_repo: str) -> str:
    if path_in_repo.startswith('/'):
        path_in_repo = path_in_repo[1:]
    if path_in_repo == '.' or path_in_repo == '..' or path_in_repo.startswith('../'):
        raise ValueError(f"Invalid `path_in_repo` in CommitOperation: '{path_in_repo}'")
    if path_in_repo.startswith('./'):
        path_in_repo = path_in_repo[2:]
    for forbidden in FORBIDDEN_FOLDERS:
        if any((part == forbidden for part in path_in_repo.split('/'))):
            raise ValueError(f"Invalid `path_in_repo` in CommitOperation: cannot update files under a '{forbidden}/' folder (path: '{path_in_repo}').")
    return path_in_repo
CommitOperation = Union[CommitOperationAdd, CommitOperationCopy, CommitOperationDelete]

def _warn_on_overwriting_operations(operations: list[CommitOperation]) -> None:
    nb_additions_per_path: dict[str, int] = defaultdict(int)
    for operation in operations:
        path_in_repo = operation.path_in_repo
        if isinstance(operation, CommitOperationAdd):
            if nb_additions_per_path[path_in_repo] > 0:
                warnings.warn(f"About to update multiple times the same file in the same commit: '{path_in_repo}'. This can cause undesired inconsistencies in your repo.")
            nb_additions_per_path[path_in_repo] += 1
            for parent in PurePosixPath(path_in_repo).parents:
                nb_additions_per_path[str(parent)] += 1
        if isinstance(operation, CommitOperationDelete):
            if nb_additions_per_path[str(PurePosixPath(path_in_repo))] > 0:
                if operation.is_folder:
                    warnings.warn(f"About to delete a folder containing files that have just been updated within the same commit: '{path_in_repo}'. This can cause undesired inconsistencies in your repo.")
                else:
                    warnings.warn(f"About to delete a file that have just been updated within the same commit: '{path_in_repo}'. This can cause undesired inconsistencies in your repo.")

@validate_hf_hub_args
def _upload_files(*, additions: list[CommitOperationAdd], repo_type: str, repo_id: str, headers: dict[str, str], endpoint: Optional[str]=None, num_threads: int=5, revision: Optional[str]=None, create_pr: Optional[bool]=None):
    xet_additions: list[CommitOperationAdd] = []
    lfs_actions: list[dict[str, Any]] = []
    lfs_oid2addop: dict[str, CommitOperationAdd] = {}
    for chunk in chunk_iterable(additions, chunk_size=UPLOAD_BATCH_MAX_NUM_FILES):
        chunk_list = [op for op in chunk]
        transfers: list[str] = ['basic', 'multipart']
        has_buffered_io_data = any((isinstance(op.path_or_fileobj, io.BufferedIOBase) for op in chunk_list))
        if is_xet_available():
            if not has_buffered_io_data:
                transfers.append('xet')
            else:
                logger.warning('Uploading files as a binary IO buffer is not supported by Xet Storage. Falling back to HTTP upload.')
        actions_chunk, errors_chunk, chosen_transfer = post_lfs_batch_info(upload_infos=[op.upload_info for op in chunk_list], repo_id=repo_id, repo_type=repo_type, revision=revision, endpoint=endpoint, headers=headers, token=None, transfers=transfers)
        if errors_chunk:
            message = '\n'.join([f"Encountered error for file with OID {err.get('oid')}: `{err.get('error', {}).get('message')}" for err in errors_chunk])
            raise ValueError(f'LFS batch API returned errors:\n{message}')
        if chosen_transfer == 'xet' and 'xet' in transfers:
            xet_additions.extend(chunk_list)
        else:
            lfs_actions.extend(actions_chunk)
            for op in chunk_list:
                lfs_oid2addop[op.upload_info.sha256.hex()] = op
    if len(lfs_actions) > 0:
        _upload_lfs_files(actions=lfs_actions, oid2addop=lfs_oid2addop, headers=headers, endpoint=endpoint, num_threads=num_threads)
    if len(xet_additions) > 0:
        _upload_xet_files(additions=xet_additions, repo_type=repo_type, repo_id=repo_id, headers=headers, endpoint=endpoint, revision=revision, create_pr=create_pr)

@validate_hf_hub_args
def _upload_lfs_files(*, actions: list[dict[str, Any]], oid2addop: dict[str, CommitOperationAdd], headers: dict[str, str], endpoint: Optional[str]=None, num_threads: int=5):
    filtered_actions = []
    for action in actions:
        if action.get('actions') is None:
            logger.debug(f"Content of file {oid2addop[action['oid']].path_in_repo} is already present upstream - skipping upload.")
        else:
            filtered_actions.append(action)

    def _wrapped_lfs_upload(batch_action) -> None:
        try:
            operation = oid2addop[batch_action['oid']]
            lfs_upload(operation=operation, lfs_batch_action=batch_action, headers=headers, endpoint=endpoint)
        except Exception as exc:
            raise RuntimeError(f"Error while uploading '{operation.path_in_repo}' to the Hub.") from exc
    if len(filtered_actions) == 1:
        logger.debug('Uploading 1 LFS file to the Hub')
        _wrapped_lfs_upload(filtered_actions[0])
    else:
        logger.debug(f'Uploading {len(filtered_actions)} LFS files to the Hub using up to {num_threads} threads concurrently')
        thread_map(_wrapped_lfs_upload, filtered_actions, desc=f'Upload {len(filtered_actions)} LFS files', max_workers=num_threads, tqdm_class=hf_tqdm)

@validate_hf_hub_args
def _upload_xet_files(*, additions: list[CommitOperationAdd], repo_type: str, repo_id: str, headers: dict[str, str], endpoint: Optional[str]=None, revision: Optional[str]=None, create_pr: Optional[bool]=None):
    if len(additions) == 0:
        return
    from hf_xet import upload_bytes, upload_files
    from .utils._xet_progress_reporting import XetProgressReporter
    try:
        xet_connection_info = fetch_xet_connection_info_from_repo_info(token_type=XetTokenType.WRITE, repo_id=repo_id, repo_type=repo_type, revision=revision, headers=headers, endpoint=endpoint, params={'create_pr': '1'} if create_pr else None)
    except HfHubHTTPError as e:
        if e.response.status_code == 401:
            raise XetAuthorizationError(f'You are unauthorized to upload to xet storage for {repo_type}/{repo_id}. Please check that you have configured your access token with write access to the repo.') from e
        raise
    xet_endpoint = xet_connection_info.endpoint
    access_token_info = (xet_connection_info.access_token, xet_connection_info.expiration_unix_epoch)

    def token_refresher() -> tuple[str, int]:
        new_xet_connection = fetch_xet_connection_info_from_repo_info(token_type=XetTokenType.WRITE, repo_id=repo_id, repo_type=repo_type, revision=revision, headers=headers, endpoint=endpoint, params={'create_pr': '1'} if create_pr else None)
        if new_xet_connection is None:
            raise XetRefreshTokenError('Failed to refresh xet token')
        return (new_xet_connection.access_token, new_xet_connection.expiration_unix_epoch)
    if not are_progress_bars_disabled():
        progress = XetProgressReporter()
        progress_callback = progress.update_progress
    else:
        progress, progress_callback = (None, None)
    try:
        all_bytes_ops = [op for op in additions if isinstance(op.path_or_fileobj, bytes)]
        all_paths_ops = [op for op in additions if isinstance(op.path_or_fileobj, (str, Path))]
        xet_headers = headers.copy()
        xet_headers.pop('authorization', None)
        if len(all_paths_ops) > 0:
            all_paths = [str(op.path_or_fileobj) for op in all_paths_ops]
            all_sha256s = [op.upload_info.sha256.hex() for op in all_paths_ops]
            upload_files(all_paths, xet_endpoint, access_token_info, token_refresher, progress_callback, repo_type, request_headers=xet_headers, sha256s=all_sha256s)
        if len(all_bytes_ops) > 0:
            all_bytes = [op.path_or_fileobj for op in all_bytes_ops]
            all_sha256s = [op.upload_info.sha256.hex() for op in all_bytes_ops]
            upload_bytes(all_bytes, xet_endpoint, access_token_info, token_refresher, progress_callback, repo_type, request_headers=xet_headers, sha256s=all_sha256s)
    finally:
        if progress is not None:
            progress.close(False)
    return

def _validate_preupload_info(preupload_info: dict):
    files = preupload_info.get('files')
    if not isinstance(files, list):
        raise ValueError('preupload_info is improperly formatted')
    for file_info in files:
        if not (isinstance(file_info, dict) and isinstance(file_info.get('path'), str) and isinstance(file_info.get('uploadMode'), str) and (file_info['uploadMode'] in ('lfs', 'regular'))):
            raise ValueError('preupload_info is improperly formatted:')
    return preupload_info

@validate_hf_hub_args
def _fetch_upload_modes(additions: Iterable[CommitOperationAdd], repo_type: str, repo_id: str, headers: dict[str, str], revision: str, endpoint: Optional[str]=None, create_pr: bool=False, gitignore_content: Optional[str]=None) -> None:
    endpoint = endpoint if endpoint is not None else constants.ENDPOINT
    upload_modes: dict[str, UploadMode] = {}
    should_ignore_info: dict[str, bool] = {}
    oid_info: dict[str, Optional[str]] = {}
    for chunk in chunk_iterable(additions, 256):
        payload: dict = {'files': [{'path': op.path_in_repo, 'sample': base64.b64encode(op.upload_info.sample).decode('ascii'), 'size': op.upload_info.size} for op in chunk]}
        if gitignore_content is not None:
            payload['gitIgnore'] = gitignore_content
        resp = http_backoff('POST', f'{endpoint}/api/{repo_type}s/{repo_id}/preupload/{revision}', json=payload, headers=headers, params={'create_pr': '1'} if create_pr else None)
        hf_raise_for_status(resp)
        preupload_info = _validate_preupload_info(resp.json())
        upload_modes.update(**{file['path']: file['uploadMode'] for file in preupload_info['files']})
        should_ignore_info.update(**{file['path']: file['shouldIgnore'] for file in preupload_info['files']})
        oid_info.update(**{file['path']: file.get('oid') for file in preupload_info['files']})
    for addition in additions:
        addition._upload_mode = upload_modes[addition.path_in_repo]
        addition._should_ignore = should_ignore_info[addition.path_in_repo]
        addition._remote_oid = oid_info[addition.path_in_repo]
    for addition in additions:
        if addition.upload_info.size == 0:
            addition._upload_mode = 'regular'

@validate_hf_hub_args
def _fetch_files_to_copy(copies: Iterable[CommitOperationCopy], repo_type: str, repo_id: str, headers: dict[str, str], revision: str, endpoint: Optional[str]=None) -> dict[tuple[str, Optional[str]], Union['RepoFile', bytes]]:
    from .hf_api import HfApi, RepoFolder
    hf_api = HfApi(endpoint=endpoint, headers=headers)
    files_to_copy: dict[tuple[str, Optional[str]], Union['RepoFile', bytes]] = {}
    oid_info: dict[tuple[str, Optional[str]], Optional[str]] = {}
    dest_paths = [op.path_in_repo for op in copies]
    for offset in range(0, len(dest_paths), FETCH_LFS_BATCH_SIZE):
        dest_repo_files = hf_api.get_paths_info(repo_id=repo_id, paths=dest_paths[offset:offset + FETCH_LFS_BATCH_SIZE], revision=revision, repo_type=repo_type)
        for file in dest_repo_files:
            if not isinstance(file, RepoFolder):
                oid_info[file.path, revision] = file.blob_id
    for src_revision, operations in groupby(copies, key=lambda op: op.src_revision):
        operations = list(operations)
        src_paths = [op.src_path_in_repo for op in operations]
        for offset in range(0, len(src_paths), FETCH_LFS_BATCH_SIZE):
            src_repo_files = hf_api.get_paths_info(repo_id=repo_id, paths=src_paths[offset:offset + FETCH_LFS_BATCH_SIZE], revision=src_revision or revision, repo_type=repo_type)
            for src_repo_file in src_repo_files:
                if isinstance(src_repo_file, RepoFolder):
                    raise NotImplementedError('Copying a folder is not implemented.')
                oid_info[src_repo_file.path, src_revision] = src_repo_file.blob_id
                if src_repo_file.lfs:
                    files_to_copy[src_repo_file.path, src_revision] = src_repo_file
                else:
                    url = hf_hub_url(endpoint=endpoint, repo_type=repo_type, repo_id=repo_id, revision=src_revision or revision, filename=src_repo_file.path)
                    response = get_session().get(url, headers=headers)
                    hf_raise_for_status(response)
                    files_to_copy[src_repo_file.path, src_revision] = response.content
        for operation in operations:
            if (operation.src_path_in_repo, src_revision) not in files_to_copy:
                raise EntryNotFoundError(f'Cannot copy {operation.src_path_in_repo} at revision {src_revision or revision}: file is missing on repo.')
            operation._src_oid = oid_info.get((operation.src_path_in_repo, operation.src_revision))
            operation._dest_oid = oid_info.get((operation.path_in_repo, revision))
    return files_to_copy

def _prepare_commit_payload(operations: Iterable[CommitOperation], files_to_copy: dict[tuple[str, Optional[str]], Union['RepoFile', bytes]], commit_message: str, commit_description: Optional[str]=None, parent_commit: Optional[str]=None) -> Iterable[dict[str, Any]]:
    commit_description = commit_description if commit_description is not None else ''
    header_value = {'summary': commit_message, 'description': commit_description}
    if parent_commit is not None:
        header_value['parentCommit'] = parent_commit
    yield {'key': 'header', 'value': header_value}
    nb_ignored_files = 0
    for operation in operations:
        if isinstance(operation, CommitOperationAdd) and operation._should_ignore:
            logger.debug(f"Skipping file '{operation.path_in_repo}' in commit (ignored by gitignore file).")
            nb_ignored_files += 1
            continue
        if isinstance(operation, CommitOperationAdd) and operation._upload_mode == 'regular':
            yield {'key': 'file', 'value': {'content': operation.b64content().decode(), 'path': operation.path_in_repo, 'encoding': 'base64'}}
        elif isinstance(operation, CommitOperationAdd) and operation._upload_mode == 'lfs':
            yield {'key': 'lfsFile', 'value': {'path': operation.path_in_repo, 'algo': 'sha256', 'oid': operation.upload_info.sha256.hex(), 'size': operation.upload_info.size}}
        elif isinstance(operation, CommitOperationDelete):
            yield {'key': 'deletedFolder' if operation.is_folder else 'deletedFile', 'value': {'path': operation.path_in_repo}}
        elif isinstance(operation, CommitOperationCopy):
            file_to_copy = files_to_copy[operation.src_path_in_repo, operation.src_revision]
            if isinstance(file_to_copy, bytes):
                yield {'key': 'file', 'value': {'content': base64.b64encode(file_to_copy).decode(), 'path': operation.path_in_repo, 'encoding': 'base64'}}
            elif file_to_copy.lfs:
                yield {'key': 'lfsFile', 'value': {'path': operation.path_in_repo, 'algo': 'sha256', 'oid': file_to_copy.lfs.sha256}}
            else:
                raise ValueError('Malformed files_to_copy (should be raw file content as bytes or RepoFile objects with LFS info.')
        else:
            raise ValueError(f"Unknown operation to commit. Operation: {operation}. Upload mode: {getattr(operation, '_upload_mode', None)}")
    if nb_ignored_files > 0:
        logger.info(f'Skipped {nb_ignored_files} file(s) in commit (ignored by gitignore file).')

import collections
import io
import itertools
import os
from dataclasses import dataclass
from typing import Any, Callable, Iterator, Optional, Union
import pandas as pd
import pyarrow as pa
import pyarrow.dataset as ds
import pyarrow.json as paj
import pyarrow.parquet as pq
import datasets
from datasets import config
from datasets.builder import Key
from datasets.features.features import FeatureType, _visit, _visit_with_path, _VisitPath, require_storage_cast
from datasets.utils.file_utils import readline
logger = datasets.utils.logging.get_logger(__name__)

def count_path_segments(path):
    return path.replace('\\', '/').count('/')

@dataclass
class FolderBasedBuilderConfig(datasets.BuilderConfig):
    features: Optional[datasets.Features] = None
    drop_labels: bool = None
    drop_metadata: bool = None
    metadata_filenames: list[str] = None
    filters: Optional[Union[ds.Expression, list[tuple], list[list[tuple]]]] = None

    def __post_init__(self):
        super().__post_init__()

class FolderBasedBuilder(datasets.GeneratorBasedBuilder):
    BASE_FEATURE: type[FeatureType]
    BASE_COLUMN_NAME: str
    BUILDER_CONFIG_CLASS: FolderBasedBuilderConfig
    EXTENSIONS: list[str]
    METADATA_FILENAMES: list[str] = ['metadata.csv', 'metadata.jsonl', 'metadata.parquet']

    def _info(self):
        if not self.config.data_dir and (not self.config.data_files):
            raise ValueError('Folder-based datasets require either `data_dir` or `data_files` to be specified. Neither was provided.')
        return datasets.DatasetInfo(features=self.config.features)

    def _split_generators(self, dl_manager):
        if not self.config.data_files:
            raise ValueError(f'At least one data file must be specified, but got data_files={self.config.data_files}')
        dl_manager.download_config.extract_on_the_fly = True
        do_analyze = not self.config.drop_labels or not self.config.drop_metadata
        labels, path_depths = (set(), set())
        all_metadata_files = collections.defaultdict(set)
        metadata_filenames = self.config.metadata_filenames or self.METADATA_FILENAMES

        def analyze(files_or_archives, downloaded_files_or_dirs, split):
            if len(downloaded_files_or_dirs) == 0:
                return
            if os.path.isfile(downloaded_files_or_dirs[0]):
                original_files, downloaded_files = (files_or_archives, downloaded_files_or_dirs)
                for original_file, downloaded_file in zip(original_files, downloaded_files):
                    original_file, downloaded_file = (str(original_file), str(downloaded_file))
                    _, original_file_ext = os.path.splitext(original_file)
                    if original_file_ext.lower() in self.EXTENSIONS:
                        if not self.config.drop_labels:
                            labels.add(os.path.basename(os.path.dirname(original_file)))
                            path_depths.add(count_path_segments(original_file))
                    elif os.path.basename(original_file) in metadata_filenames:
                        all_metadata_files[split].add((original_file, None, downloaded_file))
                    else:
                        original_file_name = os.path.basename(original_file)
                        logger.debug(f"The file '{original_file_name}' was ignored: it is not a {self.BASE_COLUMN_NAME}, and is not {metadata_filenames} either.")
            else:
                archives, downloaded_dirs = (files_or_archives, downloaded_files_or_dirs)
                for archive, downloaded_dir in zip(archives, downloaded_dirs):
                    archive, downloaded_dir = (str(archive), str(downloaded_dir))
                    for downloaded_dir_file in dl_manager.iter_files(downloaded_dir):
                        _, downloaded_dir_file_ext = os.path.splitext(downloaded_dir_file)
                        if downloaded_dir_file_ext in self.EXTENSIONS:
                            if not self.config.drop_labels:
                                labels.add(os.path.basename(os.path.dirname(downloaded_dir_file)))
                                path_depths.add(count_path_segments(downloaded_dir_file))
                        elif os.path.basename(downloaded_dir_file) in metadata_filenames:
                            all_metadata_files[split].add((None, downloaded_dir, downloaded_dir_file))
                        else:
                            archive_file_name = os.path.basename(archive)
                            original_file_name = os.path.basename(downloaded_dir_file)
                            logger.debug(f"The file '{original_file_name}' from the archive '{archive_file_name}' was ignored: it is not a {self.BASE_COLUMN_NAME}, and is not {metadata_filenames} either.")
        data_files = self.config.data_files
        splits = []
        for split_name, files in data_files.items():
            files, metadata_files, archives = self._split_files_and_metadata_and_archives(files)
            downloaded_files = dl_manager.download(files)
            downloaded_metadata_files = dl_manager.download(metadata_files)
            downloaded_dirs = dl_manager.download_and_extract(archives)
            if do_analyze:
                logger.info(f'Searching for labels and/or metadata files in {split_name} data files...')
                analyze(files, downloaded_files, split_name)
                analyze(metadata_files, downloaded_metadata_files, split_name)
                analyze(archives, downloaded_dirs, split_name)
                if all_metadata_files:
                    add_metadata = not self.config.drop_metadata
                    add_labels = False
                else:
                    add_metadata = False
                    add_labels = len(labels) > 1 and len(path_depths) == 1 if self.config.drop_labels is None else not self.config.drop_labels
                if add_labels:
                    logger.info("Adding the labels inferred from data directories to the dataset's features...")
                if add_metadata:
                    logger.info('Adding metadata to the dataset...')
            else:
                add_labels, add_metadata, all_metadata_files = (False, False, {})
            files = tuple(zip(files, [None] * len(files), downloaded_files))
            files += tuple(((archive, downloaded_dir, dl_manager.iter_files(downloaded_dir)) for archive, downloaded_dir in zip(archives, downloaded_dirs)))
            splits.append(datasets.SplitGenerator(name=split_name, gen_kwargs={'files': files, 'metadata_files': all_metadata_files.get(split_name, []), 'add_labels': add_labels, 'add_metadata': add_metadata}))
        if add_metadata:
            features_per_metadata_file: list[tuple[str, datasets.Features]] = []
            metadata_ext = {os.path.splitext(original_metadata_file or downloaded_metadata_file)[-1] for original_metadata_file, _, downloaded_metadata_file in itertools.chain.from_iterable(all_metadata_files.values())}
            if len(metadata_ext) > 1:
                raise ValueError(f'Found metadata files with different extensions: {list(metadata_ext)}')
            metadata_ext = metadata_ext.pop()
            for split_metadata_files in all_metadata_files.values():
                pa_metadata_table = None
                for _, _, downloaded_metadata_file in split_metadata_files:
                    for pa_metadata_table in self._read_metadata(downloaded_metadata_file, metadata_ext=metadata_ext):
                        break
                    if pa_metadata_table is not None:
                        features_per_metadata_file.append((downloaded_metadata_file, datasets.Features.from_arrow_schema(pa_metadata_table.schema)))
                        break
            for downloaded_metadata_file, metadata_features in features_per_metadata_file:
                if metadata_features != features_per_metadata_file[0][1]:
                    raise ValueError(f'Metadata files {downloaded_metadata_file} and {features_per_metadata_file[0][0]} have different features: {features_per_metadata_file[0]} != {metadata_features}')
            metadata_features = features_per_metadata_file[0][1]
            feature_not_found = True

            def _set_feature(feature):
                nonlocal feature_not_found
                if isinstance(feature, dict):
                    out = type(feature)()
                    for key in feature:
                        if (key == 'file_name' or key.endswith('_file_name')) and (feature[key] == datasets.Value('string') or feature[key] == datasets.Value('large_string')):
                            key = key[:-len('_file_name')] or self.BASE_COLUMN_NAME
                            out[key] = self.BASE_FEATURE()
                            feature_not_found = False
                        elif (key == 'file_names' or key.endswith('_file_names')) and feature[key] in [datasets.List(datasets.Value('string')), datasets.List(datasets.Value('large_string'))]:
                            key = key[:-len('_file_names')] or self.BASE_COLUMN_NAME + 's'
                            out[key] = datasets.List(self.BASE_FEATURE())
                            feature_not_found = False
                        elif (key == 'file_names' or key.endswith('_file_names')) and (feature[key] == [datasets.Value('string')] or feature[key] == [datasets.Value('large_string')]):
                            key = key[:-len('_file_names')] or self.BASE_COLUMN_NAME + 's'
                            out[key] = [self.BASE_FEATURE()]
                            feature_not_found = False
                        else:
                            out[key] = feature[key]
                    return out
                return feature
            metadata_features = _visit(metadata_features, _set_feature)
            if feature_not_found:
                raise ValueError('`file_name`, `*_file_name`, `file_names` or `*_file_names` must be present as dictionary key in metadata files')
        else:
            metadata_features = None
        if self.config.features is None:
            if add_metadata:
                self.info.features = metadata_features
            elif add_labels:
                self.info.features = datasets.Features({self.BASE_COLUMN_NAME: self.BASE_FEATURE(), 'label': datasets.ClassLabel(names=sorted(labels))})
            else:
                self.info.features = datasets.Features({self.BASE_COLUMN_NAME: self.BASE_FEATURE()})
        return splits

    def _split_files_and_metadata_and_archives(self, data_files):
        files, metadata_files, archives = ([], [], [])
        metadata_filenames = self.config.metadata_filenames or self.METADATA_FILENAMES
        for data_file in data_files:
            data_file_root, data_file_ext = os.path.splitext(data_file)
            _, second_data_file_ext = os.path.splitext(data_file_root)
            if data_file_ext.lower() in self.EXTENSIONS or second_data_file_ext.lower() in self.EXTENSIONS:
                files.append(data_file)
            elif os.path.basename(data_file) in metadata_filenames:
                metadata_files.append(data_file)
            elif data_file_ext.lower() == '.zip':
                archives.append(data_file)
        return (files, metadata_files, archives)

    def _read_metadata(self, metadata_file: str, metadata_ext: str='') -> Iterator[pa.Table]:
        if self.config.filters is not None:
            filter_expr = pq.filters_to_expression(self.config.filters) if isinstance(self.config.filters, list) else self.config.filters
        else:
            filter_expr = None
        if metadata_ext == '.csv':
            chunksize = 10000
            schema = self.config.features.arrow_schema if self.config.features else None
            dtype = {name: dtype.to_pandas_dtype() if not require_storage_cast(feature) else object for name, dtype, feature in zip(schema.names, schema.types, self.config.features.values())} if schema is not None else None
            csv_file_reader = pd.read_csv(metadata_file, iterator=True, dtype=dtype, chunksize=chunksize)
            for df in csv_file_reader:
                pa_table = pa.Table.from_pandas(df)
                if self.config.filters is not None:
                    pa_table = pa_table.filter(filter_expr)
                if len(pa_table) > 0:
                    yield pa_table
        elif metadata_ext == '.jsonl':
            with open(metadata_file, 'rb') as f:
                chunksize: int = 10 << 20
                block_size = max(chunksize // 32, 16 << 10)
                while True:
                    batch = f.read(chunksize)
                    if not batch:
                        break
                    try:
                        batch += f.readline()
                    except (AttributeError, io.UnsupportedOperation):
                        batch += readline(f)
                    while True:
                        try:
                            pa_table = paj.read_json(io.BytesIO(batch), read_options=paj.ReadOptions(block_size=block_size))
                            break
                        except (pa.ArrowInvalid, pa.ArrowNotImplementedError) as e:
                            if isinstance(e, pa.ArrowInvalid) and 'straddling' not in str(e) or block_size > len(batch):
                                raise
                            else:
                                logger.debug(f"Batch of {len(batch)} bytes couldn't be parsed with block_size={block_size}. Retrying with block_size={block_size * 2}.")
                                block_size *= 2
                    if self.config.filters is not None:
                        pa_table = pa_table.filter(filter_expr)
                    if len(pa_table) > 0:
                        yield pa_table
        else:
            with open(metadata_file, 'rb') as f:
                parquet_fragment = ds.ParquetFileFormat().make_fragment(f)
                if parquet_fragment.row_groups:
                    batch_size = parquet_fragment.row_groups[0].num_rows
                else:
                    batch_size = config.DEFAULT_MAX_BATCH_SIZE
                for record_batch in parquet_fragment.to_batches(batch_size=batch_size, filter=filter_expr, batch_readahead=0, fragment_readahead=0):
                    yield pa.Table.from_batches([record_batch])

    def _generate_shards(self, files, metadata_files, add_metadata, add_labels):
        if add_metadata:
            for _, _, downloaded_metadata_file in metadata_files:
                yield downloaded_metadata_file
        else:
            for _, downloaded_dir, downloaded_file in files:
                yield (downloaded_dir or downloaded_file)

    def _generate_examples(self, files, metadata_files, add_metadata, add_labels):
        if add_metadata:
            feature_paths = []

            def find_feature_path(feature, feature_path):
                nonlocal feature_paths
                if feature_path and isinstance(feature, self.BASE_FEATURE):
                    feature_paths.append(feature_path)
            _visit_with_path(self.info.features, find_feature_path)
            for shard_idx, metadata_file_info in enumerate(metadata_files):
                if len(metadata_file_info) == 2:
                    original_metadata_file, downloaded_metadata_file = metadata_file_info
                else:
                    original_metadata_file, downloaded_metadata_dir, downloaded_metadata_file = metadata_file_info
                metadata_ext = os.path.splitext(original_metadata_file or downloaded_metadata_file)[-1]
                downloaded_metadata_dir = os.path.dirname(downloaded_metadata_file)

                def set_feature(item, feature_path: _VisitPath):
                    if len(feature_path) == 2 and isinstance(feature_path[0], str) and (feature_path[1] == 0):
                        item[feature_path[0]] = item.pop('file_names', None) or item.pop(feature_path[0] + '_file_names', None)
                    elif len(feature_path) == 1 and isinstance(feature_path[0], str):
                        item[feature_path[0]] = item.pop('file_name', None) or item.pop(feature_path[0] + '_file_name', None)
                    elif len(feature_path) == 0:
                        file_relpath = os.path.normpath(item).replace('\\', '/')
                        item = os.path.join(downloaded_metadata_dir, file_relpath)
                    return item
                for pa_metadata_table in self._read_metadata(downloaded_metadata_file, metadata_ext=metadata_ext):
                    for sample_idx, sample in enumerate(pa_metadata_table.to_pylist()):
                        for feature_path in feature_paths:
                            _nested_apply(sample, feature_path, set_feature)
                        yield (Key(shard_idx, sample_idx), sample)
        else:
            if self.config.filters is not None:
                filter_expr = pq.filters_to_expression(self.config.filters) if isinstance(self.config.filters, list) else self.config.filters
            for shard_idx, (original_file, _, downloaded_files) in enumerate(files):
                if isinstance(downloaded_files, str):
                    downloaded_files = [downloaded_files]
                for sample_idx, downloaded_file in enumerate(downloaded_files):
                    sample = {self.BASE_COLUMN_NAME: downloaded_file}
                    if add_labels:
                        sample['label'] = os.path.basename(os.path.dirname(original_file or downloaded_file))
                    if self.config.filters is not None:
                        pa_table = pa.Table.from_pylist([sample]).filter(filter_expr)
                        if len(pa_table) == 0:
                            continue
                    yield (Key(shard_idx, sample_idx), sample)

def _nested_apply(item: Any, feature_path: _VisitPath, func: Callable[[Any, _VisitPath], Any]):
    item = func(item, feature_path)
    if feature_path:
        key = feature_path[0]
        if key == 0:
            for i in range(len(item)):
                item[i] = _nested_apply(item[i], feature_path[1:], func)
        else:
            item[key] = _nested_apply(item[key], feature_path[1:], func)
    return item

from __future__ import annotations
import enum
import logging
import time
import types
import typing
import h2.config
import h2.connection
import h2.events
import h2.exceptions
import h2.settings
from .._backends.base import NetworkStream
from .._exceptions import ConnectionNotAvailable, LocalProtocolError, RemoteProtocolError
from .._models import Origin, Request, Response
from .._synchronization import Lock, Semaphore, ShieldCancellation
from .._trace import Trace
from .interfaces import ConnectionInterface
logger = logging.getLogger('httpcore.http2')

def has_body_headers(request: Request) -> bool:
    return any((k.lower() == b'content-length' or k.lower() == b'transfer-encoding' for k, v in request.headers))

class HTTPConnectionState(enum.IntEnum):
    ACTIVE = 1
    IDLE = 2
    CLOSED = 3

class HTTP2Connection(ConnectionInterface):
    READ_NUM_BYTES = 64 * 1024
    CONFIG = h2.config.H2Configuration(validate_inbound_headers=False)

    def __init__(self, origin: Origin, stream: NetworkStream, keepalive_expiry: float | None=None):
        self._origin = origin
        self._network_stream = stream
        self._keepalive_expiry: float | None = keepalive_expiry
        self._h2_state = h2.connection.H2Connection(config=self.CONFIG)
        self._state = HTTPConnectionState.IDLE
        self._expire_at: float | None = None
        self._request_count = 0
        self._init_lock = Lock()
        self._state_lock = Lock()
        self._read_lock = Lock()
        self._write_lock = Lock()
        self._sent_connection_init = False
        self._used_all_stream_ids = False
        self._connection_error = False
        self._events: dict[int, list[h2.events.ResponseReceived | h2.events.DataReceived | h2.events.StreamEnded | h2.events.StreamReset,]] = {}
        self._connection_terminated: h2.events.ConnectionTerminated | None = None
        self._read_exception: Exception | None = None
        self._write_exception: Exception | None = None

    def handle_request(self, request: Request) -> Response:
        if not self.can_handle_request(request.url.origin):
            raise RuntimeError(f'Attempted to send request to {request.url.origin} on connection to {self._origin}')
        with self._state_lock:
            if self._state in (HTTPConnectionState.ACTIVE, HTTPConnectionState.IDLE):
                self._request_count += 1
                self._expire_at = None
                self._state = HTTPConnectionState.ACTIVE
            else:
                raise ConnectionNotAvailable()
        with self._init_lock:
            if not self._sent_connection_init:
                try:
                    sci_kwargs = {'request': request}
                    with Trace('send_connection_init', logger, request, sci_kwargs):
                        self._send_connection_init(**sci_kwargs)
                except BaseException as exc:
                    with ShieldCancellation():
                        self.close()
                    raise exc
                self._sent_connection_init = True
                self._max_streams = 1
                local_settings_max_streams = self._h2_state.local_settings.max_concurrent_streams
                self._max_streams_semaphore = Semaphore(local_settings_max_streams)
                for _ in range(local_settings_max_streams - self._max_streams):
                    self._max_streams_semaphore.acquire()
        self._max_streams_semaphore.acquire()
        try:
            stream_id = self._h2_state.get_next_available_stream_id()
            self._events[stream_id] = []
        except h2.exceptions.NoAvailableStreamIDError:
            self._used_all_stream_ids = True
            self._request_count -= 1
            raise ConnectionNotAvailable()
        try:
            kwargs = {'request': request, 'stream_id': stream_id}
            with Trace('send_request_headers', logger, request, kwargs):
                self._send_request_headers(request=request, stream_id=stream_id)
            with Trace('send_request_body', logger, request, kwargs):
                self._send_request_body(request=request, stream_id=stream_id)
            with Trace('receive_response_headers', logger, request, kwargs) as trace:
                status, headers = self._receive_response(request=request, stream_id=stream_id)
                trace.return_value = (status, headers)
            return Response(status=status, headers=headers, content=HTTP2ConnectionByteStream(self, request, stream_id=stream_id), extensions={'http_version': b'HTTP/2', 'network_stream': self._network_stream, 'stream_id': stream_id})
        except BaseException as exc:
            with ShieldCancellation():
                kwargs = {'stream_id': stream_id}
                with Trace('response_closed', logger, request, kwargs):
                    self._response_closed(stream_id=stream_id)
            if isinstance(exc, h2.exceptions.ProtocolError):
                if self._connection_terminated:
                    raise RemoteProtocolError(self._connection_terminated)
                raise LocalProtocolError(exc)
            raise exc

    def _send_connection_init(self, request: Request) -> None:
        self._h2_state.local_settings = h2.settings.Settings(client=True, initial_values={h2.settings.SettingCodes.ENABLE_PUSH: 0, h2.settings.SettingCodes.MAX_CONCURRENT_STREAMS: 100, h2.settings.SettingCodes.MAX_HEADER_LIST_SIZE: 65536})
        del self._h2_state.local_settings[h2.settings.SettingCodes.ENABLE_CONNECT_PROTOCOL]
        self._h2_state.initiate_connection()
        self._h2_state.increment_flow_control_window(2 ** 24)
        self._write_outgoing_data(request)

    def _send_request_headers(self, request: Request, stream_id: int) -> None:
        end_stream = not has_body_headers(request)
        authority = [v for k, v in request.headers if k.lower() == b'host'][0]
        headers = [(b':method', request.method), (b':authority', authority), (b':scheme', request.url.scheme), (b':path', request.url.target)] + [(k.lower(), v) for k, v in request.headers if k.lower() not in (b'host', b'transfer-encoding')]
        self._h2_state.send_headers(stream_id, headers, end_stream=end_stream)
        self._h2_state.increment_flow_control_window(2 ** 24, stream_id=stream_id)
        self._write_outgoing_data(request)

    def _send_request_body(self, request: Request, stream_id: int) -> None:
        if not has_body_headers(request):
            return
        assert isinstance(request.stream, typing.Iterable)
        for data in request.stream:
            self._send_stream_data(request, stream_id, data)
        self._send_end_stream(request, stream_id)

    def _send_stream_data(self, request: Request, stream_id: int, data: bytes) -> None:
        while data:
            max_flow = self._wait_for_outgoing_flow(request, stream_id)
            chunk_size = min(len(data), max_flow)
            chunk, data = (data[:chunk_size], data[chunk_size:])
            self._h2_state.send_data(stream_id, chunk)
            self._write_outgoing_data(request)

    def _send_end_stream(self, request: Request, stream_id: int) -> None:
        self._h2_state.end_stream(stream_id)
        self._write_outgoing_data(request)

    def _receive_response(self, request: Request, stream_id: int) -> tuple[int, list[tuple[bytes, bytes]]]:
        while True:
            event = self._receive_stream_event(request, stream_id)
            if isinstance(event, h2.events.ResponseReceived):
                break
        status_code = 200
        headers = []
        assert event.headers is not None
        for k, v in event.headers:
            if k == b':status':
                status_code = int(v.decode('ascii', errors='ignore'))
            elif not k.startswith(b':'):
                headers.append((k, v))
        return (status_code, headers)

    def _receive_response_body(self, request: Request, stream_id: int) -> typing.Iterator[bytes]:
        while True:
            event = self._receive_stream_event(request, stream_id)
            if isinstance(event, h2.events.DataReceived):
                assert event.flow_controlled_length is not None
                assert event.data is not None
                amount = event.flow_controlled_length
                self._h2_state.acknowledge_received_data(amount, stream_id)
                self._write_outgoing_data(request)
                yield event.data
            elif isinstance(event, h2.events.StreamEnded):
                break

    def _receive_stream_event(self, request: Request, stream_id: int) -> h2.events.ResponseReceived | h2.events.DataReceived | h2.events.StreamEnded:
        while not self._events.get(stream_id):
            self._receive_events(request, stream_id)
        event = self._events[stream_id].pop(0)
        if isinstance(event, h2.events.StreamReset):
            raise RemoteProtocolError(event)
        return event

    def _receive_events(self, request: Request, stream_id: int | None=None) -> None:
        with self._read_lock:
            if self._connection_terminated is not None:
                last_stream_id = self._connection_terminated.last_stream_id
                if stream_id and last_stream_id and (stream_id > last_stream_id):
                    self._request_count -= 1
                    raise ConnectionNotAvailable()
                raise RemoteProtocolError(self._connection_terminated)
            if stream_id is None or not self._events.get(stream_id):
                events = self._read_incoming_data(request)
                for event in events:
                    if isinstance(event, h2.events.RemoteSettingsChanged):
                        with Trace('receive_remote_settings', logger, request) as trace:
                            self._receive_remote_settings_change(event)
                            trace.return_value = event
                    elif isinstance(event, (h2.events.ResponseReceived, h2.events.DataReceived, h2.events.StreamEnded, h2.events.StreamReset)):
                        if event.stream_id in self._events:
                            self._events[event.stream_id].append(event)
                    elif isinstance(event, h2.events.ConnectionTerminated):
                        self._connection_terminated = event
        self._write_outgoing_data(request)

    def _receive_remote_settings_change(self, event: h2.events.RemoteSettingsChanged) -> None:
        max_concurrent_streams = event.changed_settings.get(h2.settings.SettingCodes.MAX_CONCURRENT_STREAMS)
        if max_concurrent_streams:
            new_max_streams = min(max_concurrent_streams.new_value, self._h2_state.local_settings.max_concurrent_streams)
            if new_max_streams and new_max_streams != self._max_streams:
                while new_max_streams > self._max_streams:
                    self._max_streams_semaphore.release()
                    self._max_streams += 1
                while new_max_streams < self._max_streams:
                    self._max_streams_semaphore.acquire()
                    self._max_streams -= 1

    def _response_closed(self, stream_id: int) -> None:
        self._max_streams_semaphore.release()
        del self._events[stream_id]
        with self._state_lock:
            if self._connection_terminated and (not self._events):
                self.close()
            elif self._state == HTTPConnectionState.ACTIVE and (not self._events):
                self._state = HTTPConnectionState.IDLE
                if self._keepalive_expiry is not None:
                    now = time.monotonic()
                    self._expire_at = now + self._keepalive_expiry
                if self._used_all_stream_ids:
                    self.close()

    def close(self) -> None:
        self._h2_state.close_connection()
        self._state = HTTPConnectionState.CLOSED
        self._network_stream.close()

    def _read_incoming_data(self, request: Request) -> list[h2.events.Event]:
        timeouts = request.extensions.get('timeout', {})
        timeout = timeouts.get('read', None)
        if self._read_exception is not None:
            raise self._read_exception
        try:
            data = self._network_stream.read(self.READ_NUM_BYTES, timeout)
            if data == b'':
                raise RemoteProtocolError('Server disconnected')
        except Exception as exc:
            self._read_exception = exc
            self._connection_error = True
            raise exc
        events: list[h2.events.Event] = self._h2_state.receive_data(data)
        return events

    def _write_outgoing_data(self, request: Request) -> None:
        timeouts = request.extensions.get('timeout', {})
        timeout = timeouts.get('write', None)
        with self._write_lock:
            data_to_send = self._h2_state.data_to_send()
            if self._write_exception is not None:
                raise self._write_exception
            try:
                self._network_stream.write(data_to_send, timeout)
            except Exception as exc:
                self._write_exception = exc
                self._connection_error = True
                raise exc

    def _wait_for_outgoing_flow(self, request: Request, stream_id: int) -> int:
        local_flow: int = self._h2_state.local_flow_control_window(stream_id)
        max_frame_size: int = self._h2_state.max_outbound_frame_size
        flow = min(local_flow, max_frame_size)
        while flow == 0:
            self._receive_events(request)
            local_flow = self._h2_state.local_flow_control_window(stream_id)
            max_frame_size = self._h2_state.max_outbound_frame_size
            flow = min(local_flow, max_frame_size)
        return flow

    def can_handle_request(self, origin: Origin) -> bool:
        return origin == self._origin

    def is_available(self) -> bool:
        return self._state != HTTPConnectionState.CLOSED and (not self._connection_error) and (not self._used_all_stream_ids) and (not self._h2_state.state_machine.state == h2.connection.ConnectionState.CLOSED)

    def has_expired(self) -> bool:
        now = time.monotonic()
        return self._expire_at is not None and now > self._expire_at

    def is_idle(self) -> bool:
        return self._state == HTTPConnectionState.IDLE

    def is_closed(self) -> bool:
        return self._state == HTTPConnectionState.CLOSED

    def info(self) -> str:
        origin = str(self._origin)
        return f'{origin!r}, HTTP/2, {self._state.name}, Request Count: {self._request_count}'

    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        origin = str(self._origin)
        return f'<{class_name} [{origin!r}, {self._state.name}, Request Count: {self._request_count}]>'

    def __enter__(self) -> HTTP2Connection:
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        self.close()

class HTTP2ConnectionByteStream:

    def __init__(self, connection: HTTP2Connection, request: Request, stream_id: int) -> None:
        self._connection = connection
        self._request = request
        self._stream_id = stream_id
        self._closed = False

    def __iter__(self) -> typing.Iterator[bytes]:
        kwargs = {'request': self._request, 'stream_id': self._stream_id}
        try:
            with Trace('receive_response_body', logger, self._request, kwargs):
                for chunk in self._connection._receive_response_body(request=self._request, stream_id=self._stream_id):
                    yield chunk
        except BaseException as exc:
            with ShieldCancellation():
                self.close()
            raise exc

    def close(self) -> None:
        if not self._closed:
            self._closed = True
            kwargs = {'stream_id': self._stream_id}
            with Trace('response_closed', logger, self._request, kwargs):
                self._connection._response_closed(stream_id=self._stream_id)

import bz2
import gzip
import lzma
import os
import shutil
import struct
import tarfile
import warnings
import zipfile
from abc import ABC, abstractmethod
from pathlib import Path
from typing import TYPE_CHECKING, Optional, Union
from .. import config
from ._filelock import FileLock
from .logging import get_logger
if TYPE_CHECKING:
    import py7zr
    import rarfile
logger = get_logger(__name__)

class ExtractManager:

    def __init__(self, cache_dir: Optional[str]=None):
        self.extract_dir = os.path.join(cache_dir, config.EXTRACTED_DATASETS_DIR) if cache_dir else config.EXTRACTED_DATASETS_PATH
        self.extractor = Extractor

    def _get_output_path(self, path: str) -> str:
        from .file_utils import hash_url_to_filename
        abs_path = os.path.abspath(path)
        return os.path.join(self.extract_dir, hash_url_to_filename(abs_path))

    def _do_extract(self, output_path: str, force_extract: bool) -> bool:
        return force_extract or (not os.path.isfile(output_path) and (not (os.path.isdir(output_path) and os.listdir(output_path))))

    def extract(self, input_path: str, force_extract: bool=False) -> str:
        extractor_format = self.extractor.infer_extractor_format(input_path)
        if not extractor_format:
            return input_path
        output_path = self._get_output_path(input_path)
        if self._do_extract(output_path, force_extract):
            self.extractor.extract(input_path, output_path, extractor_format)
        return output_path

class BaseExtractor(ABC):

    @classmethod
    @abstractmethod
    def is_extractable(cls, path: Union[Path, str], **kwargs) -> bool:
        ...

    @staticmethod
    @abstractmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        ...

class MagicNumberBaseExtractor(BaseExtractor, ABC):
    magic_numbers: list[bytes] = []

    @staticmethod
    def read_magic_number(path: Union[Path, str], magic_number_length: int):
        with open(path, 'rb') as f:
            return f.read(magic_number_length)

    @classmethod
    def is_extractable(cls, path: Union[Path, str], magic_number: bytes=b'') -> bool:
        if not magic_number:
            magic_number_length = max((len(cls_magic_number) for cls_magic_number in cls.magic_numbers))
            try:
                magic_number = cls.read_magic_number(path, magic_number_length)
            except OSError:
                return False
        return any((magic_number.startswith(cls_magic_number) for cls_magic_number in cls.magic_numbers))

class TarExtractor(BaseExtractor):

    @classmethod
    def is_extractable(cls, path: Union[Path, str], **kwargs) -> bool:
        return tarfile.is_tarfile(path)

    @staticmethod
    def safemembers(members: tarfile.TarFile, output_path: Union[Path, str]):

        def resolved(path: Union[Path, str]) -> str:
            return os.path.realpath(os.path.abspath(path))

        def badpath(path: str, base: str) -> bool:
            return not resolved(os.path.join(base, path)).startswith(base)

        def badlink(info: tarfile.TarInfo, base: str) -> bool:
            tip = resolved(os.path.join(base, os.path.dirname(info.name)))
            return badpath(info.linkname, base=tip)
        base = resolved(output_path)
        for finfo in members:
            if badpath(finfo.name, base):
                logger.error(f'Extraction of {finfo.name} is blocked (illegal path)')
            elif finfo.issym() and badlink(finfo, base):
                logger.error(f'Extraction of {finfo.name} is blocked: Symlink to {finfo.linkname}')
            elif finfo.islnk() and badlink(finfo, base):
                logger.error(f'Extraction of {finfo.name} is blocked: Hard link to {finfo.linkname}')
            else:
                yield finfo

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        os.makedirs(output_path, exist_ok=True)
        tar_file = tarfile.open(input_path)
        tar_file.extractall(output_path, members=TarExtractor.safemembers(tar_file, output_path))
        tar_file.close()

class GzipExtractor(MagicNumberBaseExtractor):
    magic_numbers = [b'\x1f\x8b']

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        with gzip.open(input_path, 'rb') as gzip_file:
            with open(output_path, 'wb') as extracted_file:
                shutil.copyfileobj(gzip_file, extracted_file)

class ZipExtractor(MagicNumberBaseExtractor):
    magic_numbers = [b'PK\x03\x04', b'PK\x05\x06', b'PK\x07\x08']

    @classmethod
    def is_extractable(cls, path: Union[Path, str], magic_number: bytes=b'') -> bool:
        if super().is_extractable(path, magic_number=magic_number):
            return True
        try:
            from zipfile import _CD_SIGNATURE, _ECD_DISK_NUMBER, _ECD_DISK_START, _ECD_ENTRIES_TOTAL, _ECD_OFFSET, _ECD_SIZE, _EndRecData, sizeCentralDir, stringCentralDir, structCentralDir
            with open(path, 'rb') as fp:
                endrec = _EndRecData(fp)
                if endrec:
                    if endrec[_ECD_ENTRIES_TOTAL] == 0 and endrec[_ECD_SIZE] == 0 and (endrec[_ECD_OFFSET] == 0):
                        return True
                    elif endrec[_ECD_DISK_NUMBER] == endrec[_ECD_DISK_START]:
                        fp.seek(endrec[_ECD_OFFSET])
                        if fp.tell() == endrec[_ECD_OFFSET] and endrec[_ECD_SIZE] >= sizeCentralDir:
                            data = fp.read(sizeCentralDir)
                            if len(data) == sizeCentralDir:
                                centdir = struct.unpack(structCentralDir, data)
                                if centdir[_CD_SIGNATURE] == stringCentralDir:
                                    return True
            return False
        except Exception:
            return False

    @staticmethod
    def safemembers(members: list[zipfile.ZipInfo], output_path: Union[Path, str]):

        def resolved(path: Union[Path, str]) -> str:
            return os.path.realpath(os.path.abspath(path))

        def badpath(path: str, base: str) -> bool:
            return not resolved(os.path.join(base, path)).startswith(base)
        base = resolved(output_path)
        for finfo in members:
            if badpath(finfo.filename, base):
                logger.error(f'Extraction of {finfo.filename} is blocked (illegal path)')
            else:
                yield finfo

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        os.makedirs(output_path, exist_ok=True)
        with zipfile.ZipFile(input_path, 'r') as zip_file:
            zip_file.extractall(output_path, members=ZipExtractor.safemembers(zip_file.filelist, output_path))
            zip_file.close()

class XzExtractor(MagicNumberBaseExtractor):
    magic_numbers = [b'\xfd7zXZ\x00']

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        with lzma.open(input_path) as compressed_file:
            with open(output_path, 'wb') as extracted_file:
                shutil.copyfileobj(compressed_file, extracted_file)

class RarExtractor(MagicNumberBaseExtractor):
    magic_numbers = [b'Rar!\x1a\x07\x00', b'Rar!\x1a\x07\x01\x00']

    @staticmethod
    def safemembers(members: list['rarfile.RarInfo'], output_path: Union[Path, str]):

        def resolved(path: Union[Path, str]) -> str:
            return os.path.realpath(os.path.abspath(path))

        def badpath(path: str, base: str) -> bool:
            return not resolved(os.path.join(base, path)).startswith(base)

        def badlink(info: 'rarfile.RarInfo', base: str) -> bool:
            tip = resolved(os.path.join(base, os.path.dirname(info.filename)))
            redir_type, redir_flags, link_name = info.file_redir
            return badpath(link_name, base=tip)
        base = resolved(output_path)
        for finfo in members:
            if badpath(finfo.filename, base):
                logger.error(f'Extraction of {finfo.filename} is blocked (illegal path)')
            elif finfo.is_symlink() and badlink(finfo, base):
                logger.error(f'Extraction of {finfo.filename} is blocked: Symlink to {finfo.file_redir}')
            else:
                yield finfo

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        if not config.RARFILE_AVAILABLE:
            raise ImportError('Please pip install rarfile')
        import rarfile
        os.makedirs(output_path, exist_ok=True)
        rf = rarfile.RarFile(input_path)
        rf.extractall(output_path, members=RarExtractor.safemembers(rf.infolist(), output_path))
        rf.close()

class ZstdExtractor(MagicNumberBaseExtractor):
    magic_numbers = [b'(\xb5/\xfd']

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        if not config.ZSTANDARD_AVAILABLE:
            raise ImportError('Please pip install zstandard')
        import zstandard as zstd
        dctx = zstd.ZstdDecompressor()
        with open(input_path, 'rb') as ifh, open(output_path, 'wb') as ofh:
            dctx.copy_stream(ifh, ofh)

class Bzip2Extractor(MagicNumberBaseExtractor):
    magic_numbers = [b'BZh']

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        with bz2.open(input_path, 'rb') as compressed_file:
            with open(output_path, 'wb') as extracted_file:
                shutil.copyfileobj(compressed_file, extracted_file)

class SevenZipExtractor(MagicNumberBaseExtractor):
    magic_numbers = [b"7z\xbc\xaf'\x1c"]

    @staticmethod
    def safemembers(members: list['py7zr.FileInfo'], output_path: Union[Path, str]):

        def resolved(path: Union[Path, str]) -> str:
            return os.path.realpath(os.path.abspath(path))

        def badpath(path: str, base: str) -> bool:
            return not resolved(os.path.join(base, path)).startswith(base)

        def badlink(info: 'py7zr.FileInfo', base: str) -> bool:
            tip = resolved(os.path.join(base, os.path.dirname(info.filename)))
            return badpath(os.path.basename(info.filename), base=tip)
        base = resolved(output_path)
        for finfo in members:
            if badpath(finfo.filename, base):
                logger.error(f'Extraction of {finfo.filename} is blocked (illegal path)')
            else:
                yield finfo

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        if not config.PY7ZR_AVAILABLE:
            raise ImportError('Please pip install py7zr')
        import py7zr
        os.makedirs(output_path, exist_ok=True)
        with py7zr.SevenZipFile(input_path, 'r') as archive:
            targets = [finfo.filename for finfo in SevenZipExtractor.safemembers(archive.list(), output_path)]
            archive.extract(output_path, targets=targets)

class Lz4Extractor(MagicNumberBaseExtractor):
    magic_numbers = [b'\x04"M\x18']

    @staticmethod
    def extract(input_path: Union[Path, str], output_path: Union[Path, str]) -> None:
        if not config.LZ4_AVAILABLE:
            raise ImportError('Please pip install lz4')
        import lz4.frame
        with lz4.frame.open(input_path, 'rb') as compressed_file:
            with open(output_path, 'wb') as extracted_file:
                shutil.copyfileobj(compressed_file, extracted_file)

class Extractor:
    extractors: dict[str, type[BaseExtractor]] = {'tar': TarExtractor, 'gzip': GzipExtractor, 'zip': ZipExtractor, 'xz': XzExtractor, 'rar': RarExtractor, 'zstd': ZstdExtractor, 'bz2': Bzip2Extractor, '7z': SevenZipExtractor, 'lz4': Lz4Extractor}

    @classmethod
    def _get_magic_number_max_length(cls):
        return max((len(extractor_magic_number) for extractor in cls.extractors.values() if issubclass(extractor, MagicNumberBaseExtractor) for extractor_magic_number in extractor.magic_numbers))

    @staticmethod
    def _read_magic_number(path: Union[Path, str], magic_number_length: int):
        try:
            return MagicNumberBaseExtractor.read_magic_number(path, magic_number_length=magic_number_length)
        except OSError:
            return b''

    @classmethod
    def is_extractable(cls, path: Union[Path, str], return_extractor: bool=False) -> bool:
        warnings.warn("Method 'is_extractable' was deprecated in version 2.4.0 and will be removed in 3.0.0. Use 'infer_extractor_format' instead.", category=FutureWarning)
        extractor_format = cls.infer_extractor_format(path)
        if extractor_format:
            return True if not return_extractor else (True, cls.extractors[extractor_format])
        return False if not return_extractor else (False, None)

    @classmethod
    def infer_extractor_format(cls, path: Union[Path, str]) -> Optional[str]:
        magic_number_max_length = cls._get_magic_number_max_length()
        magic_number = cls._read_magic_number(path, magic_number_max_length)
        for extractor_format, extractor in cls.extractors.items():
            if extractor.is_extractable(path, magic_number=magic_number):
                return extractor_format

    @classmethod
    def extract(cls, input_path: Union[Path, str], output_path: Union[Path, str], extractor_format: str) -> None:
        os.makedirs(os.path.dirname(output_path), exist_ok=True)
        lock_path = str(Path(output_path).with_suffix('.lock'))
        with FileLock(lock_path):
            shutil.rmtree(output_path, ignore_errors=True)
            extractor = cls.extractors[extractor_format]
            return extractor.extract(input_path, output_path)

