            info.repo_url = repo_url
        if paper_url is not None:
            info.paper_url = paper_url
        if docs_url is not None:
            info.docs_url = docs_url
        if language is not None:
            info.model_card_data.language = language
        if library_name is not None:
            info.model_card_data.library_name = library_name
        if license is not None:
            info.model_card_data.license = license
        if license_name is not None:
            info.model_card_data.license_name = license_name
        if license_link is not None:
            info.model_card_data.license_link = license_link
        if pipeline_tag is not None:
            info.model_card_data.pipeline_tag = pipeline_tag
        if tags is not None:
            normalized_tags = list(tags)
            if info.model_card_data.tags is not None:
                info.model_card_data.tags.extend(normalized_tags)
            else:
                info.model_card_data.tags = normalized_tags
        if info.model_card_data.tags is not None:
            info.model_card_data.tags = sorted(set(info.model_card_data.tags))
        cls._hub_mixin_coders = coders or {}
        cls._hub_mixin_jsonable_custom_types = tuple(cls._hub_mixin_coders.keys())
        cls._hub_mixin_init_parameters = dict(inspect.signature(cls.__init__).parameters)
        cls._hub_mixin_jsonable_default_values = {param.name: cls._encode_arg(param.default) for param in cls._hub_mixin_init_parameters.values() if param.default is not inspect.Parameter.empty and cls._is_jsonable(param.default)}
        cls._hub_mixin_inject_config = 'config' in inspect.signature(cls._from_pretrained).parameters

    def __new__(cls: type[T], *args, **kwargs) -> T:
        instance = super().__new__(cls)
        if instance._hub_mixin_config is not None:
            return instance
        passed_values = {**{key: value for key, value in zip(list(cls._hub_mixin_init_parameters)[1:], args)}, **kwargs}
        if is_dataclass(passed_values.get('config')):
            instance._hub_mixin_config = passed_values['config']
            return instance
        init_config = {**cls._hub_mixin_jsonable_default_values, **{key: cls._encode_arg(value) for key, value in passed_values.items() if instance._is_jsonable(value)}}
        passed_config = init_config.pop('config', {})
        if isinstance(passed_config, dict):
            init_config.update(passed_config)
        if init_config != {}:
            instance._hub_mixin_config = init_config
        return instance

    @classmethod
    def _is_jsonable(cls, value: Any) -> bool:
        if is_dataclass(value):
            return True
        if isinstance(value, cls._hub_mixin_jsonable_custom_types):
            return True
        return is_jsonable(value)

    @classmethod
    def _encode_arg(cls, arg: Any) -> Any:
        if is_dataclass(arg):
            return asdict(arg)
        for type_, (encoder, _) in cls._hub_mixin_coders.items():
            if isinstance(arg, type_):
                if arg is None:
                    return None
                return encoder(arg)
        return arg

    @classmethod
    def _decode_arg(cls, expected_type: type[ARGS_T], value: Any) -> Optional[ARGS_T]:
        if is_simple_optional_type(expected_type):
            if value is None:
                return None
            expected_type = unwrap_simple_optional_type(expected_type)
        if is_dataclass(expected_type):
            return _load_dataclass(expected_type, value)
        for type_, (_, decoder) in cls._hub_mixin_coders.items():
            if inspect.isclass(expected_type) and issubclass(expected_type, type_):
                return decoder(value)
        return value

    def save_pretrained(self, save_directory: Union[str, Path], *, config: Optional[Union[dict, DataclassInstance]]=None, repo_id: Optional[str]=None, push_to_hub: bool=False, model_card_kwargs: Optional[dict[str, Any]]=None, **push_to_hub_kwargs) -> Optional[str]:
        save_directory = Path(save_directory)
        save_directory.mkdir(parents=True, exist_ok=True)
        config_path = save_directory / constants.CONFIG_NAME
        config_path.unlink(missing_ok=True)
        self._save_pretrained(save_directory)
        if config is None:
            config = self._hub_mixin_config
        if config is not None:
            if is_dataclass(config):
                config = asdict(config)
            if not config_path.exists():
                config_str = json.dumps(config, sort_keys=True, indent=2)
                config_path.write_text(config_str)
        model_card_path = save_directory / 'README.md'
        model_card_kwargs = model_card_kwargs if model_card_kwargs is not None else {}
        if not model_card_path.exists():
            self.generate_model_card(**model_card_kwargs).save(save_directory / 'README.md')
        if push_to_hub:
            kwargs = push_to_hub_kwargs.copy()
            if config is not None:
                kwargs['config'] = config
            if repo_id is None:
                repo_id = save_directory.name
            return self.push_to_hub(repo_id=repo_id, model_card_kwargs=model_card_kwargs, **kwargs)
        return None

    def _save_pretrained(self, save_directory: Path) -> None:
        raise NotImplementedError

    @classmethod
    @validate_hf_hub_args
    def from_pretrained(cls: type[T], pretrained_model_name_or_path: Union[str, Path], *, force_download: bool=False, token: Optional[Union[str, bool]]=None, cache_dir: Optional[Union[str, Path]]=None, local_files_only: bool=False, revision: Optional[str]=None, **model_kwargs) -> T:
        model_id = str(pretrained_model_name_or_path)
        config_file: Optional[str] = None
        if os.path.isdir(model_id):
            if constants.CONFIG_NAME in os.listdir(model_id):
                config_file = os.path.join(model_id, constants.CONFIG_NAME)
            else:
                logger.warning(f'{constants.CONFIG_NAME} not found in {Path(model_id).resolve()}')
        else:
            try:
                config_file = hf_hub_download(repo_id=model_id, filename=constants.CONFIG_NAME, revision=revision, cache_dir=cache_dir, force_download=force_download, token=token, local_files_only=local_files_only)
            except HfHubHTTPError as e:
                logger.info(f'{constants.CONFIG_NAME} not found on the HuggingFace Hub: {str(e)}')
        config = None
        if config_file is not None:
            with open(config_file, 'r', encoding='utf-8') as f:
                config = json.load(f)
            for key, value in config.items():
                if key in cls._hub_mixin_init_parameters:
                    expected_type = cls._hub_mixin_init_parameters[key].annotation
                    if expected_type is not inspect.Parameter.empty:
                        config[key] = cls._decode_arg(expected_type, value)
            for param in cls._hub_mixin_init_parameters.values():
                if param.name not in model_kwargs and param.name in config:
                    model_kwargs[param.name] = config[param.name]
            if 'config' in cls._hub_mixin_init_parameters and 'config' not in model_kwargs:
                config_annotation = cls._hub_mixin_init_parameters['config'].annotation
                config = cls._decode_arg(config_annotation, config)
                model_kwargs['config'] = config
            if is_dataclass(cls):
                for key in cls.__dataclass_fields__:
                    if key not in model_kwargs and key in config:
                        model_kwargs[key] = config[key]
            elif any((param.kind == inspect.Parameter.VAR_KEYWORD for param in cls._hub_mixin_init_parameters.values())):
                for key, value in config.items():
                    if key not in model_kwargs:
                        model_kwargs[key] = value
            if cls._hub_mixin_inject_config and 'config' not in model_kwargs:
                model_kwargs['config'] = config
        instance = cls._from_pretrained(model_id=str(model_id), revision=revision, cache_dir=cache_dir, force_download=force_download, local_files_only=local_files_only, token=token, **model_kwargs)
        if config is not None and getattr(instance, '_hub_mixin_config', None) in (None, {}):
            instance._hub_mixin_config = config
        return instance

    @classmethod
    def _from_pretrained(cls: type[T], *, model_id: str, revision: Optional[str], cache_dir: Optional[Union[str, Path]], force_download: bool, local_files_only: bool, token: Optional[Union[str, bool]], **model_kwargs) -> T:
        raise NotImplementedError

    @validate_hf_hub_args
    def push_to_hub(self, repo_id: str, *, config: Optional[Union[dict, DataclassInstance]]=None, commit_message: str='Push model using huggingface_hub.', private: Optional[bool]=None, token: Optional[str]=None, branch: Optional[str]=None, create_pr: Optional[bool]=None, allow_patterns: Optional[Union[list[str], str]]=None, ignore_patterns: Optional[Union[list[str], str]]=None, delete_patterns: Optional[Union[list[str], str]]=None, model_card_kwargs: Optional[dict[str, Any]]=None) -> str:
        api = HfApi(token=token)
        repo_id = api.create_repo(repo_id=repo_id, private=private, exist_ok=True).repo_id
        with SoftTemporaryDirectory() as tmp:
            saved_path = Path(tmp) / repo_id
            self.save_pretrained(saved_path, config=config, model_card_kwargs=model_card_kwargs)
            return api.upload_folder(repo_id=repo_id, repo_type='model', folder_path=saved_path, commit_message=commit_message, revision=branch, create_pr=create_pr, allow_patterns=allow_patterns, ignore_patterns=ignore_patterns, delete_patterns=delete_patterns)

    def generate_model_card(self, *args, **kwargs) -> ModelCard:
        card = ModelCard.from_template(card_data=self._hub_mixin_info.model_card_data, template_str=self._hub_mixin_info.model_card_template, repo_url=self._hub_mixin_info.repo_url, paper_url=self._hub_mixin_info.paper_url, docs_url=self._hub_mixin_info.docs_url, **kwargs)
        return card

class PyTorchModelHubMixin(ModelHubMixin):

    def __init_subclass__(cls, *args, tags: Optional[list[str]]=None, **kwargs) -> None:
        tags = tags or []
        tags.append('pytorch_model_hub_mixin')
        kwargs['tags'] = tags
        return super().__init_subclass__(*args, **kwargs)

    def _save_pretrained(self, save_directory: Path) -> None:
        model_to_save = self.module if hasattr(self, 'module') else self
        save_model_as_safetensor(model_to_save, str(save_directory / constants.SAFETENSORS_SINGLE_FILE))

    @classmethod
    def _from_pretrained(cls, *, model_id: str, revision: Optional[str], cache_dir: Optional[Union[str, Path]], force_download: bool, local_files_only: bool, token: Union[str, bool, None], map_location: str='cpu', strict: bool=False, **model_kwargs):
        model = cls(**model_kwargs)
        if os.path.isdir(model_id):
            print('Loading weights from local directory')
            model_file = os.path.join(model_id, constants.SAFETENSORS_SINGLE_FILE)
            return cls._load_as_safetensor(model, model_file, map_location, strict)
        else:
            try:
                model_file = hf_hub_download(repo_id=model_id, filename=constants.SAFETENSORS_SINGLE_FILE, revision=revision, cache_dir=cache_dir, force_download=force_download, token=token, local_files_only=local_files_only)
                return cls._load_as_safetensor(model, model_file, map_location, strict)
            except EntryNotFoundError:
                model_file = hf_hub_download(repo_id=model_id, filename=constants.PYTORCH_WEIGHTS_NAME, revision=revision, cache_dir=cache_dir, force_download=force_download, token=token, local_files_only=local_files_only)
                return cls._load_as_pickle(model, model_file, map_location, strict)

    @classmethod
    def _load_as_pickle(cls, model: T, model_file: str, map_location: str, strict: bool) -> T:
        state_dict = torch.load(model_file, map_location=torch.device(map_location), weights_only=True)
        model.load_state_dict(state_dict, strict=strict)
        model.eval()
        return model

    @classmethod
    def _load_as_safetensor(cls, model: T, model_file: str, map_location: str, strict: bool) -> T:
        if packaging.version.parse(safetensors.__version__) < packaging.version.parse('0.4.3'):
            load_model_as_safetensor(model, model_file, strict=strict)
            if map_location != 'cpu':
                logger.warning("Loading model weights on other devices than 'cpu' is not supported natively in your version of safetensors. This means that the model is loaded on 'cpu' first and then copied to the device. This leads to a slower loading time. Please update safetensors to version 0.4.3 or above for improved performance.")
                model.to(map_location)
        else:
            safetensors.torch.load_model(model, model_file, strict=strict, device=map_location)
        return model

def _load_dataclass(datacls: type[DataclassInstance], data: dict) -> DataclassInstance:
    return datacls(**{k: v for k, v in data.items() if k in datacls.__dataclass_fields__})

from __future__ import annotations
import io
import json
import os
from typing import TYPE_CHECKING, Any, Literal
from warnings import catch_warnings, filterwarnings
from pandas._libs import lib
from pandas.compat._optional import import_optional_dependency
from pandas.errors import AbstractMethodError, Pandas4Warning
from pandas.util._decorators import set_module
from pandas.util._validators import check_dtype_backend
from pandas import DataFrame, get_option
from pandas.io._util import arrow_table_to_pandas
from pandas.io.common import IOHandles, get_handle, is_fsspec_url, is_url, stringify_path
if TYPE_CHECKING:
    from pandas._typing import DtypeBackend, FilePath, ParquetCompressionOptions, ReadBuffer, StorageOptions, WriteBuffer

def get_engine(engine: str) -> BaseImpl:
    if engine == 'auto':
        engine = get_option('io.parquet.engine')
    if engine == 'auto':
        engine_classes = [PyArrowImpl, FastParquetImpl]
        error_msgs = ''
        for engine_class in engine_classes:
            try:
                return engine_class()
            except ImportError as err:
                error_msgs += '\n - ' + str(err)
        raise ImportError(f"Unable to find a usable engine; tried using: 'pyarrow', 'fastparquet'.\nA suitable version of pyarrow or fastparquet is required for parquet support.\nTrying to import the above resulted in these errors:{error_msgs}")
    if engine == 'pyarrow':
        return PyArrowImpl()
    elif engine == 'fastparquet':
        return FastParquetImpl()
    raise ValueError("engine must be one of 'pyarrow', 'fastparquet'")

def _get_path_or_handle(path: FilePath | ReadBuffer[bytes] | WriteBuffer[bytes], fs: Any, storage_options: StorageOptions | None=None, mode: str='rb', is_dir: bool=False) -> tuple[FilePath | ReadBuffer[bytes] | WriteBuffer[bytes], IOHandles[bytes] | None, Any]:
    path_or_handle = stringify_path(path)
    if fs is not None:
        pa_fs = import_optional_dependency('pyarrow.fs', errors='ignore')
        fsspec = import_optional_dependency('fsspec', errors='ignore')
        if pa_fs is not None and isinstance(fs, pa_fs.FileSystem):
            if storage_options:
                raise NotImplementedError('storage_options not supported with a pyarrow FileSystem.')
        elif fsspec is not None and isinstance(fs, fsspec.spec.AbstractFileSystem):
            pass
        else:
            raise ValueError(f'filesystem must be a pyarrow or fsspec FileSystem, not a {type(fs).__name__}')
    if is_fsspec_url(path_or_handle) and fs is None:
        if storage_options is None:
            pa = import_optional_dependency('pyarrow')
            pa_fs = import_optional_dependency('pyarrow.fs')
            try:
                fs, path_or_handle = pa_fs.FileSystem.from_uri(path)
            except (TypeError, pa.ArrowInvalid):
                pass
        if fs is None:
            fsspec = import_optional_dependency('fsspec')
            fs, path_or_handle = fsspec.core.url_to_fs(path_or_handle, **storage_options or {})
    elif storage_options and (not is_url(path_or_handle) or mode != 'rb'):
        raise ValueError('storage_options passed with buffer, or non-supported URL')
    handles = None
    if not fs and (not is_dir) and isinstance(path_or_handle, str) and (not os.path.isdir(path_or_handle)):
        handles = get_handle(path_or_handle, mode, is_text=False, storage_options=storage_options)
        fs = None
        path_or_handle = handles.handle
    return (path_or_handle, handles, fs)

class BaseImpl:

    @staticmethod
    def validate_dataframe(df: DataFrame) -> None:
        if not isinstance(df, DataFrame):
            raise ValueError('to_parquet only supports IO with DataFrames')

    def write(self, df: DataFrame, path, compression, **kwargs) -> None:
        raise AbstractMethodError(self)

    def read(self, path, columns=None, **kwargs) -> DataFrame:
        raise AbstractMethodError(self)

class PyArrowImpl(BaseImpl):

    def __init__(self) -> None:
        import_optional_dependency('pyarrow', extra='pyarrow is required for parquet support.')
        import pyarrow.parquet
        import pandas.core.arrays.arrow.extension_types
        self.api = pyarrow

    def write(self, df: DataFrame, path: FilePath | WriteBuffer[bytes], compression: ParquetCompressionOptions='snappy', index: bool | None=None, storage_options: StorageOptions | None=None, partition_cols: list[str] | None=None, filesystem=None, **kwargs) -> None:
        self.validate_dataframe(df)
        from_pandas_kwargs: dict[str, Any] = {'schema': kwargs.pop('schema', None)}
        if index is not None:
            from_pandas_kwargs['preserve_index'] = index
        table = self.api.Table.from_pandas(df, **from_pandas_kwargs)
        if df.attrs:
            df_metadata = {'PANDAS_ATTRS': json.dumps(df.attrs)}
            existing_metadata = table.schema.metadata
            merged_metadata = {**existing_metadata, **df_metadata}
            table = table.replace_schema_metadata(merged_metadata)
        path_or_handle, handles, filesystem = _get_path_or_handle(path, filesystem, storage_options=storage_options, mode='wb', is_dir=partition_cols is not None)
        if isinstance(path_or_handle, io.BufferedWriter) and hasattr(path_or_handle, 'name') and isinstance(path_or_handle.name, (str, bytes)):
            if isinstance(path_or_handle.name, bytes):
                path_or_handle = path_or_handle.name.decode()
            else:
                path_or_handle = path_or_handle.name
        try:
            if partition_cols is not None:
                self.api.parquet.write_to_dataset(table, path_or_handle, compression=compression, partition_cols=partition_cols, filesystem=filesystem, **kwargs)
            else:
                self.api.parquet.write_table(table, path_or_handle, compression=compression, filesystem=filesystem, **kwargs)
        finally:
            if handles is not None:
                handles.close()

    def read(self, path, columns=None, filters=None, dtype_backend: DtypeBackend | lib.NoDefault=lib.no_default, storage_options: StorageOptions | None=None, filesystem=None, to_pandas_kwargs: dict[str, Any] | None=None, **kwargs) -> DataFrame:
        kwargs['use_pandas_metadata'] = True
        path_or_handle, handles, filesystem = _get_path_or_handle(path, filesystem, storage_options=storage_options, mode='rb')
        try:
            pa_table = self.api.parquet.read_table(path_or_handle, columns=columns, filesystem=filesystem, filters=filters, **kwargs)
            with catch_warnings():
                filterwarnings('ignore', 'make_block is deprecated', Pandas4Warning)
                result = arrow_table_to_pandas(pa_table, dtype_backend=dtype_backend, to_pandas_kwargs=to_pandas_kwargs)
            if pa_table.schema.metadata:
                if b'PANDAS_ATTRS' in pa_table.schema.metadata:
                    df_metadata = pa_table.schema.metadata[b'PANDAS_ATTRS']
                    result.attrs = json.loads(df_metadata)
            return result
        finally:
            if handles is not None:
                handles.close()

class FastParquetImpl(BaseImpl):

    def __init__(self) -> None:
        fastparquet = import_optional_dependency('fastparquet', extra='fastparquet is required for parquet support.')
        self.api = fastparquet

    def write(self, df: DataFrame, path, compression: Literal['snappy', 'gzip', 'brotli'] | None='snappy', index=None, partition_cols=None, storage_options: StorageOptions | None=None, filesystem=None, **kwargs) -> None:
        self.validate_dataframe(df)
        if 'partition_on' in kwargs and partition_cols is not None:
            raise ValueError('Cannot use both partition_on and partition_cols. Use partition_cols for partitioning data')
        if 'partition_on' in kwargs:
            partition_cols = kwargs.pop('partition_on')
        if partition_cols is not None:
            kwargs['file_scheme'] = 'hive'
        if filesystem is not None:
            raise NotImplementedError('filesystem is not implemented for the fastparquet engine.')
        path = stringify_path(path)
        if is_fsspec_url(path):
            fsspec = import_optional_dependency('fsspec')
            kwargs['open_with'] = lambda path, _: fsspec.open(path, 'wb', **storage_options or {}).open()
        elif storage_options:
            raise ValueError('storage_options passed with file object or non-fsspec file path')
        with catch_warnings(record=True):
            self.api.write(path, df, compression=compression, write_index=index, partition_on=partition_cols, **kwargs)

    def read(self, path, columns=None, filters=None, storage_options: StorageOptions | None=None, filesystem=None, to_pandas_kwargs: dict | None=None, **kwargs) -> DataFrame:
        parquet_kwargs: dict[str, Any] = {}
        dtype_backend = kwargs.pop('dtype_backend', lib.no_default)
        parquet_kwargs['pandas_nulls'] = False
        if dtype_backend is not lib.no_default:
            raise ValueError("The 'dtype_backend' argument is not supported for the fastparquet engine")
        if filesystem is not None:
            raise NotImplementedError('filesystem is not implemented for the fastparquet engine.')
        if to_pandas_kwargs is not None:
            raise NotImplementedError('to_pandas_kwargs is not implemented for the fastparquet engine.')
        path = stringify_path(path)
        handles = None
        if is_fsspec_url(path):
            fsspec = import_optional_dependency('fsspec')
            parquet_kwargs['fs'] = fsspec.open(path, 'rb', **storage_options or {}).fs
        elif isinstance(path, str) and (not os.path.isdir(path)):
            handles = get_handle(path, 'rb', is_text=False, storage_options=storage_options)
            path = handles.handle
        try:
            parquet_file = self.api.ParquetFile(path, **parquet_kwargs)
            with catch_warnings():
                filterwarnings('ignore', 'make_block is deprecated', Pandas4Warning)
                return parquet_file.to_pandas(columns=columns, filters=filters, **kwargs)
        finally:
            if handles is not None:
                handles.close()

def to_parquet(df: DataFrame, path: FilePath | WriteBuffer[bytes] | None=None, engine: str='auto', compression: ParquetCompressionOptions='snappy', index: bool | None=None, storage_options: StorageOptions | None=None, partition_cols: list[str] | None=None, filesystem: Any=None, **kwargs) -> bytes | None:
    if isinstance(partition_cols, str):
        partition_cols = [partition_cols]
    impl = get_engine(engine)
    path_or_buf: FilePath | WriteBuffer[bytes] = io.BytesIO() if path is None else path
    impl.write(df, path_or_buf, compression=compression, index=index, partition_cols=partition_cols, storage_options=storage_options, filesystem=filesystem, **kwargs)
    if path is None:
        assert isinstance(path_or_buf, io.BytesIO)
        return path_or_buf.getvalue()
    else:
        return None

@set_module('pandas')
def read_parquet(path: FilePath | ReadBuffer[bytes], engine: str='auto', columns: list[str] | None=None, storage_options: StorageOptions | None=None, dtype_backend: DtypeBackend | lib.NoDefault=lib.no_default, filesystem: Any=None, filters: list[tuple] | list[list[tuple]] | None=None, to_pandas_kwargs: dict | None=None, **kwargs) -> DataFrame:
    impl = get_engine(engine)
    check_dtype_backend(dtype_backend)
    return impl.read(path, columns=columns, filters=filters, storage_options=storage_options, dtype_backend=dtype_backend, filesystem=filesystem, to_pandas_kwargs=to_pandas_kwargs, **kwargs)

import glob
import json
import os
import shutil
import time
from pathlib import Path
from typing import Optional, Union
import pyarrow as pa
import datasets
import datasets.config
import datasets.data_files
from datasets.builder import Key
from datasets.naming import camelcase_to_snakecase, filenames_for_dataset_split
logger = datasets.utils.logging.get_logger(__name__)

def _get_modification_time(cached_directory_path):
    return Path(cached_directory_path).stat().st_mtime

def _find_hash_in_cache(dataset_name: str, config_name: Optional[str], cache_dir: Optional[str], config_kwargs: dict, custom_features: Optional[datasets.Features]) -> tuple[str, str, str]:
    if config_name or config_kwargs or custom_features:
        config_id = datasets.BuilderConfig(config_name or 'default').create_config_id(config_kwargs=config_kwargs, custom_features=custom_features)
    else:
        config_id = None
    cache_dir = os.path.expanduser(str(cache_dir or datasets.config.HF_DATASETS_CACHE))
    namespace_and_dataset_name = dataset_name.split('/')
    namespace_and_dataset_name[-1] = camelcase_to_snakecase(namespace_and_dataset_name[-1])
    cached_relative_path = '___'.join(namespace_and_dataset_name)
    cached_datasets_directory_path_root = os.path.join(cache_dir, cached_relative_path)
    cached_directory_paths = [cached_directory_path for cached_directory_path in glob.glob(os.path.join(cached_datasets_directory_path_root, config_id or '*', '*', '*')) if os.path.isdir(cached_directory_path) and (config_kwargs or custom_features or json.loads(Path(cached_directory_path, 'dataset_info.json').read_text(encoding='utf-8'))['config_name'] == Path(cached_directory_path).parts[-3])]
    if not cached_directory_paths:
        cached_directory_paths = [cached_directory_path for cached_directory_path in glob.glob(os.path.join(cached_datasets_directory_path_root, '*', '*', '*')) if os.path.isdir(cached_directory_path)]
        available_configs = sorted({Path(cached_directory_path).parts[-3] for cached_directory_path in cached_directory_paths})
        raise ValueError(f"Couldn't find cache for {dataset_name}" + (f" for config '{config_id}'" if config_id else '') + (f'\nAvailable configs in the cache: {available_configs}' if available_configs else ''))
    cached_directory_path = Path(sorted(cached_directory_paths, key=_get_modification_time)[-1])
    version, hash = cached_directory_path.parts[-2:]
    other_configs = [Path(_cached_directory_path).parts[-3] for _cached_directory_path in glob.glob(os.path.join(cached_datasets_directory_path_root, '*', version, hash)) if os.path.isdir(_cached_directory_path) and (config_kwargs or custom_features or json.loads(Path(_cached_directory_path, 'dataset_info.json').read_text(encoding='utf-8'))['config_name'] == Path(_cached_directory_path).parts[-3])]
    if not config_id and len(other_configs) > 1:
        raise ValueError(f"There are multiple '{dataset_name}' configurations in the cache: {', '.join(other_configs)}\nPlease specify which configuration to reload from the cache, e.g.\n\tload_dataset('{dataset_name}', '{other_configs[0]}')")
    config_name = cached_directory_path.parts[-3]
    warning_msg = f"Found the latest cached dataset configuration '{config_name}' at {cached_directory_path} (last modified on {time.ctime(_get_modification_time(cached_directory_path))})."
    logger.warning(warning_msg)
    return (config_name, version, hash)

class Cache(datasets.ArrowBasedBuilder):

    def __init__(self, cache_dir: Optional[str]=None, dataset_name: Optional[str]=None, config_name: Optional[str]=None, version: Optional[str]='0.0.0', hash: Optional[str]=None, base_path: Optional[str]=None, info: Optional[datasets.DatasetInfo]=None, features: Optional[datasets.Features]=None, token: Optional[Union[bool, str]]=None, repo_id: Optional[str]=None, data_files: Optional[Union[str, list, dict, datasets.data_files.DataFilesDict]]=None, data_dir: Optional[str]=None, storage_options: Optional[dict]=None, writer_batch_size: Optional[int]=None, **config_kwargs):
        if repo_id is None and dataset_name is None:
            raise ValueError('repo_id or dataset_name is required for the Cache dataset builder')
        if data_files is not None:
            config_kwargs['data_files'] = data_files
        if data_dir is not None:
            config_kwargs['data_dir'] = data_dir
        if hash == 'auto' and version == 'auto':
            config_name, version, hash = _find_hash_in_cache(dataset_name=repo_id or dataset_name, config_name=config_name, cache_dir=cache_dir, config_kwargs=config_kwargs, custom_features=features)
        elif hash == 'auto' or version == 'auto':
            raise NotImplementedError("Pass both hash='auto' and version='auto' instead")
        super().__init__(cache_dir=cache_dir, dataset_name=dataset_name, config_name=config_name, version=version, hash=hash, base_path=base_path, info=info, token=token, repo_id=repo_id, storage_options=storage_options, writer_batch_size=writer_batch_size)

    def _info(self) -> datasets.DatasetInfo:
        return datasets.DatasetInfo()

    def download_and_prepare(self, output_dir: Optional[str]=None, *args, **kwargs):
        if not os.path.exists(self.cache_dir):
            raise ValueError(f"Cache directory for {self.dataset_name} doesn't exist at {self.cache_dir}")
        if output_dir is not None and output_dir != self.cache_dir:
            shutil.copytree(self.cache_dir, output_dir)

    def _split_generators(self, dl_manager):
        if isinstance(self.info.splits, datasets.SplitDict):
            split_infos: list[datasets.SplitInfo] = list(self.info.splits.values())
        else:
            raise ValueError(f'Missing splits info for {self.dataset_name} in cache directory {self.cache_dir}')
        return [datasets.SplitGenerator(name=split_info.name, gen_kwargs={'files': filenames_for_dataset_split(self.cache_dir, dataset_name=self.dataset_name, split=split_info.name, filetype_suffix='arrow', shard_lengths=split_info.shard_lengths)}) for split_info in split_infos]

    def _generate_shards(self, files):
        yield from files

    def _generate_tables(self, files):
        for file_idx, file in enumerate(files):
            with open(file, 'rb') as f:
                try:
                    for batch_idx, record_batch in enumerate(pa.ipc.open_stream(f)):
                        pa_table = pa.Table.from_batches([record_batch])
                        yield (Key(file_idx, batch_idx), pa_table)
                except ValueError as e:
                    logger.error(f"Failed to read file '{file}' with error {type(e)}: {e}")
                    raise

import asyncio
import io
import os
import pathlib
import sys
from contextlib import suppress
from enum import Enum, auto
from mimetypes import MimeTypes
from stat import S_ISREG
from types import MappingProxyType
from typing import IO, TYPE_CHECKING, Any, Awaitable, Callable, Final, Iterator, List, Optional, Set, Tuple, Union, cast
from . import hdrs
from .abc import AbstractStreamWriter
from .helpers import ETAG_ANY, ETag, must_be_empty_body
from .typedefs import LooseHeaders, PathLike
from .web_exceptions import HTTPForbidden, HTTPNotFound, HTTPNotModified, HTTPPartialContent, HTTPPreconditionFailed, HTTPRequestRangeNotSatisfiable
from .web_response import StreamResponse
__all__ = ('FileResponse',)
if TYPE_CHECKING:
    from .web_request import BaseRequest
_T_OnChunkSent = Optional[Callable[[bytes], Awaitable[None]]]
NOSENDFILE: Final[bool] = bool(os.environ.get('AIOHTTP_NOSENDFILE'))
CONTENT_TYPES: Final[MimeTypes] = MimeTypes()
ENCODING_EXTENSIONS = MappingProxyType({ext: CONTENT_TYPES.encodings_map[ext] for ext in ('.br', '.gz')})
FALLBACK_CONTENT_TYPE = 'application/octet-stream'
ADDITIONAL_CONTENT_TYPES = MappingProxyType({'application/gzip': '.gz', 'application/x-brotli': '.br', 'application/x-bzip2': '.bz2', 'application/x-compress': '.Z', 'application/x-xz': '.xz'})

class _FileResponseResult(Enum):
    SEND_FILE = auto()
    NOT_ACCEPTABLE = auto()
    PRE_CONDITION_FAILED = auto()
    NOT_MODIFIED = auto()
CONTENT_TYPES.encodings_map.clear()
for content_type, extension in ADDITIONAL_CONTENT_TYPES.items():
    CONTENT_TYPES.add_type(content_type, extension)
_CLOSE_FUTURES: Set[asyncio.Future[None]] = set()

class FileResponse(StreamResponse):

    def __init__(self, path: PathLike, chunk_size: int=256 * 1024, status: int=200, reason: Optional[str]=None, headers: Optional[LooseHeaders]=None) -> None:
        super().__init__(status=status, reason=reason, headers=headers)
        self._path = pathlib.Path(path)
        self._chunk_size = chunk_size

    def _seek_and_read(self, fobj: IO[Any], offset: int, chunk_size: int) -> bytes:
        fobj.seek(offset)
        return fobj.read(chunk_size)

    async def _sendfile_fallback(self, writer: AbstractStreamWriter, fobj: IO[Any], offset: int, count: int) -> AbstractStreamWriter:
        chunk_size = self._chunk_size
        loop = asyncio.get_event_loop()
        chunk = await loop.run_in_executor(None, self._seek_and_read, fobj, offset, min(chunk_size, count))
        while chunk:
            await writer.write(chunk)
            count = count - len(chunk)
            if count <= 0:
                break
            chunk = await loop.run_in_executor(None, fobj.read, min(chunk_size, count))
        await writer.drain()
        return writer

    async def _sendfile(self, request: 'BaseRequest', fobj: IO[Any], offset: int, count: int) -> AbstractStreamWriter:
        writer = await super().prepare(request)
        assert writer is not None
        if NOSENDFILE or self.compression:
            return await self._sendfile_fallback(writer, fobj, offset, count)
        loop = request._loop
        transport = request.transport
        assert transport is not None
        try:
            await loop.sendfile(transport, fobj, offset, count)
        except NotImplementedError:
            return await self._sendfile_fallback(writer, fobj, offset, count)
        await super().write_eof()
        return writer

    @staticmethod
    def _etag_match(etag_value: str, etags: Tuple[ETag, ...], *, weak: bool) -> bool:
        if len(etags) == 1 and etags[0].value == ETAG_ANY:
            return True
        return any((etag.value == etag_value for etag in etags if weak or not etag.is_weak))

    async def _not_modified(self, request: 'BaseRequest', etag_value: str, last_modified: float) -> Optional[AbstractStreamWriter]:
        self.set_status(HTTPNotModified.status_code)
        self._length_check = False
        self.etag = etag_value
        self.last_modified = last_modified
        return await super().prepare(request)

    async def _precondition_failed(self, request: 'BaseRequest') -> Optional[AbstractStreamWriter]:
        self.set_status(HTTPPreconditionFailed.status_code)
        self.content_length = 0
        return await super().prepare(request)

    def _make_response(self, request: 'BaseRequest', accept_encoding: str) -> Tuple[_FileResponseResult, Optional[io.BufferedReader], os.stat_result, Optional[str]]:
        file_path, st, file_encoding = self._get_file_path_stat_encoding(accept_encoding)
        if not file_path:
            return (_FileResponseResult.NOT_ACCEPTABLE, None, st, None)
        etag_value = f'{st.st_mtime_ns:x}-{st.st_size:x}'
        if (ifmatch := request.if_match) is not None and (not self._etag_match(etag_value, ifmatch, weak=False)):
            return (_FileResponseResult.PRE_CONDITION_FAILED, None, st, file_encoding)
        if (unmodsince := request.if_unmodified_since) is not None and ifmatch is None and (st.st_mtime > unmodsince.timestamp()):
            return (_FileResponseResult.PRE_CONDITION_FAILED, None, st, file_encoding)
        if (ifnonematch := request.if_none_match) is not None and self._etag_match(etag_value, ifnonematch, weak=True):
            return (_FileResponseResult.NOT_MODIFIED, None, st, file_encoding)
        if (modsince := request.if_modified_since) is not None and ifnonematch is None and (st.st_mtime <= modsince.timestamp()):
            return (_FileResponseResult.NOT_MODIFIED, None, st, file_encoding)
        fobj = file_path.open('rb')
        with suppress(OSError):
            st = os.stat(fobj.fileno())
        return (_FileResponseResult.SEND_FILE, fobj, st, file_encoding)

    def _get_file_path_stat_encoding(self, accept_encoding: str) -> Tuple[Optional[pathlib.Path], os.stat_result, Optional[str]]:
        file_path = self._path
        for file_extension, file_encoding in ENCODING_EXTENSIONS.items():
            if file_encoding not in accept_encoding:
                continue
            compressed_path = file_path.with_suffix(file_path.suffix + file_extension)
            with suppress(OSError):
                st = compressed_path.lstat()
                if S_ISREG(st.st_mode):
                    return (compressed_path, st, file_encoding)
        st = file_path.stat()
        return (file_path if S_ISREG(st.st_mode) else None, st, None)

    async def prepare(self, request: 'BaseRequest') -> Optional[AbstractStreamWriter]:
        loop = asyncio.get_running_loop()
        accept_encoding = request.headers.get(hdrs.ACCEPT_ENCODING, '').lower()
        try:
            response_result, fobj, st, file_encoding = await loop.run_in_executor(None, self._make_response, request, accept_encoding)
        except PermissionError:
            self.set_status(HTTPForbidden.status_code)
            return await super().prepare(request)
        except OSError:
            self.set_status(HTTPNotFound.status_code)
            return await super().prepare(request)
        if response_result is _FileResponseResult.NOT_ACCEPTABLE:
            self.set_status(HTTPForbidden.status_code)
            return await super().prepare(request)
        if response_result is _FileResponseResult.PRE_CONDITION_FAILED:
            return await self._precondition_failed(request)
        if response_result is _FileResponseResult.NOT_MODIFIED:
            etag_value = f'{st.st_mtime_ns:x}-{st.st_size:x}'
            last_modified = st.st_mtime
            return await self._not_modified(request, etag_value, last_modified)
        assert fobj is not None
        try:
            return await self._prepare_open_file(request, fobj, st, file_encoding)
        finally:
            close_future = loop.run_in_executor(None, fobj.close)
            _CLOSE_FUTURES.add(close_future)
            close_future.add_done_callback(_CLOSE_FUTURES.remove)

    async def _prepare_open_file(self, request: 'BaseRequest', fobj: io.BufferedReader, st: os.stat_result, file_encoding: Optional[str]) -> Optional[AbstractStreamWriter]:
        status = self._status
        file_size: int = st.st_size
        file_mtime: float = st.st_mtime
        count: int = file_size
        start: Optional[int] = None
        if (ifrange := request.if_range) is None or file_mtime <= ifrange.timestamp():
            try:
                rng = request.http_range
                start = rng.start
                end: Optional[int] = rng.stop
            except ValueError:
                self._headers[hdrs.CONTENT_RANGE] = f'bytes */{file_size}'
                self.set_status(HTTPRequestRangeNotSatisfiable.status_code)
                return await super().prepare(request)
            if start is not None:
                if start < 0 and end is None:
                    start += file_size
                    if start < 0:
                        start = 0
                    count = file_size - start
                else:
                    count = min(end if end is not None else file_size, file_size) - start
                if start >= file_size:
                    self._headers[hdrs.CONTENT_RANGE] = f'bytes */{file_size}'
                    self.set_status(HTTPRequestRangeNotSatisfiable.status_code)
                    return await super().prepare(request)
                status = HTTPPartialContent.status_code
                self.set_status(status)
        if hdrs.CONTENT_TYPE not in self._headers:
            if sys.version_info >= (3, 13):
                guesser = CONTENT_TYPES.guess_file_type
            else:
                guesser = CONTENT_TYPES.guess_type
            self.content_type = guesser(self._path)[0] or FALLBACK_CONTENT_TYPE
        if file_encoding:
            self._headers[hdrs.CONTENT_ENCODING] = file_encoding
            self._headers[hdrs.VARY] = hdrs.ACCEPT_ENCODING
            self._compression = False
        self.etag = f'{st.st_mtime_ns:x}-{st.st_size:x}'
        self.last_modified = file_mtime
        self.content_length = count
        self._headers[hdrs.ACCEPT_RANGES] = 'bytes'
        if status == HTTPPartialContent.status_code:
            real_start = start
            assert real_start is not None
            self._headers[hdrs.CONTENT_RANGE] = 'bytes {}-{}/{}'.format(real_start, real_start + count - 1, file_size)
        if count == 0 or must_be_empty_body(request.method, status):
            return await super().prepare(request)
        offset = start or 0
        return await self._sendfile(request, fobj, offset, count)

from __future__ import annotations
import logging
from datetime import datetime, timezone
from errno import ENOTEMPTY
from io import BytesIO
from pathlib import PurePath, PureWindowsPath
from typing import Any, ClassVar
from fsspec import AbstractFileSystem
from fsspec.implementations.local import LocalFileSystem
from fsspec.utils import stringify_path
logger = logging.getLogger('fsspec.memoryfs')

class MemoryFileSystem(AbstractFileSystem):
    store: ClassVar[dict[str, Any]] = {}
    pseudo_dirs = ['']
    protocol = 'memory'
    root_marker = '/'

    @classmethod
    def _strip_protocol(cls, path):
        if isinstance(path, PurePath):
            if isinstance(path, PureWindowsPath):
                return LocalFileSystem._strip_protocol(path)
            else:
                path = stringify_path(path)
        path = path.removeprefix('memory://')
        if '::' in path or '://' in path:
            return path.rstrip('/')
        path = path.lstrip('/').rstrip('/')
        return '/' + path if path else ''

    def ls(self, path, detail=True, **kwargs):
        path = self._strip_protocol(path)
        if path in self.store:
            if not detail:
                return [path]
            return [{'name': path, 'size': self.store[path].size, 'type': 'file', 'created': self.store[path].created.timestamp()}]
        paths = set()
        starter = path + '/'
        out = []
        for p2 in tuple(self.store):
            if p2.startswith(starter):
                if '/' not in p2[len(starter):]:
                    out.append({'name': p2, 'size': self.store[p2].size, 'type': 'file', 'created': self.store[p2].created.timestamp()})
                elif len(p2) > len(starter):
                    ppath = starter + p2[len(starter):].split('/', 1)[0]
                    if ppath not in paths:
                        out = out or []
                        out.append({'name': ppath, 'size': 0, 'type': 'directory'})
                        paths.add(ppath)
        for p2 in self.pseudo_dirs:
            if p2.startswith(starter):
                if '/' not in p2[len(starter):]:
                    if p2 not in paths:
                        out.append({'name': p2, 'size': 0, 'type': 'directory'})
                        paths.add(p2)
                else:
                    ppath = starter + p2[len(starter):].split('/', 1)[0]
                    if ppath not in paths:
                        out.append({'name': ppath, 'size': 0, 'type': 'directory'})
                        paths.add(ppath)
        if not out:
            if path in self.pseudo_dirs:
                return []
            raise FileNotFoundError(path)
        if detail:
            return out
        return sorted([f['name'] for f in out])

    def mkdir(self, path, create_parents=True, **kwargs):
        path = self._strip_protocol(path)
        if path in self.store or path in self.pseudo_dirs:
            raise FileExistsError(path)
        if self._parent(path).strip('/') and self.isfile(self._parent(path)):
            raise NotADirectoryError(self._parent(path))
        if create_parents and self._parent(path).strip('/'):
            try:
                self.mkdir(self._parent(path), create_parents, **kwargs)
            except FileExistsError:
                pass
        if path and path not in self.pseudo_dirs:
            self.pseudo_dirs.append(path)

    def makedirs(self, path, exist_ok=False):
        try:
            self.mkdir(path, create_parents=True)
        except FileExistsError:
            if not exist_ok:
                raise

    def pipe_file(self, path, value, mode='overwrite', **kwargs):
        mode = 'xb' if mode == 'create' else 'wb'
        self.open(path, mode=mode, data=value)

    def rmdir(self, path):
        path = self._strip_protocol(path)
        if path == '':
            return
        if path in self.pseudo_dirs:
            if not self.ls(path):
                self.pseudo_dirs.remove(path)
            else:
                raise OSError(ENOTEMPTY, 'Directory not empty', path)
        else:
            raise FileNotFoundError(path)

    def info(self, path, **kwargs):
        logger.debug('info: %s', path)
        path = self._strip_protocol(path)
        if path in self.pseudo_dirs or any((p.startswith(path + '/') for p in list(self.store) + self.pseudo_dirs)):
            return {'name': path, 'size': 0, 'type': 'directory'}
        elif path in self.store:
            filelike = self.store[path]
            return {'name': path, 'size': filelike.size, 'type': 'file', 'created': getattr(filelike, 'created', None)}
        else:
            raise FileNotFoundError(path)

    def _open(self, path, mode='rb', block_size=None, autocommit=True, cache_options=None, **kwargs):
        path = self._strip_protocol(path)
        if 'x' in mode and self.exists(path):
            raise FileExistsError
        if path in self.pseudo_dirs:
            raise IsADirectoryError(path)
        parent = path
        while len(parent) > 1:
            parent = self._parent(parent)
            if self.isfile(parent):
                raise FileExistsError(parent)
        if mode in ['rb', 'ab', 'r+b', 'a+b']:
            if path in self.store:
                f = self.store[path]
                if 'a' in mode:
                    f.seek(0, 2)
                else:
                    f.seek(0)
                return f
            else:
                raise FileNotFoundError(path)
        elif mode in {'wb', 'w+b', 'xb', 'x+b'}:
            if 'x' in mode and self.exists(path):
                raise FileExistsError
            m = MemoryFile(self, path, kwargs.get('data'))
            if not self._intrans:
                m.commit()
            return m
        else:
            name = self.__class__.__name__
            raise ValueError(f'unsupported file mode for {name}: {mode!r}')

    def cp_file(self, path1, path2, **kwargs):
        path1 = self._strip_protocol(path1)
        path2 = self._strip_protocol(path2)
        if self.isfile(path1):
            self.store[path2] = MemoryFile(self, path2, self.store[path1].getvalue())
        elif self.isdir(path1):
            if path2 not in self.pseudo_dirs:
                self.pseudo_dirs.append(path2)
        else:
            raise FileNotFoundError(path1)

    def cat_file(self, path, start=None, end=None, **kwargs):
        logger.debug('cat: %s', path)
        path = self._strip_protocol(path)
        try:
            return bytes(self.store[path].getbuffer()[start:end])
        except KeyError as e:
            raise FileNotFoundError(path) from e

    def _rm(self, path):
        path = self._strip_protocol(path)
        try:
            del self.store[path]
        except KeyError as e:
            raise FileNotFoundError(path) from e

    def modified(self, path):
        path = self._strip_protocol(path)
        try:
            return self.store[path].modified
        except KeyError as e:
            raise FileNotFoundError(path) from e

    def created(self, path):
        path = self._strip_protocol(path)
        try:
            return self.store[path].created
        except KeyError as e:
            raise FileNotFoundError(path) from e

    def isfile(self, path):
        path = self._strip_protocol(path)
        return path in self.store

    def rm(self, path, recursive=False, maxdepth=None):
        if isinstance(path, str):
            path = self._strip_protocol(path)
        else:
            path = [self._strip_protocol(p) for p in path]
        paths = self.expand_path(path, recursive=recursive, maxdepth=maxdepth)
        for p in reversed(paths):
            if self.isfile(p):
                self.rm_file(p)
            elif not self.exists(p):
                continue
            else:
                self.rmdir(p)

class MemoryFile(BytesIO):

    def __init__(self, fs=None, path=None, data=None):
        logger.debug('open file %s', path)
        self.fs = fs
        self.path = path
        self.created = datetime.now(tz=timezone.utc)
        self.modified = datetime.now(tz=timezone.utc)
        if data:
            super().__init__(data)
            self.seek(0)

    @property
    def size(self):
        return self.getbuffer().nbytes

    def __enter__(self):
        return self

    def close(self):
        pass

    def discard(self):
        pass

    def commit(self):
        self.fs.store[self.path] = self
        self.modified = datetime.now(tz=timezone.utc)

import os
from numpy._utils import set_module
_open = open

def _check_mode(mode, encoding, newline):
    if 't' in mode:
        if 'b' in mode:
            raise ValueError(f'Invalid mode: {mode!r}')
    else:
        if encoding is not None:
            raise ValueError("Argument 'encoding' not supported in binary mode")
        if newline is not None:
            raise ValueError("Argument 'newline' not supported in binary mode")

class _FileOpeners:

    def __init__(self):
        self._loaded = False
        self._file_openers = {None: open}

    def _load(self):
        if self._loaded:
            return
        try:
            import bz2
            self._file_openers['.bz2'] = bz2.open
        except ImportError:
            pass
        try:
            import gzip
            self._file_openers['.gz'] = gzip.open
        except ImportError:
            pass
        try:
            import lzma
            self._file_openers['.xz'] = lzma.open
            self._file_openers['.lzma'] = lzma.open
        except (ImportError, AttributeError):
            pass
        self._loaded = True

    def keys(self):
        self._load()
        return list(self._file_openers.keys())

    def __getitem__(self, key):
        self._load()
        return self._file_openers[key]
_file_openers = _FileOpeners()

def open(path, mode='r', destpath=os.curdir, encoding=None, newline=None):
    ds = DataSource(destpath)
    return ds.open(path, mode, encoding=encoding, newline=newline)

@set_module('numpy.lib.npyio')
class DataSource:

    def __init__(self, destpath=os.curdir):
        if destpath:
            self._destpath = os.path.abspath(destpath)
            self._istmpdest = False
        else:
            import tempfile
            self._destpath = tempfile.mkdtemp()
            self._istmpdest = True

    def __del__(self):
        if hasattr(self, '_istmpdest') and self._istmpdest:
            import shutil
            shutil.rmtree(self._destpath)

    def _iszip(self, filename):
        fname, ext = os.path.splitext(filename)
        return ext in _file_openers.keys()

    def _iswritemode(self, mode):
        _writemodes = ('w', '+')
        return any((c in _writemodes for c in mode))

    def _splitzipext(self, filename):
        if self._iszip(filename):
            return os.path.splitext(filename)
        else:
            return (filename, None)

    def _possible_names(self, filename):
        names = [filename]
        if not self._iszip(filename):
            for zipext in _file_openers.keys():
                if zipext:
                    names.append(filename + zipext)
        return names

    def _isurl(self, path):
        from urllib.parse import urlparse
        scheme, netloc, upath, uparams, uquery, ufrag = urlparse(path)
        return bool(scheme and netloc)

    def _cache(self, path):
        import shutil
        from urllib.request import urlopen
        upath = self.abspath(path)
        if not os.path.exists(os.path.dirname(upath)):
            os.makedirs(os.path.dirname(upath))
        if self._isurl(path):
            with urlopen(path) as openedurl:
                with _open(upath, 'wb') as f:
                    shutil.copyfileobj(openedurl, f)
        else:
            shutil.copyfile(path, upath)
        return upath

    def _findfile(self, path):
        if not self._isurl(path):
            filelist = self._possible_names(path)
            filelist += self._possible_names(self.abspath(path))
        else:
            filelist = self._possible_names(self.abspath(path))
            filelist = filelist + self._possible_names(path)
        for name in filelist:
            if self.exists(name):
                if self._isurl(name):
                    name = self._cache(name)
                return name
        return None

    def abspath(self, path):
        from urllib.parse import urlparse
        splitpath = path.split(self._destpath, 2)
        if len(splitpath) > 1:
            path = splitpath[1]
        scheme, netloc, upath, uparams, uquery, ufrag = urlparse(path)
        netloc = self._sanitize_relative_path(netloc)
        upath = self._sanitize_relative_path(upath)
        return os.path.join(self._destpath, netloc, upath)

    def _sanitize_relative_path(self, path):
        last = None
        path = os.path.normpath(path)
        while path != last:
            last = path
            path = path.lstrip(os.sep).lstrip('/')
            path = path.lstrip(os.pardir).removeprefix('..')
            drive, path = os.path.splitdrive(path)
        return path

    def exists(self, path):
        if os.path.exists(path):
            return True
        from urllib.error import URLError
        from urllib.request import urlopen
        upath = self.abspath(path)
        if os.path.exists(upath):
            return True
        if self._isurl(path):
            try:
                netfile = urlopen(path)
                netfile.close()
                del netfile
                return True
            except URLError:
                return False
        return False

    def open(self, path, mode='r', encoding=None, newline=None):
        if self._isurl(path) and self._iswritemode(mode):
            raise ValueError('URLs are not writeable')
        found = self._findfile(path)
        if found:
            _fname, ext = self._splitzipext(found)
            if ext == 'bz2':
                mode.replace('+', '')
            return _file_openers[ext](found, mode=mode, encoding=encoding, newline=newline)
        else:
            raise FileNotFoundError(f'{path} not found.')

class Repository(DataSource):

    def __init__(self, baseurl, destpath=os.curdir):
        DataSource.__init__(self, destpath=destpath)
        self._baseurl = baseurl

    def __del__(self):
        DataSource.__del__(self)

    def _fullpath(self, path):
        splitpath = path.split(self._baseurl, 2)
        if len(splitpath) == 1:
            result = os.path.join(self._baseurl, path)
        else:
            result = path
        return result

    def _findfile(self, path):
        return DataSource._findfile(self, self._fullpath(path))

    def abspath(self, path):
        return DataSource.abspath(self, self._fullpath(path))

    def exists(self, path):
        return DataSource.exists(self, self._fullpath(path))

    def open(self, path, mode='r', encoding=None, newline=None):
        return DataSource.open(self, self._fullpath(path), mode, encoding=encoding, newline=newline)

    def listdir(self):
        if self._isurl(self._baseurl):
            raise NotImplementedError('Directory listing of URLs, not supported yet.')
        else:
            return os.listdir(self._baseurl)

