from datasets.utils.json import find_mixed_struct_types_field_paths, get_json_field_path_from_pyarrow_json_error, get_json_field_paths_from_feature, insert_json_field_path, json_encode_field, json_encode_fields_in_json_lines, set_json_types_in_feature, ujson_dumps, ujson_loads
logger = datasets.utils.logging.get_logger(__name__)

def pandas_read_json(path_or_buf, **kwargs):
    if datasets.config.PANDAS_VERSION.major >= 2:
        kwargs['dtype_backend'] = 'pyarrow'
    return pd.read_json(path_or_buf, **kwargs)

class FullReadDisallowed(Exception):
    pass

@dataclass
class JsonConfig(datasets.BuilderConfig):
    features: Optional[datasets.Features] = None
    encoding: str = 'utf-8'
    encoding_errors: Optional[str] = None
    field: Optional[str] = None
    use_threads: bool = True
    block_size: Optional[int] = None
    chunksize: int = 10 << 20
    newlines_in_values: Optional[bool] = None
    on_mixed_types: Optional[Literal['use_json']] = 'use_json'

    def __post_init__(self):
        super().__post_init__()

class Json(datasets.ArrowBasedBuilder):
    BUILDER_CONFIG_CLASS = JsonConfig

    def _info(self):
        if self.config.block_size is not None:
            logger.warning('The JSON loader parameter `block_size` is deprecated. Please use `chunksize` instead')
            self.config.chunksize = self.config.block_size
        if self.config.use_threads is not True:
            logger.warning("The JSON loader parameter `use_threads` is deprecated and doesn't have any effect anymore.")
        if self.config.newlines_in_values is not None:
            raise ValueError('The JSON loader parameter `newlines_in_values` is no longer supported')
        return datasets.DatasetInfo(features=self.config.features)

    def _split_generators(self, dl_manager):
        if not self.config.data_files:
            raise ValueError(f'At least one data file must be specified, but got data_files={self.config.data_files}')
        dl_manager.download_config.extract_on_the_fly = True
        base_data_files = dl_manager.download(self.config.data_files)
        extracted_data_files = dl_manager.extract(base_data_files)
        splits = []
        for split_name, extracted_files in extracted_data_files.items():
            files_iterables = [dl_manager.iter_files(extracted_file) for extracted_file in extracted_files]
            splits.append(datasets.SplitGenerator(name=split_name, gen_kwargs={'files_iterables': files_iterables, 'base_files': base_data_files[split_name]}))
        if self.info.features is None:
            try:
                pa_table = next(iter(self._generate_tables(**splits[0].gen_kwargs, allow_full_read=False)))[1]
                self.info.features = datasets.Features.from_arrow_schema(pa_table.schema)
            except FullReadDisallowed:
                pass
        return splits

    def _cast_table(self, pa_table: pa.Table, json_field_paths=()) -> pa.Table:
        if self.info.features is not None:
            for column_name in set(self.info.features) - set(pa_table.column_names):
                type = self.info.features.arrow_schema.field(column_name).type
                pa_table = pa_table.append_column(column_name, pa.array([None] * len(pa_table), type=type))
            for i, column_name in enumerate(pa_table.column_names):
                if pa.types.is_struct(pa_table[column_name].type) and self.info.features.get(column_name, None) == datasets.Value('string'):
                    jsonl = pa_table[column_name].to_pandas(types_mapper=pd.ArrowDtype).to_json(orient='records', lines=True)
                    string_array = pa.array((None if x.strip() == 'null' else x.strip() for x in jsonl.split('\n') if x.strip()), type=pa.string())
                    pa_table = pa_table.set_column(i, column_name, string_array)
            pa_table = table_cast(pa_table, self.info.features.arrow_schema)
        elif json_field_paths:
            features = datasets.Features.from_arrow_schema(pa_table.schema)
            features = set_json_types_in_feature(features, json_field_paths)
            pa_table = table_cast(pa_table, features.arrow_schema)
        return pa_table

    def _generate_shards(self, base_files, files_iterables):
        yield from base_files

    def _generate_tables(self, base_files, files_iterables, allow_full_read=True):
        json_field_paths = []
        if self.info.features is not None:
            json_field_paths = get_json_field_paths_from_feature(self.info.features)
        for shard_idx, files_iterable in enumerate(files_iterables):
            for file in files_iterable:
                if self.config.field is not None:
                    if not allow_full_read:
                        raise FullReadDisallowed()
                    with open(file, encoding=self.config.encoding, errors=self.config.encoding_errors) as f:
                        dataset = ujson_loads(f.read())
                    dataset = dataset[self.config.field]
                    df = pandas_read_json(io.StringIO(ujson_dumps(dataset)))
                    if df.columns.tolist() == [0]:
                        df.columns = list(self.config.features) if self.config.features else ['text']
                    pa_table = pa.Table.from_pandas(df, preserve_index=False)
                    yield (Key(shard_idx, 0), self._cast_table(pa_table))
                else:
                    with open(file, 'rb') as f:
                        batch_idx = 0
                        block_size = max(self.config.chunksize // 32, 16 << 10)
                        encoding_errors = self.config.encoding_errors if self.config.encoding_errors is not None else 'strict'
                        while True:
                            batch = f.read(self.config.chunksize)
                            if not batch:
                                break
                            if batch.startswith(b'['):
                                if not allow_full_read:
                                    raise FullReadDisallowed()
                                else:
                                    full_data = batch + f.read()
                                    if b'{' in batch[:100].split(b'"', 1)[0]:
                                        batch = '\n'.join((ujson_dumps(x) for x in ujson_loads(full_data))).encode()
                                    else:
                                        batch = '\n'.join((ujson_dumps({'text': x}) for x in ujson_loads(full_data))).encode()
                            try:
                                batch += f.readline()
                            except (AttributeError, io.UnsupportedOperation):
                                batch += readline(f)
                            if self.config.encoding != 'utf-8':
                                batch = batch.decode(self.config.encoding, errors=encoding_errors).encode('utf-8')
                            if shard_idx == 0 and batch_idx == 0 and (self.info.features is None) and (self.config.on_mixed_types == 'use_json'):
                                try:
                                    examples = [ujson_loads(line) for line in batch.splitlines()]
                                except ValueError:
                                    pass
                                else:
                                    json_field_paths += find_mixed_struct_types_field_paths(examples)
                            original_batch = batch
                            if json_field_paths:
                                examples = [ujson_loads(line) for line in batch.splitlines()]
                                for json_field_path in json_field_paths:
                                    examples = [json_encode_field(examples, json_field_path) for examples in examples]
                                batch = '\n'.join((ujson_dumps(example) for example in examples)).encode()
                            block_size = len(batch) if len(batch) // 8 > block_size else block_size
                            try:
                                while True:
                                    try:
                                        pa_table = paj.read_json(io.BytesIO(batch), read_options=paj.ReadOptions(block_size=block_size))
                                        break
                                    except (pa.ArrowInvalid, pa.ArrowNotImplementedError) as e:
                                        if batch.startswith(b'['):
                                            raise
                                        elif self.config.on_mixed_types == 'use_json' and (isinstance(e, pa.ArrowInvalid) and 'JSON parse error: Column(' in str(e) and (') changed from' in str(e))):
                                            json_field_path = get_json_field_path_from_pyarrow_json_error(str(e))
                                            insert_json_field_path(json_field_paths, json_field_path)
                                            batch = json_encode_fields_in_json_lines(original_batch, json_field_paths)
                                        elif ('straddling' in str(e) or 'JSON conversion to' in str(e)) and block_size < len(batch):
                                            logger.debug(f"Batch of {len(batch)} bytes couldn't be parsed with block_size={block_size}. Retrying with block_size={block_size * 2}.")
                                            block_size *= 2
                                        else:
                                            raise
                            except pa.ArrowInvalid as e:
                                if not allow_full_read:
                                    raise FullReadDisallowed()
                                try:
                                    with open(file, encoding=self.config.encoding, errors=self.config.encoding_errors) as f:
                                        df = pandas_read_json(f)
                                except ValueError:
                                    logger.error(f"Failed to load JSON from file '{file}' with error {type(e)}: {e}")
                                    raise e
                                if df.columns.tolist() == [0]:
                                    df.columns = list(self.config.features) if self.config.features else ['text']
                                try:
                                    pa_table = pa.Table.from_pandas(df, preserve_index=False)
                                except pa.ArrowInvalid as e:
                                    logger.error(f"Failed to convert pandas DataFrame to Arrow Table from file '{file}' with error {type(e)}: {e}")
                                    raise ValueError(f'Failed to convert pandas DataFrame to Arrow Table from file {file}.') from None
                                yield (Key(shard_idx, 0), self._cast_table(pa_table))
                                break
                            yield (Key(shard_idx, batch_idx), self._cast_table(pa_table, json_field_paths=json_field_paths))
                            batch_idx += 1

from __future__ import annotations
import functools
import logging
import typing
import warnings
from types import TracebackType
from urllib.parse import urljoin
from ._collections import HTTPHeaderDict, RecentlyUsedContainer
from ._request_methods import RequestMethods
from .connection import ProxyConfig
from .connectionpool import HTTPConnectionPool, HTTPSConnectionPool, port_by_scheme
from .exceptions import LocationValueError, MaxRetryError, ProxySchemeUnknown, URLSchemeUnknown
from .response import BaseHTTPResponse
from .util.connection import _TYPE_SOCKET_OPTIONS
from .util.proxy import connection_requires_http_tunnel
from .util.retry import Retry
from .util.timeout import Timeout
from .util.url import Url, parse_url
if typing.TYPE_CHECKING:
    import ssl
    from typing_extensions import Self
__all__ = ['PoolManager', 'ProxyManager', 'proxy_from_url']
log = logging.getLogger(__name__)
SSL_KEYWORDS = ('key_file', 'cert_file', 'cert_reqs', 'ca_certs', 'ca_cert_data', 'ssl_version', 'ssl_minimum_version', 'ssl_maximum_version', 'ca_cert_dir', 'ssl_context', 'key_password', 'server_hostname')
_DEFAULT_BLOCKSIZE = 16384

class PoolKey(typing.NamedTuple):
    key_scheme: str
    key_host: str
    key_port: int | None
    key_timeout: Timeout | float | int | None
    key_retries: Retry | bool | int | None
    key_block: bool | None
    key_source_address: tuple[str, int] | None
    key_key_file: str | None
    key_key_password: str | None
    key_cert_file: str | None
    key_cert_reqs: str | None
    key_ca_certs: str | None
    key_ca_cert_data: str | bytes | None
    key_ssl_version: int | str | None
    key_ssl_minimum_version: ssl.TLSVersion | None
    key_ssl_maximum_version: ssl.TLSVersion | None
    key_ca_cert_dir: str | None
    key_ssl_context: ssl.SSLContext | None
    key_maxsize: int | None
    key_headers: frozenset[tuple[str, str]] | None
    key__proxy: Url | None
    key__proxy_headers: frozenset[tuple[str, str]] | None
    key__proxy_config: ProxyConfig | None
    key_socket_options: _TYPE_SOCKET_OPTIONS | None
    key__socks_options: frozenset[tuple[str, str]] | None
    key_assert_hostname: bool | str | None
    key_assert_fingerprint: str | None
    key_server_hostname: str | None
    key_blocksize: int | None

def _default_key_normalizer(key_class: type[PoolKey], request_context: dict[str, typing.Any]) -> PoolKey:
    context = request_context.copy()
    context['scheme'] = context['scheme'].lower()
    context['host'] = context['host'].lower()
    for key in ('headers', '_proxy_headers', '_socks_options'):
        if key in context and context[key] is not None:
            context[key] = frozenset(context[key].items())
    socket_opts = context.get('socket_options')
    if socket_opts is not None:
        context['socket_options'] = tuple(socket_opts)
    for key in list(context.keys()):
        context['key_' + key] = context.pop(key)
    for field in key_class._fields:
        if field not in context:
            context[field] = None
    if context.get('key_blocksize') is None:
        context['key_blocksize'] = _DEFAULT_BLOCKSIZE
    return key_class(**context)
key_fn_by_scheme = {'http': functools.partial(_default_key_normalizer, PoolKey), 'https': functools.partial(_default_key_normalizer, PoolKey)}
pool_classes_by_scheme = {'http': HTTPConnectionPool, 'https': HTTPSConnectionPool}

class PoolManager(RequestMethods):
    proxy: Url | None = None
    proxy_config: ProxyConfig | None = None

    def __init__(self, num_pools: int=10, headers: typing.Mapping[str, str] | None=None, **connection_pool_kw: typing.Any) -> None:
        super().__init__(headers)
        if 'retries' in connection_pool_kw:
            retries = connection_pool_kw['retries']
            if not isinstance(retries, Retry):
                retries = Retry.from_int(retries)
                connection_pool_kw = connection_pool_kw.copy()
                connection_pool_kw['retries'] = retries
        self.connection_pool_kw = connection_pool_kw
        self.pools: RecentlyUsedContainer[PoolKey, HTTPConnectionPool]
        self.pools = RecentlyUsedContainer(num_pools)
        self.pool_classes_by_scheme = pool_classes_by_scheme
        self.key_fn_by_scheme = key_fn_by_scheme.copy()

    def __enter__(self) -> Self:
        return self

    def __exit__(self, exc_type: type[BaseException] | None, exc_val: BaseException | None, exc_tb: TracebackType | None) -> typing.Literal[False]:
        self.clear()
        return False

    def _new_pool(self, scheme: str, host: str, port: int, request_context: dict[str, typing.Any] | None=None) -> HTTPConnectionPool:
        pool_cls: type[HTTPConnectionPool] = self.pool_classes_by_scheme[scheme]
        if request_context is None:
            request_context = self.connection_pool_kw.copy()
        if request_context.get('blocksize') is None:
            request_context['blocksize'] = _DEFAULT_BLOCKSIZE
        for key in ('scheme', 'host', 'port'):
            request_context.pop(key, None)
        if scheme == 'http':
            for kw in SSL_KEYWORDS:
                request_context.pop(kw, None)
        return pool_cls(host, port, **request_context)

    def clear(self) -> None:
        self.pools.clear()

    def connection_from_host(self, host: str | None, port: int | None=None, scheme: str | None='http', pool_kwargs: dict[str, typing.Any] | None=None) -> HTTPConnectionPool:
        if not host:
            raise LocationValueError('No host specified.')
        request_context = self._merge_pool_kwargs(pool_kwargs)
        request_context['scheme'] = scheme or 'http'
        if not port:
            port = port_by_scheme.get(request_context['scheme'].lower(), 80)
        request_context['port'] = port
        request_context['host'] = host
        return self.connection_from_context(request_context)

    def connection_from_context(self, request_context: dict[str, typing.Any]) -> HTTPConnectionPool:
        if 'strict' in request_context:
            warnings.warn("The 'strict' parameter is no longer needed on Python 3+. This will raise an error in urllib3 v2.1.0.", DeprecationWarning)
            request_context.pop('strict')
        scheme = request_context['scheme'].lower()
        pool_key_constructor = self.key_fn_by_scheme.get(scheme)
        if not pool_key_constructor:
            raise URLSchemeUnknown(scheme)
        pool_key = pool_key_constructor(request_context)
        return self.connection_from_pool_key(pool_key, request_context=request_context)

    def connection_from_pool_key(self, pool_key: PoolKey, request_context: dict[str, typing.Any]) -> HTTPConnectionPool:
        with self.pools.lock:
            pool = self.pools.get(pool_key)
            if pool:
                return pool
            scheme = request_context['scheme']
            host = request_context['host']
            port = request_context['port']
            pool = self._new_pool(scheme, host, port, request_context=request_context)
            self.pools[pool_key] = pool
        return pool

    def connection_from_url(self, url: str, pool_kwargs: dict[str, typing.Any] | None=None) -> HTTPConnectionPool:
        u = parse_url(url)
        return self.connection_from_host(u.host, port=u.port, scheme=u.scheme, pool_kwargs=pool_kwargs)

    def _merge_pool_kwargs(self, override: dict[str, typing.Any] | None) -> dict[str, typing.Any]:
        base_pool_kwargs = self.connection_pool_kw.copy()
        if override:
            for key, value in override.items():
                if value is None:
                    try:
                        del base_pool_kwargs[key]
                    except KeyError:
                        pass
                else:
                    base_pool_kwargs[key] = value
        return base_pool_kwargs

    def _proxy_requires_url_absolute_form(self, parsed_url: Url) -> bool:
        if self.proxy is None:
            return False
        return not connection_requires_http_tunnel(self.proxy, self.proxy_config, parsed_url.scheme)

    def urlopen(self, method: str, url: str, redirect: bool=True, **kw: typing.Any) -> BaseHTTPResponse:
        u = parse_url(url)
        if u.scheme is None:
            warnings.warn("URLs without a scheme (ie 'https://') are deprecated and will raise an error in a future version of urllib3. To avoid this DeprecationWarning ensure all URLs start with 'https://' or 'http://'. Read more in this issue: https://github.com/urllib3/urllib3/issues/2920", category=DeprecationWarning, stacklevel=2)
        conn = self.connection_from_host(u.host, port=u.port, scheme=u.scheme)
        kw['assert_same_host'] = False
        kw['redirect'] = False
        if 'headers' not in kw:
            kw['headers'] = self.headers
        if self._proxy_requires_url_absolute_form(u):
            response = conn.urlopen(method, url, **kw)
        else:
            response = conn.urlopen(method, u.request_uri, **kw)
        redirect_location = redirect and response.get_redirect_location()
        if not redirect_location:
            return response
        redirect_location = urljoin(url, redirect_location)
        if response.status == 303:
            method = 'GET'
            kw['body'] = None
            kw['headers'] = HTTPHeaderDict(kw['headers'])._prepare_for_method_change()
        retries = kw.get('retries', response.retries)
        if not isinstance(retries, Retry):
            retries = Retry.from_int(retries, redirect=redirect)
        if retries.remove_headers_on_redirect and (not conn.is_same_host(redirect_location)):
            new_headers = kw['headers'].copy()
            for header in kw['headers']:
                if header.lower() in retries.remove_headers_on_redirect:
                    new_headers.pop(header, None)
            kw['headers'] = new_headers
        try:
            retries = retries.increment(method, url, response=response, _pool=conn)
        except MaxRetryError:
            if retries.raise_on_redirect:
                response.drain_conn()
                raise
            return response
        kw['retries'] = retries
        kw['redirect'] = redirect
        log.info('Redirecting %s -> %s', url, redirect_location)
        response.drain_conn()
        return self.urlopen(method, redirect_location, **kw)

class ProxyManager(PoolManager):

    def __init__(self, proxy_url: str, num_pools: int=10, headers: typing.Mapping[str, str] | None=None, proxy_headers: typing.Mapping[str, str] | None=None, proxy_ssl_context: ssl.SSLContext | None=None, use_forwarding_for_https: bool=False, proxy_assert_hostname: None | str | typing.Literal[False]=None, proxy_assert_fingerprint: str | None=None, **connection_pool_kw: typing.Any) -> None:
        if isinstance(proxy_url, HTTPConnectionPool):
            str_proxy_url = f'{proxy_url.scheme}://{proxy_url.host}:{proxy_url.port}'
        else:
            str_proxy_url = proxy_url
        proxy = parse_url(str_proxy_url)
        if proxy.scheme not in ('http', 'https'):
            raise ProxySchemeUnknown(proxy.scheme)
        if not proxy.port:
            port = port_by_scheme.get(proxy.scheme, 80)
            proxy = proxy._replace(port=port)
        self.proxy = proxy
        self.proxy_headers = proxy_headers or {}
        self.proxy_ssl_context = proxy_ssl_context
        self.proxy_config = ProxyConfig(proxy_ssl_context, use_forwarding_for_https, proxy_assert_hostname, proxy_assert_fingerprint)
        connection_pool_kw['_proxy'] = self.proxy
        connection_pool_kw['_proxy_headers'] = self.proxy_headers
        connection_pool_kw['_proxy_config'] = self.proxy_config
        super().__init__(num_pools, headers, **connection_pool_kw)

    def connection_from_host(self, host: str | None, port: int | None=None, scheme: str | None='http', pool_kwargs: dict[str, typing.Any] | None=None) -> HTTPConnectionPool:
        if scheme == 'https':
            return super().connection_from_host(host, port, scheme, pool_kwargs=pool_kwargs)
        return super().connection_from_host(self.proxy.host, self.proxy.port, self.proxy.scheme, pool_kwargs=pool_kwargs)

    def _set_proxy_headers(self, url: str, headers: typing.Mapping[str, str] | None=None) -> typing.Mapping[str, str]:
        headers_ = {'Accept': '*/*'}
        netloc = parse_url(url).netloc
        if netloc:
            headers_['Host'] = netloc
        if headers:
            headers_.update(headers)
        return headers_

    def urlopen(self, method: str, url: str, redirect: bool=True, **kw: typing.Any) -> BaseHTTPResponse:
        u = parse_url(url)
        if not connection_requires_http_tunnel(self.proxy, self.proxy_config, u.scheme):
            headers = kw.get('headers', self.headers)
            kw['headers'] = self._set_proxy_headers(url, headers)
        return super().urlopen(method, url, redirect=redirect, **kw)

def proxy_from_url(url: str, **kw: typing.Any) -> ProxyManager:
    return ProxyManager(proxy_url=url, **kw)

from __future__ import annotations
import enum
import logging
import ssl
import time
import types
import typing
import h11
from .._backends.base import NetworkStream
from .._exceptions import ConnectionNotAvailable, LocalProtocolError, RemoteProtocolError, WriteError, map_exceptions
from .._models import Origin, Request, Response
from .._synchronization import Lock, ShieldCancellation
from .._trace import Trace
from .interfaces import ConnectionInterface
logger = logging.getLogger('httpcore.http11')
H11SendEvent = typing.Union[h11.Request, h11.Data, h11.EndOfMessage]

class HTTPConnectionState(enum.IntEnum):
    NEW = 0
    ACTIVE = 1
    IDLE = 2
    CLOSED = 3

class HTTP11Connection(ConnectionInterface):
    READ_NUM_BYTES = 64 * 1024
    MAX_INCOMPLETE_EVENT_SIZE = 100 * 1024

    def __init__(self, origin: Origin, stream: NetworkStream, keepalive_expiry: float | None=None) -> None:
        self._origin = origin
        self._network_stream = stream
        self._keepalive_expiry: float | None = keepalive_expiry
        self._expire_at: float | None = None
        self._state = HTTPConnectionState.NEW
        self._state_lock = Lock()
        self._request_count = 0
        self._h11_state = h11.Connection(our_role=h11.CLIENT, max_incomplete_event_size=self.MAX_INCOMPLETE_EVENT_SIZE)

    def handle_request(self, request: Request) -> Response:
        if not self.can_handle_request(request.url.origin):
            raise RuntimeError(f'Attempted to send request to {request.url.origin} on connection to {self._origin}')
        with self._state_lock:
            if self._state in (HTTPConnectionState.NEW, HTTPConnectionState.IDLE):
                self._request_count += 1
                self._state = HTTPConnectionState.ACTIVE
                self._expire_at = None
            else:
                raise ConnectionNotAvailable()
        try:
            kwargs = {'request': request}
            try:
                with Trace('send_request_headers', logger, request, kwargs) as trace:
                    self._send_request_headers(**kwargs)
                with Trace('send_request_body', logger, request, kwargs) as trace:
                    self._send_request_body(**kwargs)
            except WriteError:
                pass
            with Trace('receive_response_headers', logger, request, kwargs) as trace:
                http_version, status, reason_phrase, headers, trailing_data = self._receive_response_headers(**kwargs)
                trace.return_value = (http_version, status, reason_phrase, headers)
            network_stream = self._network_stream
            if status == 101 or (request.method == b'CONNECT' and 200 <= status < 300):
                network_stream = HTTP11UpgradeStream(network_stream, trailing_data)
            return Response(status=status, headers=headers, content=HTTP11ConnectionByteStream(self, request), extensions={'http_version': http_version, 'reason_phrase': reason_phrase, 'network_stream': network_stream})
        except BaseException as exc:
            with ShieldCancellation():
                with Trace('response_closed', logger, request) as trace:
                    self._response_closed()
            raise exc

    def _send_request_headers(self, request: Request) -> None:
        timeouts = request.extensions.get('timeout', {})
        timeout = timeouts.get('write', None)
        with map_exceptions({h11.LocalProtocolError: LocalProtocolError}):
            event = h11.Request(method=request.method, target=request.url.target, headers=request.headers)
        self._send_event(event, timeout=timeout)

    def _send_request_body(self, request: Request) -> None:
        timeouts = request.extensions.get('timeout', {})
        timeout = timeouts.get('write', None)
        assert isinstance(request.stream, typing.Iterable)
        for chunk in request.stream:
            event = h11.Data(data=chunk)
            self._send_event(event, timeout=timeout)
        self._send_event(h11.EndOfMessage(), timeout=timeout)

    def _send_event(self, event: h11.Event, timeout: float | None=None) -> None:
        bytes_to_send = self._h11_state.send(event)
        if bytes_to_send is not None:
            self._network_stream.write(bytes_to_send, timeout=timeout)

    def _receive_response_headers(self, request: Request) -> tuple[bytes, int, bytes, list[tuple[bytes, bytes]], bytes]:
        timeouts = request.extensions.get('timeout', {})
        timeout = timeouts.get('read', None)
        while True:
            event = self._receive_event(timeout=timeout)
            if isinstance(event, h11.Response):
                break
            if isinstance(event, h11.InformationalResponse) and event.status_code == 101:
                break
        http_version = b'HTTP/' + event.http_version
        headers = event.headers.raw_items()
        trailing_data, _ = self._h11_state.trailing_data
        return (http_version, event.status_code, event.reason, headers, trailing_data)

    def _receive_response_body(self, request: Request) -> typing.Iterator[bytes]:
        timeouts = request.extensions.get('timeout', {})
        timeout = timeouts.get('read', None)
        while True:
            event = self._receive_event(timeout=timeout)
            if isinstance(event, h11.Data):
                yield bytes(event.data)
            elif isinstance(event, (h11.EndOfMessage, h11.PAUSED)):
                break

    def _receive_event(self, timeout: float | None=None) -> h11.Event | type[h11.PAUSED]:
        while True:
            with map_exceptions({h11.RemoteProtocolError: RemoteProtocolError}):
                event = self._h11_state.next_event()
            if event is h11.NEED_DATA:
                data = self._network_stream.read(self.READ_NUM_BYTES, timeout=timeout)
                if data == b'' and self._h11_state.their_state == h11.SEND_RESPONSE:
                    msg = 'Server disconnected without sending a response.'
                    raise RemoteProtocolError(msg)
                self._h11_state.receive_data(data)
            else:
                return event

    def _response_closed(self) -> None:
        with self._state_lock:
            if self._h11_state.our_state is h11.DONE and self._h11_state.their_state is h11.DONE:
                self._state = HTTPConnectionState.IDLE
                self._h11_state.start_next_cycle()
                if self._keepalive_expiry is not None:
                    now = time.monotonic()
                    self._expire_at = now + self._keepalive_expiry
            else:
                self.close()

    def close(self) -> None:
        self._state = HTTPConnectionState.CLOSED
        self._network_stream.close()

    def can_handle_request(self, origin: Origin) -> bool:
        return origin == self._origin

    def is_available(self) -> bool:
        return self._state == HTTPConnectionState.IDLE

    def has_expired(self) -> bool:
        now = time.monotonic()
        keepalive_expired = self._expire_at is not None and now > self._expire_at
        server_disconnected = self._state == HTTPConnectionState.IDLE and self._network_stream.get_extra_info('is_readable')
        return keepalive_expired or server_disconnected

    def is_idle(self) -> bool:
        return self._state == HTTPConnectionState.IDLE

    def is_closed(self) -> bool:
        return self._state == HTTPConnectionState.CLOSED

    def info(self) -> str:
        origin = str(self._origin)
        return f'{origin!r}, HTTP/1.1, {self._state.name}, Request Count: {self._request_count}'

    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        origin = str(self._origin)
        return f'<{class_name} [{origin!r}, {self._state.name}, Request Count: {self._request_count}]>'

    def __enter__(self) -> HTTP11Connection:
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        self.close()

class HTTP11ConnectionByteStream:

    def __init__(self, connection: HTTP11Connection, request: Request) -> None:
        self._connection = connection
        self._request = request
        self._closed = False

    def __iter__(self) -> typing.Iterator[bytes]:
        kwargs = {'request': self._request}
        try:
            with Trace('receive_response_body', logger, self._request, kwargs):
                for chunk in self._connection._receive_response_body(**kwargs):
                    yield chunk
        except BaseException as exc:
            with ShieldCancellation():
                self.close()
            raise exc

    def close(self) -> None:
        if not self._closed:
            self._closed = True
            with Trace('response_closed', logger, self._request):
                self._connection._response_closed()

class HTTP11UpgradeStream(NetworkStream):

    def __init__(self, stream: NetworkStream, leading_data: bytes) -> None:
        self._stream = stream
        self._leading_data = leading_data

    def read(self, max_bytes: int, timeout: float | None=None) -> bytes:
        if self._leading_data:
            buffer = self._leading_data[:max_bytes]
            self._leading_data = self._leading_data[max_bytes:]
            return buffer
        else:
            return self._stream.read(max_bytes, timeout)

    def write(self, buffer: bytes, timeout: float | None=None) -> None:
        self._stream.write(buffer, timeout)

    def close(self) -> None:
        self._stream.close()

    def start_tls(self, ssl_context: ssl.SSLContext, server_hostname: str | None=None, timeout: float | None=None) -> NetworkStream:
        return self._stream.start_tls(ssl_context, server_hostname, timeout)

    def get_extra_info(self, info: str) -> typing.Any:
        return self._stream.get_extra_info(info)

import json
import logging
import mmap
import os
import shutil
import zipfile
from contextlib import contextmanager
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Generator, Iterable, Union
from ..errors import DDUFCorruptedFileError, DDUFExportError, DDUFInvalidEntryNameError
logger = logging.getLogger(__name__)
DDUF_ALLOWED_ENTRIES = {'.json', '.model', '.safetensors', '.txt'}
DDUF_FOLDER_REQUIRED_ENTRIES = {'config.json', 'tokenizer_config.json', 'preprocessor_config.json', 'scheduler_config.json'}

@dataclass
class DDUFEntry:
    filename: str
    length: int
    offset: int
    dduf_path: Path = field(repr=False)

    @contextmanager
    def as_mmap(self) -> Generator[bytes, None, None]:
        with self.dduf_path.open('rb') as f:
            with mmap.mmap(f.fileno(), length=0, access=mmap.ACCESS_READ) as mm:
                yield mm[self.offset:self.offset + self.length]

    def read_text(self, encoding: str='utf-8') -> str:
        with self.dduf_path.open('rb') as f:
            f.seek(self.offset)
            return f.read(self.length).decode(encoding=encoding)

def read_dduf_file(dduf_path: Union[os.PathLike, str]) -> dict[str, DDUFEntry]:
    entries = {}
    dduf_path = Path(dduf_path)
    logger.info(f'Reading DDUF file {dduf_path}')
    with zipfile.ZipFile(str(dduf_path), 'r') as zf:
        for info in zf.infolist():
            logger.debug(f'Reading entry {info.filename}')
            if info.compress_type != zipfile.ZIP_STORED:
                raise DDUFCorruptedFileError('Data must not be compressed in DDUF file.')
            try:
                _validate_dduf_entry_name(info.filename)
            except DDUFInvalidEntryNameError as e:
                raise DDUFCorruptedFileError(f'Invalid entry name in DDUF file: {info.filename}') from e
            offset = _get_data_offset(zf, info)
            entries[info.filename] = DDUFEntry(filename=info.filename, offset=offset, length=info.file_size, dduf_path=dduf_path)
    if 'model_index.json' not in entries:
        raise DDUFCorruptedFileError("Missing required 'model_index.json' entry in DDUF file.")
    index = json.loads(entries['model_index.json'].read_text())
    _validate_dduf_structure(index, entries.keys())
    logger.info(f'Done reading DDUF file {dduf_path}. Found {len(entries)} entries')
    return entries

def export_entries_as_dduf(dduf_path: Union[str, os.PathLike], entries: Iterable[tuple[str, Union[str, Path, bytes]]]) -> None:
    logger.info(f"Exporting DDUF file '{dduf_path}'")
    filenames = set()
    index = None
    with zipfile.ZipFile(str(dduf_path), 'w', zipfile.ZIP_STORED) as archive:
        for filename, content in entries:
            if filename in filenames:
                raise DDUFExportError(f"Can't add duplicate entry: {filename}")
            filenames.add(filename)
            if filename == 'model_index.json':
                try:
                    index = json.loads(_load_content(content).decode())
                except json.JSONDecodeError as e:
                    raise DDUFExportError("Failed to parse 'model_index.json'.") from e
            try:
                filename = _validate_dduf_entry_name(filename)
            except DDUFInvalidEntryNameError as e:
                raise DDUFExportError(f'Invalid entry name: {filename}') from e
            logger.debug(f"Adding entry '{filename}' to DDUF file")
            _dump_content_in_archive(archive, filename, content)
    if index is None:
        raise DDUFExportError("Missing required 'model_index.json' entry in DDUF file.")
    try:
        _validate_dduf_structure(index, filenames)
    except DDUFCorruptedFileError as e:
        raise DDUFExportError('Invalid DDUF file structure.') from e
    logger.info(f'Done writing DDUF file {dduf_path}')

def export_folder_as_dduf(dduf_path: Union[str, os.PathLike], folder_path: Union[str, os.PathLike]) -> None:
    folder_path = Path(folder_path)

    def _iterate_over_folder() -> Iterable[tuple[str, Path]]:
        for path in Path(folder_path).glob('**/*'):
            if not path.is_file():
                continue
            if path.suffix not in DDUF_ALLOWED_ENTRIES:
                logger.debug(f"Skipping file '{path}' (file type not allowed)")
                continue
            path_in_archive = path.relative_to(folder_path)
            if len(path_in_archive.parts) >= 3:
                logger.debug(f"Skipping file '{path}' (nested directories not allowed)")
                continue
            yield (path_in_archive.as_posix(), path)
    export_entries_as_dduf(dduf_path, _iterate_over_folder())

def _dump_content_in_archive(archive: zipfile.ZipFile, filename: str, content: Union[str, os.PathLike, bytes]) -> None:
    with archive.open(filename, 'w', force_zip64=True) as archive_fh:
        if isinstance(content, (str, Path)):
            content_path = Path(content)
            with content_path.open('rb') as content_fh:
                shutil.copyfileobj(content_fh, archive_fh, 1024 * 1024 * 8)
        elif isinstance(content, bytes):
            archive_fh.write(content)
        else:
            raise DDUFExportError(f'Invalid content type for {filename}. Must be str, Path or bytes.')

def _load_content(content: Union[str, Path, bytes]) -> bytes:
    if isinstance(content, (str, Path)):
        return Path(content).read_bytes()
    elif isinstance(content, bytes):
        return content
    else:
        raise DDUFExportError(f'Invalid content type. Must be str, Path or bytes. Got {type(content)}.')

def _validate_dduf_entry_name(entry_name: str) -> str:
    if '.' + entry_name.split('.')[-1] not in DDUF_ALLOWED_ENTRIES:
        raise DDUFInvalidEntryNameError(f'File type not allowed: {entry_name}')
    if '\\' in entry_name:
        raise DDUFInvalidEntryNameError(f"Entry names must use UNIX separators ('/'). Got {entry_name}.")
    entry_name = entry_name.strip('/')
    if entry_name.count('/') > 1:
        raise DDUFInvalidEntryNameError(f'DDUF only supports 1 level of directory. Got {entry_name}.')
    return entry_name

def _validate_dduf_structure(index: Any, entry_names: Iterable[str]) -> None:
    if not isinstance(index, dict):
        raise DDUFCorruptedFileError(f"Invalid 'model_index.json' content. Must be a dictionary. Got {type(index)}.")
    dduf_folders = {entry.split('/')[0] for entry in entry_names if '/' in entry}
    for folder in dduf_folders:
        if folder not in index:
            raise DDUFCorruptedFileError(f"Missing required entry '{folder}' in 'model_index.json'.")
        if not any((f'{folder}/{required_entry}' in entry_names for required_entry in DDUF_FOLDER_REQUIRED_ENTRIES)):
            raise DDUFCorruptedFileError(f"Missing required file in folder '{folder}'. Must contains at least one of {DDUF_FOLDER_REQUIRED_ENTRIES}.")

def _get_data_offset(zf: zipfile.ZipFile, info: zipfile.ZipInfo) -> int:
    if zf.fp is None:
        raise DDUFCorruptedFileError('ZipFile object must be opened in read mode.')
    header_offset = info.header_offset
    zf.fp.seek(header_offset)
    local_file_header = zf.fp.read(30)
    if len(local_file_header) < 30:
        raise DDUFCorruptedFileError('Incomplete local file header.')
    filename_len = int.from_bytes(local_file_header[26:28], 'little')
    extra_field_len = int.from_bytes(local_file_header[28:30], 'little')
    data_offset = header_offset + 30 + filename_len + extra_field_len
    return data_offset

import os
import re
from pathlib import Path
from typing import Any, Literal, Optional, Union
import yaml
from huggingface_hub.file_download import hf_hub_download
from huggingface_hub.hf_api import upload_file
from huggingface_hub.repocard_data import CardData, DatasetCardData, EvalResult, ModelCardData, SpaceCardData, eval_results_to_model_index, model_index_to_eval_results
from huggingface_hub.utils import HfHubHTTPError, get_session, hf_raise_for_status, is_jinja_available, yaml_dump
from . import constants
from .errors import EntryNotFoundError
from .utils import SoftTemporaryDirectory, logging, validate_hf_hub_args
logger = logging.get_logger(__name__)
TEMPLATE_MODELCARD_PATH = Path(__file__).parent / 'templates' / 'modelcard_template.md'
TEMPLATE_DATASETCARD_PATH = Path(__file__).parent / 'templates' / 'datasetcard_template.md'
REGEX_YAML_BLOCK = re.compile('^(\\s*---[\\r\\n]+)([\\S\\s]*?)([\\r\\n]+---(\\r\\n|\\n|$))')

class RepoCard:
    card_data_class = CardData
    default_template_path = TEMPLATE_MODELCARD_PATH
    repo_type = 'model'

    def __init__(self, content: str, ignore_metadata_errors: bool=False):
        self.ignore_metadata_errors = ignore_metadata_errors
        self.content = content

    @property
    def content(self):
        line_break = _detect_line_ending(self._content) or '\n'
        return f'---{line_break}{self.data.to_yaml(line_break=line_break, original_order=self._original_order)}{line_break}---{line_break}{self.text}'

    @content.setter
    def content(self, content: str):
        self._content = content
        match = REGEX_YAML_BLOCK.search(content)
        if match:
            yaml_block = match.group(2)
            self.text = content[match.end():]
            data_dict = yaml.safe_load(yaml_block)
            if data_dict is None:
                data_dict = {}
            if not isinstance(data_dict, dict):
                raise ValueError('repo card metadata block should be a dict')
        else:
            logger.warning('Repo card metadata block was not found. Setting CardData to empty.')
            data_dict = {}
            self.text = content
        self.data = self.card_data_class(**data_dict, ignore_metadata_errors=self.ignore_metadata_errors)
        self._original_order = list(data_dict.keys())

    def __str__(self):
        return self.content

    def save(self, filepath: Union[Path, str]):
        filepath = Path(filepath)
        filepath.parent.mkdir(parents=True, exist_ok=True)
        with open(filepath, mode='w', newline='', encoding='utf-8') as f:
            f.write(str(self))

    @classmethod
    def load(cls, repo_id_or_path: Union[str, Path], repo_type: Optional[str]=None, token: Optional[str]=None, ignore_metadata_errors: bool=False):
        if Path(repo_id_or_path).is_file():
            card_path = Path(repo_id_or_path)
        elif isinstance(repo_id_or_path, str):
            card_path = Path(hf_hub_download(repo_id_or_path, constants.REPOCARD_NAME, repo_type=repo_type or cls.repo_type, token=token))
        else:
            raise ValueError(f'Cannot load RepoCard: path not found on disk ({repo_id_or_path}).')
        with card_path.open(mode='r', newline='', encoding='utf-8') as f:
            return cls(f.read(), ignore_metadata_errors=ignore_metadata_errors)

    def validate(self, repo_type: Optional[str]=None):
        repo_type = repo_type or self.repo_type
        body = {'repoType': repo_type, 'content': str(self)}
        headers = {'Accept': 'text/plain'}
        try:
            response = get_session().post('https://huggingface.co/api/validate-yaml', json=body, headers=headers)
            hf_raise_for_status(response)
        except HfHubHTTPError as exc:
            if response.status_code == 400:
                raise ValueError(response.text)
            else:
                raise exc

    def push_to_hub(self, repo_id: str, token: Optional[str]=None, repo_type: Optional[str]=None, commit_message: Optional[str]=None, commit_description: Optional[str]=None, revision: Optional[str]=None, create_pr: Optional[bool]=None, parent_commit: Optional[str]=None):
        repo_type = repo_type or self.repo_type
        self.validate(repo_type=repo_type)
        with SoftTemporaryDirectory() as tmpdir:
            tmp_path = Path(tmpdir) / constants.REPOCARD_NAME
            tmp_path.write_text(str(self), encoding='utf-8')
            url = upload_file(path_or_fileobj=str(tmp_path), path_in_repo=constants.REPOCARD_NAME, repo_id=repo_id, token=token, repo_type=repo_type, commit_message=commit_message, commit_description=commit_description, create_pr=create_pr, revision=revision, parent_commit=parent_commit)
        return url

    @classmethod
    def from_template(cls, card_data: CardData, template_path: Optional[str]=None, template_str: Optional[str]=None, **template_kwargs):
        if is_jinja_available():
            import jinja2
        else:
            raise ImportError('Using RepoCard.from_template requires Jinja2 to be installed. Please install it with `pip install Jinja2`.')
        kwargs = card_data.to_dict().copy()
        kwargs.update(template_kwargs)
        if template_path is not None:
            template_str = Path(template_path).read_text()
        if template_str is None:
            template_str = Path(cls.default_template_path).read_text()
        template = jinja2.Template(template_str)
        content = template.render(card_data=card_data.to_yaml(), **kwargs)
        return cls(content)

class ModelCard(RepoCard):
    card_data_class = ModelCardData
    default_template_path = TEMPLATE_MODELCARD_PATH
    repo_type = 'model'

    @classmethod
    def from_template(cls, card_data: ModelCardData, template_path: Optional[str]=None, template_str: Optional[str]=None, **template_kwargs):
        return super().from_template(card_data, template_path, template_str, **template_kwargs)

class DatasetCard(RepoCard):
    card_data_class = DatasetCardData
    default_template_path = TEMPLATE_DATASETCARD_PATH
    repo_type = 'dataset'

    @classmethod
    def from_template(cls, card_data: DatasetCardData, template_path: Optional[str]=None, template_str: Optional[str]=None, **template_kwargs):
        return super().from_template(card_data, template_path, template_str, **template_kwargs)

class SpaceCard(RepoCard):
    card_data_class = SpaceCardData
    default_template_path = TEMPLATE_MODELCARD_PATH
    repo_type = 'space'

def _detect_line_ending(content: str) -> Literal['\r', '\n', '\r\n', None]:
    cr = content.count('\r')
    lf = content.count('\n')
    crlf = content.count('\r\n')
    if cr + lf == 0:
        return None
    if crlf == cr and crlf == lf:
        return '\r\n'
    if cr > lf:
        return '\r'
    else:
        return '\n'

def metadata_load(local_path: Union[str, Path]) -> Optional[dict]:
    content = Path(local_path).read_text()
    match = REGEX_YAML_BLOCK.search(content)
    if match:
        yaml_block = match.group(2)
        data = yaml.safe_load(yaml_block)
        if data is None or isinstance(data, dict):
            return data
        raise ValueError('repo card metadata block should be a dict')
    else:
        return None

def metadata_save(local_path: Union[str, Path], data: dict) -> None:
    line_break = '\n'
    content = ''
    if os.path.exists(local_path):
        with open(local_path, 'r', newline='', encoding='utf8') as readme:
            content = readme.read()
            if isinstance(readme.newlines, tuple):
                line_break = readme.newlines[0]
            elif isinstance(readme.newlines, str):
                line_break = readme.newlines
    with open(local_path, 'w', newline='', encoding='utf8') as readme:
        data_yaml = yaml_dump(data, sort_keys=False, line_break=line_break)
        match = REGEX_YAML_BLOCK.search(content)
        if match:
            output = content[:match.start()] + f'---{line_break}{data_yaml}---{line_break}' + content[match.end():]
        else:
            output = f'---{line_break}{data_yaml}---{line_break}{content}'
        readme.write(output)
        readme.close()

def metadata_eval_result(*, model_pretty_name: str, task_pretty_name: str, task_id: str, metrics_pretty_name: str, metrics_id: str, metrics_value: Any, dataset_pretty_name: str, dataset_id: str, metrics_config: Optional[str]=None, metrics_verified: bool=False, dataset_config: Optional[str]=None, dataset_split: Optional[str]=None, dataset_revision: Optional[str]=None, metrics_verification_token: Optional[str]=None) -> dict:
    return {'model-index': eval_results_to_model_index(model_name=model_pretty_name, eval_results=[EvalResult(task_name=task_pretty_name, task_type=task_id, metric_name=metrics_pretty_name, metric_type=metrics_id, metric_value=metrics_value, dataset_name=dataset_pretty_name, dataset_type=dataset_id, metric_config=metrics_config, verified=metrics_verified, verify_token=metrics_verification_token, dataset_config=dataset_config, dataset_split=dataset_split, dataset_revision=dataset_revision)])}

@validate_hf_hub_args
def metadata_update(repo_id: str, metadata: dict, *, repo_type: Optional[str]=None, overwrite: bool=False, token: Optional[str]=None, commit_message: Optional[str]=None, commit_description: Optional[str]=None, revision: Optional[str]=None, create_pr: bool=False, parent_commit: Optional[str]=None) -> str:
    commit_message = commit_message if commit_message is not None else 'Update metadata with huggingface_hub'
    card_class: type[RepoCard]
    if repo_type is None or repo_type == 'model':
        card_class = ModelCard
    elif repo_type == 'dataset':
        card_class = DatasetCard
    elif repo_type == 'space':
        card_class = RepoCard
    else:
        raise ValueError(f'Unknown repo_type: {repo_type}')
    try:
        card = card_class.load(repo_id, token=token, repo_type=repo_type)
    except EntryNotFoundError:
        if repo_type == 'space':
            raise ValueError("Cannot update metadata on a Space that doesn't contain a `README.md` file.")
        card = card_class.from_template(CardData())
    for key, value in metadata.items():
        if key == 'model-index':
            if 'name' not in value[0]:
                value[0]['name'] = getattr(card, 'model_name', repo_id)
            model_name, new_results = model_index_to_eval_results(value)
            if card.data.eval_results is None:
                card.data.eval_results = new_results
                card.data.model_name = model_name
            else:
                existing_results = card.data.eval_results
                for new_result in new_results:
                    result_found = False
                    for existing_result in existing_results:
                        if new_result.is_equal_except_value(existing_result):
                            if new_result != existing_result and (not overwrite):
                                raise ValueError(f"You passed a new value for the existing metric 'name: {new_result.metric_name}, type: {new_result.metric_type}'. Set `overwrite=True` to overwrite existing metrics.")
                            result_found = True
                            existing_result.metric_value = new_result.metric_value
                            if existing_result.verified is True:
                                existing_result.verify_token = new_result.verify_token
                    if not result_found:
                        card.data.eval_results.append(new_result)
        elif card.data.get(key) is not None and (not overwrite) and (card.data.get(key) != value):
            raise ValueError(f"You passed a new value for the existing meta data field '{key}'. Set `overwrite=True` to overwrite existing metadata.")
        else:
            card.data[key] = value
    return card.push_to_hub(repo_id, token=token, repo_type=repo_type, commit_message=commit_message, commit_description=commit_description, create_pr=create_pr, revision=revision, parent_commit=parent_commit)

import base64
import re
import requests
from ..spec import AbstractFileSystem
from ..utils import infer_storage_options
from .memory import MemoryFile

class GithubFileSystem(AbstractFileSystem):
    url = 'https://api.github.com/repos/{org}/{repo}/git/trees/{sha}'
    content_url = 'https://api.github.com/repos/{org}/{repo}/contents/{path}?ref={sha}'
    protocol = 'github'
    timeout = (60, 60)

    def __init__(self, org, repo, sha=None, username=None, token=None, timeout=None, **kwargs):
        super().__init__(**kwargs)
        self.org = org
        self.repo = repo
        if (username is None) ^ (token is None):
            raise ValueError('Auth required both username and token')
        self.username = username
        self.token = token
        if timeout is not None:
            self.timeout = timeout
        if sha is None:
            u = 'https://api.github.com/repos/{org}/{repo}'
            r = requests.get(u.format(org=org, repo=repo), timeout=self.timeout, **self.kw)
            r.raise_for_status()
            sha = r.json()['default_branch']
        self.root = sha
        self.ls('')
        try:
            from .http import HTTPFileSystem
            self.http_fs = HTTPFileSystem(**kwargs)
        except ImportError:
            self.http_fs = None

    @property
    def kw(self):
        if self.username:
            return {'auth': (self.username, self.token)}
        return {}

    @classmethod
    def repos(cls, org_or_user, is_org=True):
        r = requests.get(f"https://api.github.com/{['users', 'orgs'][is_org]}/{org_or_user}/repos", timeout=cls.timeout)
        r.raise_for_status()
        return [repo['name'] for repo in r.json()]

    @property
    def tags(self):
        r = requests.get(f'https://api.github.com/repos/{self.org}/{self.repo}/tags', timeout=self.timeout, **self.kw)
        r.raise_for_status()
        return [t['name'] for t in r.json()]

    @property
    def branches(self):
        r = requests.get(f'https://api.github.com/repos/{self.org}/{self.repo}/branches', timeout=self.timeout, **self.kw)
        r.raise_for_status()
        return [t['name'] for t in r.json()]

    @property
    def refs(self):
        return {'tags': self.tags, 'branches': self.branches}

    def ls(self, path, detail=False, sha=None, _sha=None, **kwargs):
        path = self._strip_protocol(path)
        if path == '':
            _sha = sha or self.root
        if _sha is None:
            parts = path.rstrip('/').split('/')
            so_far = ''
            _sha = sha or self.root
            for part in parts:
                out = self.ls(so_far, True, sha=sha, _sha=_sha)
                so_far += '/' + part if so_far else part
                out = [o for o in out if o['name'] == so_far]
                if not out:
                    raise FileNotFoundError(path)
                out = out[0]
                if out['type'] == 'file':
                    if detail:
                        return [out]
                    else:
                        return path
                _sha = out['sha']
        if path not in self.dircache or sha not in [self.root, None]:
            r = requests.get(self.url.format(org=self.org, repo=self.repo, sha=_sha), timeout=self.timeout, **self.kw)
            if r.status_code == 404:
                raise FileNotFoundError(path)
            r.raise_for_status()
            types = {'blob': 'file', 'tree': 'directory'}
            out = [{'name': path + '/' + f['path'] if path else f['path'], 'mode': f['mode'], 'type': types[f['type']], 'size': f.get('size', 0), 'sha': f['sha']} for f in r.json()['tree'] if f['type'] in types]
            if sha in [self.root, None]:
                self.dircache[path] = out
        else:
            out = self.dircache[path]
        if detail:
            return out
        else:
            return sorted([f['name'] for f in out])

    def invalidate_cache(self, path=None):
        self.dircache.clear()

    @classmethod
    def _strip_protocol(cls, path):
        opts = infer_storage_options(path)
        if 'username' not in opts:
            return super()._strip_protocol(path)
        return opts['path'].lstrip('/')

    @staticmethod
    def _get_kwargs_from_urls(path):
        opts = infer_storage_options(path)
        if 'username' not in opts:
            return {}
        out = {'org': opts['username'], 'repo': opts['password']}
        if opts['host']:
            out['sha'] = opts['host']
        return out

    def _open(self, path, mode='rb', block_size=None, cache_options=None, sha=None, **kwargs):
        if mode != 'rb':
            raise NotImplementedError
        url = self.content_url.format(org=self.org, repo=self.repo, path=path, sha=sha or self.root)
        r = requests.get(url, timeout=self.timeout, **self.kw)
        if r.status_code == 404:
            raise FileNotFoundError(path)
        r.raise_for_status()
        content_json = r.json()
        if content_json['content']:
            content = base64.b64decode(content_json['content'])
            if not content.startswith(b'version https://git-lfs.github.com/'):
                return MemoryFile(None, None, content)
        if self.http_fs is None:
            raise ImportError('Please install fsspec[http] to access github files >1 MB or git-lfs tracked files.')
        return self.http_fs.open(content_json['download_url'], mode=mode, block_size=block_size, cache_options=cache_options, **kwargs)

    def rm(self, path, recursive=False, maxdepth=None, message=None):
        path = self.expand_path(path, recursive=recursive, maxdepth=maxdepth)
        for p in reversed(path):
            self.rm_file(p, message=message)

    def rm_file(self, path, message=None, **kwargs):
        if not self.username:
            raise ValueError('Authentication required')
        path = self._strip_protocol(path)
        sha = self._get_sha_from_cache(path)
        if not sha:
            url = self.content_url.format(org=self.org, repo=self.repo, path=path.lstrip('/'), sha=self.root)
            r = requests.get(url, timeout=self.timeout, **self.kw)
            if r.status_code == 404:
                raise FileNotFoundError(path)
            r.raise_for_status()
            sha = r.json()['sha']
        delete_url = self.content_url.format(org=self.org, repo=self.repo, path=path, sha=self.root)
        branch = self.root
        data = {'message': message or f'Delete {path}', 'sha': sha, **({'branch': branch} if branch else {})}
        r = requests.delete(delete_url, json=data, timeout=self.timeout, **self.kw)
        error_message = r.json().get('message', '')
        if re.search('Branch .+ not found', error_message):
            error = 'Remove only works when the filesystem is initialised from a branch or default (None)'
            raise ValueError(error)
        r.raise_for_status()
        self.invalidate_cache(path)

    def _get_sha_from_cache(self, path):
        for entries in self.dircache.values():
            for entry in entries:
                entry_path = entry.get('name')
                if entry_path and entry_path == path and ('sha' in entry):
                    return entry['sha']
        return None

import re
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING, Dict, List, Optional
import pyarrow as pa
from huggingface_hub import HfApi
import datasets
from datasets import Audio, Image, Video
from datasets.builder import Key
from datasets.table import table_cast
from datasets.utils.file_utils import is_local_path
if TYPE_CHECKING:
    import lance
    import lance.file
logger = datasets.utils.logging.get_logger(__name__)
MAGIC_BYTES_EXTENSION_AND_FEATURE_TYPES = [('1A 45 DF A3', '.mkv', Video()), ('66 74 79 70 69 73 6F 6D', '.mp4', Video()), ('66 74 79 70 4D 53 4E 56', '.mp4', Video()), ('52 49 46 46', '.avi', Video()), ('00 00 01 BA', '.mpeg', Video()), ('00 00 01 BA', '.mpeg', Video()), ('00 00 01 B3', '.mov', Video()), ('89 50 4E 47', '.png', Image()), ('FF D8', '.jpg', Image()), ('49 49', '.tif', Image()), ('47 49 46 38', '.gif', Image()), ('52 49 46 46', '.wav', Audio()), ('49 44 33', '.mp3', Audio()), ('66 4C 61 43', '.flac', Audio())]

@dataclass
class LanceConfig(datasets.BuilderConfig):
    features: Optional[datasets.Features] = None
    columns: Optional[List[str]] = None
    batch_size: Optional[int] = 256
    token: Optional[str] = None

def resolve_dataset_uris(files: List[str]) -> Dict[str, List[str]]:
    dataset_uris = set()
    for file_path in files:
        path = Path(file_path)
        if path.parent.name in {'_transactions', '_indices', '_versions'}:
            dataset_root = path.parent.parent
            dataset_uris.add(str(dataset_root))
    return list(dataset_uris)

def _fix_hf_uri(uri: str) -> str:
    if '@' in uri:
        matched = re.match('(hf://.+?)(@[0-9a-f]+)(/.*)', uri)
        if matched:
            uri = matched.group(1) + matched.group(3)
    return uri

def _fix_local_version_file(uri: str) -> str:
    if '/_versions/' in uri and is_local_path(uri):
        path = Path(uri)
        if path.is_symlink():
            data = path.read_bytes()
            path.unlink()
            path.write_bytes(data)
    return uri

class Lance(datasets.ArrowBasedBuilder, datasets.builder._CountableBuilderMixin):
    BUILDER_CONFIG_CLASS = LanceConfig
    METADATA_EXTENSIONS = ['.idx', '.txn', '.manifest']

    def _info(self):
        return datasets.DatasetInfo(features=self.config.features)

    def _split_generators(self, dl_manager):
        import lance
        import lance.file
        if not self.config.data_files:
            raise ValueError(f'At least one data file must be specified, but got data_files={self.config.data_files}')
        if self.repo_id:
            api = HfApi(**dl_manager.download_config.storage_options.get('hf', {}))
            dataset_sha = api.dataset_info(self.repo_id).sha
            if dataset_sha != self.hash:
                raise NotImplementedError(f"lance doesn't support loading other revisions than 'main' yet, but got {self.hash}")
        data_files = dl_manager.download(self.config.data_files)
        data_files = {split: [_fix_hf_uri(file) for file in files] for split, files in data_files.items()}
        data_files = {split: [_fix_local_version_file(file) for file in files] for split, files in data_files.items()}
        splits: list[datasets.SplitGenerator] = []
        for split_name, files in data_files.items():
            storage_options = dl_manager.download_config.storage_options.get(files[0].split('://', 0)[0] + '://')
            lance_dataset_uris = resolve_dataset_uris(files)
            if lance_dataset_uris:
                lance_datasets = [lance.dataset(uri, storage_options=storage_options) for uri in lance_dataset_uris]
                fragments = [frag for lance_dataset in lance_datasets for frag in lance_dataset.get_fragments()]
                if self.info.features is None:
                    pa_schema = fragments[0]._ds.schema
                    first_row_first_bytes = {}
                    for field in pa_schema:
                        if self.config.columns is not None and field.name not in self.config.columns:
                            continue
                        if pa.types.is_binary(field.type) or pa.types.is_large_binary(field.type):
                            try:
                                first_row_first_bytes[field.name] = lance_datasets[0].take_blobs(field.name, [0])[0].read(16)
                            except ValueError:
                                first_row_first_bytes[field.name] = lance_datasets[0].take([0], [field.name]).to_pylist()[0][field.name][:16]
                splits.append(datasets.SplitGenerator(name=split_name, gen_kwargs={'fragments': fragments, 'lance_files_paths': None, 'lance_files': None}))
            else:
                lance_files = [lance.file.LanceFileReader(file, storage_options=storage_options, columns=self.config.columns) for file in files]
                if self.info.features is None:
                    pa_schema = lance_files[0].metadata().schema
                    first_row_first_bytes = {field_name: value[:16] for field_name, value in lance_files[0].take_rows([0]).to_table().to_pylist()[0].items() if isinstance(value, bytes)}
                splits.append(datasets.SplitGenerator(name=split_name, gen_kwargs={'fragments': None, 'lance_files_paths': files, 'lance_files': lance_files}))
            if self.info.features is None:
                if self.config.columns:
                    fields = [pa_schema.field(name) for name in self.config.columns if pa_schema.get_field_index(name) != -1]
                    pa_schema = pa.schema(fields)
                features = datasets.Features.from_arrow_schema(pa_schema)
                for field_name, first_bytes in first_row_first_bytes.items():
                    for magic_bytes_hex, _, feature_type in MAGIC_BYTES_EXTENSION_AND_FEATURE_TYPES:
                        magic_bytes = bytes.fromhex(magic_bytes_hex)
                        if magic_bytes in first_bytes[:len(magic_bytes) * 2]:
                            features[field_name] = feature_type
                            break
                self.info.features = features
        return splits

    def _cast_table(self, pa_table: pa.Table) -> pa.Table:
        if self.info.features is not None:
            pa_table = table_cast(pa_table, self.info.features.arrow_schema)
        return pa_table

    def _generate_shards(self, fragments: Optional[List['lance.LanceFragment']], lance_files_paths: Optional[list[str]], lance_files: Optional[List['lance.file.LanceFileReader']]):
        if fragments:
            for fragment in fragments:
                paths = [data_file.path for data_file in fragment.metadata.data_files()]
                yield (paths[0] if len(paths) == 1 else {'fragment_data_files': paths})
        else:
            yield from lance_files_paths

    def _generate_num_examples(self, fragments: Optional[List['lance.LanceFragment']], lance_files_paths: Optional[list[str]], lance_files: Optional[List['lance.file.LanceFileReader']]):
        if fragments:
            for fragment in fragments:
                yield fragment.count_rows()
        else:
            for lance_file in lance_files:
                yield lance_file.num_rows()

    def _generate_tables(self, fragments: Optional[List['lance.LanceFragment']], lance_files_paths: Optional[list[str]], lance_files: Optional[List['lance.file.LanceFileReader']]):
        if fragments:
            for frag_idx, fragment in enumerate(fragments):
                for batch_idx, batch in enumerate(fragment.to_batches(columns=self.config.columns, batch_size=self.config.batch_size, blob_handling='all_binary')):
                    table = pa.Table.from_batches([batch])
                    yield (Key(frag_idx, batch_idx), self._cast_table(table))
        else:
            for file_idx, lance_file in enumerate(lance_files):
                for batch_idx, batch in enumerate(lance_file.read_all(batch_size=self.config.batch_size).to_batches()):
                    table = pa.Table.from_batches([batch])
                    yield (Key(file_idx, batch_idx), self._cast_table(table))

import errno
import json
import os
import re
import shutil
import subprocess
import venv
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Annotated, Literal, Optional
import typer
from huggingface_hub.errors import CLIError, CLIExtensionInstallError
from huggingface_hub.utils import StatusLine, get_session, logging
from ._cli_utils import FormatOpt, OutputFormat, QuietOpt, print_list_output, typer_factory
DEFAULT_EXTENSION_OWNER = 'huggingface'
EXTENSIONS_ROOT = Path('~/.local/share/hf/extensions')
MANIFEST_FILENAME = 'manifest.json'
EXTENSIONS_HELP = 'Manage hf CLI extensions.\n\nSecurity Warning: extensions are third-party executables or Python packages. Install only from sources you trust.'
extensions_cli = typer_factory(help=EXTENSIONS_HELP)
_EXTENSIONS_DEFAULT_BRANCH = 'main'
_EXTENSIONS_GITHUB_TOPIC = 'hf-extension'
_EXTENSIONS_DOWNLOAD_TIMEOUT = 10
_EXTENSIONS_PIP_INSTALL_TIMEOUT = 300
logger = logging.get_logger(__name__)

@dataclass
class ExtensionManifest:
    owner: str
    repo: str
    repo_id: str
    short_name: str
    executable_name: str
    executable_path: str
    type: Literal['binary', 'python']
    installed_at: datetime
    source: str
    description: Optional[str] = None

    @classmethod
    def load(cls, path: Path) -> 'ExtensionManifest':
        manifest_path = path / MANIFEST_FILENAME
        if not manifest_path.is_file():
            raise CLIError(f'Manifest file not found at {manifest_path}. Your extension may be corrupted.')
        data = json.loads(manifest_path.read_text())
        data['installed_at'] = datetime.fromisoformat(data['installed_at'])
        return ExtensionManifest(**data)

    def save(self, path: Path) -> None:
        manifest_path = path / MANIFEST_FILENAME
        manifest_path.parent.mkdir(parents=True, exist_ok=True)
        data = asdict(self)
        data['installed_at'] = self.installed_at.isoformat()
        manifest_path.write_text(json.dumps(data, indent=2, sort_keys=True))

@extensions_cli.command('install', examples=['hf extensions install hf-claude', 'hf extensions install hanouticelina/hf-claude', 'hf extensions install alvarobartt/hf-mem'])
def extension_install(ctx: typer.Context, repo_id: Annotated[str, typer.Argument(help='GitHub extension repository in `[OWNER/]hf-<name>` format.')], force: Annotated[bool, typer.Option('--force', help='Overwrite if already installed.')]=False) -> None:
    owner, repo_name, short_name = _normalize_repo_id(repo_id)
    root_ctx = ctx.find_root()
    reserved_commands = set(getattr(root_ctx.command, 'commands', {}).keys())
    if short_name in reserved_commands:
        raise CLIError(f"Cannot install extension '{short_name}' because it conflicts with an existing `hf {short_name}` command.")
    extension_dir = _get_extension_dir(short_name)
    extension_exists = extension_dir.exists()
    if extension_exists and (not force):
        raise CLIError(f"Extension '{short_name}' is already installed. Use --force to overwrite.")
    branch, description = _resolve_github_repo_info(owner=owner, repo_name=repo_name)
    if extension_exists:
        shutil.rmtree(extension_dir)
    try:
        binary = _fetch_remote_binary(owner=owner, repo_name=repo_name, branch=branch, short_name=short_name)
    except Exception:
        binary = None
    if binary is not None:
        print('Binary found, installing as binary extension...')
        manifest = _install_binary_extension(owner=owner, repo_name=repo_name, short_name=short_name, extension_dir=extension_dir, binary=binary)
        print(f'Binary extension installed successfully from {owner}/{repo_name}.')
    else:
        print('Binary not found, trying to install as Python extension...')
        manifest = _install_python_extension(owner=owner, repo_name=repo_name, short_name=short_name, extension_dir=extension_dir, branch=branch)
        print(f'Python extension installed successfully from {owner}/{repo_name}.')
    description = _try_fetch_remote_description(owner=owner, repo_name=repo_name, branch=branch, candidate_description=description)
    manifest.description = description
    manifest.save(extension_dir)
    print(f'Run it with: hf {short_name}')

@extensions_cli.command('exec', context_settings={'allow_extra_args': True, 'allow_interspersed_args': False, 'ignore_unknown_options': True}, examples=['hf extensions exec claude -- --help', 'hf extensions exec claude --model zai-org/GLM-5'])
def extension_exec(ctx: typer.Context, name: Annotated[str, typer.Argument(help='Extension name (with or without `hf-` prefix).')]) -> None:
    short_name = _normalize_extension_name(name)
    executable_path = _resolve_installed_executable_path(short_name)
    if not executable_path.is_file():
        raise CLIError(f"Extension '{short_name}' is not installed.")
    exit_code = _execute_extension_binary(executable_path=executable_path, args=list(ctx.args))
    raise typer.Exit(code=exit_code)

@extensions_cli.command('list | ls', examples=['hf extensions list'])
def extension_list(format: FormatOpt=OutputFormat.table, quiet: QuietOpt=False) -> None:
    rows = [{'command': f'hf {manifest.short_name}', 'source': str(manifest.repo_id), 'type': str(manifest.type), 'installed': manifest.installed_at.strftime('%Y-%m-%d'), 'description': manifest.description} for manifest in _list_installed_extensions()]
    print_list_output(rows, format=format, quiet=quiet, id_key='command')

@extensions_cli.command('search', examples=['hf extensions search'])
def extension_search(format: FormatOpt=OutputFormat.table, quiet: QuietOpt=False) -> None:
    response = get_session().get('https://api.github.com/search/repositories', params={'q': f'topic:{_EXTENSIONS_GITHUB_TOPIC}', 'sort': 'stars', 'order': 'desc', 'per_page': 100}, follow_redirects=True, timeout=_EXTENSIONS_DOWNLOAD_TIMEOUT)
    response.raise_for_status()
    data = response.json()
    installed = {m.short_name for m in _list_installed_extensions()}
    rows = []
    for repo in data.get('items', []):
        repo_name = repo['name']
        short_name = repo_name[3:] if repo_name.startswith('hf-') else repo_name
        rows.append({'name': short_name, 'repo': repo['full_name'], 'stars': repo.get('stargazers_count', 0), 'description': repo.get('description') or '', 'installed': 'yes' if short_name in installed else ''})
    print_list_output(rows, format=format, quiet=quiet, id_key='repo', alignments={'stars': 'right'})

@extensions_cli.command('remove | rm', examples=['hf extensions remove claude'])
def extension_remove(name: Annotated[str, typer.Argument(help='Extension name to remove (with or without `hf-` prefix).')]) -> None:
    short_name = _normalize_extension_name(name)
    extension_dir = _get_extension_dir(short_name)
    if not extension_dir.is_dir():
        raise CLIError(f"Extension '{short_name}' is not installed.")
    shutil.rmtree(extension_dir)
    print(f"Removed extension '{short_name}'.")

def _list_installed_extensions() -> list[ExtensionManifest]:
    root_dir = EXTENSIONS_ROOT.expanduser()
    if not root_dir.is_dir():
        return []
    manifests = []
    for extension_dir in sorted(root_dir.iterdir()):
        if not extension_dir.is_dir() or not extension_dir.name.startswith('hf-'):
            continue
        try:
            manifests.append(ExtensionManifest.load(extension_dir))
        except Exception as e:
            logger.debug(f"Failed to load manifest for extension '{extension_dir.name}': {e}")
            continue
    return manifests

def list_installed_extensions_for_help() -> list[tuple[str, str]]:
    entries = []
    for manifest in _list_installed_extensions():
        tag = f'[extension {manifest.repo_id}]'
        help_text = f'{manifest.description} {tag}' if manifest.description is not None else tag
        entries.append((manifest.short_name, help_text))
    return entries

def dispatch_unknown_top_level_extension(args: list[str], known_commands: set[str]) -> Optional[int]:
    if not args:
        return None
    command_name = args[0]
    if command_name.startswith('-'):
        return None
    if command_name in known_commands:
        return None
    short_name = command_name[3:] if command_name.startswith('hf-') else command_name
    if not short_name:
        return None
    try:
        executable_path = _resolve_installed_executable_path(short_name)
    except Exception:
        return None
    if not executable_path.is_file():
        return None
    return _execute_extension_binary(executable_path=executable_path, args=list(args[1:]))

def _fetch_remote_binary(owner: str, repo_name: str, branch: str, short_name: str) -> bytes:
    executable_name = _get_executable_name(short_name)
    raw_url = f'https://raw.githubusercontent.com/{owner}/{repo_name}/refs/heads/{branch}/{executable_name}'
    response = get_session().get(raw_url, follow_redirects=True, timeout=_EXTENSIONS_DOWNLOAD_TIMEOUT)
    response.raise_for_status()
    return response.content

def _install_binary_extension(*, owner: str, repo_name: str, short_name: str, extension_dir: Path, binary: bytes) -> ExtensionManifest:
    executable_name = _get_executable_name(short_name)
    extension_dir.mkdir(parents=True, exist_ok=False)
    executable_path = extension_dir / executable_name
    executable_path.write_bytes(binary)
    if os.name != 'nt':
        os.chmod(executable_path, 493)
    return ExtensionManifest(owner=owner, repo=repo_name, repo_id=f'{owner}/{repo_name}', short_name=short_name, executable_name=executable_name, executable_path=str(executable_path), type='binary', installed_at=datetime.now(timezone.utc), source=f'https://github.com/{owner}/{repo_name}')

def _install_python_extension(*, owner: str, repo_name: str, short_name: str, extension_dir: Path, branch: str) -> ExtensionManifest:
    source_url = f'https://github.com/{owner}/{repo_name}/archive/refs/heads/{branch}.zip'
    venv_dir = extension_dir / 'venv'
    installed = False
    status = StatusLine()
    try:
        status.update(f'Creating virtual environment in {venv_dir}')
        if extension_dir.exists():
            shutil.rmtree(extension_dir, ignore_errors=True)
        extension_dir.mkdir(parents=True, exist_ok=False)
        uv_path = shutil.which('uv')
        venv_python = _get_venv_python_path(venv_dir)
        if uv_path:
            subprocess.run([uv_path, 'venv', str(venv_dir)], check=True)
            status.done(f'Virtual environment created in {venv_dir}')
            status.update(f'Installing package from {source_url}')
            subprocess.run([uv_path, 'pip', 'install', '--python', str(venv_python), source_url], check=True, timeout=_EXTENSIONS_PIP_INSTALL_TIMEOUT)
        else:
            venv.EnvBuilder(with_pip=True).create(str(venv_dir))
            status.done(f'Virtual environment created in {venv_dir}')
            status.update(f'Installing package from {source_url}')
            subprocess.run([str(venv_python), '-m', 'pip', 'install', '--disable-pip-version-check', '--no-input', source_url], check=True, timeout=_EXTENSIONS_PIP_INSTALL_TIMEOUT)
        status.done(f'Package installed from {source_url}')
        executable_name = _get_executable_name(short_name)
        venv_executable = _get_venv_extension_executable_path(venv_dir, short_name)
        if not venv_executable.is_file():
            raise CLIError(f"Installed package from '{owner}/{repo_name}' does not expose the required console script '{executable_name}'.")
        manifest = ExtensionManifest(owner=owner, repo=repo_name, repo_id=f'{owner}/{repo_name}', short_name=short_name, executable_name=executable_name, executable_path=str(venv_executable.resolve()), type='python', installed_at=datetime.now(timezone.utc), source=f'https://github.com/{owner}/{repo_name}')
        installed = True
        return manifest
    except CLIError:
        raise
    except subprocess.TimeoutExpired as e:
        raise CLIExtensionInstallError(f"Pip install timed out after {_EXTENSIONS_PIP_INSTALL_TIMEOUT}s for '{owner}/{repo_name}'. See pip output above for details.") from e
    except subprocess.CalledProcessError as e:
        raise CLIExtensionInstallError(f"Failed to install pip package from '{owner}/{repo_name}' (exit code {e.returncode}). See pip output above for details.") from e
    except Exception as e:
        raise CLIExtensionInstallError(f"Failed to set up pip extension from '{owner}/{repo_name}': {e}") from e
    finally:
        if not installed:
            shutil.rmtree(extension_dir, ignore_errors=True)

def _try_fetch_remote_description(owner: str, repo_name: str, branch: str, candidate_description: Optional[str]) -> Optional[str]:
    try:
        response = get_session().get(f'https://raw.githubusercontent.com/{owner}/{repo_name}/refs/heads/{branch}/{MANIFEST_FILENAME}', follow_redirects=True)
        response.raise_for_status()
        data = response.json()
        description = data.get('description')
        if isinstance(description, str):
            return description
    except Exception:
        pass
    try:
        response = get_session().get(f'https://raw.githubusercontent.com/{owner}/{repo_name}/refs/heads/{branch}/pyproject.toml', follow_redirects=True)
        response.raise_for_status()
        for line in response.text.splitlines():
            line = line.strip()
            if line.startswith('description'):
                _, _, value = line.partition('=')
                return value.strip().strip('"\'')
    except Exception:
        pass
    return candidate_description

def _get_extensions_root() -> Path:
    root_dir = EXTENSIONS_ROOT.expanduser()
    root_dir.mkdir(parents=True, exist_ok=True)
    return root_dir

def _get_extension_dir(short_name: str) -> Path:
    safe_name = _validate_extension_short_name(short_name, original_input=short_name)
    root = _get_extensions_root().resolve()
    target = (root / f'hf-{safe_name}').resolve()
    if root not in target.parents:
        raise CLIError(f"Invalid extension name '{short_name}'.")
    return target

def _resolve_github_repo_info(owner: str, repo_name: str) -> tuple[str, Optional[str]]:
    try:
        response = get_session().get(f'https://api.github.com/repos/{owner}/{repo_name}', follow_redirects=True, timeout=_EXTENSIONS_DOWNLOAD_TIMEOUT)
        response.raise_for_status()
        data = response.json()
        return (data['default_branch'], data.get('description'))
    except Exception:
        return (_EXTENSIONS_DEFAULT_BRANCH, None)

def _get_executable_name(short_name: str) -> str:
    name = f'hf-{short_name}'
    if os.name == 'nt':
        name += '.exe'
    return name

def _resolve_installed_executable_path(short_name: str) -> Path:
    extension_dir = _get_extension_dir(short_name)
    manifest = ExtensionManifest.load(extension_dir)
    return Path(manifest.executable_path).expanduser()

def _get_venv_python_path(venv_dir: Path) -> Path:
    if os.name == 'nt':
        return venv_dir / 'Scripts' / 'python.exe'
    return venv_dir / 'bin' / 'python'

def _get_venv_extension_executable_path(venv_dir: Path, short_name: str) -> Path:
    executable_name = _get_executable_name(short_name)
    if os.name == 'nt':
        return venv_dir / 'Scripts' / executable_name
    return venv_dir / 'bin' / executable_name
_ALLOWED_EXTENSION_NAME = re.compile('^[A-Za-z0-9][A-Za-z0-9._-]*$')

def _validate_extension_short_name(short_name: str, *, original_input: str) -> str:
    name = short_name.strip()
    if not name:
        raise CLIError('Extension name cannot be empty.')
    if any((sep in name for sep in ('/', '\\'))):
        raise CLIError(f"Invalid extension name '{original_input}'.")
    if '..' in name or ':' in name:
        raise CLIError(f"Invalid extension name '{original_input}'.")
    if not _ALLOWED_EXTENSION_NAME.fullmatch(name):
        raise CLIError(f"Invalid extension name '{original_input}'. Allowed characters: letters, digits, '.', '_' and '-'.")
    return name

def _normalize_repo_id(repo_id: str) -> tuple[str, str, str]:
    if '://' in repo_id:
        raise CLIError('Only GitHub repositories in `[OWNER/]hf-<name>` format are supported.')
    parts = repo_id.split('/')
    if len(parts) == 1:
        owner = DEFAULT_EXTENSION_OWNER
        repo_name = parts[0]
    elif len(parts) == 2 and all(parts):
        owner, repo_name = parts
    else:
        raise CLIError(f"Expected `[OWNER/]REPO` format, got '{repo_id}'.")
    if not repo_name.startswith('hf-'):
        raise CLIError(f"Extension repository name must start with 'hf-', got '{repo_name}'.")
    short_name = repo_name[3:]
    if not short_name:
        raise CLIError("Invalid extension repository name 'hf-'.")
    _validate_extension_short_name(short_name, original_input=repo_id)
    return (owner, repo_name, short_name)

def _normalize_extension_name(name: str) -> str:
    candidate = name.strip()
    if not candidate:
        raise CLIError('Extension name cannot be empty.')
    normalized = candidate[3:] if candidate.startswith('hf-') else candidate
    return _validate_extension_short_name(normalized, original_input=name)

def _execute_extension_binary(executable_path: Path, args: list[str]) -> int:
    try:
        return subprocess.call([str(executable_path)] + args)
    except OSError as e:
        if os.name == 'nt' or e.errno != errno.ENOEXEC:
            raise
        return subprocess.call(['sh', str(executable_path)] + args)

from __future__ import annotations
import base64
import urllib
import requests
from requests.adapters import HTTPAdapter, Retry
from typing_extensions import override
from fsspec import AbstractFileSystem
from fsspec.spec import AbstractBufferedFile

class DatabricksException(Exception):

    def __init__(self, error_code, message, details=None):
        super().__init__(message)
        self.error_code = error_code
        self.message = message
        self.details = details

class DatabricksFileSystem(AbstractFileSystem):

    def __init__(self, instance, token, **kwargs):
        self.instance = instance
        self.token = token
        self.session = requests.Session()
        self.retries = Retry(total=10, backoff_factor=0.05, status_forcelist=[408, 429, 500, 502, 503, 504])
        self.session.mount('https://', HTTPAdapter(max_retries=self.retries))
        self.session.headers.update({'Authorization': f'Bearer {self.token}'})
        super().__init__(**kwargs)

    @override
    def _ls_from_cache(self, path) -> list[dict[str, str | int]] | None:
        self.dircache.pop(path.rstrip('/'), None)
        parent = self._parent(path)
        if parent in self.dircache:
            for entry in self.dircache[parent]:
                if entry['name'] == path.rstrip('/'):
                    if entry['type'] != 'directory':
                        return [entry]
                    return []
            raise FileNotFoundError(path)

    def ls(self, path, detail=True, **kwargs):
        try:
            out = self._ls_from_cache(path)
        except FileNotFoundError:
            self.dircache.pop(self._parent(path), None)
            out = None
        if not out:
            try:
                r = self._send_to_api(method='get', endpoint='list', json={'path': path})
            except DatabricksException as e:
                if e.error_code == 'RESOURCE_DOES_NOT_EXIST':
                    raise FileNotFoundError(e.message) from e
                raise
            files = r.get('files', [])
            out = [{'name': o['path'], 'type': 'directory' if o['is_dir'] else 'file', 'size': o['file_size']} for o in files]
            self.dircache[path] = out
        if detail:
            return out
        return [o['name'] for o in out]

    def makedirs(self, path, exist_ok=True):
        if not exist_ok:
            try:
                self._send_to_api(method='get', endpoint='get-status', json={'path': path})
                raise FileExistsError(f'Path {path} already exists')
            except DatabricksException as e:
                if e.error_code == 'RESOURCE_DOES_NOT_EXIST':
                    pass
        try:
            self._send_to_api(method='post', endpoint='mkdirs', json={'path': path})
        except DatabricksException as e:
            if e.error_code == 'RESOURCE_ALREADY_EXISTS':
                raise FileExistsError(e.message) from e
            raise
        self.invalidate_cache(self._parent(path))

    def mkdir(self, path, create_parents=True, **kwargs):
        if not create_parents:
            raise NotImplementedError
        self.mkdirs(path, **kwargs)

    def rm(self, path, recursive=False, **kwargs):
        try:
            self._send_to_api(method='post', endpoint='delete', json={'path': path, 'recursive': recursive})
        except DatabricksException as e:
            if e.error_code == 'PARTIAL_DELETE':
                self.rm(path=path, recursive=recursive)
            elif e.error_code == 'IO_ERROR':
                raise OSError(e.message) from e
            raise
        self.invalidate_cache(self._parent(path))

    def mv(self, source_path, destination_path, recursive=False, maxdepth=None, **kwargs):
        if recursive:
            raise NotImplementedError
        if maxdepth:
            raise NotImplementedError
        try:
            self._send_to_api(method='post', endpoint='move', json={'source_path': source_path, 'destination_path': destination_path})
        except DatabricksException as e:
            if e.error_code == 'RESOURCE_DOES_NOT_EXIST':
                raise FileNotFoundError(e.message) from e
            elif e.error_code == 'RESOURCE_ALREADY_EXISTS':
                raise FileExistsError(e.message) from e
            raise
        self.invalidate_cache(self._parent(source_path))
        self.invalidate_cache(self._parent(destination_path))

    def _open(self, path, mode='rb', block_size='default', **kwargs):
        return DatabricksFile(self, path, mode=mode, block_size=block_size, **kwargs)

    def _send_to_api(self, method, endpoint, json):
        if method == 'post':
            session_call = self.session.post
        elif method == 'get':
            session_call = self.session.get
        else:
            raise ValueError(f'Do not understand method {method}')
        url = urllib.parse.urljoin(f'https://{self.instance}/api/2.0/dbfs/', endpoint)
        r = session_call(url, json=json)
        try:
            r.raise_for_status()
        except requests.HTTPError as e:
            try:
                exception_json = e.response.json()
            except Exception:
                raise e from None
            raise DatabricksException(**exception_json) from e
        return r.json()

    def _create_handle(self, path, overwrite=True):
        try:
            r = self._send_to_api(method='post', endpoint='create', json={'path': path, 'overwrite': overwrite})
            return r['handle']
        except DatabricksException as e:
            if e.error_code == 'RESOURCE_ALREADY_EXISTS':
                raise FileExistsError(e.message) from e
            raise

    def _close_handle(self, handle):
        try:
            self._send_to_api(method='post', endpoint='close', json={'handle': handle})
        except DatabricksException as e:
            if e.error_code == 'RESOURCE_DOES_NOT_EXIST':
                raise FileNotFoundError(e.message) from e
            raise

    def _add_data(self, handle, data):
        data = base64.b64encode(data).decode()
        try:
            self._send_to_api(method='post', endpoint='add-block', json={'handle': handle, 'data': data})
        except DatabricksException as e:
            if e.error_code == 'RESOURCE_DOES_NOT_EXIST':
                raise FileNotFoundError(e.message) from e
            elif e.error_code == 'MAX_BLOCK_SIZE_EXCEEDED':
                raise ValueError(e.message) from e
            raise

    def _get_data(self, path, start, end):
        try:
            r = self._send_to_api(method='get', endpoint='read', json={'path': path, 'offset': start, 'length': end - start})
            return base64.b64decode(r['data'])
        except DatabricksException as e:
            if e.error_code == 'RESOURCE_DOES_NOT_EXIST':
                raise FileNotFoundError(e.message) from e
            elif e.error_code in ['INVALID_PARAMETER_VALUE', 'MAX_READ_SIZE_EXCEEDED']:
                raise ValueError(e.message) from e
            raise

    def invalidate_cache(self, path=None):
        if path is None:
            self.dircache.clear()
        else:
            self.dircache.pop(path, None)
        super().invalidate_cache(path)

class DatabricksFile(AbstractBufferedFile):
    DEFAULT_BLOCK_SIZE = 1 * 2 ** 20

    def __init__(self, fs, path, mode='rb', block_size='default', autocommit=True, cache_type='readahead', cache_options=None, **kwargs):
        if block_size is None or block_size == 'default':
            block_size = self.DEFAULT_BLOCK_SIZE
        assert block_size == self.DEFAULT_BLOCK_SIZE, f'Only the default block size is allowed, not {block_size}'
        super().__init__(fs, path, mode=mode, block_size=block_size, autocommit=autocommit, cache_type=cache_type, cache_options=cache_options or {}, **kwargs)

    def _initiate_upload(self):
        self.handle = self.fs._create_handle(self.path)

    def _upload_chunk(self, final=False):
        self.buffer.seek(0)
        data = self.buffer.getvalue()
        data_chunks = [data[start:end] for start, end in self._to_sized_blocks(len(data))]
        for data_chunk in data_chunks:
            self.fs._add_data(handle=self.handle, data=data_chunk)
        if final:
            self.fs._close_handle(handle=self.handle)
            return True

    def _fetch_range(self, start, end):
        return_buffer = b''
        length = end - start
        for chunk_start, chunk_end in self._to_sized_blocks(length, start):
            return_buffer += self.fs._get_data(path=self.path, start=chunk_start, end=chunk_end)
        return return_buffer

    def _to_sized_blocks(self, length, start=0):
        end = start + length
        for data_chunk in range(start, end, self.blocksize):
            data_start = data_chunk
            data_end = min(end, data_chunk + self.blocksize)
            yield (data_start, data_end)

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import TYPE_CHECKING, Any, ClassVar, Literal, Optional, TypedDict, Union
import numpy as np
import pyarrow as pa
from .. import config
from ..download.download_config import DownloadConfig
from ..table import array_cast
from ..utils.file_utils import is_local_path, xopen
from ..utils.py_utils import no_op_if_value_is_null, string_to_dict
if TYPE_CHECKING:
    import torch
    from torchcodec.decoders import VideoDecoder
    from .features import FeatureType

class Example(TypedDict):
    path: Optional[str]
    bytes: Optional[bytes]

@dataclass
class Video:
    decode: bool = True
    stream_index: Optional[int] = None
    dimension_order: Literal['NCHW', 'NHWC'] = 'NCHW'
    num_ffmpeg_threads: int = 1
    device: Optional[Union[str, 'torch.device']] = 'cpu'
    seek_mode: Literal['exact', 'approximate'] = 'exact'
    id: Optional[str] = field(default=None, repr=False)
    dtype: ClassVar[str] = 'torchcodec.decoders.VideoDecoder'
    pa_type: ClassVar[Any] = pa.struct({'bytes': pa.binary(), 'path': pa.string()})
    _type: str = field(default='Video', init=False, repr=False)

    def __call__(self):
        return self.pa_type

    def encode_example(self, value: Union[str, bytes, bytearray, Example, np.ndarray, 'VideoDecoder']) -> Example:
        if value is None:
            raise ValueError('value must be provided')
        if config.TORCHCODEC_AVAILABLE:
            from torchcodec.decoders import VideoDecoder
        else:
            VideoDecoder = None
        if isinstance(value, list):
            value = np.array(value)
        if isinstance(value, str):
            return {'path': value, 'bytes': None}
        elif isinstance(value, Path):
            return {'path': str(value.absolute()), 'bytes': None}
        elif isinstance(value, (bytes, bytearray)):
            return {'path': None, 'bytes': value}
        elif isinstance(value, np.ndarray):
            return encode_np_array(value)
        elif VideoDecoder is not None and isinstance(value, VideoDecoder):
            return encode_torchcodec_video(value)
        elif isinstance(value, dict):
            path, bytes_ = (value.get('path'), value.get('bytes'))
            if path is not None and os.path.isfile(path):
                return {'bytes': None, 'path': path}
            elif bytes_ is not None or path is not None:
                return {'bytes': bytes_, 'path': path}
            else:
                raise ValueError(f"A video sample should have one of 'path' or 'bytes' but they are missing or None in {value}.")
        else:
            raise TypeError(f'Unsupported encode_example type: {type(value)}')

    def decode_example(self, value: Union[str, Example], token_per_repo_id: Optional[dict[str, Union[bool, str]]]=None) -> 'VideoDecoder':
        if not self.decode:
            raise RuntimeError('Decoding is disabled for this feature. Please use Video(decode=True) instead.')
        if config.TORCHCODEC_AVAILABLE:
            from torchcodec.decoders import VideoDecoder
        else:
            raise ImportError("To support decoding videos, please install 'torchcodec'.")
        if token_per_repo_id is None:
            token_per_repo_id = {}
        if isinstance(value, str):
            path, bytes_ = (value, None)
        else:
            path, bytes_ = (value['path'], value['bytes'])
        if bytes_ is None:
            if path is None:
                raise ValueError(f"A video should have one of 'path' or 'bytes' but both are None in {value}.")
            elif is_local_path(path):
                video = VideoDecoder(path, stream_index=self.stream_index, dimension_order=self.dimension_order, num_ffmpeg_threads=self.num_ffmpeg_threads, device=self.device, seek_mode=self.seek_mode)
            else:
                video = hf_video_reader(path, token_per_repo_id=token_per_repo_id, dimension_order=self.dimension_order, num_ffmpeg_threads=self.num_ffmpeg_threads, device=self.device, seek_mode=self.seek_mode)
        else:
            video = VideoDecoder(bytes_, stream_index=self.stream_index, dimension_order=self.dimension_order, num_ffmpeg_threads=self.num_ffmpeg_threads, device=self.device, seek_mode=self.seek_mode)
        video._hf_encoded = {'path': path, 'bytes': bytes_}
        video.metadata.path = path
        return video

    def flatten(self) -> Union['FeatureType', dict[str, 'FeatureType']]:
        from .features import Value
        return self if self.decode else {'bytes': Value('binary'), 'path': Value('string')}

    def cast_storage(self, storage: Union[pa.StringArray, pa.StructArray, pa.ListArray]) -> pa.StructArray:
        if pa.types.is_string(storage.type):
            bytes_array = pa.array([None] * len(storage), type=pa.binary())
            storage = pa.StructArray.from_arrays([bytes_array, storage], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_large_binary(storage.type):
            storage = array_cast(storage, pa.binary())
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_binary(storage.type):
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_struct(storage.type):
            if storage.type.get_field_index('bytes') >= 0:
                bytes_array = storage.field('bytes')
            else:
                bytes_array = pa.array([None] * len(storage), type=pa.binary())
            if storage.type.get_field_index('path') >= 0:
                path_array = storage.field('path')
            else:
                path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([bytes_array, path_array], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_list(storage.type):
            bytes_array = pa.array([encode_np_array(np.array(arr))['bytes'] if arr is not None else None for arr in storage.to_pylist()], type=pa.binary())
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([bytes_array, path_array], ['bytes', 'path'], mask=bytes_array.is_null())
        return array_cast(storage, self.pa_type)

    def embed_storage(self, storage: pa.StructArray, token_per_repo_id=None) -> pa.StructArray:
        if token_per_repo_id is None:
            token_per_repo_id = {}

        @no_op_if_value_is_null
        def path_to_bytes(path):
            source_url = path.split('::')[-1]
            pattern = config.HUB_DATASETS_URL if source_url.startswith(config.HF_ENDPOINT) else config.HUB_DATASETS_HFFS_URL
            source_url_fields = string_to_dict(source_url, pattern)
            token = token_per_repo_id.get(source_url_fields['repo_id']) if source_url_fields is not None else None
            download_config = DownloadConfig(token=token)
            with xopen(path, 'rb', download_config=download_config) as f:
                return f.read()
        bytes_array = pa.array([(path_to_bytes(x['path']) if x['bytes'] is None else x['bytes']) if x is not None else None for x in storage.to_pylist()], type=pa.binary())
        path_array = pa.array([os.path.basename(path) if path is not None else None for path in storage.field('path').to_pylist()], type=pa.string())
        storage = pa.StructArray.from_arrays([bytes_array, path_array], ['bytes', 'path'], mask=bytes_array.is_null())
        return array_cast(storage, self.pa_type)

def video_to_bytes(video: 'VideoDecoder') -> bytes:
    raise NotImplementedError()

def encode_torchcodec_video(video: 'VideoDecoder') -> Example:
    if hasattr(video, '_hf_encoded'):
        return video._hf_encoded
    else:
        raise NotImplementedError("Encoding a VideoDecoder that doesn't come from datasets.Video.decode() is not implemented")

def encode_np_array(array: np.ndarray) -> Example:
    raise NotImplementedError()

def hf_video_reader(path: str, token_per_repo_id: Optional[dict[str, Union[bool, str]]]=None, stream: str='video', dimension_order: Literal['NCHW', 'NHWC']='NCHW', num_ffmpeg_threads: int=1, device: Optional[Union[str, 'torch.device']]='cpu', seek_mode: Literal['exact', 'approximate']='exact') -> 'VideoDecoder':
    from torchcodec.decoders import VideoDecoder
    if token_per_repo_id is None:
        token_per_repo_id = {}
    source_url = path.split('::')[-1]
    pattern = config.HUB_DATASETS_URL if source_url.startswith(config.HF_ENDPOINT) else config.HUB_DATASETS_HFFS_URL
    source_url_fields = string_to_dict(source_url, pattern)
    token = token_per_repo_id.get(source_url_fields['repo_id']) if source_url_fields is not None else None
    download_config = DownloadConfig(token=token)
    f = xopen(path, 'rb', download_config=download_config)
    stream_id = 0 if len(stream.split(':')) == 1 else int(stream.split(':')[1])
    vd = VideoDecoder(f, stream_index=stream_id, dimension_order=dimension_order, num_ffmpeg_threads=num_ffmpeg_threads, device=device, seek_mode=seek_mode)
    return vd

import errno
import io
import os
import secrets
import shutil
from contextlib import suppress
from functools import cached_property, wraps
from urllib.parse import parse_qs
from fsspec.spec import AbstractFileSystem
from fsspec.utils import get_package_version_without_import, infer_storage_options, mirror_from, tokenize

def wrap_exceptions(func):

    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except OSError as exception:
            if not exception.args:
                raise
            message, *args = exception.args
            if isinstance(message, str) and 'does not exist' in message:
                raise FileNotFoundError(errno.ENOENT, message) from exception
            else:
                raise
    return wrapper
PYARROW_VERSION = None

class ArrowFSWrapper(AbstractFileSystem):
    root_marker = '/'

    def __init__(self, fs, **kwargs):
        global PYARROW_VERSION
        PYARROW_VERSION = get_package_version_without_import('pyarrow')
        self.fs = fs
        super().__init__(**kwargs)

    @property
    def protocol(self):
        return self.fs.type_name

    @cached_property
    def fsid(self):
        return 'hdfs_' + tokenize(self.fs.host, self.fs.port)

    @classmethod
    def _strip_protocol(cls, path):
        ops = infer_storage_options(path)
        path = ops['path']
        if path.startswith('//'):
            path = path[1:]
        return path

    def ls(self, path, detail=False, **kwargs):
        path = self._strip_protocol(path)
        from pyarrow.fs import FileSelector
        try:
            entries = [self._make_entry(entry) for entry in self.fs.get_file_info(FileSelector(path))]
        except (FileNotFoundError, NotADirectoryError):
            entries = [self.info(path, **kwargs)]
        if detail:
            return entries
        else:
            return [entry['name'] for entry in entries]

    def info(self, path, **kwargs):
        path = self._strip_protocol(path)
        [info] = self.fs.get_file_info([path])
        return self._make_entry(info)

    def exists(self, path):
        path = self._strip_protocol(path)
        try:
            self.info(path)
        except FileNotFoundError:
            return False
        else:
            return True

    def _make_entry(self, info):
        from pyarrow.fs import FileType
        if info.type is FileType.Directory:
            kind = 'directory'
        elif info.type is FileType.File:
            kind = 'file'
        elif info.type is FileType.NotFound:
            raise FileNotFoundError(errno.ENOENT, os.strerror(errno.ENOENT), info.path)
        else:
            kind = 'other'
        return {'name': info.path, 'size': info.size, 'type': kind, 'mtime': info.mtime}

    @wrap_exceptions
    def cp_file(self, path1, path2, **kwargs):
        path1 = self._strip_protocol(path1).rstrip('/')
        path2 = self._strip_protocol(path2).rstrip('/')
        with self._open(path1, 'rb') as lstream:
            tmp_fname = f'{path2}.tmp.{secrets.token_hex(6)}'
            try:
                with self.open(tmp_fname, 'wb') as rstream:
                    shutil.copyfileobj(lstream, rstream)
                self.fs.move(tmp_fname, path2)
            except BaseException:
                with suppress(FileNotFoundError):
                    self.fs.delete_file(tmp_fname)
                raise

    @wrap_exceptions
    def mv(self, path1, path2, **kwargs):
        path1 = self._strip_protocol(path1).rstrip('/')
        path2 = self._strip_protocol(path2).rstrip('/')
        self.fs.move(path1, path2)

    @wrap_exceptions
    def rm_file(self, path):
        path = self._strip_protocol(path)
        self.fs.delete_file(path)

    @wrap_exceptions
    def rm(self, path, recursive=False, maxdepth=None):
        path = self._strip_protocol(path).rstrip('/')
        if self.isdir(path):
            if recursive:
                self.fs.delete_dir(path)
            else:
                raise ValueError("Can't delete directories without recursive=False")
        else:
            self.fs.delete_file(path)

    @wrap_exceptions
    def _open(self, path, mode='rb', block_size=None, seekable=True, **kwargs):
        if mode == 'rb':
            if seekable:
                method = self.fs.open_input_file
            else:
                method = self.fs.open_input_stream
        elif mode == 'wb':
            method = self.fs.open_output_stream
        elif mode == 'ab':
            method = self.fs.open_append_stream
        else:
            raise ValueError(f'unsupported mode for Arrow filesystem: {mode!r}')
        _kwargs = {}
        if mode != 'rb' or not seekable:
            if int(PYARROW_VERSION.split('.')[0]) >= 4:
                _kwargs['compression'] = None
        stream = method(path, **_kwargs)
        return ArrowFile(self, stream, path, mode, block_size, **kwargs)

    @wrap_exceptions
    def mkdir(self, path, create_parents=True, **kwargs):
        path = self._strip_protocol(path)
        if create_parents:
            self.makedirs(path, exist_ok=True)
        else:
            self.fs.create_dir(path, recursive=False)

    @wrap_exceptions
    def makedirs(self, path, exist_ok=False):
        path = self._strip_protocol(path)
        self.fs.create_dir(path, recursive=True)

    @wrap_exceptions
    def rmdir(self, path):
        path = self._strip_protocol(path)
        self.fs.delete_dir(path)

    @wrap_exceptions
    def modified(self, path):
        path = self._strip_protocol(path)
        return self.fs.get_file_info(path).mtime

    def cat_file(self, path, start=None, end=None, **kwargs):
        kwargs.setdefault('seekable', start not in [None, 0])
        return super().cat_file(path, start=None, end=None, **kwargs)

    def get_file(self, rpath, lpath, **kwargs):
        kwargs.setdefault('seekable', False)
        super().get_file(rpath, lpath, **kwargs)

@mirror_from('stream', ['read', 'seek', 'tell', 'write', 'readable', 'writable', 'close', 'seekable'])
class ArrowFile(io.IOBase):

    def __init__(self, fs, stream, path, mode, block_size=None, **kwargs):
        self.path = path
        self.mode = mode
        self.fs = fs
        self.stream = stream
        self.blocksize = self.block_size = block_size
        self.kwargs = kwargs

    def __enter__(self):
        return self

    @property
    def size(self):
        if self.stream.seekable():
            return self.stream.size()
        return None

    def __exit__(self, *args):
        return self.close()

class HadoopFileSystem(ArrowFSWrapper):
    protocol = 'hdfs'

    def __init__(self, host='default', port=0, user=None, kerb_ticket=None, replication=3, extra_conf=None, **kwargs):
        from pyarrow.fs import HadoopFileSystem
        fs = HadoopFileSystem(host=host, port=port, user=user, kerb_ticket=kerb_ticket, replication=replication, extra_conf=extra_conf)
        super().__init__(fs=fs, **kwargs)

    @staticmethod
    def _get_kwargs_from_urls(path):
        ops = infer_storage_options(path)
        out = {}
        if ops.get('host', None):
            out['host'] = ops['host']
        if ops.get('username', None):
            out['user'] = ops['username']
        if ops.get('port', None):
            out['port'] = ops['port']
        if ops.get('url_query', None):
            queries = parse_qs(ops['url_query'])
            if queries.get('replication', None):
                out['replication'] = int(queries['replication'][0])
        return out

import os
from dataclasses import dataclass, field
from io import BytesIO
from pathlib import Path
from typing import TYPE_CHECKING, Any, ClassVar, Optional, Union
import numpy as np
import pyarrow as pa
from .. import config
from ..download.download_config import DownloadConfig
from ..table import array_cast
from ..utils.file_utils import is_local_path, xopen
from ..utils.py_utils import no_op_if_value_is_null, string_to_dict
if TYPE_CHECKING:
    from torchcodec.decoders import AudioDecoder
    from .features import FeatureType

@dataclass
class Audio:
    sampling_rate: Optional[int] = None
    decode: bool = True
    num_channels: Optional[int] = None
    stream_index: Optional[int] = None
    id: Optional[str] = field(default=None, repr=False)
    dtype: ClassVar[str] = 'dict'
    pa_type: ClassVar[Any] = pa.struct({'bytes': pa.binary(), 'path': pa.string()})
    _type: str = field(default='Audio', init=False, repr=False)

    def __call__(self):
        return self.pa_type

    def encode_example(self, value: Union[str, bytes, bytearray, dict, 'AudioDecoder']) -> dict:
        try:
            import torch
            from torchcodec.encoders import AudioEncoder
        except ImportError as err:
            raise ImportError("To support encoding audio data, please install 'torchcodec'.") from err
        if value is None:
            raise ValueError('value must be provided')
        if config.TORCHCODEC_AVAILABLE:
            from torchcodec.decoders import AudioDecoder
        else:
            AudioDecoder = None
        if isinstance(value, str):
            return {'bytes': None, 'path': value}
        elif isinstance(value, Path):
            return {'bytes': None, 'path': str(value.absolute())}
        elif isinstance(value, (bytes, bytearray)):
            return {'bytes': value, 'path': None}
        elif AudioDecoder is not None and isinstance(value, AudioDecoder):
            return encode_torchcodec_audio(value)
        elif 'array' in value:
            buffer = BytesIO()
            AudioEncoder(torch.from_numpy(value['array'].astype(np.float32)), sample_rate=value['sampling_rate']).to_file_like(buffer, format='wav', num_channels=self.num_channels)
            return {'bytes': buffer.getvalue(), 'path': None}
        elif value.get('path') is not None and os.path.isfile(value['path']):
            if value['path'].endswith('pcm'):
                if value.get('sampling_rate') is None:
                    raise KeyError("To use PCM files, please specify a 'sampling_rate' in Audio object")
                if value.get('bytes'):
                    bytes_value = np.frombuffer(value['bytes'], dtype=np.int16).astype(np.float32) / 32767
                else:
                    bytes_value = np.memmap(value['path'], dtype='h', mode='r').astype(np.float32) / 32767
                buffer = BytesIO()
                AudioEncoder(torch.from_numpy(bytes_value), sample_rate=value['sampling_rate']).to_file_like(buffer, format='wav', num_channels=self.num_channels)
                return {'bytes': buffer.getvalue(), 'path': None}
            else:
                return {'bytes': None, 'path': value.get('path')}
        elif value.get('bytes') is not None or value.get('path') is not None:
            return {'bytes': value.get('bytes'), 'path': value.get('path')}
        else:
            raise ValueError(f"An audio sample should have one of 'path' or 'bytes' but they are missing or None in {value}.")

    def decode_example(self, value: dict, token_per_repo_id: Optional[dict[str, Union[str, bool, None]]]=None) -> 'AudioDecoder':
        if config.TORCHCODEC_AVAILABLE:
            from ._torchcodec import AudioDecoder
        else:
            raise ImportError("To support decoding audio data, please install 'torchcodec'.")
        if not self.decode:
            raise RuntimeError('Decoding is disabled for this feature. Please use Audio(decode=True) instead.')
        path, bytes = (value['path'], value['bytes']) if value['bytes'] is not None else (value['path'], None)
        if path is None and bytes is None:
            raise ValueError(f"An audio sample should have one of 'path' or 'bytes' but both are None in {value}.")
        if bytes is None and is_local_path(path):
            audio = AudioDecoder(path, stream_index=self.stream_index, sample_rate=self.sampling_rate, num_channels=self.num_channels)
        elif bytes is None:
            token_per_repo_id = token_per_repo_id or {}
            source_url = path.split('::')[-1]
            pattern = config.HUB_DATASETS_URL if source_url.startswith(config.HF_ENDPOINT) else config.HUB_DATASETS_HFFS_URL
            source_url_fields = string_to_dict(source_url, pattern)
            token = token_per_repo_id.get(source_url_fields['repo_id']) if source_url_fields is not None else None
            download_config = DownloadConfig(token=token)
            f = xopen(path, 'rb', download_config=download_config)
            audio = AudioDecoder(f, stream_index=self.stream_index, sample_rate=self.sampling_rate, num_channels=self.num_channels)
        else:
            audio = AudioDecoder(bytes, stream_index=self.stream_index, sample_rate=self.sampling_rate, num_channels=self.num_channels)
        audio._hf_encoded = {'path': path, 'bytes': bytes}
        audio.metadata.path = path
        return audio

    def flatten(self) -> Union['FeatureType', dict[str, 'FeatureType']]:
        from .features import Value
        if self.decode:
            raise ValueError('Cannot flatten a decoded Audio feature.')
        return {'bytes': Value('binary'), 'path': Value('string')}

    def cast_storage(self, storage: Union[pa.StringArray, pa.StructArray]) -> pa.StructArray:
        if pa.types.is_string(storage.type):
            bytes_array = pa.array([None] * len(storage), type=pa.binary())
            storage = pa.StructArray.from_arrays([bytes_array, storage], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_large_binary(storage.type):
            storage = array_cast(storage, pa.binary())
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_binary(storage.type):
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_struct(storage.type) and storage.type.get_all_field_indices('array'):
            storage = pa.array([Audio().encode_example(x) if x is not None else None for x in storage.to_numpy(zero_copy_only=False)])
        elif pa.types.is_struct(storage.type):
            if storage.type.get_field_index('bytes') >= 0:
                bytes_array = storage.field('bytes')
            else:
                bytes_array = pa.array([None] * len(storage), type=pa.binary())
            if storage.type.get_field_index('path') >= 0:
                path_array = storage.field('path')
            else:
                path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([bytes_array, path_array], ['bytes', 'path'], mask=storage.is_null())
        return array_cast(storage, self.pa_type)

    def embed_storage(self, storage: pa.StructArray, token_per_repo_id=None) -> pa.StructArray:
        if token_per_repo_id is None:
            token_per_repo_id = {}

        @no_op_if_value_is_null
        def path_to_bytes(path):
            source_url = path.split('::')[-1]
            pattern = config.HUB_DATASETS_URL if source_url.startswith(config.HF_ENDPOINT) else config.HUB_DATASETS_HFFS_URL
            source_url_fields = string_to_dict(source_url, pattern)
            token = token_per_repo_id.get(source_url_fields['repo_id']) if source_url_fields is not None else None
            download_config = DownloadConfig(token=token)
            with xopen(path, 'rb', download_config=download_config) as f:
                return f.read()
        bytes_array = pa.array([(path_to_bytes(x['path']) if x['bytes'] is None else x['bytes']) if x is not None else None for x in storage.to_pylist()], type=pa.binary())
        path_array = pa.array([os.path.basename(path) if path is not None else None for path in storage.field('path').to_pylist()], type=pa.string())
        storage = pa.StructArray.from_arrays([bytes_array, path_array], ['bytes', 'path'], mask=bytes_array.is_null())
        return array_cast(storage, self.pa_type)

def encode_torchcodec_audio(audio: 'AudioDecoder') -> dict:
    if hasattr(audio, '_hf_encoded'):
        return audio._hf_encoded
    else:
        try:
            from torchcodec.encoders import AudioEncoder
        except ImportError as err:
            raise ImportError("To support encoding audio data, please install 'torchcodec'.") from err
        samples = audio.get_all_samples()
        buffer = BytesIO()
        num_channels = samples.data.shape[0]
        AudioEncoder(samples.data.cpu(), sample_rate=samples.sample_rate).to_file_like(buffer, format='wav', num_channels=num_channels)
        return {'bytes': buffer.getvalue(), 'path': None}

import os
