_SUB_SPEC_RE = re.compile(f'\n^\n (?P<split>{_split_re[1:-1]})\n (\\[\n    ((?P<from>-?[\\d_]+)\n     (?P<from_pct>%)?)?\n    :\n    ((?P<to>-?[\\d_]+)\n     (?P<to_pct>%)?)?\n \\])?(\\((?P<rounding>[^\\)]*)\\))?\n$\n', re.X)
_ADDITION_SEP_RE = re.compile('\\s*\\+\\s*')

