@validate_hf_hub_args
def snapshot_download(repo_id: str, *, repo_type: Optional[str]=None, revision: Optional[str]=None, cache_dir: Union[str, Path, None]=None, local_dir: Union[str, Path, None]=None, library_name: Optional[str]=None, library_version: Optional[str]=None, user_agent: Optional[Union[dict, str]]=None, etag_timeout: float=constants.DEFAULT_ETAG_TIMEOUT, force_download: bool=False, token: Optional[Union[bool, str]]=None, local_files_only: bool=False, allow_patterns: Optional[Union[list[str], str]]=None, ignore_patterns: Optional[Union[list[str], str]]=None, max_workers: int=8, tqdm_class: Optional[type[base_tqdm]]=None, headers: Optional[dict[str, str]]=None, endpoint: Optional[str]=None, dry_run: bool=False) -> Union[str, list[DryRunFileInfo]]:
    if cache_dir is None:
        cache_dir = constants.HF_HUB_CACHE
    if revision is None:
        revision = constants.DEFAULT_REVISION
    if isinstance(cache_dir, Path):
        cache_dir = str(cache_dir)
    if repo_type is None:
        repo_type = 'model'
    if repo_type not in constants.REPO_TYPES:
        raise ValueError(f'Invalid repo type: {repo_type}. Accepted repo types are: {str(constants.REPO_TYPES)}')
    storage_folder = os.path.join(cache_dir, repo_folder_name(repo_id=repo_id, repo_type=repo_type))
    api = HfApi(library_name=library_name, library_version=library_version, user_agent=user_agent, endpoint=endpoint, headers=headers, token=token)
    repo_info: Union[ModelInfo, DatasetInfo, SpaceInfo, None] = None
    api_call_error: Optional[Exception] = None
    if not local_files_only:
        try:
            repo_info = api.repo_info(repo_id=repo_id, repo_type=repo_type, revision=revision)
        except httpx.ProxyError:
            raise
        except (httpx.ConnectError, httpx.TimeoutException, OfflineModeIsEnabled) as error:
            api_call_error = error
            pass
        except RevisionNotFoundError:
            raise
        except HfHubHTTPError as error:
            api_call_error = error
            pass
    if repo_info is None:
        if dry_run:
            raise DryRunError('Dry run cannot be performed as the repository cannot be accessed. Please check your internet connection or authentication token.') from api_call_error
        commit_hash = None
        if REGEX_COMMIT_HASH.match(revision):
            commit_hash = revision
        else:
            ref_path = os.path.join(storage_folder, 'refs', revision)
            if os.path.exists(ref_path):
                with open(ref_path) as f:
                    commit_hash = f.read()
        if commit_hash is not None and local_dir is None:
            snapshot_folder = os.path.join(storage_folder, 'snapshots', commit_hash)
            if os.path.exists(snapshot_folder):
                return snapshot_folder
        if local_dir is not None:
            local_dir = Path(local_dir)
            if local_dir.is_dir() and any(local_dir.iterdir()):
                logger.warning(f'Returning existing local_dir `{local_dir}` as remote repo cannot be accessed in `snapshot_download` ({api_call_error}).')
                return str(local_dir.resolve())
        if local_files_only:
            raise LocalEntryNotFoundError("Cannot find an appropriate cached snapshot folder for the specified revision on the local disk and outgoing traffic has been disabled. To enable repo look-ups and downloads online, pass 'local_files_only=False' as input.")
        elif isinstance(api_call_error, OfflineModeIsEnabled):
            raise LocalEntryNotFoundError("Cannot find an appropriate cached snapshot folder for the specified revision on the local disk and outgoing traffic has been disabled. To enable repo look-ups and downloads online, set 'HF_HUB_OFFLINE=0' as environment variable.") from api_call_error
        elif isinstance(api_call_error, (RepositoryNotFoundError, GatedRepoError)) or (isinstance(api_call_error, HfHubHTTPError) and api_call_error.response.status_code == 401):
            raise api_call_error
        else:
            raise LocalEntryNotFoundError(f'Got: {api_call_error.__class__.__name__}: {api_call_error}\nAn error happened while trying to locate the files on the Hub and we cannot find the appropriate snapshot folder for the specified revision on the local disk. Please check your internet connection and try again.') from api_call_error
    assert repo_info.sha is not None, 'Repo info returned from server must have a revision sha.'
    repo_files: Iterable[str] = [f.rfilename for f in repo_info.siblings] if repo_info.siblings is not None else []
    unreliable_nb_files = repo_info.siblings is None or len(repo_info.siblings) == 0 or len(repo_info.siblings) > LARGE_REPO_THRESHOLD
    if unreliable_nb_files:
        logger.info('Number of files in the repo is unreliable. Using `list_repo_tree` to ensure all files are listed.')
        repo_files = (f.rfilename for f in api.list_repo_tree(repo_id=repo_id, recursive=True, revision=revision, repo_type=repo_type) if isinstance(f, RepoFile))
    filtered_repo_files: Iterable[str] = filter_repo_objects(items=repo_files, allow_patterns=allow_patterns, ignore_patterns=ignore_patterns)
    if not unreliable_nb_files:
        filtered_repo_files = list(filtered_repo_files)
        tqdm_desc = f'Fetching {len(filtered_repo_files)} files'
    else:
        tqdm_desc = 'Fetching ... files'
    if dry_run:
        tqdm_desc = '[dry-run] ' + tqdm_desc
    commit_hash = repo_info.sha
    snapshot_folder = os.path.join(storage_folder, 'snapshots', commit_hash)
    if revision != commit_hash:
        ref_path = os.path.join(storage_folder, 'refs', revision)
        try:
            os.makedirs(os.path.dirname(ref_path), exist_ok=True)
            with open(ref_path, 'w') as f:
                f.write(commit_hash)
        except OSError as e:
            logger.warning(f'Ignored error while writing commit hash to {ref_path}: {e}.')
    results: List[Union[str, DryRunFileInfo]] = []
    tqdm_class = tqdm_class or hf_tqdm
    bytes_progress = tqdm_class(desc='Downloading (incomplete total...)', disable=is_tqdm_disabled(log_level=logger.getEffectiveLevel()), total=0, initial=0, unit='B', unit_scale=True, name='huggingface_hub.snapshot_download')

    class _AggregatedTqdm:

        def __init__(self, *args, **kwargs):
            total = kwargs.pop('total', None)
            if total is not None:
                bytes_progress.total += total
                bytes_progress.refresh()
            initial = kwargs.pop('initial', 0)
            if initial:
                bytes_progress.update(initial)

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc_value, traceback):
            pass

        def update(self, n: Optional[Union[int, float]]=1) -> None:
            bytes_progress.update(n)

    def _inner_hf_hub_download(repo_file: str) -> None:
        results.append(hf_hub_download(repo_id, filename=repo_file, repo_type=repo_type, revision=commit_hash, endpoint=endpoint, cache_dir=cache_dir, local_dir=local_dir, library_name=library_name, library_version=library_version, user_agent=user_agent, etag_timeout=etag_timeout, force_download=force_download, token=token, headers=headers, tqdm_class=_AggregatedTqdm, dry_run=dry_run))
    thread_map(_inner_hf_hub_download, filtered_repo_files, desc=tqdm_desc, max_workers=max_workers, tqdm_class=tqdm_class)
    bytes_progress.set_description('Download complete')
    if dry_run:
        assert all((isinstance(r, DryRunFileInfo) for r in results))
        return results
    if local_dir is not None:
        return str(os.path.realpath(local_dir))
    return snapshot_folder

from __future__ import annotations
import inspect
import warnings
from json import dumps as json_dumps
from typing import Any, AsyncIterable, AsyncIterator, Iterable, Iterator, Mapping
from urllib.parse import urlencode
from ._exceptions import StreamClosed, StreamConsumed
from ._multipart import MultipartStream
from ._types import AsyncByteStream, RequestContent, RequestData, RequestFiles, ResponseContent, SyncByteStream
from ._utils import peek_filelike_length, primitive_value_to_str
__all__ = ['ByteStream']

class ByteStream(AsyncByteStream, SyncByteStream):

    def __init__(self, stream: bytes) -> None:
        self._stream = stream

    def __iter__(self) -> Iterator[bytes]:
        yield self._stream

    async def __aiter__(self) -> AsyncIterator[bytes]:
        yield self._stream

class IteratorByteStream(SyncByteStream):
    CHUNK_SIZE = 65536

    def __init__(self, stream: Iterable[bytes]) -> None:
        self._stream = stream
        self._is_stream_consumed = False
        self._is_generator = inspect.isgenerator(stream)

    def __iter__(self) -> Iterator[bytes]:
        if self._is_stream_consumed and self._is_generator:
            raise StreamConsumed()
        self._is_stream_consumed = True
        if hasattr(self._stream, 'read'):
            chunk = self._stream.read(self.CHUNK_SIZE)
            while chunk:
                yield chunk
                chunk = self._stream.read(self.CHUNK_SIZE)
        else:
            for part in self._stream:
                yield part

class AsyncIteratorByteStream(AsyncByteStream):
    CHUNK_SIZE = 65536

    def __init__(self, stream: AsyncIterable[bytes]) -> None:
        self._stream = stream
        self._is_stream_consumed = False
        self._is_generator = inspect.isasyncgen(stream)

    async def __aiter__(self) -> AsyncIterator[bytes]:
        if self._is_stream_consumed and self._is_generator:
            raise StreamConsumed()
        self._is_stream_consumed = True
        if hasattr(self._stream, 'aread'):
            chunk = await self._stream.aread(self.CHUNK_SIZE)
            while chunk:
                yield chunk
                chunk = await self._stream.aread(self.CHUNK_SIZE)
        else:
            async for part in self._stream:
                yield part

class UnattachedStream(AsyncByteStream, SyncByteStream):

    def __iter__(self) -> Iterator[bytes]:
        raise StreamClosed()

    async def __aiter__(self) -> AsyncIterator[bytes]:
        raise StreamClosed()
        yield b''

def encode_content(content: str | bytes | Iterable[bytes] | AsyncIterable[bytes]) -> tuple[dict[str, str], SyncByteStream | AsyncByteStream]:
    if isinstance(content, (bytes, str)):
        body = content.encode('utf-8') if isinstance(content, str) else content
        content_length = len(body)
        headers = {'Content-Length': str(content_length)} if body else {}
        return (headers, ByteStream(body))
    elif isinstance(content, Iterable) and (not isinstance(content, dict)):
        content_length_or_none = peek_filelike_length(content)
        if content_length_or_none is None:
            headers = {'Transfer-Encoding': 'chunked'}
        else:
            headers = {'Content-Length': str(content_length_or_none)}
        return (headers, IteratorByteStream(content))
    elif isinstance(content, AsyncIterable):
        headers = {'Transfer-Encoding': 'chunked'}
        return (headers, AsyncIteratorByteStream(content))
    raise TypeError(f"Unexpected type for 'content', {type(content)!r}")

def encode_urlencoded_data(data: RequestData) -> tuple[dict[str, str], ByteStream]:
    plain_data = []
    for key, value in data.items():
        if isinstance(value, (list, tuple)):
            plain_data.extend([(key, primitive_value_to_str(item)) for item in value])
        else:
            plain_data.append((key, primitive_value_to_str(value)))
    body = urlencode(plain_data, doseq=True).encode('utf-8')
    content_length = str(len(body))
    content_type = 'application/x-www-form-urlencoded'
    headers = {'Content-Length': content_length, 'Content-Type': content_type}
    return (headers, ByteStream(body))

def encode_multipart_data(data: RequestData, files: RequestFiles, boundary: bytes | None) -> tuple[dict[str, str], MultipartStream]:
    multipart = MultipartStream(data=data, files=files, boundary=boundary)
    headers = multipart.get_headers()
    return (headers, multipart)

def encode_text(text: str) -> tuple[dict[str, str], ByteStream]:
    body = text.encode('utf-8')
    content_length = str(len(body))
    content_type = 'text/plain; charset=utf-8'
    headers = {'Content-Length': content_length, 'Content-Type': content_type}
    return (headers, ByteStream(body))

def encode_html(html: str) -> tuple[dict[str, str], ByteStream]:
    body = html.encode('utf-8')
    content_length = str(len(body))
    content_type = 'text/html; charset=utf-8'
    headers = {'Content-Length': content_length, 'Content-Type': content_type}
    return (headers, ByteStream(body))

def encode_json(json: Any) -> tuple[dict[str, str], ByteStream]:
    body = json_dumps(json, ensure_ascii=False, separators=(',', ':'), allow_nan=False).encode('utf-8')
    content_length = str(len(body))
    content_type = 'application/json'
    headers = {'Content-Length': content_length, 'Content-Type': content_type}
    return (headers, ByteStream(body))

def encode_request(content: RequestContent | None=None, data: RequestData | None=None, files: RequestFiles | None=None, json: Any | None=None, boundary: bytes | None=None) -> tuple[dict[str, str], SyncByteStream | AsyncByteStream]:
    if data is not None and (not isinstance(data, Mapping)):
        message = "Use 'content=<...>' to upload raw bytes/text content."
        warnings.warn(message, DeprecationWarning, stacklevel=2)
        return encode_content(data)
    if content is not None:
        return encode_content(content)
    elif files:
        return encode_multipart_data(data or {}, files, boundary)
    elif data:
        return encode_urlencoded_data(data)
    elif json is not None:
        return encode_json(json)
    return ({}, ByteStream(b''))

def encode_response(content: ResponseContent | None=None, text: str | None=None, html: str | None=None, json: Any | None=None) -> tuple[dict[str, str], SyncByteStream | AsyncByteStream]:
    if content is not None:
        return encode_content(content)
    elif text is not None:
        return encode_text(text)
    elif html is not None:
        return encode_html(html)
    elif json is not None:
        return encode_json(json)
    return ({}, ByteStream(b''))

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import TYPE_CHECKING, Any, ClassVar, Dict, Optional, Union
import pyarrow as pa
from .. import config
from ..download.download_config import DownloadConfig
from ..table import array_cast
from ..utils.file_utils import is_local_path, xopen
from ..utils.py_utils import no_op_if_value_is_null, string_to_dict
if TYPE_CHECKING:
    import nibabel as nib
    from .features import FeatureType
if config.NIBABEL_AVAILABLE:
    import nibabel as nib

    class Nifti1ImageWrapper(nib.nifti1.Nifti1Image):

        def __init__(self, nifti_image: nib.nifti1.Nifti1Image):
            super().__init__(dataobj=nifti_image.dataobj, affine=nifti_image.affine, header=nifti_image.header, extra=nifti_image.extra, file_map=nifti_image.file_map, dtype=nifti_image.get_data_dtype())
            self.nifti_image = nifti_image

        def _repr_html_(self):
            from ipyniivue import NiiVue, ShowRender, SliceType, Volume
            from IPython.display import display
            bytes_ = self.nifti_image.to_bytes()
            nv = NiiVue()
            nv.set_slice_type(SliceType.MULTIPLANAR)
            nv.opts.multiplanar_show_render = ShowRender.ALWAYS
            nv.opts.show_3d_crosshair = True
            nv.opts.multiplanar_force_render = True
            name = None
            if hasattr(self.nifti_image, 'file_map'):
                if 'image' in self.nifti_image.file_map and getattr(self.nifti_image.file_map['image'], 'filename', None) is not None:
                    name = self.nifti_image.file_map['image'].filename
            if name is None:
                name = 'volume.nii.gz'
            volume = Volume(name=name, data=bytes_)
            nv.load_volumes([volume])
            display(nv)

@dataclass
class Nifti:
    decode: bool = True
    id: Optional[str] = field(default=None, repr=False)
    dtype: ClassVar[str] = 'nibabel.nifti1.Nifti1Image'
    pa_type: ClassVar[Any] = pa.struct({'bytes': pa.binary(), 'path': pa.string()})
    _type: str = field(default='Nifti', init=False, repr=False)

    def __call__(self):
        return self.pa_type

    def encode_example(self, value: Union[str, bytes, bytearray, dict, 'nib.Nifti1Image']) -> dict:
        if config.NIBABEL_AVAILABLE:
            import nibabel as nib
        else:
            nib = None
        if isinstance(value, str):
            return {'path': value, 'bytes': None}
        elif isinstance(value, Path):
            return {'path': str(value.absolute()), 'bytes': None}
        elif isinstance(value, (bytes, bytearray)):
            return {'path': None, 'bytes': value}
        elif nib is not None and isinstance(value, nib.spatialimages.SpatialImage):
            return encode_nibabel_image(value)
        elif isinstance(value, dict):
            if value.get('path') is not None and os.path.isfile(value['path']):
                return {'bytes': None, 'path': value.get('path')}
            elif value.get('bytes') is not None or value.get('path') is not None:
                return {'bytes': value.get('bytes'), 'path': value.get('path')}
            else:
                raise ValueError(f"A nifti sample should have one of 'path' or 'bytes' but they are missing or None in {value}.")
        else:
            raise ValueError(f'A nifti sample should be a string, bytes, Path, nibabel image, or dict, but got {type(value)}.')

    def decode_example(self, value: dict, token_per_repo_id=None) -> 'Nifti1ImageWrapper':
        if config.NIBABEL_AVAILABLE:
            import nibabel as nib
        else:
            raise ImportError("To support decoding NIfTI files, please install 'nibabel'.")
        if token_per_repo_id is None:
            token_per_repo_id = {}
        path, bytes_ = (value['path'], value['bytes'])
        if bytes_ is None:
            if path is None:
                raise ValueError(f"A nifti should have one of 'path' or 'bytes' but both are None in {value}.")
            else:
                if path.startswith('gzip://') and is_local_path(path.split('::')[-1]):
                    path = path.split('::')[-1]
                if is_local_path(path):
                    nifti = nib.load(path)
                else:
                    source_url = path.split('::')[-1]
                    pattern = config.HUB_DATASETS_URL if source_url.startswith(config.HF_ENDPOINT) else config.HUB_DATASETS_HFFS_URL
                    source_url_fields = string_to_dict(source_url, pattern)
                    token = token_per_repo_id.get(source_url_fields['repo_id']) if source_url_fields is not None else None
                    download_config = DownloadConfig(token=token)
                    with xopen(path, 'rb', download_config=download_config) as f:
                        nifti = nib.load(f)
        else:
            import gzip
            if bytes_[:2] == b'\x1f\x8b':
                bytes_ = gzip.decompress(bytes_)
            nifti = nib.Nifti1Image.from_bytes(bytes_)
        return Nifti1ImageWrapper(nifti)

    def embed_storage(self, storage: pa.StructArray, token_per_repo_id=None) -> pa.StructArray:
        if token_per_repo_id is None:
            token_per_repo_id = {}

        @no_op_if_value_is_null
        def path_to_bytes(path):
            source_url = path.split('::')[-1]
            pattern = config.HUB_DATASETS_URL if source_url.startswith(config.HF_ENDPOINT) else config.HUB_DATASETS_HFFS_URL
            source_url_fields = string_to_dict(source_url, pattern)
            token = token_per_repo_id.get(source_url_fields['repo_id']) if source_url_fields is not None else None
            download_config = DownloadConfig(token=token)
            with xopen(path, 'rb', download_config=download_config) as f:
                return f.read()
        bytes_array = pa.array([(path_to_bytes(x['path']) if x['bytes'] is None else x['bytes']) if x is not None else None for x in storage.to_pylist()], type=pa.binary())
        path_array = pa.array([os.path.basename(path) if path is not None else None for path in storage.field('path').to_pylist()], type=pa.string())
        storage = pa.StructArray.from_arrays([bytes_array, path_array], ['bytes', 'path'], mask=bytes_array.is_null())
        return array_cast(storage, self.pa_type)

    def flatten(self) -> Union['FeatureType', Dict[str, 'FeatureType']]:
        from .features import Value
        return self if self.decode else {'bytes': Value('binary'), 'path': Value('string')}

    def cast_storage(self, storage: Union[pa.StringArray, pa.StructArray, pa.BinaryArray]) -> pa.StructArray:
        if pa.types.is_string(storage.type):
            bytes_array = pa.array([None] * len(storage), type=pa.binary())
            storage = pa.StructArray.from_arrays([bytes_array, storage], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_binary(storage.type):
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ['bytes', 'path'], mask=storage.is_null())
        elif pa.types.is_struct(storage.type):
            if storage.type.get_field_index('bytes') >= 0:
                bytes_array = storage.field('bytes')
            else:
                bytes_array = pa.array([None] * len(storage), type=pa.binary())
            if storage.type.get_field_index('path') >= 0:
                path_array = storage.field('path')
            else:
                path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([bytes_array, path_array], ['bytes', 'path'], mask=storage.is_null())
        return array_cast(storage, self.pa_type)

def encode_nibabel_image(img: 'nib.Nifti1Image', force_bytes: bool=False) -> dict[str, Optional[Union[str, bytes]]]:
    if hasattr(img, 'file_map') and img.file_map is not None and (not force_bytes):
        filename = img.file_map['image'].filename
        return {'path': filename, 'bytes': None}
    bytes_data = img.to_bytes()
    return {'path': None, 'bytes': bytes_data}

from __future__ import annotations
import os
import pickle
import time
from typing import TYPE_CHECKING
from fsspec.utils import atomic_write
try:
    import ujson as json
except ImportError:
    if not TYPE_CHECKING:
        import json
if TYPE_CHECKING:
    from collections.abc import Iterator
    from typing import Any, Literal, TypeAlias
    from .cached import CachingFileSystem
    Detail: TypeAlias = dict[str, Any]

class CacheMetadata:

    def __init__(self, storage: list[str]):
        if not storage:
            raise ValueError('CacheMetadata expects at least one storage location')
        self._storage = storage
        self.cached_files: list[Detail] = [{}]
        self._force_save_pickle = False

    def _load(self, fn: str) -> Detail:
        try:
            with open(fn, 'r') as f:
                loaded = json.load(f)
        except ValueError:
            with open(fn, 'rb') as f:
                loaded = pickle.load(f)
        for c in loaded.values():
            if isinstance(c.get('blocks'), list):
                c['blocks'] = set(c['blocks'])
        return loaded

    def _save(self, metadata_to_save: Detail, fn: str) -> None:
        if self._force_save_pickle:
            with atomic_write(fn) as f:
                pickle.dump(metadata_to_save, f)
        else:
            with atomic_write(fn, mode='w') as f:
                json.dump(metadata_to_save, f)

    def _scan_locations(self, writable_only: bool=False) -> Iterator[tuple[str, str, bool]]:
        n = len(self._storage)
        for i, storage in enumerate(self._storage):
            writable = i == n - 1
            if writable_only and (not writable):
                continue
            yield (os.path.join(storage, 'cache'), storage, writable)

    def check_file(self, path: str, cfs: CachingFileSystem | None) -> Literal[False] | tuple[Detail, str]:
        for (fn, base, _), cache in zip(self._scan_locations(), self.cached_files):
            if path not in cache:
                continue
            detail = cache[path].copy()
            if cfs is not None:
                if cfs.check_files and detail['uid'] != cfs.fs.ukey(path):
                    continue
                if cfs.expiry and time.time() - detail['time'] > cfs.expiry:
                    continue
            fn = os.path.join(base, detail['fn'])
            if os.path.exists(fn):
                return (detail, fn)
        return False

    def clear_expired(self, expiry_time: int) -> tuple[list[str], bool]:
        expired_files = []
        for path, detail in self.cached_files[-1].copy().items():
            if time.time() - detail['time'] > expiry_time:
                fn = detail.get('fn', '')
                if not fn:
                    raise RuntimeError(f"Cache metadata does not contain 'fn' for {path}")
                fn = os.path.join(self._storage[-1], fn)
                expired_files.append(fn)
                self.cached_files[-1].pop(path)
        if self.cached_files[-1]:
            cache_path = os.path.join(self._storage[-1], 'cache')
            self._save(self.cached_files[-1], cache_path)
        writable_cache_empty = not self.cached_files[-1]
        return (expired_files, writable_cache_empty)

    def load(self) -> None:
        cached_files = []
        for fn, _, _ in self._scan_locations():
            if os.path.exists(fn):
                cached_files.append(self._load(fn))
            else:
                cached_files.append({})
        self.cached_files = cached_files or [{}]

    def on_close_cached_file(self, f: Any, path: str) -> None:
        c = self.cached_files[-1][path]
        if c['blocks'] is not True and len(c['blocks']) * f.blocksize >= f.size:
            c['blocks'] = True

    def pop_file(self, path: str) -> str | None:
        details = self.check_file(path, None)
        if not details:
            return None
        _, fn = details
        if fn.startswith(self._storage[-1]):
            self.cached_files[-1].pop(path)
            self.save()
        else:
            raise PermissionError('Can only delete cached file in last, writable cache location')
        return fn

    def save(self) -> None:
        for (fn, _, writable), cache in zip(self._scan_locations(), self.cached_files):
            if not writable:
                continue
            if os.path.exists(fn):
                cached_files = self._load(fn)
                for k, c in cached_files.items():
                    if k in cache:
                        if c['blocks'] is True or cache[k]['blocks'] is True:
                            c['blocks'] = True
                        else:
                            blocks = cache[k]['blocks']
                            blocks.update(c['blocks'])
                            c['blocks'] = blocks
                        c['time'] = max(c['time'], cache[k]['time'])
                        c['uid'] = cache[k]['uid']
                for k, c in cache.items():
                    if k not in cached_files:
                        cached_files[k] = c
            else:
                cached_files = cache
            cache = {k: v.copy() for k, v in cached_files.items()}
            for c in cache.values():
                if isinstance(c['blocks'], set):
                    c['blocks'] = list(c['blocks'])
            self._save(cache, fn)
            self.cached_files[-1] = cached_files

    def update_file(self, path: str, detail: Detail) -> None:
        self.cached_files[-1][path] = detail

import base64
import io
import json
import logging
import mimetypes
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING, Any, AsyncIterable, BinaryIO, Iterable, Literal, NoReturn, Optional, Union, overload
import httpx
from huggingface_hub.errors import GenerationError, HfHubHTTPError, IncompleteGenerationError, OverloadedError, TextGenerationError, UnknownError, ValidationError
from ..utils import get_session, is_numpy_available, is_pillow_available
from ._generated.types import ChatCompletionStreamOutput, TextGenerationStreamOutput
if TYPE_CHECKING:
    from PIL.Image import Image
UrlT = str
PathT = Union[str, Path]
ContentT = Union[bytes, BinaryIO, PathT, UrlT, 'Image', bytearray, memoryview]
TASKS_EXPECTING_IMAGES = {'text-to-image', 'image-to-image'}
logger = logging.getLogger(__name__)

@dataclass
class RequestParameters:
    url: str
    task: str
    model: Optional[str]
    json: Optional[Union[str, dict, list]]
    data: Optional[bytes]
    headers: dict[str, Any]

class MimeBytes(bytes):
    mime_type: Optional[str]

    def __new__(cls, data: bytes, mime_type: Optional[str]=None):
        obj = super().__new__(cls, data)
        obj.mime_type = mime_type
        if isinstance(data, MimeBytes) and mime_type is None:
            obj.mime_type = data.mime_type
        return obj

def _import_numpy():
    if not is_numpy_available():
        raise ImportError('Please install numpy to use deal with embeddings (`pip install numpy`).')
    import numpy
    return numpy

def _import_pil_image():
    if not is_pillow_available():
        raise ImportError("Please install Pillow to use deal with images (`pip install Pillow`). If you don't want the image to be post-processed, use `client.post(...)` and get the raw response from the server.")
    from PIL import Image
    return Image

@overload
def _open_as_mime_bytes(content: ContentT) -> MimeBytes:
    ...

@overload
def _open_as_mime_bytes(content: Literal[None]) -> Literal[None]:
    ...

def _open_as_mime_bytes(content: Optional[ContentT]) -> Optional[MimeBytes]:
    if content is None:
        return None
    if isinstance(content, bytes):
        return MimeBytes(content)
    if isinstance(content, (bytearray, memoryview)):
        return MimeBytes(bytes(content))
    if hasattr(content, 'read'):
        logger.debug('Reading content from BinaryIO')
        data = content.read()
        mime_type = mimetypes.guess_type(str(content.name))[0] if hasattr(content, 'name') else None
        if isinstance(data, str):
            raise TypeError('Expected binary stream (bytes), but got text stream')
        return MimeBytes(data, mime_type=mime_type)
    if isinstance(content, str):
        if content.startswith('https://') or content.startswith('http://'):
            logger.debug(f'Downloading content from {content}')
            response = get_session().get(content)
            mime_type = response.headers.get('Content-Type')
            if mime_type is None:
                mime_type = mimetypes.guess_type(content)[0]
            return MimeBytes(response.content, mime_type=mime_type)
        content = Path(content)
        if not content.exists():
            raise FileNotFoundError(f'File not found at {content}. If `data` is a string, it must either be a URL or a path to a local file. To pass raw content, please encode it as bytes first.')
    if isinstance(content, Path):
        logger.debug(f'Opening content from {content}')
        return MimeBytes(content.read_bytes(), mime_type=mimetypes.guess_type(content)[0])
    if is_pillow_available():
        from PIL import Image
        if isinstance(content, Image.Image):
            logger.debug('Converting PIL Image to bytes')
            buffer = io.BytesIO()
            format = content.format or 'PNG'
            content.save(buffer, format=format)
            return MimeBytes(buffer.getvalue(), mime_type=f'image/{format.lower()}')
    raise TypeError(f'Unsupported content type: {type(content)}. Expected one of: bytes, bytearray, BinaryIO, memoryview, Path, str (URL or file path), or PIL.Image.Image.')

def _b64_encode(content: ContentT) -> str:
    raw_bytes = _open_as_mime_bytes(content)
    return base64.b64encode(raw_bytes).decode()

def _as_url(content: ContentT, default_mime_type: str) -> str:
    if isinstance(content, str) and content.startswith(('http://', 'https://', 'data:')):
        return content
    raw_bytes = _open_as_mime_bytes(content)
    mime_type = raw_bytes.mime_type or default_mime_type
    encoded_data = base64.b64encode(raw_bytes).decode()
    return f'data:{mime_type};base64,{encoded_data}'

def _b64_to_image(encoded_image: str) -> 'Image':
    Image = _import_pil_image()
    return Image.open(io.BytesIO(base64.b64decode(encoded_image)))

def _bytes_to_list(content: bytes) -> list:
    return json.loads(content.decode())

def _bytes_to_dict(content: bytes) -> dict:
    return json.loads(content.decode())

def _bytes_to_image(content: bytes) -> 'Image':
    Image = _import_pil_image()
    return Image.open(io.BytesIO(content))

def _as_dict(response: Union[bytes, dict]) -> dict:
    return json.loads(response) if isinstance(response, bytes) else response

def _stream_text_generation_response(output_lines: Iterable[str], details: bool) -> Union[Iterable[str], Iterable[TextGenerationStreamOutput]]:
    for line in output_lines:
        try:
            output = _format_text_generation_stream_output(line, details)
        except StopIteration:
            break
        if output is not None:
            yield output

async def _async_stream_text_generation_response(output_lines: AsyncIterable[str], details: bool) -> Union[AsyncIterable[str], AsyncIterable[TextGenerationStreamOutput]]:
    async for line in output_lines:
        try:
            output = _format_text_generation_stream_output(line, details)
        except StopIteration:
            break
        if output is not None:
            yield output

def _format_text_generation_stream_output(line: str, details: bool) -> Optional[Union[str, TextGenerationStreamOutput]]:
    if not line.startswith('data:'):
        return None
    if line.strip() == 'data: [DONE]':
        raise StopIteration('[DONE] signal received.')
    payload = line.lstrip('data:').rstrip('/n')
    json_payload = json.loads(payload)
    if json_payload.get('error') is not None:
        raise _parse_text_generation_error(json_payload['error'], json_payload.get('error_type'))
    output = TextGenerationStreamOutput.parse_obj_as_instance(json_payload)
    return output.token.text if not details else output

def _stream_chat_completion_response(lines: Iterable[str]) -> Iterable[ChatCompletionStreamOutput]:
    for line in lines:
        try:
            output = _format_chat_completion_stream_output(line)
        except StopIteration:
            break
        if output is not None:
            yield output

async def _async_stream_chat_completion_response(lines: AsyncIterable[str]) -> AsyncIterable[ChatCompletionStreamOutput]:
    async for line in lines:
        try:
            output = _format_chat_completion_stream_output(line)
        except StopIteration:
            break
        if output is not None:
            yield output

def _format_chat_completion_stream_output(line: str) -> Optional[ChatCompletionStreamOutput]:
    if not line.startswith('data:'):
        return None
    if line.strip() == 'data: [DONE]':
        raise StopIteration('[DONE] signal received.')
    json_payload = json.loads(line.lstrip('data:').strip())
    if json_payload.get('error') is not None:
        raise _parse_text_generation_error(json_payload['error'], json_payload.get('error_type'))
    return ChatCompletionStreamOutput.parse_obj_as_instance(json_payload)

async def _async_yield_from(client: httpx.AsyncClient, response: httpx.Response) -> AsyncIterable[str]:
    async for line in response.aiter_lines():
        yield line.strip()
_UNSUPPORTED_TEXT_GENERATION_KWARGS: dict[Optional[str], list[str]] = {}

def _set_unsupported_text_generation_kwargs(model: Optional[str], unsupported_kwargs: list[str]) -> None:
    _UNSUPPORTED_TEXT_GENERATION_KWARGS.setdefault(model, []).extend(unsupported_kwargs)

def _get_unsupported_text_generation_kwargs(model: Optional[str]) -> list[str]:
    return _UNSUPPORTED_TEXT_GENERATION_KWARGS.get(model, [])

def raise_text_generation_error(http_error: HfHubHTTPError) -> NoReturn:
    if http_error.response is None:
        raise http_error
    try:
        payload = getattr(http_error, 'response_error_payload', None) or http_error.response.json()
        error = payload.get('error')
        error_type = payload.get('error_type')
    except Exception:
        raise http_error
    if error_type is not None:
        exception = _parse_text_generation_error(error, error_type)
        raise exception from http_error
    raise http_error

def _parse_text_generation_error(error: Optional[str], error_type: Optional[str]) -> TextGenerationError:
    if error_type == 'generation':
        return GenerationError(error)
    if error_type == 'incomplete_generation':
        return IncompleteGenerationError(error)
    if error_type == 'overloaded':
        return OverloadedError(error)
    if error_type == 'validation':
        return ValidationError(error)
    return UnknownError(error)

