@set_module('pandas.plotting')
class PlotAccessor(PandasObject):
    _common_kinds = ('line', 'bar', 'barh', 'kde', 'density', 'area', 'hist', 'box')
    _series_kinds = ('pie',)
    _dataframe_kinds = ('scatter', 'hexbin')
    _kind_aliases = {'density': 'kde'}
    _all_kinds = _common_kinds + _series_kinds + _dataframe_kinds

    def __init__(self, data: Series | DataFrame) -> None:
        self._parent = data

    @staticmethod
    def _get_call_args(backend_name: str, data: Series | DataFrame, args, kwargs):
        if isinstance(data, ABCSeries):
            arg_def = [('kind', 'line'), ('ax', None), ('figsize', None), ('use_index', True), ('title', None), ('grid', None), ('legend', False), ('style', None), ('logx', False), ('logy', False), ('loglog', False), ('xticks', None), ('yticks', None), ('xlim', None), ('ylim', None), ('rot', None), ('fontsize', None), ('colormap', None), ('table', False), ('yerr', None), ('xerr', None), ('label', None), ('secondary_y', False), ('xlabel', None), ('ylabel', None)]
        elif isinstance(data, ABCDataFrame):
            arg_def = [('x', None), ('y', None), ('kind', 'line'), ('ax', None), ('subplots', False), ('sharex', None), ('sharey', False), ('layout', None), ('figsize', None), ('use_index', True), ('title', None), ('grid', None), ('legend', True), ('style', None), ('logx', False), ('logy', False), ('loglog', False), ('xticks', None), ('yticks', None), ('xlim', None), ('ylim', None), ('rot', None), ('fontsize', None), ('colormap', None), ('table', False), ('yerr', None), ('xerr', None), ('secondary_y', False), ('xlabel', None), ('ylabel', None)]
        else:
            raise TypeError(f'Called plot accessor for type {type(data).__name__}, expected Series or DataFrame')
        if args and isinstance(data, ABCSeries):
            positional_args = str(args)[1:-1]
            keyword_args = ', '.join([f'{name}={value!r}' for (name, _), value in zip(arg_def, args, strict=False)])
            msg = f'`Series.plot()` should not be called with positional arguments, only keyword arguments. The order of positional arguments will change in the future. Use `Series.plot({keyword_args})` instead of `Series.plot({positional_args})`.'
            raise TypeError(msg)
        pos_args = {name: value for (name, _), value in zip(arg_def, args, strict=False)}
        if backend_name == 'pandas.plotting._matplotlib':
            kwargs = dict(arg_def, **pos_args, **kwargs)
        else:
            kwargs = dict(pos_args, **kwargs)
        x = kwargs.pop('x', None)
        y = kwargs.pop('y', None)
        kind = kwargs.pop('kind', 'line')
        return (x, y, kind, kwargs)

    def __call__(self, *args, **kwargs):
        plot_backend = _get_plot_backend(kwargs.pop('backend', None))
        x, y, kind, kwargs = self._get_call_args(plot_backend.__name__, self._parent, args, kwargs)
        kind = self._kind_aliases.get(kind, kind)
        if plot_backend.__name__ != 'pandas.plotting._matplotlib':
            return plot_backend.plot(self._parent, x=x, y=y, kind=kind, **kwargs)
        if kind not in self._all_kinds:
            raise ValueError(f'{kind} is not a valid plot kind Valid plot kinds: {self._all_kinds}')
        data = self._parent
        if isinstance(data, ABCSeries):
            kwargs['reuse_plot'] = True
        if kind in self._dataframe_kinds:
            if isinstance(data, ABCDataFrame):
                return plot_backend.plot(data, x=x, y=y, kind=kind, **kwargs)
            else:
                raise ValueError(f'plot kind {kind} can only be used for data frames')
        elif kind in self._series_kinds:
            if isinstance(data, ABCDataFrame):
                if y is None and kwargs.get('subplots') is False:
                    raise ValueError(f"{kind} requires either y column or 'subplots=True'")
                if y is not None:
                    if is_integer(y) and (not holds_integer(data.columns)):
                        y = data.columns[y]
                    data = data[y].copy(deep=False)
                    data.index.name = y
        elif isinstance(data, ABCDataFrame):
            data_cols = data.columns
            if x is not None:
                if is_integer(x) and (not holds_integer(data.columns)):
                    x = data_cols[x]
                elif not isinstance(data[x], ABCSeries):
                    raise ValueError('x must be a label or position')
                data = data.set_index(x)
            if y is not None:
                int_ylist = is_list_like(y) and all((is_integer(c) for c in y))
                int_y_arg = is_integer(y) or int_ylist
                if int_y_arg and (not holds_integer(data.columns)):
                    y = data_cols[y]
                label_kw = kwargs['label'] if 'label' in kwargs else False
                for kw in ['xerr', 'yerr']:
                    if kw in kwargs and (isinstance(kwargs[kw], str) or is_integer(kwargs[kw])):
                        try:
                            kwargs[kw] = data[kwargs[kw]]
                        except (IndexError, KeyError, TypeError):
                            pass
                data = data[y]
                if isinstance(data, ABCSeries):
                    label_name = label_kw or y
                    data.name = label_name
                else:
                    match = is_list_like(label_kw) and len(label_kw) == len(y)
                    if label_kw and (not match):
                        raise ValueError('label should be list-like and same length as y')
                    label_name = label_kw or data.columns
                    data.columns = label_name
        return plot_backend.plot(data, kind=kind, **kwargs)
    __call__.__doc__ = __doc__

    def line(self, x: Hashable | None=None, y: Hashable | None=None, color: str | Sequence[str] | dict | None=None, **kwargs) -> PlotAccessor:
        if color is not None:
            kwargs['color'] = color
        return self(kind='line', x=x, y=y, **kwargs)

    def bar(self, x: Hashable | None=None, y: Hashable | None=None, color: str | Sequence[str] | dict | None=None, **kwargs) -> PlotAccessor:
        if color is not None:
            kwargs['color'] = color
        return self(kind='bar', x=x, y=y, **kwargs)

    def barh(self, x: Hashable | None=None, y: Hashable | None=None, color: str | Sequence[str] | dict | None=None, **kwargs) -> PlotAccessor:
        if color is not None:
            kwargs['color'] = color
        return self(kind='barh', x=x, y=y, **kwargs)

    def box(self, by: IndexLabel | None=None, **kwargs) -> PlotAccessor:
        return self(kind='box', by=by, **kwargs)

    def hist(self, by: IndexLabel | None=None, bins: int=10, **kwargs) -> PlotAccessor:
        return self(kind='hist', by=by, bins=bins, **kwargs)

    def kde(self, bw_method: Literal['scott', 'silverman'] | float | Callable | None=None, ind: np.ndarray | int | None=None, weights: np.ndarray | None=None, **kwargs) -> PlotAccessor:
        return self(kind='kde', bw_method=bw_method, ind=ind, weights=weights, **kwargs)
    density = kde

    def area(self, x: Hashable | None=None, y: Hashable | None=None, stacked: bool=True, **kwargs) -> PlotAccessor:
        return self(kind='area', x=x, y=y, stacked=stacked, **kwargs)

    def pie(self, y: IndexLabel | None=None, **kwargs) -> PlotAccessor:
        if y is not None:
            kwargs['y'] = y
        if isinstance(self._parent, ABCDataFrame) and kwargs.get('y', None) is None and (not kwargs.get('subplots', False)):
            raise ValueError("pie requires either y column or 'subplots=True'")
        return self(kind='pie', **kwargs)

    def scatter(self, x: Hashable, y: Hashable, s: Hashable | Sequence[Hashable] | None=None, c: Hashable | Sequence[Hashable] | None=None, **kwargs) -> PlotAccessor:
        return self(kind='scatter', x=x, y=y, s=s, c=c, **kwargs)

    def hexbin(self, x: Hashable, y: Hashable, C: Hashable | None=None, reduce_C_function: Callable | None=None, gridsize: int | tuple[int, int] | None=None, **kwargs) -> PlotAccessor:
        if reduce_C_function is not None:
            kwargs['reduce_C_function'] = reduce_C_function
        if gridsize is not None:
            kwargs['gridsize'] = gridsize
        return self(kind='hexbin', x=x, y=y, C=C, **kwargs)
_backends: dict[str, types.ModuleType] = {}

def _load_backend(backend: str) -> types.ModuleType:
    from importlib.metadata import entry_points
    if backend == 'matplotlib':
        try:
            module = importlib.import_module('pandas.plotting._matplotlib')
        except ImportError:
            raise ImportError('matplotlib is required for plotting when the default backend "matplotlib" is selected.') from None
        return module
    found_backend = False
    eps = entry_points()
    key = 'pandas_plotting_backends'
    if hasattr(eps, 'select'):
        entry = eps.select(group=key)
    else:
        entry = eps.get(key, ())
    for entry_point in entry:
        found_backend = entry_point.name == backend
        if found_backend:
            module = entry_point.load()
            break
    if not found_backend:
        try:
            module = importlib.import_module(backend)
            found_backend = True
        except ImportError:
            pass
    if found_backend:
        if hasattr(module, 'plot'):
            return module
    raise ValueError(f"Could not find plotting backend '{backend}'. Ensure that you've installed the package providing the '{backend}' entrypoint, or that the package has a top-level `.plot` method.")

def _get_plot_backend(backend: str | None=None):
    backend_str: str = backend or get_option('plotting.backend')
    if backend_str in _backends:
        return _backends[backend_str]
    module = _load_backend(backend_str)
    _backends[backend_str] = module
    return module

import json
import logging
from contextlib import AsyncExitStack
from datetime import timedelta
from pathlib import Path
from typing import TYPE_CHECKING, Any, AsyncIterable, Literal, Optional, TypedDict, Union, overload
from typing_extensions import NotRequired, TypeAlias, Unpack
from ...utils._runtime import get_hf_hub_version
from .._generated._async_client import AsyncInferenceClient
from .._generated.types import ChatCompletionInputMessage, ChatCompletionInputTool, ChatCompletionStreamOutput, ChatCompletionStreamOutputDeltaToolCall
from .._providers import PROVIDER_OR_POLICY_T
from .utils import format_result
if TYPE_CHECKING:
    from mcp import ClientSession
logger = logging.getLogger(__name__)
ToolName: TypeAlias = str
ServerType: TypeAlias = Literal['stdio', 'sse', 'http']

class StdioServerParameters_T(TypedDict):
    command: str
    args: NotRequired[list[str]]
    env: NotRequired[dict[str, str]]
    cwd: NotRequired[Union[str, Path, None]]

class SSEServerParameters_T(TypedDict):
    url: str
    headers: NotRequired[dict[str, Any]]
    timeout: NotRequired[float]
    sse_read_timeout: NotRequired[float]

class StreamableHTTPParameters_T(TypedDict):
    url: str
    headers: NotRequired[dict[str, Any]]
    timeout: NotRequired[timedelta]
    sse_read_timeout: NotRequired[timedelta]
    terminate_on_close: NotRequired[bool]

class MCPClient:

    def __init__(self, *, model: Optional[str]=None, provider: Optional[PROVIDER_OR_POLICY_T]=None, base_url: Optional[str]=None, api_key: Optional[str]=None):
        self.sessions: dict[ToolName, 'ClientSession'] = {}
        self.exit_stack = AsyncExitStack()
        self.available_tools: list[ChatCompletionInputTool] = []
        if model is None and base_url is None:
            raise ValueError('At least one of `model` or `base_url` should be set in `MCPClient`.')
        self.payload_model = model
        self.client = AsyncInferenceClient(model=None if base_url is not None else model, provider=provider, api_key=api_key, base_url=base_url)

    async def __aenter__(self):
        await self.client.__aenter__()
        await self.exit_stack.__aenter__()
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        await self.client.__aexit__(exc_type, exc_val, exc_tb)
        await self.cleanup()

    async def cleanup(self):
        await self.client.close()
        await self.exit_stack.aclose()

    @overload
    async def add_mcp_server(self, type: Literal['stdio'], **params: Unpack[StdioServerParameters_T]):
        ...

    @overload
    async def add_mcp_server(self, type: Literal['sse'], **params: Unpack[SSEServerParameters_T]):
        ...

    @overload
    async def add_mcp_server(self, type: Literal['http'], **params: Unpack[StreamableHTTPParameters_T]):
        ...

    async def add_mcp_server(self, type: ServerType, **params: Any):
        from mcp import ClientSession, StdioServerParameters
        from mcp import types as mcp_types
        allowed_tools = params.pop('allowed_tools', None)
        if type == 'stdio':
            from mcp.client.stdio import stdio_client
            logger.info(f"Connecting to stdio MCP server with command: {params['command']} {params.get('args', [])}")
            client_kwargs = {'command': params['command']}
            for key in ['args', 'env', 'cwd']:
                if params.get(key) is not None:
                    client_kwargs[key] = params[key]
            server_params = StdioServerParameters(**client_kwargs)
            read, write = await self.exit_stack.enter_async_context(stdio_client(server_params))
        elif type == 'sse':
            from mcp.client.sse import sse_client
            logger.info(f"Connecting to SSE MCP server at: {params['url']}")
            client_kwargs = {'url': params['url']}
            for key in ['headers', 'timeout', 'sse_read_timeout']:
                if params.get(key) is not None:
                    client_kwargs[key] = params[key]
            read, write = await self.exit_stack.enter_async_context(sse_client(**client_kwargs))
        elif type == 'http':
            from mcp.client.streamable_http import streamablehttp_client
            logger.info(f"Connecting to StreamableHTTP MCP server at: {params['url']}")
            client_kwargs = {'url': params['url']}
            for key in ['headers', 'timeout', 'sse_read_timeout', 'terminate_on_close']:
                if params.get(key) is not None:
                    client_kwargs[key] = params[key]
            read, write, _ = await self.exit_stack.enter_async_context(streamablehttp_client(**client_kwargs))
        else:
            raise ValueError(f'Unsupported server type: {type}')
        session = await self.exit_stack.enter_async_context(ClientSession(read_stream=read, write_stream=write, client_info=mcp_types.Implementation(name='huggingface_hub.MCPClient', version=get_hf_hub_version())))
        logger.debug('Initializing session...')
        await session.initialize()
        response = await session.list_tools()
        logger.debug('Connected to server with tools:', [tool.name for tool in response.tools])
        filtered_tools = response.tools
        if allowed_tools is not None:
            filtered_tools = [tool for tool in response.tools if tool.name in allowed_tools]
            logger.debug(f'Tool filtering applied. Using {len(filtered_tools)} of {len(response.tools)} available tools: {[tool.name for tool in filtered_tools]}')
        for tool in filtered_tools:
            if tool.name in self.sessions:
                logger.warning(f"Tool '{tool.name}' already defined by another server. Skipping.")
                continue
            self.sessions[tool.name] = session
            self.available_tools.append(ChatCompletionInputTool.parse_obj_as_instance({'type': 'function', 'function': {'name': tool.name, 'description': tool.description, 'parameters': tool.inputSchema}}))

    async def process_single_turn_with_tools(self, messages: list[Union[dict, ChatCompletionInputMessage]], exit_loop_tools: Optional[list[ChatCompletionInputTool]]=None, exit_if_first_chunk_no_tool: bool=False) -> AsyncIterable[Union[ChatCompletionStreamOutput, ChatCompletionInputMessage]]:
        tools = self.available_tools
        if exit_loop_tools is not None:
            tools = [*exit_loop_tools, *self.available_tools]
        response = await self.client.chat.completions.create(model=self.payload_model, messages=messages, tools=tools, tool_choice='auto', stream=True)
        message: dict[str, Any] = {'role': 'unknown', 'content': ''}
        final_tool_calls: dict[int, ChatCompletionStreamOutputDeltaToolCall] = {}
        num_of_chunks = 0
        async for chunk in response:
            num_of_chunks += 1
            delta = chunk.choices[0].delta if chunk.choices and len(chunk.choices) > 0 else None
            if not delta:
                continue
            if delta.role:
                message['role'] = delta.role
            if delta.content:
                message['content'] += delta.content
            if delta.tool_calls:
                for tool_call in delta.tool_calls:
                    idx = tool_call.index
                    if idx not in final_tool_calls:
                        final_tool_calls[idx] = tool_call
                        if final_tool_calls[idx].function.arguments is None:
                            final_tool_calls[idx].function.arguments = ''
                        continue
                    if final_tool_calls[idx].function.arguments is None:
                        final_tool_calls[idx].function.arguments = ''
                    if tool_call.function.arguments:
                        final_tool_calls[idx].function.arguments += tool_call.function.arguments
            if exit_if_first_chunk_no_tool and num_of_chunks <= 2 and (len(final_tool_calls) == 0):
                return
            yield chunk
        if message['content'] or final_tool_calls:
            if message.get('role') == 'unknown':
                message['role'] = 'assistant'
            if final_tool_calls:
                tool_calls_list: list[dict[str, Any]] = []
                for tc in final_tool_calls.values():
                    tool_calls_list.append({'id': tc.id, 'type': 'function', 'function': {'name': tc.function.name, 'arguments': tc.function.arguments or '{}'}})
                message['tool_calls'] = tool_calls_list
            messages.append(message)
        for tool_call in final_tool_calls.values():
            function_name = tool_call.function.name
            if function_name is None:
                message = ChatCompletionInputMessage.parse_obj_as_instance({'role': 'tool', 'tool_call_id': tool_call.id, 'content': 'Invalid tool call with no function name.'})
                messages.append(message)
                yield message
                continue
            try:
                function_args = json.loads(tool_call.function.arguments or '{}')
            except json.JSONDecodeError as err:
                tool_message = {'role': 'tool', 'tool_call_id': tool_call.id, 'name': function_name, 'content': f'Invalid JSON generated by the model: {err}'}
                tool_message_as_obj = ChatCompletionInputMessage.parse_obj_as_instance(tool_message)
                messages.append(tool_message_as_obj)
                yield tool_message_as_obj
                continue
            tool_message = {'role': 'tool', 'tool_call_id': tool_call.id, 'content': '', 'name': function_name}
            if exit_loop_tools and function_name in [t.function.name for t in exit_loop_tools]:
                tool_message_as_obj = ChatCompletionInputMessage.parse_obj_as_instance(tool_message)
                messages.append(tool_message_as_obj)
                yield tool_message_as_obj
                return
            session = self.sessions.get(function_name)
            if session is not None:
                try:
                    result = await session.call_tool(function_name, function_args)
                    tool_message['content'] = format_result(result)
                except Exception as err:
                    tool_message['content'] = f'Error: MCP tool call failed with error message: {err}'
            else:
                tool_message['content'] = f'Error: No session found for tool: {function_name}'
            tool_message_as_obj = ChatCompletionInputMessage.parse_obj_as_instance(tool_message)
            messages.append(tool_message_as_obj)
            yield tool_message_as_obj

import base64
import time
from abc import ABC
from typing import Any, Optional, Union
from urllib.parse import urlparse
from huggingface_hub import constants
from huggingface_hub.hf_api import InferenceProviderMapping
from huggingface_hub.inference._common import RequestParameters, _as_dict, _as_url
from huggingface_hub.inference._providers._common import TaskProviderHelper, filter_none
from huggingface_hub.utils import get_session, hf_raise_for_status
from huggingface_hub.utils.logging import get_logger
logger = get_logger(__name__)
_POLLING_INTERVAL = 0.5

class FalAITask(TaskProviderHelper, ABC):

    def __init__(self, task: str):
        super().__init__(provider='fal-ai', base_url='https://fal.run', task=task)

    def _prepare_headers(self, headers: dict, api_key: str) -> dict[str, Any]:
        headers = super()._prepare_headers(headers, api_key)
        if not api_key.startswith('hf_'):
            headers['authorization'] = f'Key {api_key}'
        return headers

    def _prepare_route(self, mapped_model: str, api_key: str) -> str:
        return f'/{mapped_model}'

class FalAIQueueTask(TaskProviderHelper, ABC):

    def __init__(self, task: str):
        super().__init__(provider='fal-ai', base_url='https://queue.fal.run', task=task)

    def _prepare_headers(self, headers: dict, api_key: str) -> dict[str, Any]:
        headers = super()._prepare_headers(headers, api_key)
        if not api_key.startswith('hf_'):
            headers['authorization'] = f'Key {api_key}'
        return headers

    def _prepare_route(self, mapped_model: str, api_key: str) -> str:
        if api_key.startswith('hf_'):
            return f'/{mapped_model}?_subdomain=queue'
        return f'/{mapped_model}'

    def get_response(self, response: Union[bytes, dict], request_params: Optional[RequestParameters]=None) -> Any:
        response_dict = _as_dict(response)
        request_id = response_dict.get('request_id')
        if not request_id:
            raise ValueError('No request ID found in the response')
        if request_params is None:
            raise ValueError(f'A `RequestParameters` object should be provided to get {self.task} responses with Fal AI.')
        parsed_url = urlparse(request_params.url)
        base_url = f"{parsed_url.scheme}://{parsed_url.netloc}{('/fal-ai' if parsed_url.netloc == 'router.huggingface.co' else '')}"
        query_param = f'?{parsed_url.query}' if parsed_url.query else ''
        model_id = urlparse(response_dict.get('response_url')).path
        status_url = f'{base_url}{str(model_id)}/status{query_param}'
        result_url = f'{base_url}{str(model_id)}{query_param}'
        status = response_dict.get('status')
        logger.info('Generating the output.. this can take several minutes.')
        while status != 'COMPLETED':
            time.sleep(_POLLING_INTERVAL)
            status_response = get_session().get(status_url, headers=request_params.headers)
            hf_raise_for_status(status_response)
            status = status_response.json().get('status')
        return get_session().get(result_url, headers=request_params.headers).json()

class FalAIAutomaticSpeechRecognitionTask(FalAITask):

    def __init__(self):
        super().__init__('automatic-speech-recognition')

    def _prepare_payload_as_dict(self, inputs: Any, parameters: dict, provider_mapping_info: InferenceProviderMapping) -> Optional[dict]:
        if isinstance(inputs, str) and inputs.startswith(('http://', 'https://')):
