class OpenFile:

    def __init__(self, fs, path, mode='rb', compression=None, encoding=None, errors=None, newline=None):
        self.fs = fs
        self.path = path
        self.mode = mode
        self.compression = get_compression(path, compression)
        self.encoding = encoding
        self.errors = errors
        self.newline = newline
        self.fobjects = []

    def __reduce__(self):
        return (OpenFile, (self.fs, self.path, self.mode, self.compression, self.encoding, self.errors, self.newline))

    def __repr__(self):
        return f"<OpenFile '{self.path}'>"

    def __enter__(self):
        mode = self.mode.replace('t', '').replace('b', '') + 'b'
        try:
            f = self.fs.open(self.path, mode=mode)
        except FileNotFoundError as e:
            if has_magic(self.path):
                raise FileNotFoundError("%s not found. The URL contains glob characters: you maybe needed\nto pass expand=True in fsspec.open() or the storage_options of \nyour library. You can also set the config value 'open_expand'\nbefore import, or fsspec.core.DEFAULT_EXPAND at runtime, to True.", self.path) from e
            raise
        self.fobjects = [f]
        if self.compression is not None:
            compress = compr[self.compression]
            f = compress(f, mode=mode[0])
            self.fobjects.append(f)
        if 'b' not in self.mode:
            f = PickleableTextIOWrapper(f, encoding=self.encoding, errors=self.errors, newline=self.newline)
            self.fobjects.append(f)
        return self.fobjects[-1]

    def __exit__(self, *args):
        self.close()

    @property
    def full_name(self):
        return _unstrip_protocol(self.path, self.fs)

    def open(self):
        return self.__enter__()

    def close(self):
        for f in reversed(self.fobjects):
            if 'r' not in self.mode and (not f.closed):
                f.flush()
            f.close()
        self.fobjects.clear()

class OpenFiles(list):

    def __init__(self, *args, mode='rb', fs=None):
        self.mode = mode
        self.fs = fs
        self.files = []
        super().__init__(*args)

    def __enter__(self):
        if self.fs is None:
            raise ValueError('Context has already been used')
        fs = self.fs
        while True:
            if hasattr(fs, 'open_many'):
                self.files = fs.open_many(self)
                return self.files
            if hasattr(fs, 'fs') and fs.fs is not None:
                fs = fs.fs
            else:
                break
        return [s.__enter__() for s in self]

    def __exit__(self, *args):
        fs = self.fs
        [s.__exit__(*args) for s in self]
        if 'r' not in self.mode:
            while True:
                if hasattr(fs, 'open_many'):
                    fs.commit_many(self.files)
                    return
                if hasattr(fs, 'fs') and fs.fs is not None:
                    fs = fs.fs
                else:
                    break

    def __getitem__(self, item):
        out = super().__getitem__(item)
        if isinstance(item, slice):
            return OpenFiles(out, mode=self.mode, fs=self.fs)
        return out

    def __repr__(self):
        return f'<List of {len(self)} OpenFile instances>'

def open_files(urlpath, mode='rb', compression=None, encoding='utf8', errors=None, name_function=None, num=1, protocol=None, newline=None, auto_mkdir=True, expand=True, **kwargs):
    fs, fs_token, paths = get_fs_token_paths(urlpath, mode, num=num, name_function=name_function, storage_options=kwargs, protocol=protocol, expand=expand)
    if fs.protocol == 'file':
        fs.auto_mkdir = auto_mkdir
    elif 'r' not in mode and auto_mkdir:
        parents = {fs._parent(path) for path in paths}
        for parent in parents:
            try:
                fs.makedirs(parent, exist_ok=True)
            except PermissionError:
                pass
    return OpenFiles([OpenFile(fs, path, mode=mode, compression=compression, encoding=encoding, errors=errors, newline=newline) for path in paths], mode=mode, fs=fs)

def _un_chain(path, kwargs):
    from fsspec.implementations.chained import ChainedFileSystem
    if '::' in path:
        x = re.compile('.*[^a-z]+.*')
        known_protocols = set(available_protocols())
        bits = []
        for p in path.split('::'):
            if p in known_protocols:
                bits.append(p + '://')
            elif '://' in p or x.match(p):
                bits.append(p)
            else:
                bits.append(p + '://')
    else:
        bits = [path]
    out = []
    previous_bit = None
    kwargs = kwargs.copy()
    for bit in reversed(bits):
        protocol = kwargs.pop('protocol', None) or split_protocol(bit)[0] or 'file'
        cls = get_filesystem_class(protocol)
        extra_kwargs = cls._get_kwargs_from_urls(bit)
        kws = kwargs.pop(protocol, {})
        if bit is bits[0]:
            kws.update(kwargs)
        kw = dict(**{k: v for k, v in extra_kwargs.items() if k not in kws or v != kws[k]}, **kws)
        bit = cls._strip_protocol(bit)
        if 'target_protocol' not in kw and issubclass(cls, ChainedFileSystem) and (not bit):
            bit = previous_bit
        out.append((bit, protocol, kw))
        previous_bit = bit
    out.reverse()
    return out

def url_to_fs(url, **kwargs):
    url = stringify_path(url)
    known_kwargs = {'compression', 'encoding', 'errors', 'expand', 'mode', 'name_function', 'newline', 'num'}
    kwargs = {k: v for k, v in kwargs.items() if k not in known_kwargs}
    chain = _un_chain(url, kwargs)
    inkwargs = {}
    for i, ch in enumerate(reversed(chain)):
        urls, protocol, kw = ch
        if i == len(chain) - 1:
            inkwargs = dict(**kw, **inkwargs)
            continue
        inkwargs['target_options'] = dict(**kw, **inkwargs)
        inkwargs['target_protocol'] = protocol
        inkwargs['fo'] = urls
    urlpath, protocol, _ = chain[0]
    fs = filesystem(protocol, **inkwargs)
    return (fs, urlpath)
DEFAULT_EXPAND = conf.get('open_expand', False)

def open(urlpath, mode='rb', compression=None, encoding='utf8', errors=None, protocol=None, newline=None, expand=None, **kwargs):
    expand = DEFAULT_EXPAND if expand is None else expand
    out = open_files(urlpath=[urlpath], mode=mode, compression=compression, encoding=encoding, errors=errors, protocol=protocol, newline=newline, expand=expand, **kwargs)
    if not out:
        raise FileNotFoundError(urlpath)
    return out[0]

def open_local(url: str | list[str] | Path | list[Path], mode: str='rb', **storage_options: dict) -> str | list[str]:
    if 'r' not in mode:
        raise ValueError('Can only ensure local files when reading')
    of = open_files(url, mode=mode, **storage_options)
    if not getattr(of[0].fs, 'local_file', False):
        raise ValueError('open_local can only be used on a filesystem which has attribute local_file=True')
    with of as files:
        paths = [f.name for f in files]
    if isinstance(url, str) and (not has_magic(url)) or isinstance(url, Path):
        return paths[0]
    return paths

def get_compression(urlpath, compression):
    if compression == 'infer':
        compression = infer_compression(urlpath)
    if compression is not None and compression not in compr:
        raise ValueError(f'Compression type {compression} not supported')
    return compression

def split_protocol(urlpath):
    urlpath = stringify_path(urlpath)
    if '://' in urlpath:
        protocol, path = urlpath.split('://', 1)
        if len(protocol) > 1:
            return (protocol, path)
    if urlpath.startswith('data:'):
        return urlpath.split(':', 1)
    return (None, urlpath)

def strip_protocol(urlpath):
    protocol, _ = split_protocol(urlpath)
    cls = get_filesystem_class(protocol)
    return cls._strip_protocol(urlpath)

def expand_paths_if_needed(paths, mode, num, fs, name_function):
    expanded_paths = []
    paths = list(paths)
    if 'w' in mode:
        if sum((1 for p in paths if '*' in p)) > 1:
            raise ValueError('When writing data, only one filename mask can be specified.')
        num = max(num, len(paths))
        for curr_path in paths:
            if '*' in curr_path:
                expanded_paths.extend(_expand_paths(curr_path, name_function, num))
            else:
                expanded_paths.append(curr_path)
        if len(expanded_paths) > num:
            expanded_paths = expanded_paths[:num]
    else:
        for curr_path in paths:
            if has_magic(curr_path):
                expanded_paths.extend(fs.glob(curr_path))
            else:
                expanded_paths.append(curr_path)
    return expanded_paths

def get_fs_token_paths(urlpath, mode='rb', num=1, name_function=None, storage_options=None, protocol=None, expand=True):
    if isinstance(urlpath, (list, tuple, set)):
        if not urlpath:
            raise ValueError('empty urlpath sequence')
        urlpath0 = stringify_path(next(iter(urlpath)))
    else:
        urlpath0 = stringify_path(urlpath)
    storage_options = storage_options or {}
    if protocol:
        storage_options['protocol'] = protocol
    chain = _un_chain(urlpath0, storage_options or {})
    inkwargs = {}
    for i, ch in enumerate(reversed(chain)):
        urls, nested_protocol, kw = ch
        if i == len(chain) - 1:
            inkwargs = dict(**kw, **inkwargs)
            continue
        inkwargs['target_options'] = dict(**kw, **inkwargs)
        inkwargs['target_protocol'] = nested_protocol
        inkwargs['fo'] = urls
    paths, protocol, _ = chain[0]
    fs = filesystem(protocol, **inkwargs)
    if isinstance(urlpath, (list, tuple, set)):
        pchains = [_un_chain(stringify_path(u), storage_options or {})[0] for u in urlpath]
        if len({pc[1] for pc in pchains}) > 1:
            raise ValueError('Protocol mismatch getting fs from %s', urlpath)
        paths = [pc[0] for pc in pchains]
    else:
        paths = fs._strip_protocol(paths)
    if isinstance(paths, (list, tuple, set)):
        if expand:
            paths = expand_paths_if_needed(paths, mode, num, fs, name_function)
        elif not isinstance(paths, list):
            paths = list(paths)
    elif ('w' in mode or 'x' in mode) and expand:
        paths = _expand_paths(paths, name_function, num)
    elif '*' in paths:
        paths = [f for f in sorted(fs.glob(paths)) if not fs.isdir(f)]
    else:
        paths = [paths]
    return (fs, fs._fs_token, paths)

def _expand_paths(path, name_function, num):
    if isinstance(path, str):
        if path.count('*') > 1:
            raise ValueError("Output path spec must contain exactly one '*'.")
        elif '*' not in path:
            path = os.path.join(path, '*.part')
        if name_function is None:
            name_function = build_name_function(num - 1)
        paths = [path.replace('*', name_function(i)) for i in range(num)]
        if paths != sorted(paths):
            logger.warning('In order to preserve order between partitions paths created with ``name_function`` should sort to partition order')
    elif isinstance(path, (tuple, list)):
        assert len(path) == num
        paths = list(path)
    else:
        raise ValueError("Path should be either\n1. A list of paths: ['foo.json', 'bar.json', ...]\n2. A directory: 'foo/\n3. A path with a '*' in it: 'foo.*.json'")
    return paths

class PickleableTextIOWrapper(io.TextIOWrapper):

    def __init__(self, buffer, encoding=None, errors=None, newline=None, line_buffering=False, write_through=False):
        self.args = (buffer, encoding, errors, newline, line_buffering, write_through)
        super().__init__(*self.args)

    def __reduce__(self):
        return (PickleableTextIOWrapper, self.args)

from typing import cast, Dict, Optional, Set, Tuple, Type, Union
from ._events import *
from ._util import LocalProtocolError, Sentinel
__all__ = ['CLIENT', 'SERVER', 'IDLE', 'SEND_RESPONSE', 'SEND_BODY', 'DONE', 'MUST_CLOSE', 'CLOSED', 'MIGHT_SWITCH_PROTOCOL', 'SWITCHED_PROTOCOL', 'ERROR']

class CLIENT(Sentinel, metaclass=Sentinel):
    pass

class SERVER(Sentinel, metaclass=Sentinel):
    pass

class IDLE(Sentinel, metaclass=Sentinel):
    pass

class SEND_RESPONSE(Sentinel, metaclass=Sentinel):
    pass

class SEND_BODY(Sentinel, metaclass=Sentinel):
    pass

class DONE(Sentinel, metaclass=Sentinel):
    pass

class MUST_CLOSE(Sentinel, metaclass=Sentinel):
    pass

class CLOSED(Sentinel, metaclass=Sentinel):
    pass

class ERROR(Sentinel, metaclass=Sentinel):
    pass

class MIGHT_SWITCH_PROTOCOL(Sentinel, metaclass=Sentinel):
    pass

class SWITCHED_PROTOCOL(Sentinel, metaclass=Sentinel):
    pass

class _SWITCH_UPGRADE(Sentinel, metaclass=Sentinel):
    pass

class _SWITCH_CONNECT(Sentinel, metaclass=Sentinel):
    pass
EventTransitionType = Dict[Type[Sentinel], Dict[Type[Sentinel], Dict[Union[Type[Event], Tuple[Type[Event], Type[Sentinel]]], Type[Sentinel]]]]
EVENT_TRIGGERED_TRANSITIONS: EventTransitionType = {CLIENT: {IDLE: {Request: SEND_BODY, ConnectionClosed: CLOSED}, SEND_BODY: {Data: SEND_BODY, EndOfMessage: DONE}, DONE: {ConnectionClosed: CLOSED}, MUST_CLOSE: {ConnectionClosed: CLOSED}, CLOSED: {ConnectionClosed: CLOSED}, MIGHT_SWITCH_PROTOCOL: {}, SWITCHED_PROTOCOL: {}, ERROR: {}}, SERVER: {IDLE: {ConnectionClosed: CLOSED, Response: SEND_BODY, (Request, CLIENT): SEND_RESPONSE}, SEND_RESPONSE: {InformationalResponse: SEND_RESPONSE, Response: SEND_BODY, (InformationalResponse, _SWITCH_UPGRADE): SWITCHED_PROTOCOL, (Response, _SWITCH_CONNECT): SWITCHED_PROTOCOL}, SEND_BODY: {Data: SEND_BODY, EndOfMessage: DONE}, DONE: {ConnectionClosed: CLOSED}, MUST_CLOSE: {ConnectionClosed: CLOSED}, CLOSED: {ConnectionClosed: CLOSED}, SWITCHED_PROTOCOL: {}, ERROR: {}}}
StateTransitionType = Dict[Tuple[Type[Sentinel], Type[Sentinel]], Dict[Type[Sentinel], Type[Sentinel]]]
STATE_TRIGGERED_TRANSITIONS: StateTransitionType = {(MIGHT_SWITCH_PROTOCOL, SWITCHED_PROTOCOL): {CLIENT: SWITCHED_PROTOCOL}, (CLOSED, DONE): {SERVER: MUST_CLOSE}, (CLOSED, IDLE): {SERVER: MUST_CLOSE}, (ERROR, DONE): {SERVER: MUST_CLOSE}, (DONE, CLOSED): {CLIENT: MUST_CLOSE}, (IDLE, CLOSED): {CLIENT: MUST_CLOSE}, (DONE, ERROR): {CLIENT: MUST_CLOSE}}

class ConnectionState:

    def __init__(self) -> None:
        self.keep_alive = True
        self.pending_switch_proposals: Set[Type[Sentinel]] = set()
        self.states: Dict[Type[Sentinel], Type[Sentinel]] = {CLIENT: IDLE, SERVER: IDLE}

    def process_error(self, role: Type[Sentinel]) -> None:
        self.states[role] = ERROR
        self._fire_state_triggered_transitions()

    def process_keep_alive_disabled(self) -> None:
        self.keep_alive = False
        self._fire_state_triggered_transitions()

    def process_client_switch_proposal(self, switch_event: Type[Sentinel]) -> None:
        self.pending_switch_proposals.add(switch_event)
        self._fire_state_triggered_transitions()

    def process_event(self, role: Type[Sentinel], event_type: Type[Event], server_switch_event: Optional[Type[Sentinel]]=None) -> None:
        _event_type: Union[Type[Event], Tuple[Type[Event], Type[Sentinel]]] = event_type
        if server_switch_event is not None:
            assert role is SERVER
            if server_switch_event not in self.pending_switch_proposals:
                raise LocalProtocolError('Received server _SWITCH_UPGRADE event without a pending proposal')
            _event_type = (event_type, server_switch_event)
        if server_switch_event is None and _event_type is Response:
            self.pending_switch_proposals = set()
        self._fire_event_triggered_transitions(role, _event_type)
        if _event_type is Request:
            assert role is CLIENT
            self._fire_event_triggered_transitions(SERVER, (Request, CLIENT))
        self._fire_state_triggered_transitions()

    def _fire_event_triggered_transitions(self, role: Type[Sentinel], event_type: Union[Type[Event], Tuple[Type[Event], Type[Sentinel]]]) -> None:
        state = self.states[role]
        try:
            new_state = EVENT_TRIGGERED_TRANSITIONS[role][state][event_type]
        except KeyError:
            event_type = cast(Type[Event], event_type)
            raise LocalProtocolError("can't handle event type {} when role={} and state={}".format(event_type.__name__, role, self.states[role])) from None
        self.states[role] = new_state

    def _fire_state_triggered_transitions(self) -> None:
        while True:
            start_states = dict(self.states)
            if self.pending_switch_proposals:
                if self.states[CLIENT] is DONE:
                    self.states[CLIENT] = MIGHT_SWITCH_PROTOCOL
            if not self.pending_switch_proposals:
                if self.states[CLIENT] is MIGHT_SWITCH_PROTOCOL:
                    self.states[CLIENT] = DONE
            if not self.keep_alive:
                for role in (CLIENT, SERVER):
                    if self.states[role] is DONE:
                        self.states[role] = MUST_CLOSE
            joint_state = (self.states[CLIENT], self.states[SERVER])
            changes = STATE_TRIGGERED_TRANSITIONS.get(joint_state, {})
            self.states.update(changes)
            if self.states == start_states:
                return

    def start_next_cycle(self) -> None:
        if self.states != {CLIENT: DONE, SERVER: DONE}:
            raise LocalProtocolError(f'not in a reusable state. self.states={self.states}')
        assert self.keep_alive
        assert not self.pending_switch_proposals
        self.states = {CLIENT: IDLE, SERVER: IDLE}

import datetime
import re
import uuid
from stat import S_ISDIR, S_ISLNK
import smbclient
import smbprotocol.exceptions
from .. import AbstractFileSystem
from ..utils import infer_storage_options

class SMBFileSystem(AbstractFileSystem):
    protocol = 'smb'

    def __init__(self, host, port=None, username=None, password=None, timeout=60, encrypt=None, share_access=None, register_session_retries=4, register_session_retry_wait=1, register_session_retry_factor=10, auto_mkdir=False, **kwargs):
        super().__init__(**kwargs)
        self.host = host
        self.port = port
        self.username = username
        self.password = password
        self.timeout = timeout
        self.encrypt = encrypt
        self.temppath = kwargs.pop('temppath', '')
        self.share_access = share_access
        self.register_session_retries = register_session_retries
        if register_session_retry_wait < 0:
            raise ValueError('register_session_retry_wait must be a non-negative integer')
        self.register_session_retry_wait = register_session_retry_wait
        if register_session_retry_factor < 1:
            raise ValueError('register_session_retry_factor must be a positive integer equal to or greater than 1')
        self.register_session_retry_factor = register_session_retry_factor
        self.auto_mkdir = auto_mkdir
        self._connect()

    @property
    def _port(self):
        return 445 if self.port is None else self.port

    def _connect(self):
        import time
        if self.register_session_retries <= -1:
            return
        retried_errors = []
        wait_time = self.register_session_retry_wait
        n_waits = self.register_session_retries - 1
        factor = self.register_session_retry_factor
        wait_times = iter((factor ** (n / n_waits - 1) * wait_time for n in range(0, n_waits + 1)))
        for attempt in range(self.register_session_retries + 1):
            try:
                smbclient.register_session(self.host, username=self.username, password=self.password, port=self._port, encrypt=self.encrypt, connection_timeout=self.timeout)
                return
            except (smbprotocol.exceptions.SMBAuthenticationError, smbprotocol.exceptions.LogonFailure):
                raise
            except ValueError as exc:
                if re.findall('\\[Errno -\\d+]', str(exc)):
                    retried_errors.append(exc)
                else:
                    raise
            except Exception as exc:
                retried_errors.append(exc)
            if attempt < self.register_session_retries:
                time.sleep(next(wait_times))
        raise retried_errors[-1]

    @classmethod
    def _strip_protocol(cls, path):
        return infer_storage_options(path)['path']

    @staticmethod
    def _get_kwargs_from_urls(path):
        out = infer_storage_options(path)
        out.pop('path', None)
        out.pop('protocol', None)
        return out

    def mkdir(self, path, create_parents=True, **kwargs):
        wpath = _as_unc_path(self.host, path)
        if create_parents:
            smbclient.makedirs(wpath, exist_ok=False, port=self._port, **kwargs)
        else:
            smbclient.mkdir(wpath, port=self._port, **kwargs)

    def makedirs(self, path, exist_ok=False):
        if _share_has_path(path):
            wpath = _as_unc_path(self.host, path)
            smbclient.makedirs(wpath, exist_ok=exist_ok, port=self._port)

    def rmdir(self, path):
        if _share_has_path(path):
            wpath = _as_unc_path(self.host, path)
            smbclient.rmdir(wpath, port=self._port)

    def info(self, path, **kwargs):
        wpath = _as_unc_path(self.host, path)
        stats = smbclient.stat(wpath, port=self._port, **kwargs)
        if S_ISDIR(stats.st_mode):
            stype = 'directory'
        elif S_ISLNK(stats.st_mode):
            stype = 'link'
        else:
            stype = 'file'
        res = {'name': path + '/' if stype == 'directory' else path, 'size': stats.st_size, 'type': stype, 'uid': stats.st_uid, 'gid': stats.st_gid, 'time': stats.st_atime, 'mtime': stats.st_mtime}
        return res

    def created(self, path):
        wpath = _as_unc_path(self.host, path)
        stats = smbclient.stat(wpath, port=self._port)
        return datetime.datetime.fromtimestamp(stats.st_ctime, tz=datetime.timezone.utc)

    def modified(self, path):
        wpath = _as_unc_path(self.host, path)
        stats = smbclient.stat(wpath, port=self._port)
        return datetime.datetime.fromtimestamp(stats.st_mtime, tz=datetime.timezone.utc)

    def ls(self, path, detail=True, **kwargs):
        unc = _as_unc_path(self.host, path)
        listed = smbclient.listdir(unc, port=self._port, **kwargs)
        dirs = ['/'.join([path.rstrip('/'), p]) for p in listed]
        if detail:
            dirs = [self.info(d) for d in dirs]
        return dirs

    def _open(self, path, mode='rb', block_size=-1, autocommit=True, cache_options=None, **kwargs):
        if self.auto_mkdir and 'w' in mode:
            self.makedirs(self._parent(path), exist_ok=True)
        bls = block_size if block_size is not None and block_size >= 0 else -1
        wpath = _as_unc_path(self.host, path)
        share_access = kwargs.pop('share_access', self.share_access)
        if 'w' in mode and autocommit is False:
            temp = _as_temp_path(self.host, path, self.temppath)
            return SMBFileOpener(wpath, temp, mode, port=self._port, block_size=bls, **kwargs)
        return smbclient.open_file(wpath, mode, buffering=bls, share_access=share_access, port=self._port, **kwargs)

    def copy(self, path1, path2, **kwargs):
        wpath1 = _as_unc_path(self.host, path1)
        wpath2 = _as_unc_path(self.host, path2)
        if self.auto_mkdir:
            self.makedirs(self._parent(path2), exist_ok=True)
        smbclient.copyfile(wpath1, wpath2, port=self._port, **kwargs)

    def _rm(self, path):
        if _share_has_path(path):
            wpath = _as_unc_path(self.host, path)
            stats = smbclient.stat(wpath, port=self._port)
            if S_ISDIR(stats.st_mode):
                smbclient.rmdir(wpath, port=self._port)
            else:
                smbclient.remove(wpath, port=self._port)

    def mv(self, path1, path2, recursive=None, maxdepth=None, **kwargs):
        wpath1 = _as_unc_path(self.host, path1)
        wpath2 = _as_unc_path(self.host, path2)
        smbclient.rename(wpath1, wpath2, port=self._port, **kwargs)

def _as_unc_path(host, path):
    rpath = path.replace('/', '\\')
    unc = f'\\\\{host}{rpath}'
    return unc

def _as_temp_path(host, path, temppath):
    share = path.split('/')[1]
    temp_file = f'/{share}{temppath}/{uuid.uuid4()}'
    unc = _as_unc_path(host, temp_file)
    return unc

def _share_has_path(path):
    parts = path.count('/')
    if path.endswith('/'):
        return parts > 2
    return parts > 1

class SMBFileOpener:

    def __init__(self, path, temp, mode, port=445, block_size=-1, **kwargs):
        self.path = path
        self.temp = temp
        self.mode = mode
        self.block_size = block_size
        self.kwargs = kwargs
        self.smbfile = None
        self._incontext = False
        self.port = port
        self._open()

    def _open(self):
        if self.smbfile is None or self.smbfile.closed:
            self.smbfile = smbclient.open_file(self.temp, self.mode, port=self.port, buffering=self.block_size, **self.kwargs)

    def commit(self):
        smbclient.replace(self.temp, self.path, port=self.port)

    def discard(self):
        smbclient.remove(self.temp, port=self.port)

    def __fspath__(self):
        return self.path

    def __iter__(self):
        return self.smbfile.__iter__()

    def __getattr__(self, item):
        return getattr(self.smbfile, item)

    def __enter__(self):
        self._incontext = True
        return self.smbfile.__enter__()

    def __exit__(self, exc_type, exc_value, traceback):
        self._incontext = False
        self.smbfile.__exit__(exc_type, exc_value, traceback)

from __future__ import annotations
import threading
import types
from ._exceptions import ExceptionMapping, PoolTimeout, map_exceptions
try:
    import trio
except (ImportError, NotImplementedError):
    trio = None
try:
    import anyio
except ImportError:
    anyio = None

def current_async_library() -> str:
    try:
        import sniffio
    except ImportError:
        environment = 'asyncio'
    else:
        environment = sniffio.current_async_library()
    if environment not in ('asyncio', 'trio'):
        raise RuntimeError('Running under an unsupported async environment.')
    if environment == 'asyncio' and anyio is None:
        raise RuntimeError("Running with asyncio requires installation of 'httpcore[asyncio]'.")
    if environment == 'trio' and trio is None:
        raise RuntimeError("Running with trio requires installation of 'httpcore[trio]'.")
    return environment

class AsyncLock:

    def __init__(self) -> None:
        self._backend = ''

    def setup(self) -> None:
        self._backend = current_async_library()
        if self._backend == 'trio':
            self._trio_lock = trio.Lock()
        elif self._backend == 'asyncio':
            self._anyio_lock = anyio.Lock()

    async def __aenter__(self) -> AsyncLock:
        if not self._backend:
            self.setup()
        if self._backend == 'trio':
            await self._trio_lock.acquire()
        elif self._backend == 'asyncio':
            await self._anyio_lock.acquire()
        return self

    async def __aexit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        if self._backend == 'trio':
            self._trio_lock.release()
        elif self._backend == 'asyncio':
            self._anyio_lock.release()

class AsyncThreadLock:

    def __enter__(self) -> AsyncThreadLock:
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        pass

class AsyncEvent:

    def __init__(self) -> None:
        self._backend = ''

    def setup(self) -> None:
        self._backend = current_async_library()
        if self._backend == 'trio':
            self._trio_event = trio.Event()
        elif self._backend == 'asyncio':
            self._anyio_event = anyio.Event()

    def set(self) -> None:
        if not self._backend:
            self.setup()
        if self._backend == 'trio':
            self._trio_event.set()
        elif self._backend == 'asyncio':
            self._anyio_event.set()

    async def wait(self, timeout: float | None=None) -> None:
        if not self._backend:
            self.setup()
        if self._backend == 'trio':
            trio_exc_map: ExceptionMapping = {trio.TooSlowError: PoolTimeout}
            timeout_or_inf = float('inf') if timeout is None else timeout
            with map_exceptions(trio_exc_map):
                with trio.fail_after(timeout_or_inf):
                    await self._trio_event.wait()
        elif self._backend == 'asyncio':
            anyio_exc_map: ExceptionMapping = {TimeoutError: PoolTimeout}
            with map_exceptions(anyio_exc_map):
                with anyio.fail_after(timeout):
                    await self._anyio_event.wait()

class AsyncSemaphore:

    def __init__(self, bound: int) -> None:
        self._bound = bound
        self._backend = ''

    def setup(self) -> None:
        self._backend = current_async_library()
        if self._backend == 'trio':
            self._trio_semaphore = trio.Semaphore(initial_value=self._bound, max_value=self._bound)
        elif self._backend == 'asyncio':
            self._anyio_semaphore = anyio.Semaphore(initial_value=self._bound, max_value=self._bound)

    async def acquire(self) -> None:
        if not self._backend:
            self.setup()
        if self._backend == 'trio':
            await self._trio_semaphore.acquire()
        elif self._backend == 'asyncio':
            await self._anyio_semaphore.acquire()

    async def release(self) -> None:
        if self._backend == 'trio':
            self._trio_semaphore.release()
        elif self._backend == 'asyncio':
            self._anyio_semaphore.release()

class AsyncShieldCancellation:

    def __init__(self) -> None:
        self._backend = current_async_library()
        if self._backend == 'trio':
            self._trio_shield = trio.CancelScope(shield=True)
        elif self._backend == 'asyncio':
            self._anyio_shield = anyio.CancelScope(shield=True)

    def __enter__(self) -> AsyncShieldCancellation:
        if self._backend == 'trio':
            self._trio_shield.__enter__()
        elif self._backend == 'asyncio':
            self._anyio_shield.__enter__()
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        if self._backend == 'trio':
            self._trio_shield.__exit__(exc_type, exc_value, traceback)
        elif self._backend == 'asyncio':
            self._anyio_shield.__exit__(exc_type, exc_value, traceback)

class Lock:

    def __init__(self) -> None:
        self._lock = threading.Lock()

    def __enter__(self) -> Lock:
        self._lock.acquire()
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        self._lock.release()

class ThreadLock:

    def __init__(self) -> None:
        self._lock = threading.Lock()

    def __enter__(self) -> ThreadLock:
        self._lock.acquire()
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        self._lock.release()

class Event:

    def __init__(self) -> None:
        self._event = threading.Event()

    def set(self) -> None:
        self._event.set()

    def wait(self, timeout: float | None=None) -> None:
        if timeout == float('inf'):
            timeout = None
        if not self._event.wait(timeout=timeout):
            raise PoolTimeout()

class Semaphore:

    def __init__(self, bound: int) -> None:
        self._semaphore = threading.Semaphore(value=bound)

    def acquire(self) -> None:
        self._semaphore.acquire()

    def release(self) -> None:
        self._semaphore.release()

class ShieldCancellation:

    def __enter__(self) -> ShieldCancellation:
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        pass

