import asyncio
import sys
from types import TracebackType
from typing import Any, Optional, Type, cast
import attr
from ._websocket.reader import WebSocketDataQueue
from .client_exceptions import ClientError, ServerTimeoutError, WSMessageTypeError
from .client_reqrep import ClientResponse
from .helpers import calculate_timeout_when, set_result
from .http import WS_CLOSED_MESSAGE, WS_CLOSING_MESSAGE, WebSocketError, WSCloseCode, WSMessage, WSMsgType
from .http_websocket import _INTERNAL_RECEIVE_TYPES, WebSocketWriter
from .streams import EofStream
from .typedefs import DEFAULT_JSON_DECODER, DEFAULT_JSON_ENCODER, JSONDecoder, JSONEncoder
if sys.version_info >= (3, 11):
    import asyncio as async_timeout
else:
    import async_timeout

@attr.s(frozen=True, slots=True)
class ClientWSTimeout:
    ws_receive = attr.ib(type=Optional[float], default=None)
    ws_close = attr.ib(type=Optional[float], default=None)
DEFAULT_WS_CLIENT_TIMEOUT = ClientWSTimeout(ws_receive=None, ws_close=10.0)

class ClientWebSocketResponse:

    def __init__(self, reader: WebSocketDataQueue, writer: WebSocketWriter, protocol: Optional[str], response: ClientResponse, timeout: ClientWSTimeout, autoclose: bool, autoping: bool, loop: asyncio.AbstractEventLoop, *, heartbeat: Optional[float]=None, compress: int=0, client_notakeover: bool=False) -> None:
        self._response = response
        self._conn = response.connection
        self._writer = writer
        self._reader = reader
        self._protocol = protocol
        self._closed = False
        self._closing = False
        self._close_code: Optional[int] = None
        self._timeout = timeout
        self._autoclose = autoclose
        self._autoping = autoping
        self._heartbeat = heartbeat
        self._heartbeat_cb: Optional[asyncio.TimerHandle] = None
        self._heartbeat_when: float = 0.0
        if heartbeat is not None:
            self._pong_heartbeat = heartbeat / 2.0
        self._pong_response_cb: Optional[asyncio.TimerHandle] = None
        self._loop = loop
        self._waiting: bool = False
        self._close_wait: Optional[asyncio.Future[None]] = None
        self._exception: Optional[BaseException] = None
        self._compress = compress
        self._client_notakeover = client_notakeover
        self._ping_task: Optional[asyncio.Task[None]] = None
        self._reset_heartbeat()

    def _cancel_heartbeat(self) -> None:
        self._cancel_pong_response_cb()
        if self._heartbeat_cb is not None:
            self._heartbeat_cb.cancel()
            self._heartbeat_cb = None
        if self._ping_task is not None:
            self._ping_task.cancel()
            self._ping_task = None

    def _cancel_pong_response_cb(self) -> None:
        if self._pong_response_cb is not None:
            self._pong_response_cb.cancel()
            self._pong_response_cb = None

    def _reset_heartbeat(self) -> None:
        if self._heartbeat is None:
            return
        self._cancel_pong_response_cb()
        loop = self._loop
        assert loop is not None
        conn = self._conn
        timeout_ceil_threshold = conn._connector._timeout_ceil_threshold if conn is not None else 5
        now = loop.time()
        when = calculate_timeout_when(now, self._heartbeat, timeout_ceil_threshold)
        self._heartbeat_when = when
        if self._heartbeat_cb is None:
            self._heartbeat_cb = loop.call_at(when, self._send_heartbeat)

    def _send_heartbeat(self) -> None:
        self._heartbeat_cb = None
        loop = self._loop
        now = loop.time()
        if now < self._heartbeat_when:
            self._heartbeat_cb = loop.call_at(self._heartbeat_when, self._send_heartbeat)
            return
        conn = self._conn
        timeout_ceil_threshold = conn._connector._timeout_ceil_threshold if conn is not None else 5
        when = calculate_timeout_when(now, self._pong_heartbeat, timeout_ceil_threshold)
        self._cancel_pong_response_cb()
        self._pong_response_cb = loop.call_at(when, self._pong_not_received)
        coro = self._writer.send_frame(b'', WSMsgType.PING)
        if sys.version_info >= (3, 12):
            ping_task = asyncio.Task(coro, loop=loop, eager_start=True)
        else:
            ping_task = loop.create_task(coro)
        if not ping_task.done():
            self._ping_task = ping_task
            ping_task.add_done_callback(self._ping_task_done)
        else:
            self._ping_task_done(ping_task)

    def _ping_task_done(self, task: 'asyncio.Task[None]') -> None:
        if not task.cancelled() and (exc := task.exception()):
            self._handle_ping_pong_exception(exc)
        self._ping_task = None

    def _pong_not_received(self) -> None:
        self._handle_ping_pong_exception(ServerTimeoutError(f'No PONG received after {self._pong_heartbeat} seconds'))

    def _handle_ping_pong_exception(self, exc: BaseException) -> None:
        if self._closed:
            return
        self._set_closed()
        self._close_code = WSCloseCode.ABNORMAL_CLOSURE
        self._exception = exc
        self._response.close()
        if self._waiting and (not self._closing):
            self._reader.feed_data(WSMessage(WSMsgType.ERROR, exc, None), 0)

    def _set_closed(self) -> None:
        self._closed = True
        self._cancel_heartbeat()

    def _set_closing(self) -> None:
        self._closing = True
        self._cancel_heartbeat()

    @property
    def closed(self) -> bool:
        return self._closed

    @property
    def close_code(self) -> Optional[int]:
        return self._close_code

    @property
    def protocol(self) -> Optional[str]:
        return self._protocol

    @property
    def compress(self) -> int:
        return self._compress

    @property
    def client_notakeover(self) -> bool:
        return self._client_notakeover

    def get_extra_info(self, name: str, default: Any=None) -> Any:
        conn = self._response.connection
        if conn is None:
            return default
        transport = conn.transport
        if transport is None:
            return default
        return transport.get_extra_info(name, default)

    def exception(self) -> Optional[BaseException]:
        return self._exception

    async def ping(self, message: bytes=b'') -> None:
        await self._writer.send_frame(message, WSMsgType.PING)

    async def pong(self, message: bytes=b'') -> None:
        await self._writer.send_frame(message, WSMsgType.PONG)

    async def send_frame(self, message: bytes, opcode: WSMsgType, compress: Optional[int]=None) -> None:
        await self._writer.send_frame(message, opcode, compress)

    async def send_str(self, data: str, compress: Optional[int]=None) -> None:
        if not isinstance(data, str):
            raise TypeError('data argument must be str (%r)' % type(data))
        await self._writer.send_frame(data.encode('utf-8'), WSMsgType.TEXT, compress=compress)

    async def send_bytes(self, data: bytes, compress: Optional[int]=None) -> None:
        if not isinstance(data, (bytes, bytearray, memoryview)):
            raise TypeError('data argument must be byte-ish (%r)' % type(data))
        await self._writer.send_frame(data, WSMsgType.BINARY, compress=compress)

    async def send_json(self, data: Any, compress: Optional[int]=None, *, dumps: JSONEncoder=DEFAULT_JSON_ENCODER) -> None:
        await self.send_str(dumps(data), compress=compress)

    async def close(self, *, code: int=WSCloseCode.OK, message: bytes=b'') -> bool:
        if self._waiting and (not self._closing):
            assert self._loop is not None
            self._close_wait = self._loop.create_future()
            self._set_closing()
            self._reader.feed_data(WS_CLOSING_MESSAGE, 0)
            await self._close_wait
        if self._closed:
            return False
        self._set_closed()
        try:
            await self._writer.close(code, message)
        except asyncio.CancelledError:
            self._close_code = WSCloseCode.ABNORMAL_CLOSURE
            self._response.close()
            raise
        except Exception as exc:
            self._close_code = WSCloseCode.ABNORMAL_CLOSURE
            self._exception = exc
            self._response.close()
            return True
        if self._close_code:
            self._response.close()
            return True
        while True:
            try:
                async with async_timeout.timeout(self._timeout.ws_close):
                    msg = await self._reader.read()
            except asyncio.CancelledError:
                self._close_code = WSCloseCode.ABNORMAL_CLOSURE
                self._response.close()
                raise
            except Exception as exc:
                self._close_code = WSCloseCode.ABNORMAL_CLOSURE
                self._exception = exc
                self._response.close()
                return True
            if msg.type is WSMsgType.CLOSE:
                self._close_code = msg.data
                self._response.close()
                return True

    async def receive(self, timeout: Optional[float]=None) -> WSMessage:
        receive_timeout = timeout or self._timeout.ws_receive
        while True:
            if self._waiting:
                raise RuntimeError('Concurrent call to receive() is not allowed')
            if self._closed:
                return WS_CLOSED_MESSAGE
            elif self._closing:
                await self.close()
                return WS_CLOSED_MESSAGE
            try:
                self._waiting = True
                try:
                    if receive_timeout:
                        async with async_timeout.timeout(receive_timeout):
                            msg = await self._reader.read()
                    else:
                        msg = await self._reader.read()
                    self._reset_heartbeat()
                finally:
                    self._waiting = False
                    if self._close_wait:
                        set_result(self._close_wait, None)
            except (asyncio.CancelledError, asyncio.TimeoutError):
                self._close_code = WSCloseCode.ABNORMAL_CLOSURE
                raise
            except EofStream:
                self._close_code = WSCloseCode.OK
                await self.close()
                return WSMessage(WSMsgType.CLOSED, None, None)
            except ClientError:
                self._set_closed()
                self._close_code = WSCloseCode.ABNORMAL_CLOSURE
                return WS_CLOSED_MESSAGE
            except WebSocketError as exc:
                self._close_code = exc.code
                await self.close(code=exc.code)
                return WSMessage(WSMsgType.ERROR, exc, None)
            except Exception as exc:
                self._exception = exc
                self._set_closing()
                self._close_code = WSCloseCode.ABNORMAL_CLOSURE
                await self.close()
                return WSMessage(WSMsgType.ERROR, exc, None)
            if msg.type not in _INTERNAL_RECEIVE_TYPES:
                return msg
            if msg.type is WSMsgType.CLOSE:
                self._set_closing()
                self._close_code = msg.data
                if not self._closed and self._autoclose:
                    await self.close()
            elif msg.type is WSMsgType.CLOSING:
                self._set_closing()
            elif msg.type is WSMsgType.PING and self._autoping:
                await self.pong(msg.data)
                continue
            elif msg.type is WSMsgType.PONG and self._autoping:
                continue
            return msg

    async def receive_str(self, *, timeout: Optional[float]=None) -> str:
        msg = await self.receive(timeout)
        if msg.type is not WSMsgType.TEXT:
            raise WSMessageTypeError(f'Received message {msg.type}:{msg.data!r} is not WSMsgType.TEXT')
        return cast(str, msg.data)

    async def receive_bytes(self, *, timeout: Optional[float]=None) -> bytes:
        msg = await self.receive(timeout)
        if msg.type is not WSMsgType.BINARY:
            raise WSMessageTypeError(f'Received message {msg.type}:{msg.data!r} is not WSMsgType.BINARY')
        return cast(bytes, msg.data)

    async def receive_json(self, *, loads: JSONDecoder=DEFAULT_JSON_DECODER, timeout: Optional[float]=None) -> Any:
        data = await self.receive_str(timeout=timeout)
        return loads(data)

    def __aiter__(self) -> 'ClientWebSocketResponse':
        return self

    async def __anext__(self) -> WSMessage:
        msg = await self.receive()
        if msg.type in (WSMsgType.CLOSE, WSMsgType.CLOSING, WSMsgType.CLOSED):
            raise StopAsyncIteration
        return msg

    async def __aenter__(self) -> 'ClientWebSocketResponse':
        return self

    async def __aexit__(self, exc_type: Optional[Type[BaseException]], exc_val: Optional[BaseException], exc_tb: Optional[TracebackType]) -> None:
        await self.close()

import json
from functools import lru_cache
from pathlib import Path
from typing import Any, Optional, Union
from urllib.parse import urlparse, urlunparse
from huggingface_hub import constants
from huggingface_hub.hf_api import InferenceProviderMapping
from huggingface_hub.inference._common import MimeBytes, RequestParameters, _b64_encode, _bytes_to_dict, _open_as_mime_bytes
from huggingface_hub.inference._providers._common import TaskProviderHelper, filter_none
from huggingface_hub.utils import build_hf_headers, get_session, get_token, hf_raise_for_status

class HFInferenceTask(TaskProviderHelper):

    def __init__(self, task: str):
        super().__init__(provider='hf-inference', base_url=constants.INFERENCE_PROXY_TEMPLATE.format(provider='hf-inference'), task=task)

    def _prepare_api_key(self, api_key: Optional[str]) -> str:
        return api_key or get_token()

    def _prepare_mapping_info(self, model: Optional[str]) -> InferenceProviderMapping:
        if model is not None and model.startswith(('http://', 'https://')):
            return InferenceProviderMapping(provider='hf-inference', providerId=model, hf_model_id=model, task=self.task, status='live')
        model_id = model if model is not None else _fetch_recommended_models().get(self.task)
        if model_id is None:
            raise ValueError(f'Task {self.task} has no recommended model for HF Inference. Please specify a model explicitly. Visit https://huggingface.co/tasks for more info.')
        _check_supported_task(model_id, self.task)
        return InferenceProviderMapping(provider='hf-inference', providerId=model_id, hf_model_id=model_id, task=self.task, status='live')

    def _prepare_url(self, api_key: str, mapped_model: str) -> str:
        if mapped_model.startswith(('http://', 'https://')):
            return mapped_model
        return f'{self.base_url}/models/{mapped_model}/pipeline/{self.task}' if self.task in ('feature-extraction', 'sentence-similarity') else f'{self.base_url}/models/{mapped_model}'

    def _prepare_payload_as_dict(self, inputs: Any, parameters: dict, provider_mapping_info: InferenceProviderMapping) -> Optional[dict]:
        if isinstance(inputs, bytes):
            raise ValueError(f'Unexpected binary input for task {self.task}.')
        if isinstance(inputs, Path):
            raise ValueError(f'Unexpected path input for task {self.task} (got {inputs})')
        return filter_none({'inputs': inputs, 'parameters': parameters})

class HFInferenceBinaryInputTask(HFInferenceTask):

    def _prepare_payload_as_dict(self, inputs: Any, parameters: dict, provider_mapping_info: InferenceProviderMapping) -> Optional[dict]:
        return None

    def _prepare_payload_as_bytes(self, inputs: Any, parameters: dict, provider_mapping_info: InferenceProviderMapping, extra_payload: Optional[dict]) -> Optional[MimeBytes]:
        parameters = filter_none(parameters)
        extra_payload = extra_payload or {}
        has_parameters = len(parameters) > 0 or len(extra_payload) > 0
        if not isinstance(inputs, (bytes, Path)) and (not isinstance(inputs, str)):
            raise ValueError(f'Expected binary inputs or a local path or a URL. Got {inputs}')
        if not has_parameters:
            return _open_as_mime_bytes(inputs)
        return MimeBytes(json.dumps({'inputs': _b64_encode(inputs), 'parameters': parameters, **extra_payload}).encode('utf-8'), mime_type='application/json')

class HFInferenceConversational(HFInferenceTask):

    def __init__(self):
        super().__init__('conversational')

    def _prepare_payload_as_dict(self, inputs: Any, parameters: dict, provider_mapping_info: InferenceProviderMapping) -> Optional[dict]:
        payload = filter_none(parameters)
        mapped_model = provider_mapping_info.provider_id
        payload_model = parameters.get('model') or mapped_model
        if payload_model is None or payload_model.startswith(('http://', 'https://')):
            payload_model = 'dummy'
        response_format = parameters.get('response_format')
        if isinstance(response_format, dict) and response_format.get('type') == 'json_schema':
            payload['response_format'] = {'type': 'json_object', 'value': response_format['json_schema']['schema']}
        return {**payload, 'model': payload_model, 'messages': inputs}

    def _prepare_url(self, api_key: str, mapped_model: str) -> str:
        base_url = mapped_model if mapped_model.startswith(('http://', 'https://')) else f"{constants.INFERENCE_PROXY_TEMPLATE.format(provider='hf-inference')}/models/{mapped_model}"
        return _build_chat_completion_url(base_url)

def _build_chat_completion_url(model_url: str) -> str:
    parsed = urlparse(model_url)
    path = parsed.path.rstrip('/')
    if path.endswith('/chat/completions'):
        return model_url
    if path.endswith('/v1'):
        new_path = path + '/chat/completions'
    elif not path:
        new_path = '/v1/chat/completions'
    else:
        new_path = path + '/v1/chat/completions'
    new_parsed = parsed._replace(path=new_path)
    return str(urlunparse(new_parsed))

@lru_cache(maxsize=1)
def _fetch_recommended_models() -> dict[str, Optional[str]]:
    response = get_session().get(f'{constants.ENDPOINT}/api/tasks', headers=build_hf_headers())
    hf_raise_for_status(response)
    return {task: next(iter(details['widgetModels']), None) for task, details in response.json().items()}

@lru_cache(maxsize=None)
def _check_supported_task(model: str, task: str) -> None:
    from huggingface_hub.hf_api import HfApi
    model_info = HfApi().model_info(model)
    pipeline_tag = model_info.pipeline_tag
    tags = model_info.tags or []
    is_conversational = 'conversational' in tags
    if task in ('text-generation', 'conversational'):
        if pipeline_tag == 'text-generation':
            if is_conversational:
                return
            if task == 'text-generation':
                return
            raise ValueError(f"Model '{model}' doesn't support task '{task}'.")
    if pipeline_tag == 'text2text-generation':
        if task == 'text-generation':
            return
        raise ValueError(f"Model '{model}' doesn't support task '{task}'.")
    if pipeline_tag == 'image-text-to-text':
        if is_conversational and task == 'conversational':
            return
        raise ValueError('Non-conversational image-text-to-text task is not supported.')
    if task in ('feature-extraction', 'sentence-similarity') and pipeline_tag in ('feature-extraction', 'sentence-similarity') and (task in tags):
        return
    if pipeline_tag != task:
        raise ValueError(f"Model '{model}' doesn't support task '{task}'. Supported tasks: '{pipeline_tag}', got: '{task}'")
    return

class HFInferenceFeatureExtractionTask(HFInferenceTask):

    def __init__(self):
        super().__init__('feature-extraction')

    def _prepare_payload_as_dict(self, inputs: Any, parameters: dict, provider_mapping_info: InferenceProviderMapping) -> Optional[dict]:
        if isinstance(inputs, bytes):
            raise ValueError(f'Unexpected binary input for task {self.task}.')
        if isinstance(inputs, Path):
            raise ValueError(f'Unexpected path input for task {self.task} (got {inputs})')
        return {'inputs': inputs, **filter_none(parameters)}

    def get_response(self, response: Union[bytes, dict], request_params: Optional[RequestParameters]=None) -> Any:
        if isinstance(response, bytes):
            return _bytes_to_dict(response)
        return response

import asyncio
from contextlib import suppress
from typing import Any, Optional, Tuple, Union
from .base_protocol import BaseProtocol
from .client_exceptions import ClientConnectionError, ClientOSError, ClientPayloadError, ServerDisconnectedError, SocketTimeoutError
from .helpers import _EXC_SENTINEL, EMPTY_BODY_STATUS_CODES, BaseTimerContext, set_exception, set_result
from .http import HttpResponseParser, RawResponseMessage
from .http_exceptions import HttpProcessingError
from .streams import EMPTY_PAYLOAD, DataQueue, StreamReader

class ResponseHandler(BaseProtocol, DataQueue[Tuple[RawResponseMessage, StreamReader]]):

    def __init__(self, loop: asyncio.AbstractEventLoop) -> None:
        BaseProtocol.__init__(self, loop=loop)
        DataQueue.__init__(self, loop)
        self._should_close = False
        self._payload: Optional[StreamReader] = None
        self._skip_payload = False
        self._payload_parser = None
        self._timer = None
        self._tail = b''
        self._upgraded = False
        self._parser: Optional[HttpResponseParser] = None
        self._read_timeout: Optional[float] = None
        self._read_timeout_handle: Optional[asyncio.TimerHandle] = None
        self._timeout_ceil_threshold: Optional[float] = 5
        self._closed: Union[None, asyncio.Future[None]] = None
        self._connection_lost_called = False

    @property
    def closed(self) -> Union[None, asyncio.Future[None]]:
        if self._closed is None and (not self._connection_lost_called):
            self._closed = self._loop.create_future()
        return self._closed

    @property
    def upgraded(self) -> bool:
        return self._upgraded

    @property
    def should_close(self) -> bool:
        return bool(self._should_close or (self._payload is not None and (not self._payload.is_eof())) or self._upgraded or (self._exception is not None) or (self._payload_parser is not None) or self._buffer or self._tail)

    def force_close(self) -> None:
        self._should_close = True

    def close(self) -> None:
        self._exception = None
        transport = self.transport
        if transport is not None:
            transport.close()
            self.transport = None
            self._payload = None
            self._drop_timeout()

    def abort(self) -> None:
        self._exception = None
        transport = self.transport
        if transport is not None:
            transport.abort()
            self.transport = None
            self._payload = None
            self._drop_timeout()

    def is_connected(self) -> bool:
        return self.transport is not None and (not self.transport.is_closing())

    def connection_lost(self, exc: Optional[BaseException]) -> None:
        self._connection_lost_called = True
        self._drop_timeout()
        original_connection_error = exc
        reraised_exc = original_connection_error
        connection_closed_cleanly = original_connection_error is None
        if self._closed is not None:
            if connection_closed_cleanly:
                set_result(self._closed, None)
            else:
                assert original_connection_error is not None
                set_exception(self._closed, ClientConnectionError(f'Connection lost: {original_connection_error!s}'), original_connection_error)
        if self._payload_parser is not None:
            with suppress(Exception):
                self._payload_parser.feed_eof()
        uncompleted = None
        if self._parser is not None:
            try:
                uncompleted = self._parser.feed_eof()
            except Exception as underlying_exc:
                if self._payload is not None:
                    client_payload_exc_msg = f'Response payload is not completed: {underlying_exc!r}'
                    if not connection_closed_cleanly:
                        client_payload_exc_msg = f'{client_payload_exc_msg!s}. {original_connection_error!r}'
                    set_exception(self._payload, ClientPayloadError(client_payload_exc_msg), underlying_exc)
        if not self.is_eof():
            if isinstance(original_connection_error, OSError):
                reraised_exc = ClientOSError(*original_connection_error.args)
            if connection_closed_cleanly:
                reraised_exc = ServerDisconnectedError(uncompleted)
            underlying_non_eof_exc = _EXC_SENTINEL if connection_closed_cleanly else original_connection_error
            assert underlying_non_eof_exc is not None
            assert reraised_exc is not None
            self.set_exception(reraised_exc, underlying_non_eof_exc)
        self._should_close = True
        self._parser = None
        self._payload = None
        self._payload_parser = None
        self._reading_paused = False
        super().connection_lost(reraised_exc)

    def eof_received(self) -> None:
        self._drop_timeout()

    def pause_reading(self) -> None:
        super().pause_reading()
        self._drop_timeout()

    def resume_reading(self) -> None:
        super().resume_reading()
        self._reschedule_timeout()

    def set_exception(self, exc: BaseException, exc_cause: BaseException=_EXC_SENTINEL) -> None:
        self._should_close = True
        self._drop_timeout()
        super().set_exception(exc, exc_cause)

    def set_parser(self, parser: Any, payload: Any) -> None:
        self._payload = payload
        self._payload_parser = parser
        self._drop_timeout()
        if self._tail:
            data, self._tail = (self._tail, b'')
            self.data_received(data)

    def set_response_params(self, *, timer: Optional[BaseTimerContext]=None, skip_payload: bool=False, read_until_eof: bool=False, auto_decompress: bool=True, read_timeout: Optional[float]=None, read_bufsize: int=2 ** 16, timeout_ceil_threshold: float=5, max_line_size: int=8190, max_field_size: int=8190, max_headers: int=128) -> None:
        self._skip_payload = skip_payload
        self._read_timeout = read_timeout
        self._timeout_ceil_threshold = timeout_ceil_threshold
        self._parser = HttpResponseParser(self, self._loop, read_bufsize, timer=timer, payload_exception=ClientPayloadError, response_with_body=not skip_payload, read_until_eof=read_until_eof, auto_decompress=auto_decompress, max_line_size=max_line_size, max_field_size=max_field_size, max_headers=max_headers)
        if self._tail:
            data, self._tail = (self._tail, b'')
            self.data_received(data)

    def _drop_timeout(self) -> None:
        if self._read_timeout_handle is not None:
            self._read_timeout_handle.cancel()
            self._read_timeout_handle = None

    def _reschedule_timeout(self) -> None:
        timeout = self._read_timeout
        if self._read_timeout_handle is not None:
            self._read_timeout_handle.cancel()
        if timeout:
            self._read_timeout_handle = self._loop.call_later(timeout, self._on_read_timeout)
        else:
            self._read_timeout_handle = None

    def start_timeout(self) -> None:
        self._reschedule_timeout()

    @property
    def read_timeout(self) -> Optional[float]:
        return self._read_timeout

    @read_timeout.setter
    def read_timeout(self, read_timeout: Optional[float]) -> None:
        self._read_timeout = read_timeout

    def _on_read_timeout(self) -> None:
        exc = SocketTimeoutError('Timeout on reading data from socket')
        self.set_exception(exc)
        if self._payload is not None:
            set_exception(self._payload, exc)

    def data_received(self, data: bytes) -> None:
        self._reschedule_timeout()
        if not data:
            return
        if self._payload_parser is not None:
            eof, tail = self._payload_parser.feed_data(data)
            if eof:
                self._payload = None
                self._payload_parser = None
                if tail:
                    self.data_received(tail)
            return
        if self._upgraded or self._parser is None:
            self._tail += data
            return
        try:
            messages, upgraded, tail = self._parser.feed_data(data)
        except BaseException as underlying_exc:
            if self.transport is not None:
                self.transport.close()
            if isinstance(underlying_exc, HttpProcessingError):
                exc = HttpProcessingError(code=underlying_exc.code, message=underlying_exc.message, headers=underlying_exc.headers)
            else:
                exc = HttpProcessingError()
            self.set_exception(exc, underlying_exc)
            return
        self._upgraded = upgraded
        payload: Optional[StreamReader] = None
        for message, payload in messages:
            if message.should_close:
                self._should_close = True
            self._payload = payload
            if self._skip_payload or message.code in EMPTY_BODY_STATUS_CODES:
                self.feed_data((message, EMPTY_PAYLOAD), 0)
            else:
                self.feed_data((message, payload), 0)
        if payload is not None:
            if payload is not EMPTY_PAYLOAD:
                payload.on_eof(self._drop_timeout)
            else:
                self._drop_timeout()
        if upgraded and tail:
            self.data_received(tail)

from typing import Any, Callable, cast, Dict, List, Optional, overload, Tuple, Type, Union
from ._events import ConnectionClosed, Data, EndOfMessage, Event, InformationalResponse, Request, Response
from ._headers import get_comma_header, has_expect_100_continue, set_comma_header
from ._readers import READERS, ReadersType
from ._receivebuffer import ReceiveBuffer
from ._state import _SWITCH_CONNECT, _SWITCH_UPGRADE, CLIENT, ConnectionState, DONE, ERROR, MIGHT_SWITCH_PROTOCOL, SEND_BODY, SERVER, SWITCHED_PROTOCOL
from ._util import LocalProtocolError, RemoteProtocolError, Sentinel
from ._writers import WRITERS, WritersType
__all__ = ['Connection', 'NEED_DATA', 'PAUSED']

class NEED_DATA(Sentinel, metaclass=Sentinel):
    pass

class PAUSED(Sentinel, metaclass=Sentinel):
    pass
DEFAULT_MAX_INCOMPLETE_EVENT_SIZE = 16 * 1024

def _keep_alive(event: Union[Request, Response]) -> bool:
    connection = get_comma_header(event.headers, b'connection')
    if b'close' in connection:
        return False
    if getattr(event, 'http_version', b'1.1') < b'1.1':
        return False
    return True

def _body_framing(request_method: bytes, event: Union[Request, Response]) -> Tuple[str, Union[Tuple[()], Tuple[int]]]:
    assert type(event) in (Request, Response)
    if type(event) is Response:
        if event.status_code in (204, 304) or request_method == b'HEAD' or (request_method == b'CONNECT' and 200 <= event.status_code < 300):
            return ('content-length', (0,))
        assert event.status_code >= 200
    transfer_encodings = get_comma_header(event.headers, b'transfer-encoding')
    if transfer_encodings:
        assert transfer_encodings == [b'chunked']
        return ('chunked', ())
    content_lengths = get_comma_header(event.headers, b'content-length')
    if content_lengths:
        return ('content-length', (int(content_lengths[0]),))
    if type(event) is Request:
        return ('content-length', (0,))
    else:
        return ('http/1.0', ())

class Connection:

    def __init__(self, our_role: Type[Sentinel], max_incomplete_event_size: int=DEFAULT_MAX_INCOMPLETE_EVENT_SIZE) -> None:
        self._max_incomplete_event_size = max_incomplete_event_size
        if our_role not in (CLIENT, SERVER):
            raise ValueError(f'expected CLIENT or SERVER, not {our_role!r}')
        self.our_role = our_role
        self.their_role: Type[Sentinel]
        if our_role is CLIENT:
            self.their_role = SERVER
        else:
            self.their_role = CLIENT
        self._cstate = ConnectionState()
        self._writer = self._get_io_object(self.our_role, None, WRITERS)
        self._reader = self._get_io_object(self.their_role, None, READERS)
        self._receive_buffer = ReceiveBuffer()
        self._receive_buffer_closed = False
        self.their_http_version: Optional[bytes] = None
        self._request_method: Optional[bytes] = None
        self.client_is_waiting_for_100_continue = False

    @property
    def states(self) -> Dict[Type[Sentinel], Type[Sentinel]]:
        return dict(self._cstate.states)

    @property
    def our_state(self) -> Type[Sentinel]:
        return self._cstate.states[self.our_role]

    @property
    def their_state(self) -> Type[Sentinel]:
        return self._cstate.states[self.their_role]

    @property
    def they_are_waiting_for_100_continue(self) -> bool:
        return self.their_role is CLIENT and self.client_is_waiting_for_100_continue

    def start_next_cycle(self) -> None:
        old_states = dict(self._cstate.states)
        self._cstate.start_next_cycle()
        self._request_method = None
        assert not self.client_is_waiting_for_100_continue
        self._respond_to_state_changes(old_states)

    def _process_error(self, role: Type[Sentinel]) -> None:
        old_states = dict(self._cstate.states)
        self._cstate.process_error(role)
        self._respond_to_state_changes(old_states)

    def _server_switch_event(self, event: Event) -> Optional[Type[Sentinel]]:
        if type(event) is InformationalResponse and event.status_code == 101:
            return _SWITCH_UPGRADE
        if type(event) is Response:
            if _SWITCH_CONNECT in self._cstate.pending_switch_proposals and 200 <= event.status_code < 300:
                return _SWITCH_CONNECT
        return None

    def _process_event(self, role: Type[Sentinel], event: Event) -> None:
        old_states = dict(self._cstate.states)
        if role is CLIENT and type(event) is Request:
            if event.method == b'CONNECT':
                self._cstate.process_client_switch_proposal(_SWITCH_CONNECT)
            if get_comma_header(event.headers, b'upgrade'):
                self._cstate.process_client_switch_proposal(_SWITCH_UPGRADE)
        server_switch_event = None
        if role is SERVER:
            server_switch_event = self._server_switch_event(event)
        self._cstate.process_event(role, type(event), server_switch_event)
        if type(event) is Request:
            self._request_method = event.method
        if role is self.their_role and type(event) in (Request, Response, InformationalResponse):
            event = cast(Union[Request, Response, InformationalResponse], event)
            self.their_http_version = event.http_version
        if type(event) in (Request, Response) and (not _keep_alive(cast(Union[Request, Response], event))):
            self._cstate.process_keep_alive_disabled()
        if type(event) is Request and has_expect_100_continue(event):
            self.client_is_waiting_for_100_continue = True
        if type(event) in (InformationalResponse, Response):
            self.client_is_waiting_for_100_continue = False
        if role is CLIENT and type(event) in (Data, EndOfMessage):
            self.client_is_waiting_for_100_continue = False
        self._respond_to_state_changes(old_states, event)

    def _get_io_object(self, role: Type[Sentinel], event: Optional[Event], io_dict: Union[ReadersType, WritersType]) -> Optional[Callable[..., Any]]:
        state = self._cstate.states[role]
        if state is SEND_BODY:
            framing_type, args = _body_framing(cast(bytes, self._request_method), cast(Union[Request, Response], event))
            return io_dict[SEND_BODY][framing_type](*args)
        else:
            return io_dict.get((role, state))

    def _respond_to_state_changes(self, old_states: Dict[Type[Sentinel], Type[Sentinel]], event: Optional[Event]=None) -> None:
        if self.our_state != old_states[self.our_role]:
            self._writer = self._get_io_object(self.our_role, event, WRITERS)
        if self.their_state != old_states[self.their_role]:
            self._reader = self._get_io_object(self.their_role, event, READERS)

    @property
    def trailing_data(self) -> Tuple[bytes, bool]:
        return (bytes(self._receive_buffer), self._receive_buffer_closed)

    def receive_data(self, data: bytes) -> None:
        if data:
            if self._receive_buffer_closed:
                raise RuntimeError('received close, then received more data?')
            self._receive_buffer += data
        else:
            self._receive_buffer_closed = True

    def _extract_next_receive_event(self) -> Union[Event, Type[NEED_DATA], Type[PAUSED]]:
        state = self.their_state
        if state is DONE and self._receive_buffer:
            return PAUSED
        if state is MIGHT_SWITCH_PROTOCOL or state is SWITCHED_PROTOCOL:
            return PAUSED
        assert self._reader is not None
        event = self._reader(self._receive_buffer)
        if event is None:
            if not self._receive_buffer and self._receive_buffer_closed:
                if hasattr(self._reader, 'read_eof'):
                    event = self._reader.read_eof()
                else:
                    event = ConnectionClosed()
        if event is None:
            event = NEED_DATA
        return event

    def next_event(self) -> Union[Event, Type[NEED_DATA], Type[PAUSED]]:
        if self.their_state is ERROR:
            raise RemoteProtocolError("Can't receive data when peer state is ERROR")
        try:
            event = self._extract_next_receive_event()
            if event not in [NEED_DATA, PAUSED]:
                self._process_event(self.their_role, cast(Event, event))
            if event is NEED_DATA:
                if len(self._receive_buffer) > self._max_incomplete_event_size:
                    raise RemoteProtocolError('Receive buffer too long', error_status_hint=431)
                if self._receive_buffer_closed:
                    raise RemoteProtocolError('peer unexpectedly closed connection')
            return event
        except BaseException as exc:
            self._process_error(self.their_role)
            if isinstance(exc, LocalProtocolError):
                exc._reraise_as_remote_protocol_error()
            else:
                raise

    @overload
    def send(self, event: ConnectionClosed) -> None:
        ...

    @overload
    def send(self, event: Union[Request, InformationalResponse, Response, Data, EndOfMessage]) -> bytes:
        ...

    @overload
    def send(self, event: Event) -> Optional[bytes]:
        ...

    def send(self, event: Event) -> Optional[bytes]:
        data_list = self.send_with_data_passthrough(event)
        if data_list is None:
            return None
        else:
            return b''.join(data_list)

    def send_with_data_passthrough(self, event: Event) -> Optional[List[bytes]]:
        if self.our_state is ERROR:
            raise LocalProtocolError("Can't send data when our state is ERROR")
        try:
            if type(event) is Response:
                event = self._clean_up_response_headers_for_sending(event)
            writer = self._writer
            self._process_event(self.our_role, event)
            if type(event) is ConnectionClosed:
                return None
            else:
                assert writer is not None
                data_list: List[bytes] = []
                writer(event, data_list.append)
                return data_list
        except:
            self._process_error(self.our_role)
            raise

    def send_failed(self) -> None:
        self._process_error(self.our_role)

    def _clean_up_response_headers_for_sending(self, response: Response) -> Response:
        assert type(response) is Response
        headers = response.headers
        need_close = False
        method_for_choosing_headers = cast(bytes, self._request_method)
        if method_for_choosing_headers == b'HEAD':
            method_for_choosing_headers = b'GET'
        framing_type, _ = _body_framing(method_for_choosing_headers, response)
        if framing_type in ('chunked', 'http/1.0'):
            headers = set_comma_header(headers, b'content-length', [])
            if self.their_http_version is None or self.their_http_version < b'1.1':
                headers = set_comma_header(headers, b'transfer-encoding', [])
                if self._request_method != b'HEAD':
                    need_close = True
            else:
                headers = set_comma_header(headers, b'transfer-encoding', [b'chunked'])
        if not self._cstate.keep_alive or need_close:
            connection = set(get_comma_header(headers, b'connection'))
            connection.discard(b'keep-alive')
            connection.add(b'close')
            headers = set_comma_header(headers, b'connection', sorted(connection))
        return Response(headers=headers, status_code=response.status_code, http_version=response.http_version, reason=response.reason)

import functools
import warnings
import numpy as np
import numpy._core.numeric as _nx
from numpy._core import atleast_3d, overrides, vstack
from numpy._core._multiarray_umath import _array_converter
from numpy._core.fromnumeric import reshape, transpose
from numpy._core.multiarray import normalize_axis_index
from numpy._core.numeric import array, asanyarray, asarray, normalize_axis_tuple, zeros, zeros_like
from numpy._core.overrides import set_module
from numpy._core.shape_base import _arrays_for_stack_dispatcher
from numpy.lib._index_tricks_impl import ndindex
from numpy.matrixlib.defmatrix import matrix
__all__ = ['column_stack', 'row_stack', 'dstack', 'array_split', 'split', 'hsplit', 'vsplit', 'dsplit', 'apply_over_axes', 'expand_dims', 'apply_along_axis', 'kron', 'tile', 'take_along_axis', 'put_along_axis']
array_function_dispatch = functools.partial(overrides.array_function_dispatch, module='numpy')

def _make_along_axis_idx(arr_shape, indices, axis):
    if not _nx.issubdtype(indices.dtype, _nx.integer):
        raise IndexError('`indices` must be an integer array')
    if len(arr_shape) != indices.ndim:
        raise ValueError('`indices` and `arr` must have the same number of dimensions')
    shape_ones = (1,) * indices.ndim
    dest_dims = list(range(axis)) + [None] + list(range(axis + 1, indices.ndim))
    fancy_index = []
    for dim, n in zip(dest_dims, arr_shape):
        if dim is None:
            fancy_index.append(indices)
        else:
            ind_shape = shape_ones[:dim] + (-1,) + shape_ones[dim + 1:]
            fancy_index.append(_nx.arange(n).reshape(ind_shape))
    return tuple(fancy_index)

def _take_along_axis_dispatcher(arr, indices, axis=None):
    return (arr, indices)

@array_function_dispatch(_take_along_axis_dispatcher)
def take_along_axis(arr, indices, axis=-1):
    if axis is None:
        if indices.ndim != 1:
            raise ValueError('when axis=None, `indices` must have a single dimension.')
        arr = np.array(arr.flat)
        axis = 0
    else:
        axis = normalize_axis_index(axis, arr.ndim)
    return arr[_make_along_axis_idx(arr.shape, indices, axis)]

def _put_along_axis_dispatcher(arr, indices, values, axis):
    return (arr, indices, values)

@array_function_dispatch(_put_along_axis_dispatcher)
def put_along_axis(arr, indices, values, axis):
    if axis is None:
        if indices.ndim != 1:
            raise ValueError('when axis=None, `indices` must have a single dimension.')
        arr = np.array(arr.flat)
        axis = 0
    else:
        axis = normalize_axis_index(axis, arr.ndim)
    arr[_make_along_axis_idx(arr.shape, indices, axis)] = values

def _apply_along_axis_dispatcher(func1d, axis, arr, *args, **kwargs):
    return (arr,)

@array_function_dispatch(_apply_along_axis_dispatcher)
def apply_along_axis(func1d, axis, arr, *args, **kwargs):
    conv = _array_converter(arr)
    arr = conv[0]
    nd = arr.ndim
    axis = normalize_axis_index(axis, nd)
    in_dims = list(range(nd))
    inarr_view = transpose(arr, in_dims[:axis] + in_dims[axis + 1:] + [axis])
    inds = ndindex(inarr_view.shape[:-1])
    inds = (ind + (Ellipsis,) for ind in inds)
    try:
        ind0 = next(inds)
    except StopIteration:
        raise ValueError('Cannot apply_along_axis when any iteration dimensions are 0') from None
    res = asanyarray(func1d(inarr_view[ind0], *args, **kwargs))
    if not isinstance(res, matrix):
        buff = zeros_like(res, shape=inarr_view.shape[:-1] + res.shape)
    else:
        buff = zeros(inarr_view.shape[:-1] + res.shape, dtype=res.dtype)
    buff_dims = list(range(buff.ndim))
    buff_permute = buff_dims[0:axis] + buff_dims[buff.ndim - res.ndim:buff.ndim] + buff_dims[axis:buff.ndim - res.ndim]
    buff[ind0] = res
    for ind in inds:
        buff[ind] = asanyarray(func1d(inarr_view[ind], *args, **kwargs))
    res = transpose(buff, buff_permute)
    return conv.wrap(res)

def _apply_over_axes_dispatcher(func, a, axes):
    return (a,)

@array_function_dispatch(_apply_over_axes_dispatcher)
def apply_over_axes(func, a, axes):
    val = asarray(a)
    N = a.ndim
    if array(axes).ndim == 0:
        axes = (axes,)
    for axis in axes:
        if axis < 0:
            axis = N + axis
        args = (val, axis)
        res = func(*args)
        if res.ndim == val.ndim:
            val = res
        else:
            res = expand_dims(res, axis)
            if res.ndim == val.ndim:
                val = res
            else:
                raise ValueError('function is not returning an array of the correct shape')
    return val

def _expand_dims_dispatcher(a, axis):
    return (a,)

@array_function_dispatch(_expand_dims_dispatcher)
def expand_dims(a, axis):
    if isinstance(a, matrix):
        a = asarray(a)
    else:
        a = asanyarray(a)
    if not isinstance(axis, (tuple, list)):
        axis = (axis,)
    out_ndim = len(axis) + a.ndim
    axis = normalize_axis_tuple(axis, out_ndim)
    shape_it = iter(a.shape)
    shape = [1 if ax in axis else next(shape_it) for ax in range(out_ndim)]
    return a.reshape(shape)

@set_module('numpy')
def row_stack(tup, *, dtype=None, casting='same_kind'):
    warnings.warn('`row_stack` alias is deprecated. Use `np.vstack` directly.', DeprecationWarning, stacklevel=2)
    return vstack(tup, dtype=dtype, casting=casting)
row_stack.__doc__ = vstack.__doc__

def _column_stack_dispatcher(tup):
    return _arrays_for_stack_dispatcher(tup)

@array_function_dispatch(_column_stack_dispatcher)
def column_stack(tup):
    arrays = []
    for v in tup:
        arr = asanyarray(v)
        if arr.ndim < 2:
            arr = array(arr, copy=None, subok=True, ndmin=2).T
        arrays.append(arr)
    return _nx.concatenate(arrays, 1)

def _dstack_dispatcher(tup):
    return _arrays_for_stack_dispatcher(tup)

@array_function_dispatch(_dstack_dispatcher)
def dstack(tup):
    arrs = atleast_3d(*tup)
    if not isinstance(arrs, tuple):
        arrs = (arrs,)
    return _nx.concatenate(arrs, 2)

def _array_split_dispatcher(ary, indices_or_sections, axis=None):
    return (ary, indices_or_sections)

@array_function_dispatch(_array_split_dispatcher)
def array_split(ary, indices_or_sections, axis=0):
    try:
        Ntotal = ary.shape[axis]
    except AttributeError:
        Ntotal = len(ary)
    try:
        Nsections = len(indices_or_sections) + 1
        div_points = [0] + list(indices_or_sections) + [Ntotal]
    except TypeError:
        Nsections = int(indices_or_sections)
        if Nsections <= 0:
            raise ValueError('number sections must be larger than 0.') from None
        Neach_section, extras = divmod(Ntotal, Nsections)
        section_sizes = [0] + extras * [Neach_section + 1] + (Nsections - extras) * [Neach_section]
        div_points = _nx.array(section_sizes, dtype=_nx.intp).cumsum()
    sub_arys = []
    sary = _nx.swapaxes(ary, axis, 0)
    for i in range(Nsections):
        st = div_points[i]
        end = div_points[i + 1]
        sub_arys.append(_nx.swapaxes(sary[st:end], axis, 0))
    return sub_arys

def _split_dispatcher(ary, indices_or_sections, axis=None):
    return (ary, indices_or_sections)

@array_function_dispatch(_split_dispatcher)
def split(ary, indices_or_sections, axis=0):
    try:
        len(indices_or_sections)
    except TypeError:
        sections = indices_or_sections
        N = ary.shape[axis]
        if N % sections:
            raise ValueError('array split does not result in an equal division') from None
    return array_split(ary, indices_or_sections, axis)

def _hvdsplit_dispatcher(ary, indices_or_sections):
    return (ary, indices_or_sections)

@array_function_dispatch(_hvdsplit_dispatcher)
def hsplit(ary, indices_or_sections):
    if _nx.ndim(ary) == 0:
        raise ValueError('hsplit only works on arrays of 1 or more dimensions')
    if ary.ndim > 1:
        return split(ary, indices_or_sections, 1)
    else:
        return split(ary, indices_or_sections, 0)

@array_function_dispatch(_hvdsplit_dispatcher)
def vsplit(ary, indices_or_sections):
    if _nx.ndim(ary) < 2:
        raise ValueError('vsplit only works on arrays of 2 or more dimensions')
    return split(ary, indices_or_sections, 0)

@array_function_dispatch(_hvdsplit_dispatcher)
def dsplit(ary, indices_or_sections):
    if _nx.ndim(ary) < 3:
        raise ValueError('dsplit only works on arrays of 3 or more dimensions')
    return split(ary, indices_or_sections, 2)

def get_array_wrap(*args):
    warnings.warn('`get_array_wrap` is deprecated. (deprecated in NumPy 2.0)', DeprecationWarning, stacklevel=2)
    wrappers = sorted(((getattr(x, '__array_priority__', 0), -i, x.__array_wrap__) for i, x in enumerate(args) if hasattr(x, '__array_wrap__')))
    if wrappers:
        return wrappers[-1][-1]
    return None

def _kron_dispatcher(a, b):
    return (a, b)

@array_function_dispatch(_kron_dispatcher)
def kron(a, b):
    b = asanyarray(b)
    a = array(a, copy=None, subok=True, ndmin=b.ndim)
    is_any_mat = isinstance(a, matrix) or isinstance(b, matrix)
    ndb, nda = (b.ndim, a.ndim)
    nd = max(ndb, nda)
    if nda == 0 or ndb == 0:
        return _nx.multiply(a, b)
    as_ = a.shape
    bs = b.shape
    if not a.flags.contiguous:
        a = reshape(a, as_)
    if not b.flags.contiguous:
        b = reshape(b, bs)
    as_ = (1,) * max(0, ndb - nda) + as_
    bs = (1,) * max(0, nda - ndb) + bs
    a_arr = expand_dims(a, axis=tuple(range(ndb - nda)))
    b_arr = expand_dims(b, axis=tuple(range(nda - ndb)))
    a_arr = expand_dims(a_arr, axis=tuple(range(1, nd * 2, 2)))
    b_arr = expand_dims(b_arr, axis=tuple(range(0, nd * 2, 2)))
    result = _nx.multiply(a_arr, b_arr, subok=not is_any_mat)
    result = result.reshape(_nx.multiply(as_, bs))
    return result if not is_any_mat else matrix(result, copy=False)

def _tile_dispatcher(A, reps):
    return (A, reps)

@array_function_dispatch(_tile_dispatcher)
def tile(A, reps):
    try:
        tup = tuple(reps)
    except TypeError:
        tup = (reps,)
    d = len(tup)
    if all((x == 1 for x in tup)) and isinstance(A, _nx.ndarray):
        return _nx.array(A, copy=True, subok=True, ndmin=d)
    else:
        c = _nx.array(A, copy=None, subok=True, ndmin=d)
    if d < c.ndim:
        tup = (1,) * (c.ndim - d) + tup
    shape_out = tuple((s * t for s, t in zip(c.shape, tup)))
    n = c.size
    if n > 0:
        for dim_in, nrep in zip(c.shape, tup):
            if nrep != 1:
                c = c.reshape(-1, n).repeat(nrep, 0)
            n //= dim_in
    return c.reshape(shape_out)

