            except ImportError:
                raise ImportError("Using SOCKS proxy, but the 'socksio' package is not installed. Make sure to install httpx using `pip install httpx[socks]`.") from None
            self._pool = httpcore.SOCKSProxy(proxy_url=httpcore.URL(scheme=proxy.url.raw_scheme, host=proxy.url.raw_host, port=proxy.url.port, target=proxy.url.raw_path), proxy_auth=proxy.raw_auth, ssl_context=ssl_context, max_connections=limits.max_connections, max_keepalive_connections=limits.max_keepalive_connections, keepalive_expiry=limits.keepalive_expiry, http1=http1, http2=http2)
        else:
            raise ValueError(f"Proxy protocol must be either 'http', 'https', 'socks5', or 'socks5h', but got {proxy.url.scheme!r}.")

    def __enter__(self: T) -> T:
        self._pool.__enter__()
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: TracebackType | None=None) -> None:
        with map_httpcore_exceptions():
            self._pool.__exit__(exc_type, exc_value, traceback)

    def handle_request(self, request: Request) -> Response:
        assert isinstance(request.stream, SyncByteStream)
        import httpcore
        req = httpcore.Request(method=request.method, url=httpcore.URL(scheme=request.url.raw_scheme, host=request.url.raw_host, port=request.url.port, target=request.url.raw_path), headers=request.headers.raw, content=request.stream, extensions=request.extensions)
        with map_httpcore_exceptions():
            resp = self._pool.handle_request(req)
        assert isinstance(resp.stream, typing.Iterable)
        return Response(status_code=resp.status, headers=resp.headers, stream=ResponseStream(resp.stream), extensions=resp.extensions)

    def close(self) -> None:
        self._pool.close()

class AsyncResponseStream(AsyncByteStream):

    def __init__(self, httpcore_stream: typing.AsyncIterable[bytes]) -> None:
        self._httpcore_stream = httpcore_stream

    async def __aiter__(self) -> typing.AsyncIterator[bytes]:
        with map_httpcore_exceptions():
            async for part in self._httpcore_stream:
                yield part

    async def aclose(self) -> None:
        if hasattr(self._httpcore_stream, 'aclose'):
            await self._httpcore_stream.aclose()

class AsyncHTTPTransport(AsyncBaseTransport):

    def __init__(self, verify: ssl.SSLContext | str | bool=True, cert: CertTypes | None=None, trust_env: bool=True, http1: bool=True, http2: bool=False, limits: Limits=DEFAULT_LIMITS, proxy: ProxyTypes | None=None, uds: str | None=None, local_address: str | None=None, retries: int=0, socket_options: typing.Iterable[SOCKET_OPTION] | None=None) -> None:
        import httpcore
        proxy = Proxy(url=proxy) if isinstance(proxy, (str, URL)) else proxy
        ssl_context = create_ssl_context(verify=verify, cert=cert, trust_env=trust_env)
        if proxy is None:
            self._pool = httpcore.AsyncConnectionPool(ssl_context=ssl_context, max_connections=limits.max_connections, max_keepalive_connections=limits.max_keepalive_connections, keepalive_expiry=limits.keepalive_expiry, http1=http1, http2=http2, uds=uds, local_address=local_address, retries=retries, socket_options=socket_options)
        elif proxy.url.scheme in ('http', 'https'):
            self._pool = httpcore.AsyncHTTPProxy(proxy_url=httpcore.URL(scheme=proxy.url.raw_scheme, host=proxy.url.raw_host, port=proxy.url.port, target=proxy.url.raw_path), proxy_auth=proxy.raw_auth, proxy_headers=proxy.headers.raw, proxy_ssl_context=proxy.ssl_context, ssl_context=ssl_context, max_connections=limits.max_connections, max_keepalive_connections=limits.max_keepalive_connections, keepalive_expiry=limits.keepalive_expiry, http1=http1, http2=http2, socket_options=socket_options)
        elif proxy.url.scheme in ('socks5', 'socks5h'):
            try:
                import socksio
            except ImportError:
                raise ImportError("Using SOCKS proxy, but the 'socksio' package is not installed. Make sure to install httpx using `pip install httpx[socks]`.") from None
            self._pool = httpcore.AsyncSOCKSProxy(proxy_url=httpcore.URL(scheme=proxy.url.raw_scheme, host=proxy.url.raw_host, port=proxy.url.port, target=proxy.url.raw_path), proxy_auth=proxy.raw_auth, ssl_context=ssl_context, max_connections=limits.max_connections, max_keepalive_connections=limits.max_keepalive_connections, keepalive_expiry=limits.keepalive_expiry, http1=http1, http2=http2)
        else:
            raise ValueError("Proxy protocol must be either 'http', 'https', 'socks5', or 'socks5h', but got {proxy.url.scheme!r}.")

    async def __aenter__(self: A) -> A:
        await self._pool.__aenter__()
        return self

    async def __aexit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: TracebackType | None=None) -> None:
        with map_httpcore_exceptions():
            await self._pool.__aexit__(exc_type, exc_value, traceback)

    async def handle_async_request(self, request: Request) -> Response:
        assert isinstance(request.stream, AsyncByteStream)
        import httpcore
        req = httpcore.Request(method=request.method, url=httpcore.URL(scheme=request.url.raw_scheme, host=request.url.raw_host, port=request.url.port, target=request.url.raw_path), headers=request.headers.raw, content=request.stream, extensions=request.extensions)
        with map_httpcore_exceptions():
            resp = await self._pool.handle_async_request(req)
        assert isinstance(resp.stream, typing.AsyncIterable)
        return Response(status_code=resp.status, headers=resp.headers, stream=AsyncResponseStream(resp.stream), extensions=resp.extensions)

    async def aclose(self) -> None:
        await self._pool.aclose()

import importlib.util
import os
import tempfile
from pathlib import PurePath
from typing import TYPE_CHECKING, NamedTuple, Optional, Union
import fsspec
import numpy as np
from .features import List
from .utils import logging
from .utils import tqdm as hf_tqdm
if TYPE_CHECKING:
    from .arrow_dataset import Dataset
    try:
        from elasticsearch import Elasticsearch
    except ImportError:
        pass
    try:
        import faiss
    except ImportError:
        pass
_has_elasticsearch = importlib.util.find_spec('elasticsearch') is not None
_has_faiss = importlib.util.find_spec('faiss') is not None
logger = logging.get_logger(__name__)

class MissingIndex(Exception):
    pass

class SearchResults(NamedTuple):
    scores: list[float]
    indices: list[int]

class BatchedSearchResults(NamedTuple):
    total_scores: list[list[float]]
    total_indices: list[list[int]]

class NearestExamplesResults(NamedTuple):
    scores: list[float]
    examples: dict

class BatchedNearestExamplesResults(NamedTuple):
    total_scores: list[list[float]]
    total_examples: list[dict]

class BaseIndex:

    def search(self, query, k: int=10, **kwargs) -> SearchResults:
        raise NotImplementedError

    def search_batch(self, queries, k: int=10, **kwargs) -> BatchedSearchResults:
        total_scores, total_indices = ([], [])
        for query in queries:
            scores, indices = self.search(query, k)
            total_scores.append(scores)
            total_indices.append(indices)
        return BatchedSearchResults(total_scores, total_indices)

    def save(self, file: Union[str, PurePath]):
        raise NotImplementedError

    @classmethod
    def load(cls, file: Union[str, PurePath]) -> 'BaseIndex':
        raise NotImplementedError

class ElasticSearchIndex(BaseIndex):

    def __init__(self, host: Optional[str]=None, port: Optional[int]=None, es_client: Optional['Elasticsearch']=None, es_index_name: Optional[str]=None, es_index_config: Optional[dict]=None):
        if not _has_elasticsearch:
            raise ImportError('You must install ElasticSearch to use ElasticSearchIndex. To do so you can run `pip install elasticsearch==7.7.1 for example`')
        if es_client is not None and (host is not None or port is not None):
            raise ValueError('Please specify either `es_client` or `(host, port)`, but not both.')
        host = host or 'localhost'
        port = port or 9200
        import elasticsearch.helpers
        from elasticsearch import Elasticsearch
        self.es_client = es_client if es_client is not None else Elasticsearch([{'host': host, 'port': str(port)}])
        self.es_index_name = es_index_name if es_index_name is not None else 'huggingface_datasets_' + os.path.basename(tempfile.NamedTemporaryFile().name)
        self.es_index_config = es_index_config if es_index_config is not None else {'settings': {'number_of_shards': 1, 'analysis': {'analyzer': {'stop_standard': {'type': 'standard', ' stopwords': '_english_'}}}}, 'mappings': {'properties': {'text': {'type': 'text', 'analyzer': 'standard', 'similarity': 'BM25'}}}}

    def add_documents(self, documents: Union[list[str], 'Dataset'], column: Optional[str]=None):
        index_name = self.es_index_name
        index_config = self.es_index_config
        self.es_client.indices.create(index=index_name, body=index_config)
        number_of_docs = len(documents)
        progress = hf_tqdm(unit='docs', total=number_of_docs)
        successes = 0

        def passage_generator():
            if column is not None:
                for i, example in enumerate(documents):
                    yield {'text': example[column], '_id': i}
            else:
                for i, example in enumerate(documents):
                    yield {'text': example, '_id': i}
        import elasticsearch as es
        for ok, action in es.helpers.streaming_bulk(client=self.es_client, index=index_name, actions=passage_generator()):
            progress.update(1)
            successes += ok
        if successes != len(documents):
            logger.warning(f'Some documents failed to be added to ElasticSearch. Failures: {len(documents) - successes}/{len(documents)}')
        logger.info(f'Indexed {successes:d} documents')

    def search(self, query: str, k=10, **kwargs) -> SearchResults:
        response = self.es_client.search(index=self.es_index_name, body={'query': {'multi_match': {'query': query, 'fields': ['text'], 'type': 'cross_fields'}}, 'size': k}, **kwargs)
        hits = response['hits']['hits']
        return SearchResults([hit['_score'] for hit in hits], [int(hit['_id']) for hit in hits])

    def search_batch(self, queries, k: int=10, max_workers=10, **kwargs) -> BatchedSearchResults:
        import concurrent.futures
        total_scores, total_indices = ([None] * len(queries), [None] * len(queries))
        with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_index = {executor.submit(self.search, query, k, **kwargs): i for i, query in enumerate(queries)}
            for future in concurrent.futures.as_completed(future_to_index):
                index = future_to_index[future]
                results: SearchResults = future.result()
                total_scores[index] = results.scores
                total_indices[index] = results.indices
        return BatchedSearchResults(total_indices=total_indices, total_scores=total_scores)

class FaissIndex(BaseIndex):

    def __init__(self, device: Optional[Union[int, list[int]]]=None, string_factory: Optional[str]=None, metric_type: Optional[int]=None, custom_index: Optional['faiss.Index']=None):
        if string_factory is not None and custom_index is not None:
            raise ValueError('Please specify either `string_factory` or `custom_index` but not both.')
        if device is not None and custom_index is not None:
            raise ValueError("Cannot pass both 'custom_index' and 'device'. Pass 'custom_index' already transferred to the target device instead.")
        self.device = device
        self.string_factory = string_factory
        self.metric_type = metric_type
        self.faiss_index = custom_index
        if not _has_faiss:
            raise ImportError('You must install Faiss to use FaissIndex. To do so you can run `conda install -c pytorch faiss-cpu` or `conda install -c pytorch faiss-gpu`. A community supported package is also available on pypi: `pip install faiss-cpu` or `pip install faiss-gpu`. Note that pip may not have the latest version of FAISS, and thus, some of the latest features and bug fixes may not be available.')

    def add_vectors(self, vectors: Union[np.array, 'Dataset'], column: Optional[str]=None, batch_size: int=1000, train_size: Optional[int]=None, faiss_verbose: Optional[bool]=None):
        import faiss
        if column and (not isinstance(vectors.features[column], List)):
            raise ValueError(f"Wrong feature type for column '{column}'. Expected 1d array, got {vectors.features[column]}")
        if self.faiss_index is None:
            size = len(vectors[0]) if column is None else len(vectors[0][column])
            if self.string_factory is not None:
                if self.metric_type is None:
                    index = faiss.index_factory(size, self.string_factory)
                else:
                    index = faiss.index_factory(size, self.string_factory, self.metric_type)
            elif self.metric_type is None:
                index = faiss.IndexFlat(size)
            else:
                index = faiss.IndexFlat(size, self.metric_type)
            self.faiss_index = self._faiss_index_to_device(index, self.device)
            logger.info(f'Created faiss index of type {type(self.faiss_index)}')
        if faiss_verbose is not None:
            self.faiss_index.verbose = faiss_verbose
            if hasattr(self.faiss_index, 'index') and self.faiss_index.index is not None:
                self.faiss_index.index.verbose = faiss_verbose
            if hasattr(self.faiss_index, 'quantizer') and self.faiss_index.quantizer is not None:
                self.faiss_index.quantizer.verbose = faiss_verbose
            if hasattr(self.faiss_index, 'clustering_index') and self.faiss_index.clustering_index is not None:
                self.faiss_index.clustering_index.verbose = faiss_verbose
        if train_size is not None:
            train_vecs = vectors[:train_size] if column is None else vectors[:train_size][column]
            logger.info(f'Training the index with the first {len(train_vecs)} vectors')
            self.faiss_index.train(train_vecs)
        else:
            logger.info('Ignored the training step of the faiss index as `train_size` is None.')
        logger.info(f'Adding {len(vectors)} vectors to the faiss index')
        for i in hf_tqdm(range(0, len(vectors), batch_size)):
            vecs = vectors[i:i + batch_size] if column is None else vectors[i:i + batch_size][column]
            self.faiss_index.add(vecs)

    @staticmethod
    def _faiss_index_to_device(index: 'faiss.Index', device: Optional[Union[int, list[int]]]=None) -> 'faiss.Index':
        if device is None:
            return index
        import faiss
        if isinstance(device, int):
            if device > -1:
                faiss_res = faiss.StandardGpuResources()
                index = faiss.index_cpu_to_gpu(faiss_res, device, index)
            else:
                index = faiss.index_cpu_to_all_gpus(index)
        elif isinstance(device, (list, tuple)):
            index = faiss.index_cpu_to_gpus_list(index, gpus=list(device))
        else:
            raise TypeError(f'The argument type: {type(device)} is not expected. ' + 'Please pass in either nothing, a positive int, a negative int, or a list of positive ints.')
        return index

    def search(self, query: np.array, k=10, **kwargs) -> SearchResults:
        if len(query.shape) != 1 and (len(query.shape) != 2 or query.shape[0] != 1):
            raise ValueError('Shape of query is incorrect, it has to be either a 1D array or 2D (1, N)')
        queries = query.reshape(1, -1)
        if not queries.flags.c_contiguous:
            queries = np.asarray(queries, order='C')
        scores, indices = self.faiss_index.search(queries, k, **kwargs)
        return SearchResults(scores[0], indices[0].astype(int))

    def search_batch(self, queries: np.array, k=10, **kwargs) -> BatchedSearchResults:
        if len(queries.shape) != 2:
            raise ValueError('Shape of query must be 2D')
        if not queries.flags.c_contiguous:
            queries = np.asarray(queries, order='C')
        scores, indices = self.faiss_index.search(queries, k, **kwargs)
        return BatchedSearchResults(scores, indices.astype(int))

    def save(self, file: Union[str, PurePath], storage_options: Optional[dict]=None):
        import faiss
        if self.device is not None and isinstance(self.device, (int, list, tuple)):
            index = faiss.index_gpu_to_cpu(self.faiss_index)
        else:
            index = self.faiss_index
        with fsspec.open(str(file), 'wb', **storage_options or {}) as f:
            faiss.write_index(index, faiss.BufferedIOWriter(faiss.PyCallbackIOWriter(f.write)))

    @classmethod
    def load(cls, file: Union[str, PurePath], device: Optional[Union[int, list[int]]]=None, storage_options: Optional[dict]=None) -> 'FaissIndex':
        import faiss
        faiss_index = cls(device=device)
        with fsspec.open(str(file), 'rb', **storage_options or {}) as f:
            index = faiss.read_index(faiss.BufferedIOReader(faiss.PyCallbackIOReader(f.read)))
        faiss_index.faiss_index = faiss_index._faiss_index_to_device(index, faiss_index.device)
        return faiss_index

class IndexableMixin:

    def __init__(self):
        self._indexes: dict[str, BaseIndex] = {}

    def __len__(self):
        raise NotImplementedError

    def __getitem__(self, key):
        raise NotImplementedError

    def is_index_initialized(self, index_name: str) -> bool:
        return index_name in self._indexes

    def _check_index_is_initialized(self, index_name: str):
        if not self.is_index_initialized(index_name):
            raise MissingIndex(f"Index with index_name '{index_name}' not initialized yet. Please make sure that you call `add_faiss_index` or `add_elasticsearch_index` first.")

    def list_indexes(self) -> list[str]:
        return list(self._indexes)

    def get_index(self, index_name: str) -> BaseIndex:
        self._check_index_is_initialized(index_name)
        return self._indexes[index_name]

    def add_faiss_index(self, column: str, index_name: Optional[str]=None, device: Optional[Union[int, list[int]]]=None, string_factory: Optional[str]=None, metric_type: Optional[int]=None, custom_index: Optional['faiss.Index']=None, batch_size: int=1000, train_size: Optional[int]=None, faiss_verbose: bool=False):
        index_name = index_name if index_name is not None else column
        faiss_index = FaissIndex(device=device, string_factory=string_factory, metric_type=metric_type, custom_index=custom_index)
        faiss_index.add_vectors(self, column=column, batch_size=batch_size, train_size=train_size, faiss_verbose=faiss_verbose)
        self._indexes[index_name] = faiss_index

    def add_faiss_index_from_external_arrays(self, external_arrays: np.array, index_name: str, device: Optional[Union[int, list[int]]]=None, string_factory: Optional[str]=None, metric_type: Optional[int]=None, custom_index: Optional['faiss.Index']=None, batch_size: int=1000, train_size: Optional[int]=None, faiss_verbose: bool=False):
        faiss_index = FaissIndex(device=device, string_factory=string_factory, metric_type=metric_type, custom_index=custom_index)
        faiss_index.add_vectors(external_arrays, column=None, batch_size=batch_size, train_size=train_size, faiss_verbose=faiss_verbose)
        self._indexes[index_name] = faiss_index

    def save_faiss_index(self, index_name: str, file: Union[str, PurePath], storage_options: Optional[dict]=None):
        index = self.get_index(index_name)
        if not isinstance(index, FaissIndex):
            raise ValueError(f"Index '{index_name}' is not a FaissIndex but a '{type(index)}'")
        index.save(file, storage_options=storage_options)
        logger.info(f'Saved FaissIndex {index_name} at {file}')

    def load_faiss_index(self, index_name: str, file: Union[str, PurePath], device: Optional[Union[int, list[int]]]=None, storage_options: Optional[dict]=None):
        index = FaissIndex.load(file, device=device, storage_options=storage_options)
        if index.faiss_index.ntotal != len(self):
            raise ValueError(f"Index size should match Dataset size, but Index '{index_name}' at {file} has {index.faiss_index.ntotal} elements while the dataset has {len(self)} examples.")
        self._indexes[index_name] = index
        logger.info(f'Loaded FaissIndex {index_name} from {file}')

    def add_elasticsearch_index(self, column: str, index_name: Optional[str]=None, host: Optional[str]=None, port: Optional[int]=None, es_client: Optional['Elasticsearch']=None, es_index_name: Optional[str]=None, es_index_config: Optional[dict]=None):
        index_name = index_name if index_name is not None else column
        es_index = ElasticSearchIndex(host=host, port=port, es_client=es_client, es_index_name=es_index_name, es_index_config=es_index_config)
        es_index.add_documents(self, column=column)
        self._indexes[index_name] = es_index

    def load_elasticsearch_index(self, index_name: str, es_index_name: str, host: Optional[str]=None, port: Optional[int]=None, es_client: Optional['Elasticsearch']=None, es_index_config: Optional[dict]=None):
        self._indexes[index_name] = ElasticSearchIndex(host=host, port=port, es_client=es_client, es_index_name=es_index_name, es_index_config=es_index_config)

    def drop_index(self, index_name: str):
        del self._indexes[index_name]

    def search(self, index_name: str, query: Union[str, np.array], k: int=10, **kwargs) -> SearchResults:
        self._check_index_is_initialized(index_name)
        return self._indexes[index_name].search(query, k, **kwargs)

    def search_batch(self, index_name: str, queries: Union[list[str], np.array], k: int=10, **kwargs) -> BatchedSearchResults:
        self._check_index_is_initialized(index_name)
        return self._indexes[index_name].search_batch(queries, k, **kwargs)

    def get_nearest_examples(self, index_name: str, query: Union[str, np.array], k: int=10, **kwargs) -> NearestExamplesResults:
        self._check_index_is_initialized(index_name)
        scores, indices = self.search(index_name, query, k, **kwargs)
        top_indices = [i for i in indices if i >= 0]
        return NearestExamplesResults(scores[:len(top_indices)], self[top_indices])

    def get_nearest_examples_batch(self, index_name: str, queries: Union[list[str], np.array], k: int=10, **kwargs) -> BatchedNearestExamplesResults:
        self._check_index_is_initialized(index_name)
        total_scores, total_indices = self.search_batch(index_name, queries, k, **kwargs)
        total_scores = [scores_i[:len([i for i in indices_i if i >= 0])] for scores_i, indices_i in zip(total_scores, total_indices)]
        total_samples = [self[[i for i in indices if i >= 0]] for indices in total_indices]
        return BatchedNearestExamplesResults(total_scores, total_samples)

import ast
import contextlib
import logging
import os
import re
from collections.abc import Sequence
from typing import ClassVar
import panel as pn
from .core import OpenFile, get_filesystem_class, split_protocol
from .registry import known_implementations
pn.extension()
logger = logging.getLogger('fsspec.gui')

class SigSlot:
    signals: ClassVar[Sequence[str]] = []
    slots: ClassVar[Sequence[str]] = []

    def __init__(self):
        self._ignoring_events = False
        self._sigs = {}
        self._map = {}
        self._setup()

    def _setup(self):
        self.panel = pn.pane.PaneBase()

    def _register(self, widget, name, thing='value', log_level=logging.DEBUG, auto=False):
        if name not in self.signals:
            raise ValueError(f'Attempt to assign an undeclared signal: {name}')
        self._sigs[name] = {'widget': widget, 'callbacks': [], 'thing': thing, 'log': log_level}
        wn = '-'.join([getattr(widget, 'name', str(widget)) if widget is not None else 'none', thing])
        self._map[wn] = name
        if widget is not None:
            widget.param.watch(self._signal, thing, onlychanged=True)
        if auto and hasattr(self, name):
            self.connect(name, getattr(self, name))

    def _repr_mimebundle_(self, *args, **kwargs):
        try:
            return self.panel._repr_mimebundle_(*args, **kwargs)
        except (ValueError, AttributeError) as exc:
            raise NotImplementedError('Panel does not seem to be set up properly') from exc

    def connect(self, signal, slot):
        self._sigs[signal]['callbacks'].append(slot)

    def _signal(self, event):
        if not self._ignoring_events:
            wn = '-'.join([event.obj.name, event.name])
            if wn in self._map and self._map[wn] in self._sigs:
                self._emit(self._map[wn], event.new)

    @contextlib.contextmanager
    def ignore_events(self):
        self._ignoring_events = True
        try:
            yield
        finally:
            self._ignoring_events = False

    def _emit(self, sig, value=None):
        logger.log(self._sigs[sig]['log'], f'{sig}: {value}')
        for callback in self._sigs[sig]['callbacks']:
            if isinstance(callback, str):
                self._emit(callback)
            else:
                try:
                    ret = callback(value)
                    if ret is False:
                        break
                except Exception as e:
                    logger.exception('Exception (%s) while executing callback for signal: %s', e, sig)

    def show(self, threads=False):
        self.panel.show(threads=threads, verbose=False)
        return self

class SingleSelect(SigSlot):
    signals = ['_selected', 'selected']
    slots = ['set_options', 'set_selection', 'add', 'clear', 'select']

    def __init__(self, **kwargs):
        self.kwargs = kwargs
        super().__init__()

    def _setup(self):
        self.panel = pn.widgets.MultiSelect(**self.kwargs)
        self._register(self.panel, '_selected', 'value')
        self._register(None, 'selected')
        self.connect('_selected', self.select_one)

    def _signal(self, *args, **kwargs):
        super()._signal(*args, **kwargs)

    def select_one(self, *_):
        with self.ignore_events():
            val = [self.panel.value[-1]] if self.panel.value else []
            self.panel.value = val
        self._emit('selected', self.panel.value)

    def set_options(self, options):
        self.panel.options = options

    def clear(self):
        self.panel.options = []

    @property
    def value(self):
        return self.panel.value

    def set_selection(self, selection):
        self.panel.value = [selection]

class FileSelector(SigSlot):
    signals = ['protocol_changed', 'selection_changed', 'directory_entered', 'home_clicked', 'up_clicked', 'go_clicked', 'filters_changed']
    slots = ['set_filters', 'go_home']

    def __init__(self, url=None, filters=None, ignore=None, kwargs=None):
        if url:
            self.init_protocol, url = split_protocol(url)
        else:
            self.init_protocol, url = ('file', os.getcwd())
        self.init_url = url
        self.init_kwargs = (kwargs if isinstance(kwargs, str) else str(kwargs)) or '{}'
        self.filters = filters
        self.ignore = [re.compile(i) for i in ignore or []]
        self._fs = None
        super().__init__()

    def _setup(self):
        self.url = pn.widgets.TextInput(name='url', value=self.init_url, align='end', sizing_mode='stretch_width', width_policy='max')
        self.protocol = pn.widgets.Select(options=sorted(known_implementations), value=self.init_protocol, name='protocol', align='center')
        self.kwargs = pn.widgets.TextInput(name='kwargs', value=self.init_kwargs, align='center')
        self.go = pn.widgets.Button(name='⇨', align='end', width=45)
        self.main = SingleSelect(size=10)
        self.home = pn.widgets.Button(name='🏠', width=40, height=30, align='end')
        self.up = pn.widgets.Button(name='‹', width=30, height=30, align='end')
        self._register(self.protocol, 'protocol_changed', auto=True)
        self._register(self.go, 'go_clicked', 'clicks', auto=True)
        self._register(self.up, 'up_clicked', 'clicks', auto=True)
        self._register(self.home, 'home_clicked', 'clicks', auto=True)
        self._register(None, 'selection_changed')
        self.main.connect('selected', self.selection_changed)
        self._register(None, 'directory_entered')
        self.prev_protocol = self.protocol.value
        self.prev_kwargs = self.storage_options
        self.filter_sel = pn.widgets.CheckBoxGroup(value=[], options=[], inline=False, align='end', width_policy='min')
        self._register(self.filter_sel, 'filters_changed', auto=True)
        self.panel = pn.Column(pn.Row(self.protocol, self.kwargs), pn.Row(self.home, self.up, self.url, self.go, self.filter_sel), self.main.panel)
        self.set_filters(self.filters)
        self.go_clicked()

    def set_filters(self, filters=None):
        self.filters = filters
        if filters:
            self.filter_sel.options = filters
            self.filter_sel.value = filters
        else:
            self.filter_sel.options = []
            self.filter_sel.value = []

    @property
    def storage_options(self):
        return ast.literal_eval(self.kwargs.value) or {}

    @property
    def fs(self):
        if self._fs is None:
            cls = get_filesystem_class(self.protocol.value)
            self._fs = cls(**self.storage_options)
        return self._fs

    @property
    def urlpath(self):
        return f'{self.protocol.value}://{self.main.value[0]}' if self.main.value else None

    def open_file(self, mode='rb', compression=None, encoding=None):
        if self.urlpath is None:
            raise ValueError('No file selected')
        return OpenFile(self.fs, self.urlpath, mode, compression, encoding)

    def filters_changed(self, values):
        self.filters = values
        self.go_clicked()

    def selection_changed(self, *_):
        if self.urlpath is None:
            return
        if self.fs.isdir(self.urlpath):
            self.url.value = self.fs._strip_protocol(self.urlpath)
        self.go_clicked()

    def go_clicked(self, *_):
        if self.prev_protocol != self.protocol.value or self.prev_kwargs != self.storage_options:
            self._fs = None
            self.prev_protocol = self.protocol.value
            self.prev_kwargs = self.storage_options
        listing = sorted(self.fs.ls(self.url.value, detail=True), key=lambda x: x['name'])
        listing = [l for l in listing if not any((i.match(l['name'].rsplit('/', 1)[-1]) for i in self.ignore))]
        folders = {'📁 ' + o['name'].rsplit('/', 1)[-1]: o['name'] for o in listing if o['type'] == 'directory'}
        files = {'📄 ' + o['name'].rsplit('/', 1)[-1]: o['name'] for o in listing if o['type'] == 'file'}
        if self.filters:
            files = {k: v for k, v in files.items() if any((v.endswith(ext) for ext in self.filters))}
        self.main.set_options(dict(**folders, **files))

    def protocol_changed(self, *_):
        self._fs = None
        self.main.options = []
        self.url.value = ''

    def home_clicked(self, *_):
        self.protocol.value = self.init_protocol
        self.kwargs.value = self.init_kwargs
        self.url.value = self.init_url
        self.go_clicked()

    def up_clicked(self, *_):
        self.url.value = self.fs._parent(self.url.value)
        self.go_clicked()

import logging
import os
import secrets
import shutil
import tempfile
import uuid
from contextlib import suppress
from datetime import datetime
from urllib.parse import quote
import requests
from ..spec import AbstractBufferedFile, AbstractFileSystem
from ..utils import infer_storage_options, tokenize
logger = logging.getLogger('webhdfs')

class WebHDFS(AbstractFileSystem):
    tempdir = str(tempfile.gettempdir())
    protocol = ('webhdfs', 'webHDFS')

    def __init__(self, host, port=50070, kerberos=False, token=None, user=None, password=None, proxy_to=None, kerb_kwargs=None, data_proxy=None, use_https=False, session_cert=None, session_verify=True, **kwargs):
        if self._cached:
            return
        super().__init__(**kwargs)
        self.url = f"{('https' if use_https else 'http')}://{host}:{port}/webhdfs/v1"
        self.kerb = kerberos
        self.kerb_kwargs = kerb_kwargs or {}
        self.pars = {}
        self.proxy = data_proxy or {}
        if token is not None:
            if user is not None or proxy_to is not None:
                raise ValueError('If passing a delegation token, must not set user or proxy_to, as these are encoded in the token')
            self.pars['delegation'] = token
        self.user = user
        self.password = password
        if password is not None:
            if user is None:
                raise ValueError('If passing a password, the user must also beset in order to set up the basic-auth')
        elif user is not None:
            self.pars['user.name'] = user
        if proxy_to is not None:
            self.pars['doas'] = proxy_to
        if kerberos and user is not None:
            raise ValueError('If using Kerberos auth, do not specify the user, this is handled by kinit.')
        self.session_cert = session_cert
        self.session_verify = session_verify
        self._connect()
        self._fsid = f'webhdfs_{tokenize(host, port)}'

    @property
    def fsid(self):
        return self._fsid

    def _connect(self):
        self.session = requests.Session()
        if self.session_cert:
            self.session.cert = self.session_cert
        self.session.verify = self.session_verify
        if self.kerb:
            from requests_kerberos import HTTPKerberosAuth
            self.session.auth = HTTPKerberosAuth(**self.kerb_kwargs)
        if self.user is not None and self.password is not None:
            from requests.auth import HTTPBasicAuth
            self.session.auth = HTTPBasicAuth(self.user, self.password)

    def _call(self, op, method='get', path=None, data=None, redirect=True, **kwargs):
        path = self._strip_protocol(path) if path is not None else ''
        url = self._apply_proxy(self.url + quote(path, safe='/='))
        args = kwargs.copy()
        args.update(self.pars)
        args['op'] = op.upper()
        logger.debug('sending %s with %s', url, method)
        out = self.session.request(method=method.upper(), url=url, params=args, data=data, allow_redirects=redirect)
        if out.status_code in [400, 401, 403, 404, 500]:
            try:
                err = out.json()
                msg = err['RemoteException']['message']
                exp = err['RemoteException']['exception']
            except (ValueError, KeyError):
                pass
            else:
                if exp in ['IllegalArgumentException', 'UnsupportedOperationException']:
                    raise ValueError(msg)
                elif exp in ['SecurityException', 'AccessControlException']:
                    raise PermissionError(msg)
                elif exp in ['FileNotFoundException']:
                    raise FileNotFoundError(msg)
                else:
                    raise RuntimeError(msg)
        out.raise_for_status()
        return out

    def _open(self, path, mode='rb', block_size=None, autocommit=True, replication=None, permissions=None, **kwargs):
        block_size = block_size or self.blocksize
        return WebHDFile(self, path, mode=mode, block_size=block_size, tempdir=self.tempdir, autocommit=autocommit, replication=replication, permissions=permissions)

    @staticmethod
    def _process_info(info):
        info['type'] = info['type'].lower()
        info['size'] = info['length']
        return info

    @classmethod
    def _strip_protocol(cls, path):
        return infer_storage_options(path)['path']

    @staticmethod
    def _get_kwargs_from_urls(urlpath):
        out = infer_storage_options(urlpath)
        out.pop('path', None)
        out.pop('protocol', None)
        if 'username' in out:
            out['user'] = out.pop('username')
        return out

    def info(self, path):
        out = self._call('GETFILESTATUS', path=path)
        info = out.json()['FileStatus']
        info['name'] = path
        return self._process_info(info)

    def created(self, path):
        info = self.info(path)
        mtime = info.get('modificationTime', None)
        if mtime is not None:
            return datetime.fromtimestamp(mtime / 1000)
        raise RuntimeError('Could not retrieve creation time (modification time).')

    def modified(self, path):
        info = self.info(path)
        mtime = info.get('modificationTime', None)
        if mtime is not None:
            return datetime.fromtimestamp(mtime / 1000)
        raise RuntimeError('Could not retrieve modification time.')

    def ls(self, path, detail=False, **kwargs):
        out = self._call('LISTSTATUS', path=path)
        infos = out.json()['FileStatuses']['FileStatus']
        for info in infos:
            self._process_info(info)
            info['name'] = path.rstrip('/') + '/' + info['pathSuffix']
        if detail:
            return sorted(infos, key=lambda i: i['name'])
        else:
            return sorted((info['name'] for info in infos))

    def content_summary(self, path):
        out = self._call('GETCONTENTSUMMARY', path=path)
        return out.json()['ContentSummary']

    def ukey(self, path):
        out = self._call('GETFILECHECKSUM', path=path, redirect=False)
        if 'Location' in out.headers:
            location = self._apply_proxy(out.headers['Location'])
            out2 = self.session.get(location)
            out2.raise_for_status()
            return out2.json()['FileChecksum']
        else:
            out.raise_for_status()
            return out.json()['FileChecksum']

    def home_directory(self):
        out = self._call('GETHOMEDIRECTORY')
        return out.json()['Path']

    def get_delegation_token(self, renewer=None):
        if renewer:
            out = self._call('GETDELEGATIONTOKEN', renewer=renewer)
        else:
            out = self._call('GETDELEGATIONTOKEN')
        t = out.json()['Token']
        if t is None:
            raise ValueError('No token available for this user/security context')
        return t['urlString']

    def renew_delegation_token(self, token):
        out = self._call('RENEWDELEGATIONTOKEN', method='put', token=token)
        return out.json()['long']

    def cancel_delegation_token(self, token):
        self._call('CANCELDELEGATIONTOKEN', method='put', token=token)

    def chmod(self, path, mod):
        self._call('SETPERMISSION', method='put', path=path, permission=mod)

    def chown(self, path, owner=None, group=None):
        kwargs = {}
        if owner is not None:
            kwargs['owner'] = owner
        if group is not None:
            kwargs['group'] = group
        self._call('SETOWNER', method='put', path=path, **kwargs)

    def set_replication(self, path, replication):
        self._call('SETREPLICATION', path=path, method='put', replication=replication)

    def mkdir(self, path, **kwargs):
        self._call('MKDIRS', method='put', path=path)

    def makedirs(self, path, exist_ok=False):
        if exist_ok is False and self.exists(path):
            raise FileExistsError(path)
        self.mkdir(path)

    def mv(self, path1, path2, **kwargs):
        self._call('RENAME', method='put', path=path1, destination=path2)

    def rm(self, path, recursive=False, **kwargs):
        self._call('DELETE', method='delete', path=path, recursive='true' if recursive else 'false')

    def rm_file(self, path, **kwargs):
        self.rm(path)

    def cp_file(self, lpath, rpath, **kwargs):
        with self.open(lpath) as lstream:
            tmp_fname = '/'.join([self._parent(rpath), f'.tmp.{secrets.token_hex(16)}'])
            try:
                with self.open(tmp_fname, 'wb') as rstream:
                    shutil.copyfileobj(lstream, rstream)
                self.mv(tmp_fname, rpath)
            except BaseException:
                with suppress(FileNotFoundError):
                    self.rm(tmp_fname)
                raise

    def _apply_proxy(self, location):
        if self.proxy and callable(self.proxy):
            location = self.proxy(location)
        elif self.proxy:
            for k, v in self.proxy.items():
                location = location.replace(k, v, 1)
        return location

class WebHDFile(AbstractBufferedFile):

    def __init__(self, fs, path, **kwargs):
        super().__init__(fs, path, **kwargs)
        kwargs = kwargs.copy()
        if kwargs.get('permissions', None) is None:
            kwargs.pop('permissions', None)
        if kwargs.get('replication', None) is None:
            kwargs.pop('replication', None)
        self.permissions = kwargs.pop('permissions', 511)
        tempdir = kwargs.pop('tempdir')
        if kwargs.pop('autocommit', False) is False:
            self.target = self.path
            self.path = os.path.join(tempdir, str(uuid.uuid4()))

    def _upload_chunk(self, final=False):
        out = self.fs.session.post(self.location, data=self.buffer.getvalue(), headers={'content-type': 'application/octet-stream'})
        out.raise_for_status()
        return True

    def _initiate_upload(self):
        kwargs = self.kwargs.copy()
        if 'a' in self.mode:
            op, method = ('APPEND', 'POST')
        else:
            op, method = ('CREATE', 'PUT')
            kwargs['overwrite'] = 'true'
        out = self.fs._call(op, method, self.path, redirect=False, **kwargs)
        location = self.fs._apply_proxy(out.headers['Location'])
        if 'w' in self.mode:
            out2 = self.fs.session.put(location, headers={'content-type': 'application/octet-stream'})
            out2.raise_for_status()
            out2 = self.fs._call('APPEND', 'POST', self.path, redirect=False, **kwargs)
            self.location = self.fs._apply_proxy(out2.headers['Location'])

    def _fetch_range(self, start, end):
        start = max(start, 0)
        end = min(self.size, end)
        if start >= end or start >= self.size:
            return b''
        out = self.fs._call('OPEN', path=self.path, offset=start, length=end - start, redirect=False)
        out.raise_for_status()
        if 'Location' in out.headers:
            location = out.headers['Location']
            out2 = self.fs.session.get(self.fs._apply_proxy(location))
            return out2.content
        else:
            return out.content

    def commit(self):
        self.fs.mv(self.path, self.target)

    def discard(self):
        self.fs.rm(self.path)

import functools
from typing import NamedTuple
import numpy as np
from numpy._core import overrides
from numpy._core._multiarray_umath import _array_converter, _unique_hash
from numpy.lib.array_utils import normalize_axis_index
array_function_dispatch = functools.partial(overrides.array_function_dispatch, module='numpy')
__all__ = ['ediff1d', 'intersect1d', 'isin', 'setdiff1d', 'setxor1d', 'union1d', 'unique', 'unique_all', 'unique_counts', 'unique_inverse', 'unique_values']

def _ediff1d_dispatcher(ary, to_end=None, to_begin=None):
    return (ary, to_end, to_begin)

@array_function_dispatch(_ediff1d_dispatcher)
def ediff1d(ary, to_end=None, to_begin=None):
    conv = _array_converter(ary)
    ary = conv[0].ravel()
    dtype_req = ary.dtype
    if to_begin is None and to_end is None:
        return ary[1:] - ary[:-1]
    if to_begin is None:
        l_begin = 0
    else:
        to_begin = np.asanyarray(to_begin)
        if not np.can_cast(to_begin, dtype_req, casting='same_kind'):
            raise TypeError('dtype of `to_begin` must be compatible with input `ary` under the `same_kind` rule.')
        to_begin = to_begin.ravel()
        l_begin = len(to_begin)
    if to_end is None:
        l_end = 0
    else:
        to_end = np.asanyarray(to_end)
        if not np.can_cast(to_end, dtype_req, casting='same_kind'):
            raise TypeError('dtype of `to_end` must be compatible with input `ary` under the `same_kind` rule.')
        to_end = to_end.ravel()
        l_end = len(to_end)
    l_diff = max(len(ary) - 1, 0)
    result = np.empty_like(ary, shape=l_diff + l_begin + l_end)
    if l_begin > 0:
        result[:l_begin] = to_begin
    if l_end > 0:
        result[l_begin + l_diff:] = to_end
    np.subtract(ary[1:], ary[:-1], result[l_begin:l_begin + l_diff])
    return conv.wrap(result)

def _unpack_tuple(x):
    if len(x) == 1:
        return x[0]
    else:
        return x

def _unique_dispatcher(ar, return_index=None, return_inverse=None, return_counts=None, axis=None, *, equal_nan=None, sorted=True):
    return (ar,)

@array_function_dispatch(_unique_dispatcher)
def unique(ar, return_index=False, return_inverse=False, return_counts=False, axis=None, *, equal_nan=True, sorted=True):
    ar = np.asanyarray(ar)
    if axis is None or ar.ndim == 1:
        if axis is not None:
            normalize_axis_index(axis, ar.ndim)
        ret = _unique1d(ar, return_index, return_inverse, return_counts, equal_nan=equal_nan, inverse_shape=ar.shape, axis=None, sorted=sorted)
        return _unpack_tuple(ret)
    try:
        ar = np.moveaxis(ar, axis, 0)
    except np.exceptions.AxisError:
        raise np.exceptions.AxisError(axis, ar.ndim) from None
    inverse_shape = [1] * ar.ndim
    inverse_shape[axis] = ar.shape[0]
    orig_shape, orig_dtype = (ar.shape, ar.dtype)
    ar = ar.reshape(orig_shape[0], np.prod(orig_shape[1:], dtype=np.intp))
    ar = np.ascontiguousarray(ar)
    dtype = [(f'f{i}', ar.dtype) for i in range(ar.shape[1])]
    try:
        if ar.shape[1] > 0:
            consolidated = ar.view(dtype)
        else:
            consolidated = np.empty(len(ar), dtype=dtype)
    except TypeError as e:
        msg = 'The axis argument to unique is not supported for dtype {dt}'
        raise TypeError(msg.format(dt=ar.dtype)) from e

    def reshape_uniq(uniq):
        n = len(uniq)
        uniq = uniq.view(orig_dtype)
        uniq = uniq.reshape(n, *orig_shape[1:])
        uniq = np.moveaxis(uniq, 0, axis)
        return uniq
    output = _unique1d(consolidated, return_index, return_inverse, return_counts, equal_nan=equal_nan, inverse_shape=inverse_shape, axis=axis, sorted=sorted)
    output = (reshape_uniq(output[0]),) + output[1:]
    return _unpack_tuple(output)

def _unique1d(ar, return_index=False, return_inverse=False, return_counts=False, *, equal_nan=True, inverse_shape=None, axis=None, sorted=True):
    ar = np.asanyarray(ar).flatten()
    if len(ar.shape) != 1:
        ar = np.asarray(ar).flatten()
    optional_indices = return_index or return_inverse
    if not optional_indices and (not return_counts) and (not np.ma.is_masked(ar)):
        conv = _array_converter(ar)
        ar_, = conv
        if (hash_unique := _unique_hash(ar_, equal_nan=equal_nan)) is not NotImplemented:
            if sorted:
                hash_unique.sort()
            return (conv.wrap(hash_unique),)
    if optional_indices:
        perm = ar.argsort(kind='mergesort' if return_index else 'quicksort')
        aux = ar[perm]
    else:
        ar.sort()
        aux = ar
    mask = np.empty(aux.shape, dtype=np.bool)
    mask[:1] = True
    if equal_nan and aux.shape[0] > 0 and (aux.dtype.kind in 'cfmM') and np.isnan(aux[-1]):
        if aux.dtype.kind == 'c':
            aux_firstnan = np.searchsorted(np.isnan(aux), True, side='left')
        else:
            aux_firstnan = np.searchsorted(aux, aux[-1], side='left')
        if aux_firstnan > 0:
            mask[1:aux_firstnan] = aux[1:aux_firstnan] != aux[:aux_firstnan - 1]
        mask[aux_firstnan] = True
        mask[aux_firstnan + 1:] = False
    else:
        mask[1:] = aux[1:] != aux[:-1]
    ret = (aux[mask],)
    if return_index:
        ret += (perm[mask],)
    if return_inverse:
        imask = np.cumsum(mask) - 1
        inv_idx = np.empty(mask.shape, dtype=np.intp)
        inv_idx[perm] = imask
        ret += (inv_idx.reshape(inverse_shape) if axis is None else inv_idx,)
    if return_counts:
        idx = np.concatenate(np.nonzero(mask) + ([mask.size],))
        ret += (np.diff(idx),)
    return ret

class UniqueAllResult(NamedTuple):
    values: np.ndarray
    indices: np.ndarray
    inverse_indices: np.ndarray
    counts: np.ndarray

class UniqueCountsResult(NamedTuple):
    values: np.ndarray
    counts: np.ndarray

class UniqueInverseResult(NamedTuple):
    values: np.ndarray
    inverse_indices: np.ndarray

def _unique_all_dispatcher(x, /):
    return (x,)

@array_function_dispatch(_unique_all_dispatcher)
def unique_all(x):
    result = unique(x, return_index=True, return_inverse=True, return_counts=True, equal_nan=False)
    return UniqueAllResult(*result)

def _unique_counts_dispatcher(x, /):
    return (x,)

@array_function_dispatch(_unique_counts_dispatcher)
def unique_counts(x):
    result = unique(x, return_index=False, return_inverse=False, return_counts=True, equal_nan=False)
    return UniqueCountsResult(*result)

def _unique_inverse_dispatcher(x, /):
    return (x,)

@array_function_dispatch(_unique_inverse_dispatcher)
def unique_inverse(x):
    result = unique(x, return_index=False, return_inverse=True, return_counts=False, equal_nan=False)
    return UniqueInverseResult(*result)

def _unique_values_dispatcher(x, /):
    return (x,)

@array_function_dispatch(_unique_values_dispatcher)
def unique_values(x):
    return unique(x, return_index=False, return_inverse=False, return_counts=False, equal_nan=False, sorted=False)

def _intersect1d_dispatcher(ar1, ar2, assume_unique=None, return_indices=None):
    return (ar1, ar2)

@array_function_dispatch(_intersect1d_dispatcher)
def intersect1d(ar1, ar2, assume_unique=False, return_indices=False):
    ar1 = np.asanyarray(ar1)
    ar2 = np.asanyarray(ar2)
    if not assume_unique:
        if return_indices:
            ar1, ind1 = unique(ar1, return_index=True)
            ar2, ind2 = unique(ar2, return_index=True)
        else:
            ar1 = unique(ar1)
            ar2 = unique(ar2)
    else:
        ar1 = ar1.ravel()
        ar2 = ar2.ravel()
    aux = np.concatenate((ar1, ar2))
    if return_indices:
        aux_sort_indices = np.argsort(aux, kind='mergesort')
        aux = aux[aux_sort_indices]
    else:
        aux.sort()
    mask = aux[1:] == aux[:-1]
    int1d = aux[:-1][mask]
    if return_indices:
        ar1_indices = aux_sort_indices[:-1][mask]
        ar2_indices = aux_sort_indices[1:][mask] - ar1.size
        if not assume_unique:
            ar1_indices = ind1[ar1_indices]
            ar2_indices = ind2[ar2_indices]
        return (int1d, ar1_indices, ar2_indices)
    else:
        return int1d

def _setxor1d_dispatcher(ar1, ar2, assume_unique=None):
    return (ar1, ar2)

@array_function_dispatch(_setxor1d_dispatcher)
def setxor1d(ar1, ar2, assume_unique=False):
    if not assume_unique:
        ar1 = unique(ar1)
        ar2 = unique(ar2)
    aux = np.concatenate((ar1, ar2), axis=None)
    if aux.size == 0:
        return aux
    aux.sort()
    flag = np.concatenate(([True], aux[1:] != aux[:-1], [True]))
    return aux[flag[1:] & flag[:-1]]

def _isin(ar1, ar2, assume_unique=False, invert=False, *, kind=None):
    ar1 = np.asarray(ar1).ravel()
    ar2 = np.asarray(ar2).ravel()
    if ar2.dtype == object:
        ar2 = ar2.reshape(-1, 1)
    if kind not in {None, 'sort', 'table'}:
        raise ValueError(f"Invalid kind: '{kind}'. Please use None, 'sort' or 'table'.")
    is_int_arrays = all((ar.dtype.kind in ('u', 'i', 'b') for ar in (ar1, ar2)))
    use_table_method = is_int_arrays and kind in {None, 'table'}
    if use_table_method:
        if ar2.size == 0:
            if invert:
                return np.ones_like(ar1, dtype=bool)
            else:
                return np.zeros_like(ar1, dtype=bool)
        if ar1.dtype == bool:
            ar1 = ar1.astype(np.uint8)
        if ar2.dtype == bool:
            ar2 = ar2.astype(np.uint8)
        ar2_min = int(np.min(ar2))
        ar2_max = int(np.max(ar2))
        ar2_range = ar2_max - ar2_min
        below_memory_constraint = ar2_range <= 6 * (ar1.size + ar2.size)
        range_safe_from_overflow = ar2_range <= np.iinfo(ar2.dtype).max
        if range_safe_from_overflow and (below_memory_constraint or kind == 'table'):
            if invert:
                outgoing_array = np.ones_like(ar1, dtype=bool)
            else:
                outgoing_array = np.zeros_like(ar1, dtype=bool)
            if invert:
                isin_helper_ar = np.ones(ar2_range + 1, dtype=bool)
                isin_helper_ar[ar2 - ar2_min] = 0
            else:
                isin_helper_ar = np.zeros(ar2_range + 1, dtype=bool)
                isin_helper_ar[ar2 - ar2_min] = 1
            basic_mask = (ar1 <= ar2_max) & (ar1 >= ar2_min)
            in_range_ar1 = ar1[basic_mask]
            if in_range_ar1.size == 0:
                return outgoing_array
            try:
                ar2_min = np.array(ar2_min, dtype=np.intp)
                dtype = np.intp
            except OverflowError:
                dtype = ar2.dtype
            out = np.empty_like(in_range_ar1, dtype=np.intp)
            outgoing_array[basic_mask] = isin_helper_ar[np.subtract(in_range_ar1, ar2_min, dtype=dtype, out=out, casting='unsafe')]
            return outgoing_array
        elif kind == 'table':
            raise RuntimeError("You have specified kind='table', but the range of values in `ar2` or `ar1` exceed the maximum integer of the datatype. Please set `kind` to None or 'sort'.")
    elif kind == 'table':
        raise ValueError("The 'table' method is only supported for boolean or integer arrays. Please select 'sort' or None for kind.")
    contains_object = ar1.dtype.hasobject or ar2.dtype.hasobject
    if len(ar2) < 10 * len(ar1) ** 0.145 or contains_object:
        if invert:
            mask = np.ones(len(ar1), dtype=bool)
            for a in ar2:
                mask &= ar1 != a
        else:
            mask = np.zeros(len(ar1), dtype=bool)
            for a in ar2:
                mask |= ar1 == a
        return mask
    if not assume_unique:
        ar1, rev_idx = np.unique(ar1, return_inverse=True)
        ar2 = np.unique(ar2)
    ar = np.concatenate((ar1, ar2))
    order = ar.argsort(kind='mergesort')
    sar = ar[order]
    if invert:
        bool_ar = sar[1:] != sar[:-1]
    else:
        bool_ar = sar[1:] == sar[:-1]
    flag = np.concatenate((bool_ar, [invert]))
    ret = np.empty(ar.shape, dtype=bool)
    ret[order] = flag
    if assume_unique:
        return ret[:len(ar1)]
    else:
        return ret[rev_idx]

def _isin_dispatcher(element, test_elements, assume_unique=None, invert=None, *, kind=None):
    return (element, test_elements)

@array_function_dispatch(_isin_dispatcher)
def isin(element, test_elements, assume_unique=False, invert=False, *, kind=None):
    element = np.asarray(element)
    return _isin(element, test_elements, assume_unique=assume_unique, invert=invert, kind=kind).reshape(element.shape)

def _union1d_dispatcher(ar1, ar2):
    return (ar1, ar2)

@array_function_dispatch(_union1d_dispatcher)
def union1d(ar1, ar2):
    return unique(np.concatenate((ar1, ar2), axis=None))

def _setdiff1d_dispatcher(ar1, ar2, assume_unique=None):
    return (ar1, ar2)

@array_function_dispatch(_setdiff1d_dispatcher)
def setdiff1d(ar1, ar2, assume_unique=False):
    if assume_unique:
        ar1 = np.asarray(ar1).ravel()
    else:
        ar1 = unique(ar1)
        ar2 = unique(ar2)
    return ar1[_isin(ar1, ar2, assume_unique=True, invert=True)]

import dask
from distributed.client import Client, _get_global_client
from distributed.worker import Worker
from fsspec import filesystem
from fsspec.spec import AbstractBufferedFile, AbstractFileSystem
from fsspec.utils import infer_storage_options

def _get_client(client):
    if client is None:
        return _get_global_client()
    elif isinstance(client, Client):
        return client
    else:
        return Client(client)

def _in_worker():
    return bool(Worker._instances)

class DaskWorkerFileSystem(AbstractFileSystem):

    def __init__(self, target_protocol=None, target_options=None, fs=None, client=None, **kwargs):
        super().__init__(**kwargs)
        if not (fs is None) ^ (target_protocol is None):
            raise ValueError('Please provide one of filesystem instance (fs) or target_protocol, not both')
        self.target_protocol = target_protocol
        self.target_options = target_options
        self.worker = None
        self.client = client
        self.fs = fs
        self._determine_worker()

    @staticmethod
    def _get_kwargs_from_urls(path):
        so = infer_storage_options(path)
        if 'host' in so and 'port' in so:
            return {'client': f"{so['host']}:{so['port']}"}
        else:
            return {}

    def _determine_worker(self):
        if _in_worker():
            self.worker = True
            if self.fs is None:
                self.fs = filesystem(self.target_protocol, **self.target_options or {})
        else:
            self.worker = False
            self.client = _get_client(self.client)
            self.rfs = dask.delayed(self)

    def mkdir(self, *args, **kwargs):
        if self.worker:
            self.fs.mkdir(*args, **kwargs)
        else:
            self.rfs.mkdir(*args, **kwargs).compute()

    def rm(self, *args, **kwargs):
        if self.worker:
            self.fs.rm(*args, **kwargs)
        else:
            self.rfs.rm(*args, **kwargs).compute()

    def copy(self, *args, **kwargs):
        if self.worker:
            self.fs.copy(*args, **kwargs)
        else:
            self.rfs.copy(*args, **kwargs).compute()

    def mv(self, *args, **kwargs):
        if self.worker:
            self.fs.mv(*args, **kwargs)
        else:
            self.rfs.mv(*args, **kwargs).compute()

    def ls(self, *args, **kwargs):
        if self.worker:
            return self.fs.ls(*args, **kwargs)
        else:
            return self.rfs.ls(*args, **kwargs).compute()

    def _open(self, path, mode='rb', block_size=None, autocommit=True, cache_options=None, **kwargs):
        if self.worker:
            return self.fs._open(path, mode=mode, block_size=block_size, autocommit=autocommit, cache_options=cache_options, **kwargs)
        else:
            return DaskFile(fs=self, path=path, mode=mode, block_size=block_size, autocommit=autocommit, cache_options=cache_options, **kwargs)

    def fetch_range(self, path, mode, start, end):
        if self.worker:
            with self._open(path, mode) as f:
                f.seek(start)
                return f.read(end - start)
        else:
            return self.rfs.fetch_range(path, mode, start, end).compute()

class DaskFile(AbstractBufferedFile):

    def __init__(self, mode='rb', **kwargs):
        if mode != 'rb':
            raise ValueError('Remote dask files can only be opened in "rb" mode')
        super().__init__(**kwargs)

    def _upload_chunk(self, final=False):
        pass

    def _initiate_upload(self):
        pass

    def _fetch_range(self, start, end):
        return self.fs.fetch_range(self.path, self.mode, start, end)

from __future__ import annotations
import ssl
import sys
import types
import typing
from .._backends.sync import SyncBackend
from .._backends.base import SOCKET_OPTION, NetworkBackend
from .._exceptions import ConnectionNotAvailable, UnsupportedProtocol
from .._models import Origin, Proxy, Request, Response
from .._synchronization import Event, ShieldCancellation, ThreadLock
from .connection import HTTPConnection
from .interfaces import ConnectionInterface, RequestInterface

class PoolRequest:

    def __init__(self, request: Request) -> None:
        self.request = request
        self.connection: ConnectionInterface | None = None
        self._connection_acquired = Event()

    def assign_to_connection(self, connection: ConnectionInterface | None) -> None:
        self.connection = connection
        self._connection_acquired.set()

    def clear_connection(self) -> None:
        self.connection = None
        self._connection_acquired = Event()

    def wait_for_connection(self, timeout: float | None=None) -> ConnectionInterface:
        if self.connection is None:
            self._connection_acquired.wait(timeout=timeout)
        assert self.connection is not None
        return self.connection

    def is_queued(self) -> bool:
        return self.connection is None

class ConnectionPool(RequestInterface):

    def __init__(self, ssl_context: ssl.SSLContext | None=None, proxy: Proxy | None=None, max_connections: int | None=10, max_keepalive_connections: int | None=None, keepalive_expiry: float | None=None, http1: bool=True, http2: bool=False, retries: int=0, local_address: str | None=None, uds: str | None=None, network_backend: NetworkBackend | None=None, socket_options: typing.Iterable[SOCKET_OPTION] | None=None) -> None:
        self._ssl_context = ssl_context
        self._proxy = proxy
        self._max_connections = sys.maxsize if max_connections is None else max_connections
        self._max_keepalive_connections = sys.maxsize if max_keepalive_connections is None else max_keepalive_connections
        self._max_keepalive_connections = min(self._max_connections, self._max_keepalive_connections)
        self._keepalive_expiry = keepalive_expiry
        self._http1 = http1
        self._http2 = http2
        self._retries = retries
        self._local_address = local_address
        self._uds = uds
        self._network_backend = SyncBackend() if network_backend is None else network_backend
        self._socket_options = socket_options
        self._connections: list[ConnectionInterface] = []
        self._requests: list[PoolRequest] = []
        self._optional_thread_lock = ThreadLock()

    def create_connection(self, origin: Origin) -> ConnectionInterface:
        if self._proxy is not None:
            if self._proxy.url.scheme in (b'socks5', b'socks5h'):
                from .socks_proxy import Socks5Connection
                return Socks5Connection(proxy_origin=self._proxy.url.origin, proxy_auth=self._proxy.auth, remote_origin=origin, ssl_context=self._ssl_context, keepalive_expiry=self._keepalive_expiry, http1=self._http1, http2=self._http2, network_backend=self._network_backend)
            elif origin.scheme == b'http':
                from .http_proxy import ForwardHTTPConnection
                return ForwardHTTPConnection(proxy_origin=self._proxy.url.origin, proxy_headers=self._proxy.headers, proxy_ssl_context=self._proxy.ssl_context, remote_origin=origin, keepalive_expiry=self._keepalive_expiry, network_backend=self._network_backend)
            from .http_proxy import TunnelHTTPConnection
            return TunnelHTTPConnection(proxy_origin=self._proxy.url.origin, proxy_headers=self._proxy.headers, proxy_ssl_context=self._proxy.ssl_context, remote_origin=origin, ssl_context=self._ssl_context, keepalive_expiry=self._keepalive_expiry, http1=self._http1, http2=self._http2, network_backend=self._network_backend)
        return HTTPConnection(origin=origin, ssl_context=self._ssl_context, keepalive_expiry=self._keepalive_expiry, http1=self._http1, http2=self._http2, retries=self._retries, local_address=self._local_address, uds=self._uds, network_backend=self._network_backend, socket_options=self._socket_options)

    @property
    def connections(self) -> list[ConnectionInterface]:
        return list(self._connections)

    def handle_request(self, request: Request) -> Response:
        scheme = request.url.scheme.decode()
        if scheme == '':
            raise UnsupportedProtocol("Request URL is missing an 'http://' or 'https://' protocol.")
        if scheme not in ('http', 'https', 'ws', 'wss'):
            raise UnsupportedProtocol(f"Request URL has an unsupported protocol '{scheme}://'.")
        timeouts = request.extensions.get('timeout', {})
        timeout = timeouts.get('pool', None)
        with self._optional_thread_lock:
            pool_request = PoolRequest(request)
            self._requests.append(pool_request)
        try:
            while True:
                with self._optional_thread_lock:
                    closing = self._assign_requests_to_connections()
                self._close_connections(closing)
                connection = pool_request.wait_for_connection(timeout=timeout)
                try:
                    response = connection.handle_request(pool_request.request)
                except ConnectionNotAvailable:
                    pool_request.clear_connection()
                else:
                    break
        except BaseException as exc:
            with self._optional_thread_lock:
                self._requests.remove(pool_request)
                closing = self._assign_requests_to_connections()
            self._close_connections(closing)
            raise exc from None
        assert isinstance(response.stream, typing.Iterable)
        return Response(status=response.status, headers=response.headers, content=PoolByteStream(stream=response.stream, pool_request=pool_request, pool=self), extensions=response.extensions)

    def _assign_requests_to_connections(self) -> list[ConnectionInterface]:
        closing_connections = []
        for connection in list(self._connections):
            if connection.is_closed():
                self._connections.remove(connection)
            elif connection.has_expired():
                self._connections.remove(connection)
                closing_connections.append(connection)
            elif connection.is_idle() and len([connection.is_idle() for connection in self._connections]) > self._max_keepalive_connections:
                self._connections.remove(connection)
                closing_connections.append(connection)
        queued_requests = [request for request in self._requests if request.is_queued()]
        for pool_request in queued_requests:
            origin = pool_request.request.url.origin
            available_connections = [connection for connection in self._connections if connection.can_handle_request(origin) and connection.is_available()]
            idle_connections = [connection for connection in self._connections if connection.is_idle()]
            if available_connections:
                connection = available_connections[0]
                pool_request.assign_to_connection(connection)
            elif len(self._connections) < self._max_connections:
                connection = self.create_connection(origin)
                self._connections.append(connection)
                pool_request.assign_to_connection(connection)
            elif idle_connections:
                connection = idle_connections[0]
                self._connections.remove(connection)
                closing_connections.append(connection)
                connection = self.create_connection(origin)
                self._connections.append(connection)
                pool_request.assign_to_connection(connection)
        return closing_connections

    def _close_connections(self, closing: list[ConnectionInterface]) -> None:
        with ShieldCancellation():
            for connection in closing:
                connection.close()

    def close(self) -> None:
        with self._optional_thread_lock:
            closing_connections = list(self._connections)
            self._connections = []
        self._close_connections(closing_connections)

    def __enter__(self) -> ConnectionPool:
        return self

    def __exit__(self, exc_type: type[BaseException] | None=None, exc_value: BaseException | None=None, traceback: types.TracebackType | None=None) -> None:
        self.close()

    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        with self._optional_thread_lock:
            request_is_queued = [request.is_queued() for request in self._requests]
            connection_is_idle = [connection.is_idle() for connection in self._connections]
            num_active_requests = request_is_queued.count(False)
            num_queued_requests = request_is_queued.count(True)
            num_active_connections = connection_is_idle.count(False)
            num_idle_connections = connection_is_idle.count(True)
        requests_info = f'Requests: {num_active_requests} active, {num_queued_requests} queued'
        connection_info = f'Connections: {num_active_connections} active, {num_idle_connections} idle'
        return f'<{class_name} [{requests_info} | {connection_info}]>'

class PoolByteStream:

    def __init__(self, stream: typing.Iterable[bytes], pool_request: PoolRequest, pool: ConnectionPool) -> None:
        self._stream = stream
        self._pool_request = pool_request
        self._pool = pool
        self._closed = False

    def __iter__(self) -> typing.Iterator[bytes]:
        try:
            for part in self._stream:
                yield part
        except BaseException as exc:
            self.close()
            raise exc from None

    def close(self) -> None:
        if not self._closed:
            self._closed = True
            with ShieldCancellation():
                if hasattr(self._stream, 'close'):
                    self._stream.close()
            with self._pool._optional_thread_lock:
                self._pool._requests.remove(self._pool_request)
                closing = self._pool._assign_requests_to_connections()
            self._pool._close_connections(closing)

import os
import ssl
import uuid
from ftplib import FTP, FTP_TLS, Error, error_perm
from typing import Any
from ..spec import AbstractBufferedFile, AbstractFileSystem
from ..utils import infer_storage_options, isfilelike
SECURITY_PROTOCOL_MAP = {'tls': ssl.PROTOCOL_TLS, 'tlsv1': ssl.PROTOCOL_TLSv1, 'tlsv1_1': ssl.PROTOCOL_TLSv1_1, 'tlsv1_2': ssl.PROTOCOL_TLSv1_2, 'sslv23': ssl.PROTOCOL_SSLv23}

class ImplicitFTPTLS(FTP_TLS):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._sock = None

    @property
    def sock(self):
        return self._sock

    @sock.setter
    def sock(self, value):
        if value is not None and (not isinstance(value, ssl.SSLSocket)):
            value = self.context.wrap_socket(value)
        self._sock = value

class FTPFileSystem(AbstractFileSystem):
    root_marker = '/'
    cachable = False
    protocol = 'ftp'

    def __init__(self, host, port=21, username=None, password=None, acct=None, block_size=None, tempdir=None, timeout=30, encoding='utf-8', tls=False, **kwargs):
        super().__init__(**kwargs)
        self.host = host
        self.port = port
        self.tempdir = tempdir or '/tmp'
        self.cred = (username or '', password or '', acct or '')
        self.timeout = timeout
        self.encoding = encoding
        if block_size is not None:
            self.blocksize = block_size
        else:
            self.blocksize = 2 ** 16
        self.tls = tls
        self._connect()
        if isinstance(self.tls, bool) and self.tls:
            self.ftp.prot_p()

    def _connect(self):
        security = None
        if self.tls:
            if isinstance(self.tls, str):
                ftp_cls = ImplicitFTPTLS
                security = SECURITY_PROTOCOL_MAP.get(self.tls, f'Not supported {self.tls} protocol')
                if isinstance(security, str):
                    raise ValueError(security)
            else:
                ftp_cls = FTP_TLS
        else:
            ftp_cls = FTP
        self.ftp = ftp_cls(timeout=self.timeout, encoding=self.encoding)
        if security:
            self.ftp.ssl_version = security
        self.ftp.connect(self.host, self.port)
        self.ftp.login(*self.cred)

    @classmethod
    def _strip_protocol(cls, path):
        return '/' + infer_storage_options(path)['path'].lstrip('/').rstrip('/')

    @staticmethod
    def _get_kwargs_from_urls(urlpath):
        out = infer_storage_options(urlpath)
        out.pop('path', None)
        out.pop('protocol', None)
        return out

    def ls(self, path, detail=True, **kwargs):
        path = self._strip_protocol(path)
        out = []
        if path not in self.dircache:
            try:
                try:
                    out = [(fn, details) for fn, details in self.ftp.mlsd(path) if fn not in ['.', '..'] and details['type'] not in ['pdir', 'cdir']]
                except error_perm:
                    out = _mlsd2(self.ftp, path)
                for fn, details in out:
                    details['name'] = '/'.join(['' if path == '/' else path, fn.lstrip('/')])
                    if details['type'] == 'file':
                        details['size'] = int(details['size'])
                    else:
                        details['size'] = 0
                    if details['type'] == 'dir':
                        details['type'] = 'directory'
                self.dircache[path] = out
            except Error:
                try:
                    info = self.info(path)
                    if info['type'] == 'file':
                        out = [(path, info)]
                except (Error, IndexError) as exc:
                    raise FileNotFoundError(path) from exc
        files = self.dircache.get(path, out)
        if not detail:
            return sorted([fn for fn, details in files])
        return [details for fn, details in files]

    def info(self, path, **kwargs):
        path = self._strip_protocol(path)
        if path == '/':
            return {'name': '/', 'size': 0, 'type': 'directory'}
        files = self.ls(self._parent(path).lstrip('/'), True)
        try:
            out = next((f for f in files if f['name'] == path))
        except StopIteration as exc:
            raise FileNotFoundError(path) from exc
        return out

    def get_file(self, rpath, lpath, **kwargs):
        if self.isdir(rpath):
            if not os.path.exists(lpath):
                os.mkdir(lpath)
            return
        if isfilelike(lpath):
            outfile = lpath
        else:
            outfile = open(lpath, 'wb')

        def cb(x):
            outfile.write(x)
        self.ftp.retrbinary(f'RETR {rpath}', blocksize=self.blocksize, callback=cb)
        if not isfilelike(lpath):
            outfile.close()

    def cat_file(self, path, start=None, end=None, **kwargs):
        if end is not None:
            return super().cat_file(path, start, end, **kwargs)
        out = []

        def cb(x):
            out.append(x)
        try:
            self.ftp.retrbinary(f'RETR {path}', blocksize=self.blocksize, rest=start, callback=cb)
        except (Error, error_perm) as orig_exc:
            raise FileNotFoundError(path) from orig_exc
        return b''.join(out)

    def _open(self, path, mode='rb', block_size=None, cache_options=None, autocommit=True, **kwargs):
        path = self._strip_protocol(path)
        block_size = block_size or self.blocksize
        return FTPFile(self, path, mode=mode, block_size=block_size, tempdir=self.tempdir, autocommit=autocommit, cache_options=cache_options)

    def _rm(self, path):
        path = self._strip_protocol(path)
        self.ftp.delete(path)
        self.invalidate_cache(self._parent(path))

    def rm(self, path, recursive=False, maxdepth=None):
        paths = self.expand_path(path, recursive=recursive, maxdepth=maxdepth)
        for p in reversed(paths):
            if self.isfile(p):
                self.rm_file(p)
            else:
                self.rmdir(p)

    def mkdir(self, path: str, create_parents: bool=True, **kwargs: Any) -> None:
        path = self._strip_protocol(path)
        parent = self._parent(path)
        if parent != self.root_marker and (not self.exists(parent)) and create_parents:
            self.mkdir(parent, create_parents=create_parents)
        self.ftp.mkd(path)
        self.invalidate_cache(self._parent(path))

    def makedirs(self, path: str, exist_ok: bool=False) -> None:
        path = self._strip_protocol(path)
        if self.exists(path):
            if not exist_ok:
                raise FileExistsError(f'{path} exists without `exist_ok`')
        else:
            self.mkdir(path, create_parents=True)

    def rmdir(self, path):
        path = self._strip_protocol(path)
        self.ftp.rmd(path)
        self.invalidate_cache(self._parent(path))

    def mv(self, path1, path2, **kwargs):
        path1 = self._strip_protocol(path1)
        path2 = self._strip_protocol(path2)
        self.ftp.rename(path1, path2)
        self.invalidate_cache(self._parent(path1))
        self.invalidate_cache(self._parent(path2))

    def __del__(self):
        self.ftp.close()

    def invalidate_cache(self, path=None):
        if path is None:
            self.dircache.clear()
        else:
            self.dircache.pop(path, None)
        super().invalidate_cache(path)

class TransferDone(Exception):
    pass

class FTPFile(AbstractBufferedFile):

    def __init__(self, fs, path, mode='rb', block_size='default', autocommit=True, cache_type='readahead', cache_options=None, **kwargs):
        super().__init__(fs, path, mode=mode, block_size=block_size, autocommit=autocommit, cache_type=cache_type, cache_options=cache_options, **kwargs)
        if not autocommit:
            self.target = self.path
            self.path = '/'.join([kwargs['tempdir'], str(uuid.uuid4())])

    def commit(self):
        self.fs.mv(self.path, self.target)

    def discard(self):
        self.fs.rm(self.path)

    def _fetch_range(self, start, end):
        out = []
        total = [0]

        def callback(x):
            total[0] += len(x)
            if total[0] > end - start:
                out.append(x[:end - start - total[0]])
                if end < self.size:
                    raise TransferDone
            else:
                out.append(x)
            if total[0] == end - start and end < self.size:
                raise TransferDone
        try:
            self.fs.ftp.retrbinary(f'RETR {self.path}', blocksize=self.blocksize, rest=start, callback=callback)
        except TransferDone:
            try:
                self.fs.ftp.abort()
                self.fs.ftp.getmultiline()
            except Error:
                self.fs._connect()
        return b''.join(out)

    def _upload_chunk(self, final=False):
        self.buffer.seek(0)
        self.fs.ftp.storbinary(f'STOR {self.path}', self.buffer, blocksize=self.blocksize, rest=self.offset)
        return True

def _mlsd2(ftp, path='.'):
    lines = []
    minfo = []
    ftp.dir(path, lines.append)
    for line in lines:
        split_line = line.split()
        if len(split_line) < 9:
            continue
        this = (split_line[-1], {'modify': ' '.join(split_line[5:8]), 'unix.owner': split_line[2], 'unix.group': split_line[3], 'unix.mode': split_line[0], 'size': split_line[4]})
        if this[1]['unix.mode'][0] == 'd':
            this[1]['type'] = 'dir'
        else:
            this[1]['type'] = 'file'
        minfo.append(this)
    return minfo

import asyncio
import socket
import weakref
from typing import Any, Dict, Final, List, Optional, Tuple, Type, Union
from .abc import AbstractResolver, ResolveResult
__all__ = ('ThreadedResolver', 'AsyncResolver', 'DefaultResolver')
try:
    import aiodns
    aiodns_default = hasattr(aiodns.DNSResolver, 'getaddrinfo')
except ImportError:
    aiodns = None
    aiodns_default = False
_NUMERIC_SOCKET_FLAGS = socket.AI_NUMERICHOST | socket.AI_NUMERICSERV
_NAME_SOCKET_FLAGS = socket.NI_NUMERICHOST | socket.NI_NUMERICSERV
_AI_ADDRCONFIG = socket.AI_ADDRCONFIG
if hasattr(socket, 'AI_MASK'):
    _AI_ADDRCONFIG &= socket.AI_MASK

class ThreadedResolver(AbstractResolver):

    def __init__(self, loop: Optional[asyncio.AbstractEventLoop]=None) -> None:
        self._loop = loop or asyncio.get_running_loop()

    async def resolve(self, host: str, port: int=0, family: socket.AddressFamily=socket.AF_INET) -> List[ResolveResult]:
        infos = await self._loop.getaddrinfo(host, port, type=socket.SOCK_STREAM, family=family, flags=_AI_ADDRCONFIG)
        hosts: List[ResolveResult] = []
        for family, _, proto, _, address in infos:
            if family == socket.AF_INET6:
                if len(address) < 3:
                    continue
                if address[3]:
                    resolved_host, _port = await self._loop.getnameinfo(address, _NAME_SOCKET_FLAGS)
                    port = int(_port)
                else:
                    resolved_host, port = address[:2]
            else:
                assert family == socket.AF_INET
                resolved_host, port = address
            hosts.append(ResolveResult(hostname=host, host=resolved_host, port=port, family=family, proto=proto, flags=_NUMERIC_SOCKET_FLAGS))
        return hosts

    async def close(self) -> None:
        pass

class AsyncResolver(AbstractResolver):

    def __init__(self, loop: Optional[asyncio.AbstractEventLoop]=None, *args: Any, **kwargs: Any) -> None:
        if aiodns is None:
            raise RuntimeError('Resolver requires aiodns library')
        self._loop = loop or asyncio.get_running_loop()
        self._manager: Optional[_DNSResolverManager] = None
        if args or kwargs:
            self._resolver = aiodns.DNSResolver(*args, **kwargs)
            return
        self._manager = _DNSResolverManager()
        self._resolver = self._manager.get_resolver(self, self._loop)
        if not hasattr(self._resolver, 'gethostbyname'):
            self.resolve = self._resolve_with_query

    async def resolve(self, host: str, port: int=0, family: socket.AddressFamily=socket.AF_INET) -> List[ResolveResult]:
        try:
            resp = await self._resolver.getaddrinfo(host, port=port, type=socket.SOCK_STREAM, family=family, flags=_AI_ADDRCONFIG)
        except aiodns.error.DNSError as exc:
            msg = exc.args[1] if len(exc.args) >= 1 else 'DNS lookup failed'
            raise OSError(None, msg) from exc
        hosts: List[ResolveResult] = []
        for node in resp.nodes:
            address: Union[Tuple[bytes, int], Tuple[bytes, int, int, int]] = node.addr
            family = node.family
            if family == socket.AF_INET6:
                if len(address) > 3 and address[3]:
                    result = await self._resolver.getnameinfo((address[0].decode('ascii'), *address[1:]), _NAME_SOCKET_FLAGS)
                    resolved_host = result.node
                else:
                    resolved_host = address[0].decode('ascii')
                    port = address[1]
            else:
                assert family == socket.AF_INET
                resolved_host = address[0].decode('ascii')
                port = address[1]
            hosts.append(ResolveResult(hostname=host, host=resolved_host, port=port, family=family, proto=0, flags=_NUMERIC_SOCKET_FLAGS))
        if not hosts:
            raise OSError(None, 'DNS lookup failed')
        return hosts

    async def _resolve_with_query(self, host: str, port: int=0, family: int=socket.AF_INET) -> List[Dict[str, Any]]:
        qtype: Final = 'AAAA' if family == socket.AF_INET6 else 'A'
        try:
            resp = await self._resolver.query(host, qtype)
        except aiodns.error.DNSError as exc:
            msg = exc.args[1] if len(exc.args) >= 1 else 'DNS lookup failed'
            raise OSError(None, msg) from exc
        hosts = []
        for rr in resp:
            hosts.append({'hostname': host, 'host': rr.host, 'port': port, 'family': family, 'proto': 0, 'flags': socket.AI_NUMERICHOST})
        if not hosts:
            raise OSError(None, 'DNS lookup failed')
        return hosts

    async def close(self) -> None:
        if self._manager:
            self._manager.release_resolver(self, self._loop)
            self._manager = None
            self._resolver = None
            return
        if self._resolver is not None:
            self._resolver.cancel()
        self._resolver = None

class _DNSResolverManager:
    _instance: Optional['_DNSResolverManager'] = None

    def __new__(cls) -> '_DNSResolverManager':
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._init()
        return cls._instance

    def _init(self) -> None:
        self._loop_data: weakref.WeakKeyDictionary[asyncio.AbstractEventLoop, tuple['aiodns.DNSResolver', weakref.WeakSet['AsyncResolver']]] = weakref.WeakKeyDictionary()

    def get_resolver(self, client: 'AsyncResolver', loop: asyncio.AbstractEventLoop) -> 'aiodns.DNSResolver':
        if loop not in self._loop_data:
            resolver = aiodns.DNSResolver(loop=loop)
            client_set: weakref.WeakSet['AsyncResolver'] = weakref.WeakSet()
            self._loop_data[loop] = (resolver, client_set)
        else:
            resolver, client_set = self._loop_data[loop]
        client_set.add(client)
        return resolver

    def release_resolver(self, client: 'AsyncResolver', loop: asyncio.AbstractEventLoop) -> None:
        current_loop_data = self._loop_data.get(loop)
        if current_loop_data is None:
            return
        resolver, client_set = current_loop_data
        client_set.discard(client)
        if not client_set:
            if resolver is not None:
                resolver.cancel()
            del self._loop_data[loop]
_DefaultType = Type[Union[AsyncResolver, ThreadedResolver]]
DefaultResolver: _DefaultType = AsyncResolver if aiodns_default else ThreadedResolver

