class Subtests:

    def __init__(self, ihook: pluggy.HookRelay, suspend_capture_ctx: Callable[[], AbstractContextManager[None]], request: SubRequest, *, _ispytest: bool=False) -> None:
        check_ispytest(_ispytest)
        self._ihook = ihook
        self._suspend_capture_ctx = suspend_capture_ctx
        self._request = request

    def test(self, msg: str | None=None, **kwargs: Any) -> _SubTestContextManager:
        return _SubTestContextManager(self._ihook, msg, kwargs, request=self._request, suspend_capture_ctx=self._suspend_capture_ctx, config=self._request.config)

@dataclasses.dataclass
class _SubTestContextManager:
    ihook: pluggy.HookRelay
    msg: str | None
    kwargs: dict[str, Any]
    suspend_capture_ctx: Callable[[], AbstractContextManager[None]]
    request: SubRequest
    config: Config

    def __enter__(self) -> None:
        __tracebackhide__ = True
        self._start = time.time()
        self._precise_start = time.perf_counter()
        self._exc_info = None
        self._exit_stack = ExitStack()
        self._captured_output = self._exit_stack.enter_context(capturing_output(self.request))
        self._captured_logs = self._exit_stack.enter_context(capturing_logs(self.request))

    def __exit__(self, exc_type: type[BaseException] | None, exc_val: BaseException | None, exc_tb: TracebackType | None) -> bool:
        __tracebackhide__ = True
        if exc_val is not None:
            exc_info = ExceptionInfo.from_exception(exc_val)
        else:
            exc_info = None
        self._exit_stack.close()
        precise_stop = time.perf_counter()
        duration = precise_stop - self._precise_start
        stop = time.time()
        call_info = CallInfo[None](None, exc_info, start=self._start, stop=stop, duration=duration, when='call', _ispytest=True)
        report = self.ihook.pytest_runtest_makereport(item=self.request.node, call=call_info)
        sub_report = SubtestReport._new(report, SubtestContext(msg=self.msg, kwargs=self.kwargs), captured_output=self._captured_output, captured_logs=self._captured_logs)
        if sub_report.failed:
            failed_subtests = self.config.stash[failed_subtests_key]
            failed_subtests[self.request.node.nodeid] += 1
        with self.suspend_capture_ctx():
            self.ihook.pytest_runtest_logreport(report=sub_report)
        if check_interactive_exception(call_info, sub_report):
            self.ihook.pytest_exception_interact(node=self.request.node, call=call_info, report=sub_report)
        if exc_val is not None:
            if isinstance(exc_val, get_reraise_exceptions(self.config)):
                return False
            if self.request.session.shouldfail:
                return False
        return True

@contextmanager
def capturing_output(request: SubRequest) -> Iterator[Captured]:
    option = request.config.getoption('capture', None)
    capman = request.config.pluginmanager.getplugin('capturemanager')
    if getattr(capman, '_capture_fixture', None):
        fixture = None
    elif option == 'sys':
        fixture = CaptureFixture(SysCapture, request, _ispytest=True)
    elif option == 'fd':
        fixture = CaptureFixture(FDCapture, request, _ispytest=True)
    else:
        fixture = None
    if fixture is not None:
        fixture._start()
    captured = Captured()
    try:
        yield captured
    finally:
        if fixture is not None:
            out, err = fixture.readouterr()
            fixture.close()
            captured.out = out
            captured.err = err

@contextmanager
def capturing_logs(request: SubRequest) -> Iterator[CapturedLogs | None]:
    logging_plugin: LoggingPlugin | None = request.config.pluginmanager.getplugin('logging-plugin')
    if logging_plugin is None:
        yield None
    else:
        handler = LogCaptureHandler()
        handler.setFormatter(logging_plugin.formatter)
        captured_logs = CapturedLogs(handler)
        with catching_logs(handler, level=logging_plugin.log_level):
            yield captured_logs

@dataclasses.dataclass
class Captured:
    out: str = ''
    err: str = ''

@dataclasses.dataclass
class CapturedLogs:
    handler: LogCaptureHandler

def pytest_report_to_serializable(report: TestReport) -> dict[str, Any] | None:
