def merge_headers(default_headers: typing.Sequence[tuple[bytes, bytes]] | None=None, override_headers: typing.Sequence[tuple[bytes, bytes]] | None=None) -> list[tuple[bytes, bytes]]:
    default_headers = [] if default_headers is None else list(default_headers)
    override_headers = [] if override_headers is None else list(override_headers)
    has_override = set((key.lower() for key, value in override_headers))
    default_headers = [(key, value) for key, value in default_headers if key.lower() not in has_override]
    return default_headers + override_headers

class AsyncHTTPProxy(AsyncConnectionPool):

    def __init__(self, proxy_url: URL | bytes | str, proxy_auth: tuple[bytes | str, bytes | str] | None=None, proxy_headers: HeadersAsMapping | HeadersAsSequence | None=None, ssl_context: ssl.SSLContext | None=None, proxy_ssl_context: ssl.SSLContext | None=None, max_connections: int | None=10, max_keepalive_connections: int | None=None, keepalive_expiry: float | None=None, http1: bool=True, http2: bool=False, retries: int=0, local_address: str | None=None, uds: str | None=None, network_backend: AsyncNetworkBackend | None=None, socket_options: typing.Iterable[SOCKET_OPTION] | None=None) -> None:
        super().__init__(ssl_context=ssl_context, max_connections=max_connections, max_keepalive_connections=max_keepalive_connections, keepalive_expiry=keepalive_expiry, http1=http1, http2=http2, network_backend=network_backend, retries=retries, local_address=local_address, uds=uds, socket_options=socket_options)
        self._proxy_url = enforce_url(proxy_url, name='proxy_url')
        if self._proxy_url.scheme == b'http' and proxy_ssl_context is not None:
            raise RuntimeError('The `proxy_ssl_context` argument is not allowed for the http scheme')
        self._ssl_context = ssl_context
        self._proxy_ssl_context = proxy_ssl_context
        self._proxy_headers = enforce_headers(proxy_headers, name='proxy_headers')
        if proxy_auth is not None:
            username = enforce_bytes(proxy_auth[0], name='proxy_auth')
            password = enforce_bytes(proxy_auth[1], name='proxy_auth')
            userpass = username + b':' + password
            authorization = b'Basic ' + base64.b64encode(userpass)
            self._proxy_headers = [(b'Proxy-Authorization', authorization)] + self._proxy_headers

    def create_connection(self, origin: Origin) -> AsyncConnectionInterface:
        if origin.scheme == b'http':
            return AsyncForwardHTTPConnection(proxy_origin=self._proxy_url.origin, proxy_headers=self._proxy_headers, remote_origin=origin, keepalive_expiry=self._keepalive_expiry, network_backend=self._network_backend, proxy_ssl_context=self._proxy_ssl_context)
        return AsyncTunnelHTTPConnection(proxy_origin=self._proxy_url.origin, proxy_headers=self._proxy_headers, remote_origin=origin, ssl_context=self._ssl_context, proxy_ssl_context=self._proxy_ssl_context, keepalive_expiry=self._keepalive_expiry, http1=self._http1, http2=self._http2, network_backend=self._network_backend)

class AsyncForwardHTTPConnection(AsyncConnectionInterface):

    def __init__(self, proxy_origin: Origin, remote_origin: Origin, proxy_headers: HeadersAsMapping | HeadersAsSequence | None=None, keepalive_expiry: float | None=None, network_backend: AsyncNetworkBackend | None=None, socket_options: typing.Iterable[SOCKET_OPTION] | None=None, proxy_ssl_context: ssl.SSLContext | None=None) -> None:
